-- ----------------------------
-- Table structure for basic_word
-- ----------------------------
DROP TABLE IF EXISTS `basic_word`;
CREATE TABLE `basic_word`  (
  `yid` int NOT NULL AUTO_INCREMENT COMMENT '音标id',
  `symbol` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '表示符号（可能是音标，也可能是单词的符号）',
  `pronunciation` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '该符号的发音（可以类比中文拼音谐音字或者英文的谐音）',
  `language` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '该符号属于那种语言',
  `example` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '使用了该符号的单词例子',
  `translation` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '举的例子的翻译',
  `type` int NULL DEFAULT NULL COMMENT '该符号的类型（1表示音标，2表示字母）',
  `wave_path` varchar(1024) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '该符号的音频文件的在项目中的地址',
  PRIMARY KEY (`yid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 256 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of basic_word
-- ----------------------------

-- ----------------------------
-- Table structure for book
-- ----------------------------
DROP TABLE IF EXISTS `book`;
CREATE TABLE `book`  (
  `book_id` int NOT NULL AUTO_INCREMENT COMMENT '单词本的id',
  `uid` int NOT NULL COMMENT '该单词本的用户',
  `language` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '单词本的语音类型',
  PRIMARY KEY (`book_id`) USING BTREE,
  INDEX `userId`(`uid`) USING BTREE,
  INDEX `language`(`language`) USING BTREE,
  CONSTRAINT `userId` FOREIGN KEY (`uid`) REFERENCES `student` (`uid`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

