-- Table structure for student_language
-- ----------------------------
DROP TABLE IF EXISTS `student_language`;
CREATE TABLE `student_language`  (
  `sl_id` int NOT NULL COMMENT '关系id',
  `sid` int NOT NULL COMMENT '学生id',
  `lg_id` int NOT NULL COMMENT '语种id',
  `learning_status` tinyint NULL DEFAULT NULL COMMENT '学习状态',
  `current_level` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '学习等级',
  `progress_percentage` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '学习进度',
