-- ----------------------------
-- Table structure for word_clamp
-- ----------------------------
DROP TABLE IF EXISTS `word_clamp`;
CREATE TABLE `word_clamp`  (
  `clamp_id` int NOT NULL AUTO_INCREMENT COMMENT '情景的id',
  `bid` int NOT NULL COMMENT '单词本的id',
  `type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '情景类型',
  `kind` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '情景属于的大类，如自然类，科学类，日常生活类等',
  `random` int NULL DEFAULT NULL,
  PRIMARY KEY (`clamp_id`) USING BTREE,
  INDEX `bookid`(`bid`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  CONSTRAINT `bookid` FOREIGN KEY (`bid`) REFERENCES `book` (`book_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 123 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

