-- ----------------------------
-- Table structure for word_list
-- ----------------------------
DROP TABLE IF EXISTS `word_list`;
CREATE TABLE `word_list`  (
  `word_id` int NOT NULL AUTO_INCREMENT COMMENT '单词的id',
  `cid` int NOT NULL COMMENT '该单词归属哪一个情景单词薄',
  `text` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '该单词在所学的语言中的写法',
  `mother_text` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '该单词的母语翻译',
  `grammer` varchar(1024) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '单词在所学的语言中的语法（词性，例句等）',
  `spell` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '音标',
  `state` int NOT NULL COMMENT '该单词的学习状态（未学会标记为难点；已学会则标记为我已学会）',
  `difficulty` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '该单词的难度（入门，进阶，提升）',
  `mp3_path` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '单词的语音',
  PRIMARY KEY (`word_id`) USING BTREE,
  INDEX `clamp_id`(`cid`) USING BTREE,
  CONSTRAINT `clamp_id` FOREIGN KEY (`cid`) REFERENCES `word_clamp` (`clamp_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 1938 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

