INSERT INTO `basic_word` VALUES (201, 'ㅍ', '/ng/', 'ko', '안녕', '你好', 1, 'src/main/resources/MP3/1719825524834.mp3');
INSERT INTO `basic_word` VALUES (202, 'ㅎ', '/h/', 'ko', '하루', '一天', 1, 'src/main/resources/MP3/1719825525251.mp3');
INSERT INTO `basic_word` VALUES (203, '/a/', '类似于英文中\"father\"的\'a\'，但通常更为前突\r\n', 'fr', 'later', '晚期', 1, 'src\\main\\resources\\MP3\\1723609891209.mp3');
INSERT INTO `basic_word` VALUES (204, '/ε/', '接近于英文中\"bed\"的\'e\'，但发音时舌头位置更低', 'fr', 'sette', '七', 1, 'src\\main\\resources\\MP3\\1723609891651.mp3');
INSERT INTO `basic_word` VALUES (205, '/e/', '类似英文中\"say\"中的\'e\'，不过更加紧张\r\n', 'fr', 'merci', '谢谢', 1, 'src\\main\\resources\\MP3\\1723609892091.mp3');
INSERT INTO `basic_word` VALUES (206, '/i/', '类似于英文中\"beet\"中的\'ee\'，在发这个音时嘴形呈窄小状态', 'fr', 'lit', '床', 1, 'src\\main\\resources\\MP3\\1723609892491.mp3');
INSERT INTO `basic_word` VALUES (207, '/o/', '接近英文中\"go\"的\'o\'，但通常发音更长', 'fr', 'eau', '水', 1, 'src\\main\\resources\\MP3\\1723609892887.mp3');
INSERT INTO `basic_word` VALUES (208, '/u/', '这个元音像英文中\"true\"的\'u\'，在发音时双唇呈现更圆的状态', 'fr', 'ou', '或者', 1, 'src\\main\\resources\\MP3\\1723609893292.mp3');
INSERT INTO `basic_word` VALUES (209, '/y/', '这个音介于[i]与[u]之间，是一种独特的法语元音', 'fr', 'tu', '你', 1, 'src\\main\\resources\\MP3\\1723609893657.mp3');
INSERT INTO `basic_word` VALUES (210, '/ɥ/', '这是另一个介于[i]和[u]之间的音，不同于[y]的是它发音时嘴部肌肉更为放松', 'fr', 'lune ', '月亮', 1, 'src\\main\\resources\\MP3\\1723609894139.mp3');
INSERT INTO `basic_word` VALUES (211, '/p/', '类似于英文中的“p”，但是法语中的爆破音较为轻微', 'fr', 'pomme', '苹果', 1, 'src\\main\\resources\\MP3\\1723609894557.mp3');
INSERT INTO `basic_word` VALUES (212, '/b/', '类似于英文中的“b”，但是法语中的爆破音较为轻微', 'fr', 'belle', '美丽', 1, 'src\\main\\resources\\MP3\\1723609894953.mp3');
INSERT INTO `basic_word` VALUES (213, '/t/', '类似英文中的“t”，在法语中这两个音也较为轻柔', 'fr', 'toute', '所有', 1, 'src\\main\\resources\\MP3\\1723609895331.mp3');
INSERT INTO `basic_word` VALUES (214, '/d/', '类似英文中的“d”，在法语中这两个音也较为轻柔', 'fr', 'déjeuner', '午餐', 1, 'src\\main\\resources\\MP3\\1723609895754.mp3');
INSERT INTO `basic_word` VALUES (215, '/k/', '类似英文中的“k”，但在法语中，这两个音的发音位置更靠后', 'fr', 'cou', '脖子', 1, 'src\\main\\resources\\MP3\\1723609896232.mp3');
INSERT INTO `basic_word` VALUES (216, '/g/', '类似英文中的“g”，但在法语中，这两个音的发音位置更靠后', 'fr', 'gilet', '背心', 1, 'src\\main\\resources\\MP3\\1723609896687.mp3');
INSERT INTO `basic_word` VALUES (217, '/f/', '类似于英文中的“f”', 'fr', 'fil', '线', 1, 'src\\main\\resources\\MP3\\1723609897019.mp3');
INSERT INTO `basic_word` VALUES (218, '/v/', '类似于英文中的“v”', 'fr', 'voix', '声音', 1, 'src\\main\\resources\\MP3\\1723609897496.mp3');
INSERT INTO `basic_word` VALUES (219, '/s/', '该发音与英语的“s”相似，但发音更为细腻', 'fr', 'sœur', '姐妹', 1, 'src\\main\\resources\\MP3\\1723609897932.mp3');
INSERT INTO `basic_word` VALUES (220, '/z/', '该发音与英语的“z”相似，但发音更为细腻', 'fr', 'zèle', '热情', 1, 'src\\main\\resources\\MP3\\1723610252789.mp3');
INSERT INTO `basic_word` VALUES (221, '/ʃ/', '类似英文中的“sh”，在法语中通过将舌头卷起来接触上腭发音', 'fr', 'chose', '事物', 1, 'src\\main\\resources\\MP3\\1723609903742.mp3');
INSERT INTO `basic_word` VALUES (222, '/ʒ/', '此音类似于[ʃ]，但振动声带，故为浊音', 'fr', 'genre', '种类', 1, 'src\\main\\resources\\MP3\\1723609904154.mp3');
INSERT INTO `basic_word` VALUES (223, '/r/', '别类似英文的“r”，但法语中的发音更为清晰', 'fr', 'rouge', '红色', 1, 'src\\main\\resources\\MP3\\1723609904558.mp3');
INSERT INTO `basic_word` VALUES (224, '/l/', '别类似英文的“l”，但法语中的发音更为清晰', 'fr', 'lit', '床', 1, 'src\\main\\resources\\MP3\\1723609904946.mp3');
INSERT INTO `basic_word` VALUES (225, '/m/', '与英文中的“m”相近', 'fr', 'mer', '海', 1, 'src\\main\\resources\\MP3\\1723609905379.mp3');
INSERT INTO `basic_word` VALUES (226, '/n/', '与英文中的“n”相近', 'fr', 'nuit', '夜晚', 1, 'src\\main\\resources\\MP3\\1723609905765.mp3');
INSERT INTO `basic_word` VALUES (227, '/ʁ/', '发音时舌尖卷起，抵住或接近上腭，声带振动，气流从舌两侧流出。', 'fr', 'rire', '笑', 1, 'src\\main\\resources\\MP3\\1723609906221.mp3');
INSERT INTO `basic_word` VALUES (228, '/w/', '类似于英文中“w”的音，但在法语中发音更为轻', 'fr', 'oui', '是的', 1, 'src\\main\\resources\\MP3\\1723609906602.mp3');
INSERT INTO `basic_word` VALUES (229, '/j/', '类似英文中的“y”，如“yes”', 'fr', 'yeux', '眼睛', 1, 'src\\main\\resources\\MP3\\1723609906997.mp3');
