INSERT INTO `word_list` VALUES (244, 3, ' 步行街', '步行街', '很抱歉，但目前我无法提供日语单词的词性、词义以及例句。此外，关于变形及其词义和例句的部分也同样需要进一步的资源或工具来查询和验证这些信息。如果你需要学习日语，我建议使用专业的日语学习资源或咨询日语教师以获取更准确的信息。如果有其他问题或需要帮助，请随时告诉我。', NULL, 0, NULL, 'src/main/resources/MP3/1720173400408.mp3');
INSERT INTO `word_list` VALUES (245, 3, ' 汽車', '汽车', '1.词性：名詞\n2.词义：自動車\n3.例句：\n   - 私は汽車で学校に行きます。 (我乘汽车去学校。)\n   - 汽車が街を走っています。 (汽车正在街上行驶。)\n\n变形及其词义：\n1. 汽車の形：名词，表示汽车的形状或样式。\n   例句：新しい汽車の形を見せてください。 (请给我看看新款汽车的样式。)\n\n2. 汽車に乗る：动词短语，表示乘坐汽车。\n   例句：毎日汽車に乗って出張します。 (每天乘坐汽车出差。)\n\n3. 汽車が走る：动词短语，表示汽车行驶。\n   例句：汽車が速く走っています。 (汽车正在快速行驶。)\n\n4. 汽車を運転する：动词短语，表示驾驶汽车。\n   例句：彼は五年間汽車を運転しています。 (他已经驾驶汽车五年了。)\n\n请注意，以上变形和例句是基于常见的日语使用习惯，实际上“汽車”这个词在现代日语中较少单独使用，更常见的是诸如“自動車”这样的词汇。', NULL, 0, NULL, 'src/main/resources/MP3/1720173400408.mp3');
INSERT INTO `word_list` VALUES (246, 3, ' 航空機', '飞机', '1.词性：名词\n2.词义：飞机\n3.例句：新しい航空機が空を飛びます。每天有许多飞机在机场起飞和降落。\n\n变形及其词义和例句：\n1. 自动词「空を飛ぶ」的名词形式，表示“飞行”的动作或状态。例句：鳥が空を飛んでいる。鸟儿在空中飞翔。\n2. 动词「航运する」的名词形式，表示“运输”的动作或状态。例句：この会社は航空機で荷物を航运しています。这家公司用飞机运送货物。\n3. 复合词「航空機操縦士」，表示驾驶飞机的人。例句：彼女は航空機操縦士であり、毎日安全に飛行させています。她是一名飞行员，每天都能安全地驾驶飞机。', NULL, 0, NULL, 'src/main/resources/MP3/1720173400926.mp3');
INSERT INTO `word_list` VALUES (247, 3, ' 船舶', '船只', '1.词性：名词\n2.词义：船只，船舶\n3.例句：\n   - 川には大きな船が浮かぶ。 (河里漂浮着一艘大船。)\n   - 船を漕ぐのが好きです。 (我喜欢划船。)\n\n变形及其词义：\n- 船を漕ぐ (动词，划船)\n  - 私は每週船を漕ぎます。 (我每周都会划船。)\n- 船乗り (名词，乘船的人)\n  - 船乗りは海の見える所に行きました。 (乘船的人去了一个可以看到海的地方。)\n- 船出 (名词，船只出发)\n  - 船出の時間は午前9時です。 (船只出发的时间是上午9点。)', NULL, 0, NULL, 'src/main/resources/MP3/1720173401265.mp3');
INSERT INTO `word_list` VALUES (248, 3, ' 交差点', '十字路口', '1. 词性：名词\n2. 词义：交差点指的是两条或多条道路在同一平面相交的地方，通常用于车辆和行人的通行。\n3. 例句：\n   - この交差点を右に曲がると、郵局が見えます。\n   - 信号が赤になったら、交差点を渡る前に車を停めてください。\n\n由于“交差点”是一个名词，它没有变形。不过，如果你想了解与“交差点”相关的词汇，可以考虑“十字路”（十字路口），这是一个特定的类型的交差点，其中两条道路以直角相交。\n\n对于“十字路”（十字路口）：\n1. 词性：名词\n2. 词义：十字路是指两条道路以直角相交形成的路口。\n3. 例句：\n   - この十字路を通り過ぎると、映画館が右手にあります。\n   - 昨夜、その十字路で交通事故が発生しました。', NULL, 0, NULL, 'src/main/resources/MP3/1720173401597.mp3');
INSERT INTO `word_list` VALUES (249, 3, ' 道路', '道路', '1.词性：名词\n2.词义：道、路\n3.例句：\n- この道路は市街を南北に貫く。(这条道路贯穿市中心南北。)\n- 雨の日は道路が濡れる。(下雨天道路会湿。)\n\n变形及词义：\n- 道路(どうろ):名词，意为道路、路。例句：学校の前に道路がある。(学校前面有一条道路。)\n- 道(みち):名词，意为路、道路。例句：山の中で迷子になったら危険だ。(在山里迷路很危险。)\n- 路地(ろじ):名词，意为小巷、胡同。例句：古い路地を通り抜けば、昔の風景が見える。(穿过古老的小巷，可以看到过去的风景。)', NULL, 0, NULL, 'src/main/resources/MP3/1720173401933.mp3');
INSERT INTO `word_list` VALUES (250, 3, ' 自行車', '自行车', '1. 词性：名詞\n2. 词义：自行車（じどうしゃ）是指不依靠畜力或人力推动，通过骑者脚踏驱动轮子转动的两轮交通工具。\n3. 例句：\n   - 私は每朝自行車で学校に行きます。(我每天早晨骑自行车去学校。)\n   - 雨が降っているので、自行車を貸してもらえますか？(下雨了，能借给我一辆自行车吗？)\n\n所有的变形及其词义：\n- 自行車（じどうしゃ）：如上所述，指自行车本身。\n  - 例文：この自行車は新しく、まだ全然使われていません。(这辆自行车是新的，还没怎么被使用过。)\n\n目前“自行車”这个名词没有其他常见的变形，它本身就是一个固有名词，用来专指自行车这类交通工具。在日本语中，名词通常保持原形不变，不像动词、形容词那样有复杂的活用形变化。', NULL, 0, NULL, 'src/main/resources/MP3/1720173402276.mp3');
INSERT INTO `word_list` VALUES (251, 3, ' 速度限制', '速度限制', '1.词性：名词\n\n2.词义：速度限制（そくどげんし）是指对车辆等移动物体在特定路段或区域内所能达到的最高或最低速度进行的限制。\n\n3.例句：\n- この道路は速度限制があります。(这条路有速度限制。)\n- 速度限制を守っていますか？(你在遵守速度限制吗？)\n\n4.变形及其词义：\n- 速度制限 (そくどせいげん)：名词，意为“速度限制”。\n  例：速度制限を緩める。(放宽速度限制。)\n\n- 速度制限解除 (そくどせいげんかいじょ)：名词，意为“解除速度限制”。\n  例：速度制限解除により、道が安全になりました。(由于解除了速度限制，道路变得更安全了。)\n\n- 速度制限違反 (そくどせいげんいひょう)：名词，意为“违反速度限制”。\n  例：速度制限違反により、罰金を納められました。(因为违反了速度限制，我不得不支付罚款。)\n\n请注意，以上信息是基于日语的一般用法提供的，并且可能存在地区差异或特殊用法。', NULL, 0, NULL, 'src/main/resources/MP3/1720173402513.mp3');
INSERT INTO `word_list` VALUES (252, 3, ' 火車', '火车', '1.词性：名詞\n2.词义：鉄道の車両。列車。\n3.例句：\n- 火車が到着した。\n- 火車に乗って出張する。\n\n變形とその意味：\n- 火車（かしゃ）： 鉄道の車両。列車。\n  - 例句：火車が到着した。\n- 火車の形（かしゃのけい）： 火車の形状。\n  - 例句：新しい火車の形を見た。\n- 火車運転手（かしゃうんてんしゅ）： 火車の運転者。\n  - 例句：火車運転手になりたい。', NULL, 0, NULL, 'src/main/resources/MP3/1720173402874.mp3');
INSERT INTO `word_list` VALUES (253, 3, ' 車庫', '车库', '1. 词性：名詞 (名词)\n2. 词义：車庫とは、自転車や自動車などの乗り物を保管するための建物または場所である。 (车库是指用来存放自行车或汽车等交通工具的建筑物或场所。)\n3. 例句：私は家の車庫に自転車を置いている。 (我把自行车放在家里的车库里。)\n   車庫には多くの車が並んでいる。 (车库里停着很多车。)\n\n4. 变形及其词义和例句：\n   - 車庫にある (在车库里)：表示某物存在于车库的状态。\n     例文：この車は車庫にある。 (这辆车在车库里。)\n   - 車庫から出る (从车库出来)：表示从车库中移动出来的动作。\n     例文：彼は車庫から車を出した。 (他从车库开车出来了。)\n   - 車庫を使う (使用车库)：表示使用车库的行为。\n     例文：私は車庫を使って、車を保管する。 (我使用车库来存放车。)\n   - 車庫に入る (进入车库)：表示进入车库的动作。\n     例文：彼は車庫に入って、車を見に行った。 (他进入车库去看车了。)', NULL, 0, NULL, 'src/main/resources/MP3/1720173403112.mp3');
INSERT INTO `word_list` VALUES (254, 3, ' 出租車', '出租车', '1.词性：名词\n2.词义：出租车，即可以出租的汽车。\n3.例句：\n- 電車が遅れているので、急いで出租車に乗った。\n  - 翻译：因为电车晚点了，我急忙打了一辆出租车。\n- 空港まで出租車で行きましょうか。\n  - 翻译：我们打车去机场吧。\n\n变形及其词义：\n- 「出租」（动词）：出租，出借\n  - 例句：家を外国人に出租しました。\n    - 翻译：我把房子租给了外国人。\n- 「車」（名词）：汽车或车辆\n  - 例句：新しい車を買いました。\n    - 翻译：我买了辆新车。\n\n注意：日语中的单词「出租車」本身不发生变形，但构成它的词语可以有各自的变形和用法，如上所示。', NULL, 0, NULL, 'src/main/resources/MP3/1720173403406.mp3');
INSERT INTO `word_list` VALUES (255, 3, ' 軌道', '轨道', '.词1性：名詞\n2.词义：物体运动的路径或者天体运行的路径。\n3.例句： \n   - 地球は太陽を中心にして一定の軌道を描いて回ります。 (地球以太阳为中心，沿着一定的轨道旋转。)\n   - 新幹線は高速鉄道の軌道を走っています。 (新干线在高速铁路的轨道上行驶。)\n\n变形及其词义：\n- 軌道（きどう）： 名词，如上所述，指的是物体运动的路径或者天体运行的路径。\n- 軌道に沿って (きどうにそて): 沿着轨道。例：列車は軌道に沿って走り続けています。(列车沿着轨道继续前行。)\n- 軌道が外れる (きどうがはずれる): 偏离轨道。例：飛行機が軌道が外れた場合、大きな危険に直面します。(如果飞机偏离了轨道，就会面临巨大的危险。)\n\n请注意，日语中的词汇变形和词义可能因语境而有所不同，以上是基于一般情况的解释。', NULL, 0, NULL, 'src/main/resources/MP3/1720173403767.mp3');
INSERT INTO `word_list` VALUES (256, 3, ' 高速道路', '高速公路', '1.词性：名词\n2.词义：高速道路是指专为快速通行设计的道路，通常指的是高速公路。\n3.例句：\n   - 私は毎日高速道路上で通ることがあります。 (我每天都会在高速公路上行驶。)\n   - 高速道路を利用すると、時間を節約できます。 (使用高速公路可以节省时间。)\n\n变形及其词义：\n- 高速道路に行く (前往高速公路)\n   - 私は明日高速道路に行く予定です。 (我计划明天去高速公路。)\n- 高速道路から降りる (从高速公路下来)\n   - 家に着く前に、高速道路から降ります。 (在到家之前，我会从高速公路下来。)\n- 高速道路を利用する (使用高速公路)\n   - 長距離旅行の際、高速道路を利用することが多いです。 (长途旅行时，经常使用高速公路。)\n\n请注意，以上提供的是基础信息和示例句子，具体的用法和例句可能会根据实际语境和需求有所不同。', NULL, 0, NULL, 'src/main/resources/MP3/1720173404025.mp3');
INSERT INTO `word_list` VALUES (257, 3, ' 交通標識', '交通标识', '1.词性：名词\n2.词义：交通标识是指设置在道路沿线或交叉口，用于指示交通流向、警告危险情况或提供其他信息的标志。\n3.例句：\n   - 信号灯は交通標識の一種である。(信号灯是交通标识的一种。)\n   - この交差点には多くの交通標識が設けられている。(在这个交叉路口有许多交通标识被设置。)\n\n变形及其词义：\n- 交通标识（交通标识）：同上，指道路上的各类标志。\n   例句：学校の近くには速さを制限する交通标识がある。(学校附近有限制速度的交通标识。)\n  \n目前“交通标識”这个词汇没有其他常见的变形。如果需要更多信息，建议查阅专业的日语词典或咨询日本语专家。', NULL, 0, NULL, 'src/main/resources/MP3/1720173404369.mp3');
INSERT INTO `word_list` VALUES (258, 3, ' 駐車場', '停车场', '1. 词性：名词\n2. 词义：停车场，指供车辆停放的场所。\n3. 例句：\n   - この駐車場はいつも混んでいます。\n   - 私は家の近くに駐車場を探しています。\n\n变形及词义：\n- 駐車場にする（动词）：将某处作为停车场使用。例句：この空地を駐車場にしましょう。\n- 駐車場がない（形容词）：没有停车场。例句：この辺りに駐車場がないんですね。\n- 駐車場を探す（动词）：寻找停车场。例句：駐車場を探しています。\n- 駐車場が必要だ（形容词）：需要停车场。例句：駐車場が必要ですね。', NULL, 0, NULL, 'src/main/resources/MP3/1720173404724.mp3');
INSERT INTO `word_list` VALUES (259, 3, ' 巴士', '公共汽车', '1性：名词.词\n2.词义：巴士（公共汽车）\n3.例句：\n   - 学校に行く時、バスで行きます。(去学校时，我坐公交车去。)\n   - 週末には、市内を觀光するためにバスを利用します。(周末为了观光市内，我会使用公交车。)\n4.变形及词义：没有特定的变形形式，但可以与其他词搭配形成复合词或短语。\n5.每个变形一个例句：由于“巴士”这个词在日语中没有直接的变形，所以无法提供相应的例句。不过，可以使用与“巴士”相关的短语或句子来展示其用法。\n   - バス停：公交车站（Bus stop）\n     例句：このバス停でバスを降ります。(我在这家公交车站下车。)\n   - バス通り：公交路线（Bus route）\n     例句：この道は重要なバス通りです。(这条路是一条重要的公交线路。)\n请注意，以上提供的例句是基于“巴士”这个词的基本意义和用法，实际上在日语中可能存在更多的用法和搭配。', NULL, 0, NULL, 'src/main/resources/MP3/1720173404993.mp3');
INSERT INTO `word_list` VALUES (260, 3, ' 信号', '信号', '1.词性：名词\n2.词义：信号，标志\n3.例句：\n   - 信号が赤になったので、道を渡ることができません。 (由于信号灯变红，无法过马路。)\n   - 彼は友達に信号を送りました。(他给朋友发送了一个信号。)\n\n变形及其词义：\n- 信号機 (しんごうき)：信号灯，例句：十字路の信号機が故障しています。(十字路口的信号灯出现了故障。)\n- 信号塔 (しんごうとう)：信号塔，例句：海辺にある信号塔が夜でも見える。(海边的信号塔即使在夜晚也能看见。)\n- 信号柱 (しんごうちゅう)：信号柱，例句：道路の側に設置された信号柱は交通ルーを示しています。(路边设置的信号柱正在指示交通路线。)', NULL, 0, NULL, 'src/main/resources/MP3/1720173405280.mp3');
INSERT INTO `word_list` VALUES (261, 3, ' 電車', '电车', '1. 词性：名词\n2. 词义：電車（でんしゃ）在日语中意味着“电车”，是城市和近郊交通的一种方式。\n3. 例句：\n   - 毎日電車に乗って通勤します。 (Mainichi densha ni notte tsūkin suru.) - 我每天乘电车上下班。\n   - 電車が遅刻している。 (Densha ga chikkushi te iru.) - 电车晚点了。\n\n4. 变形及其词义和例句：\n   - 電車の (densha no)：表示属于或与电车有关的，用作定语。\n     例句：電車の中で本を読んでいた。(Densha no naka de hon o yonde ita.) - 我在电车里看书。\n   - 電車で (densha de)：表示手段或方法，意为“通过电车”。\n     例句：私は電車で仕事場に行きます。(Watashi wa densha de shigoto ba ni ikimasu.) - 我乘电车去工作地点。\n   - 電車に (densha ni)：表示目的地或方向，意为“到电车”。\n     例句：この駐車場は電車に便利です。(Kono chūshajō wa densha ni benri desu.) - 这个停车场到电车很方便。', NULL, 0, NULL, 'src/main/resources/MP3/1720173405280.mp3');
INSERT INTO `word_list` VALUES (262, 3, ' 交通灯', '交通灯', '1.词性：名词\n2.词义：交通信号灯，特指用于控制交通流的红绿灯。\n3.例句：\n- 交叉点には新しい交通灯が設置されています。 (在十字路口设置了新的交通灯。)\n- 交通灯が赤に変わったので、車を停めました。 (因为交通灯变红了，所以我把车停了下来。)\n\n变形及词义：\n- 交通灯の：形式名词「の」与「交通灯」结合，表示所属关系。\n  - 例句：この交差点の交通灯はとても機能的です。 (这个交叉点的交通灯非常有效。)\n- 交通灯を：宾格形式的「交通灯」，表示动作的对象。\n  - 例句：警察は交通灯を点検しています。 (警察正在检查交通灯。)\n- 交通灯が：主格或描述体状态的「交通灯」。\n  - 例句：交通灯が故障しているので、注意してください。 (由于交通灯出现故障，请注意。)\n  \n请注意，日语中名词通常不变形，而是通过助词来表达不同的语法功能。以上是根据上下文可能使用的几种情况。', NULL, 0, NULL, 'src/main/resources/MP3/1720173405884.mp3');
INSERT INTO `word_list` VALUES (263, 3, ' 行人', '行人', '1.词性：名词\n2.词义：行人（指的是走路的人，尤指城市中步行的人）\n3.例句：\n   - 街角には多くの行人が通行しています。\n     （在街角有许多行人通过。）\n   - 大雨で行人が少なくなった。\n     （因为大雨，行人变少了。）\n\n变形及其词义：\n- 行人间（行人之间）：この交差点では、行人间の安全を考虑して信号を导入しました。\n  （这个十字路口考虑到了行人之间的安全，引入了交通灯。）\n- 行人用（供行人使用的）：道路の两侧には行人用の步道が设けられています。\n  （道路两侧设置了供行人使用的人行道。）\n\n目前“行人”这个词在日语中没有更多的变形形式，它通常作为一个普通名词使用，描述的是行走的人们，特别是在城市街道上的步行者。', NULL, 0, NULL, 'src/main/resources/MP3/1720173406277.mp3');
INSERT INTO `word_list` VALUES (264, 31, ' ダムスポーツ ', ' dumbbell sports', '1. 词性：名词\n2. 词义：ダムスポーツ（Damusupōto）是指一种运动，通常是指美式足球。\n3. 例句：\n   - 私はアメリカンフットボーライの大好きで、よくダムスポーツを見る。\n     （我非常喜欢美式足球，经常看比赛。）\n   - ダムスポーツが好きですか？最近の試合を見ましたか？\n     （你喜欢美式足球吗？有看最近的赛事吗？）\n\n变形及词义：\n- ダムスポーツに関心を持っています。（我对美式足球感兴趣。）\n- ダムスポーツの試合を観戦するのが楽しいです。（观看美式足球比赛很有趣。）\n- ダムスポーツの選手が大好きです。（我非常喜欢美式足球的运动员。）\n\n请注意，\"ダムスポーツ\"是一个专有名词，表示特定的运动项目，因此它本身并没有变形。以上提供的是包含该词的例句，展示了如何在句子中使用这个词。', NULL, 0, NULL, 'src/main/resources/MP3/1720173406544.mp3');
INSERT INTO `word_list` VALUES (265, 31, ' サッカー ', ' soccer', '1.词性：名词\n2.词义：足球\n3.例句：\n- 「サッカーが大好きです。」（我喜欢足球。）\n- 「サッカーの試合を見ました。」（我看了足球比赛。）\n4.变形：无变形\n5.其他相关单词：\n- サッカーボール（足球）\n- サッカー場（足球场）\n- サッカー選手（足球运动员）', NULL, 0, NULL, 'src/main/resources/MP3/1720173406875.mp3');
INSERT INTO `word_list` VALUES (266, 31, ' スポーツジャンル ', ' sports genre', '1.词性：名词\n2.词义：体育杂志\n3.例句：\n  - 私は最近スポーツジャンルをよく読んでいる。(我最近经常阅读体育杂志。)\n  - スポーツジャンルの最新号が出たので買いました。(体育杂志的最新一期已经出版，所以我买了。)\n\n变形及其词义：\n- スポーツジャンルの：体育杂志的（形容词用法）\n  例：スポーツジャンルの記事を読んで、野球の試合に興味を持ってきた。(读了体育杂志的文章后，我对棒球比赛产生了兴趣。)\n- スポーツジャンルだ：是体育杂志（断定用法）\n  例：これはスポーツジャンルだ。(这是体育杂志。)\n- スポーツジャンルを：把体育杂志（宾格用法）\n  例：友達がスポーツジャンルを貸してくれた。(朋友借给我体育杂志。)', NULL, 0, NULL, 'src/main/resources/MP3/1720173407134.mp3');
INSERT INTO `word_list` VALUES (267, 31, ' スポーツアクション ', ' sports action', '1.词性：名词\n2.词义：体育赛事\n3.例句： \n   - 今年のスポーツアクションは何時からなん時までですか。\n   - 昨年、私はスポーツアクションに参加して、たくさんの人と出会えた。\n\n变形及词义：\n- スポーツアクションに参加する：参加体育赛事\n  - 例：来週、私はローライのスポーツアクションに参加するつもりです。\n\n- スポーツアクションを見る：观看体育赛事\n  - 例：昨日、私はテレビでスポーツアクションを見ました。\n\n- スポーツアクションがある：有体育赛事\n  - 例：来月、私たちの学校には大きいスポーツアクションがあります。', NULL, 0, NULL, 'src/main/resources/MP3/1720173407495.mp3');
INSERT INTO `word_list` VALUES (268, 31, ' テニス ', ' tennis', '1. 词性：名词\n2. 词义：网球\n3. 例句：\n   - 私はテニスが好きです。(我喜欢打网球。)\n   - 毎周日にテニスをします。(我每周日都打网球。)\n\n变形及其词义：\n- テニスがいいです。(网球很好。)\n- テニスをやったのは誰？(谁在打网球？)\n- テニスが大好きです。(我非常喜欢网球。)', NULL, 0, NULL, 'src/main/resources/MP3/1720173407770.mp3');
INSERT INTO `word_list` VALUES (269, 31, ' スポーツマネー ', ' sportsmanship', '1. 词性：名词\n2. 词义：体育经理，负责管理体育相关事务的人。\n3. 例句：\n   - スポーツマネーは試合の計画と運営を担当します。\n   - 私が夢を追うのを支えてくれたスポーツマネーに感謝します。\n\n变形及词义：\n- このスポーツマネーは経験豊富で、多くの大会を成功裏に導いた。\n  - この体育经理经验丰富，成功地指导了许多大赛。\n- 彼女はスポーツマネーとして活躍し、多くの新鋭選手を発掘しました。\n  - 她作为体育经理活跃，发掘了许多新秀选手。', NULL, 0, NULL, 'src/main/resources/MP3/1720173408028.mp3');
INSERT INTO `word_list` VALUES (270, 31, ' フットボルト ', ' weightlifting', '1. 词性：名词（名詞）\n2. 词义：足球（soccer ball）\n3. 例句：\n   - フットボルトを蹴るのが好きです。 (我喜欢踢足球。)\n   - 新しいフットボルトを買いました。 (我买了一个新的足球。)\n\n变形及其词义和例句：\n- 原型：フットボルト (足球)\n  - 例句：フットボルトを使ってゲームを始めましょう。 (让我们用足球开始比赛吧。)\n- 连用形：通常不用于修饰，但可以作为复合词的一部分。\n  - 例句：（无明显连用形例句，因为名词通常不这样使用）\n- 终止形：与原型相同，表示句子的结束。\n  - 例句：こんなフットボルトが欲しいですか？ (你想要什么样的足球？)\n- 连体形：与原型相同，用来修饰名词。\n  - 例句：フットボルトがなくなってしまいました。 (足球不见了。)\n- 假定形：通常不用于名词。\n  - 例句：（名词没有假定形）\n- 命令形：通常不用于名词。\n  - 例句：（名词没有命令形）\n\n由于“フットボルト”是一个名词，它没有动词那样的变形。上述解释主要围绕名词的使用情境进行说明，而不是变形，因为名词在日语中不像动词那样具有多种变形。', NULL, 0, NULL, 'src/main/resources/MP3/1720173408405.mp3');
INSERT INTO `word_list` VALUES (271, 31, ' プロスポーツ ', ' professional sports', '1.词性：名詞\n2.词义：プロフェッショナル スポーツ，即“职业运动”。\n3.例句：\n- 私は小さい頃からプロスポーツを見るのが大好きです。\n- 彼はプロスポーツに夢中になって、毎日の訓練を欠かさず。\n\n变形及其词义和例句如下：\n\n- プロアスリート (名词)：职业运动员\n  - 例：彼女は若くしても、すでにプロアスリートとして活躍しています。\n\n- プロゲーム (名词)：职业比赛\n  - 例：今週は多くのプロゲームがテレビで中継されています。\n\n- プロデュエル (名词)：职业教练\n  - 例：あの選手は天才的だと言われ、その背中には優秀なプロデュエルがいる。\n\n请注意，日语中通常不会像上述这样直接从\"プロスポーツ\"派生出其他单词，而是将\"プロ\"作为前缀与其他体育相关词汇结合使用，表示“职业”的意思。上述派生词是假设性的，为了回答你的问题而构造的，实际上可能并不常用或根本不存在。', NULL, 0, NULL, 'src/main/resources/MP3/1720173408672.mp3');
INSERT INTO `word_list` VALUES (272, 31, ' スポーツウォーカー ', ' sports watch', '1. 词性：名词\n2. 词义：体育工作者\n3. 例句：\n   - スポーツウォーカーは運動選手のために労力を尽くします。\n     （体育工作者为运动员们竭尽全力。）\n   - 私の兄は小学校でスポーツウォーカーを務めています。\n     （我的哥哥在小学担任体育老师。）\n\n变形及其词义：\n- スポーツウォーカーになる（成为体育工作者）\n  - 例：彼は子供の頃からスポーツをやり、今はスポーツウォーカーになっています。\n    （他从孩提时代就从事体育活动，现在是体育工作者。）\n- スポーツウォーカーとして（作为体育工作者）\n  - 例：スポーツウォーカーとして、彼は多くの学生に対して運動の重要性を教えています。\n    （作为一名体育工作者，他向许多学生传授运动的重要性。）\n- スポーツウォーカーだ（是体育工作者）\n  - 例：私の父はスポーツウォーカーだ、毎日運動場で活躍しています。\n    （我的父亲是体育工作者，每天都在运动场上活跃着。）\n\n请注意，由于日语的语法和表达方式与中文不同，直接翻译可能不完全符合日语习惯，但上述例子应能正确传达相应的意思。', NULL, 0, NULL, 'src/main/resources/MP3/1720173409003.mp3');
INSERT INTO `word_list` VALUES (273, 31, ' キレーン ', ' cycling', '1.词性：外来語（名词）\n2.词义： キレート（德语“Kärntner”、英语“Carinthia”）の略。アウストライア州の名。\n3.例句： キレーンは美しい景色がある。\n4.变形：无\n5.例句：无法提供，因为该单词没有变形。', NULL, 0, NULL, 'src/main/resources/MP3/1720173409372.mp3');
INSERT INTO `word_list` VALUES (274, 31, ' スポーツヘルパー ', ' sports helper', '1.词性：名词\n2.词义：体育助理员，体育教练\n3.例句：\n- 私はスポーツヘルパーです。 (我是体育助理员。)\n- 彼女は小さい頃からスポーツヘルパーを目指していました。 (她从小就立志成为一名体育助理员。)\n\n变形及其词义：\n- スポーツヘルパーになる：成为体育助理员\n例句：大学を卒業すると、彼はスポーツヘルパーになりました。 (大学毕业后，他成为了一名体育助理员。)\n\n- スポーツヘルパーとしまう：成为体育助理员\n例句：彼女は夢を実現して、スポーツヘルパーとしました。 (她实现了梦想，成为了一名体育助理员。)\n\n- スポーツヘルパーだ：是体育助理员\n例句：彼は若い頃からスポーツヘルパーだった。 (他年轻时就是一名体育助理员。)', NULL, 0, NULL, 'src/main/resources/MP3/1720173409610.mp3');
INSERT INTO `word_list` VALUES (275, 31, ' ランニング ', ' running', '1. 词性：名词（Noun）\n2. 词义：跑步，赛跑\n3. 例句：\n   - 私は週に二回ランニングをする。(我每周跑步两次。)\n   - 彼女は高校のランニング部の選手である。(她是高中田径队的跑步选手。)\n\n变形及词义：\n- ランネー（Runner）：跑步者，赛跑者\n  例：彼は優れたランネーである。(他是一名优秀的跑步者。)\n- ランニングマット（Running mate）：跑步伴侣，赛跑搭档\n  例：私たちは彼此のランニングマットである。(我们是彼此的跑步伴侣。)\n- ランニング履き（Running shoes）：跑步鞋\n  例：新しいランニング履きを買いました。(我买了一双新的跑步鞋。)', NULL, 0, NULL, 'src/main/resources/MP3/1720173409977.mp3');
INSERT INTO `word_list` VALUES (276, 31, ' スポーツチャンピオン ', ' sports champion', '1. 词性：名词\n2. 词义：体育冠军\n3. 例句：\n   - 彼はスポーツチャンピオンになりたがっています。\n   - スポーツチャンピオンは厳しい訓練を受けました。\n\n变形及其词义，每个变形一个例句：\n- スポーツチャンピオン（名词）：体育冠军\n   - 例句：スポーツチャンピオンは厳しい訓練を受けました。\n- スポーツチャンピオンになる（动词）：成为体育冠军\n   - 例句：彼女は夢であって、スポーツチャンピオンになりたいです。\n- スポーツチャンピオンだ（形容词）：是体育冠军\n   - 例句：彼はスポーツチャンピオンだと言われています。', NULL, 0, NULL, 'src/main/resources/MP3/1720173410235.mp3');
INSERT INTO `word_list` VALUES (277, 31, ' バドミントン ', ' badminton', '1.词性：名词\n2.词义：羽毛球\n3.例句： \n   - 私はバドミントンが好きです。(我喜欢打羽毛球。)\n   - バドミントンをして、健康を保つためにはどうぞよろしくお願いします。(为了保持健康，请务必和我一起打羽毛球。)\n\n所有的变形及其词义：\n\n1. バドミントンをやる (玩羽毛球)\n   - 私たちはバドミントンをやりました。(我们玩了羽毛球。)\n\n2. バドミントンが大好き (非常喜欢羽毛球)\n   - 彼はバドミントンが大好きです。(他非常喜欢羽毛球。)\n\n3. バドミントンの試合 (羽毛球比赛)\n   - 来週、バドミントンの試合を見に行きます。(下周我要去看羽毛球比赛。)\n\n4. バドミントン部 (羽毛球俱乐部)\n   - 私はバドミントン部に参加しました。(我加入了羽毛球俱乐部。)', NULL, 0, NULL, 'src/main/resources/MP3/1720173410578.mp3');
INSERT INTO `word_list` VALUES (278, 31, ' スポーツ ', ' sports', '1.词性：名词\n2.词义：运动\n3.例句：\n- 私はよくスポーツをする。(我常常做运动。)\n- スポーツが好きです。(我喜欢运动。)\n\n变形及词义：\n- 动词形式：運動する（うんどうする）\n  - 例文：私は毎日運動をします。(我每天都做运动。)\n- 形容词形式：運動的（うんどうてき）\n  - 例文：この学校は運動的な環境を提供しています。(这所学校提供了一个有利于运动的环环境。)\n- 名词形式：運動員（うんどういん）\n  - 例文：彼はオリンピックに出場する運動員です。(他是一位参加奥运会的运动员。)', NULL, 0, NULL, 'src/main/resources/MP3/1720173410848.mp3');
INSERT INTO `word_list` VALUES (279, 31, ' バレーボール ', ' volleyball', '1. 词性：名词\n2. 词义：排球（バレーボール）是指一种在室内进行的团队运动，两队通过一个网分开，通过手或手臂将球打向对方场地以得分。\n3. 例句：\n   - 私はバレーボールが大好きで、毎周プラクティスに参加します。\n   - 高校では、バレーボール部に加入して、每日練習をしています。\n\n变形及词义：\n- バレー (名词): 排球场上的一个位置，通常指攻击手的位置。\n  - 例句：彼女はバレーのポジションで活躍しています。\n- ボール (名词): 通常指球类游戏中使用的球。\n  - 例句：試合に出場する前に、ボールを充气する必要があります。', NULL, 0, NULL, 'src/main/resources/MP3/1720173411127.mp3');
INSERT INTO `word_list` VALUES (280, 31, ' ジュニアスポーツ ', ' junior sports', '1.词性：名詞（名词）\n2.词义：青少年運動（青少年体育）\n3.例句： \n   - 彼は小学校にいたる時、ジュニアスポーツクラブに加入しました。\n   - この学校では、ジュニアスポーツの推進を目的としています。\n4.变形及词义：无相关变形，该单词为复合词构成，由“ジュニア”（junior，青少年）和“スポーツ”（sports，体育）组成，整体表示“青少年运动”或“青少年体育”，没有进一步的变形。\n\n请注意，日语中的词汇变形通常指的是动词、形容词等词性的活用变化，而名词一般不涉及变形问题，所以对于复合名词“ジュニアスポーツ”，我们不讨论其变形。', NULL, 0, NULL, 'src/main/resources/MP3/1720173411472.mp3');
INSERT INTO `word_list` VALUES (281, 31, ' スポーツセンター ', ' sports center', '1. 词性：名词\n2. 词义：体育馆，体育中心\n3. 例句：\n   - 私は毎日スポーツセンターで運動をします。(我每天在体育中心运动。)\n   - 明日、スポーツセンターに行ってバスケットボールをしましょう。(明天我们去体育中心打篮球吧。)', NULL, 0, NULL, 'src/main/resources/MP3/1720173411798.mp3');
INSERT INTO `word_list` VALUES (282, 31, ' スポーツチューム ', ' sports club', '1. 词性：名词\n2. 词义：运动中心，体育馆\n3. 例句：\n   - 私は毎日スポーツチュームに行って運動をする。(我每天都去运动中心做运动。)\n   - スポーツチュームには多くの種類の運動器具があります。(运动中心有很多种类的运动器材。)\n\n变形及其词义：\n- スポーツチュームで (场所副词)：在运动中心\n  - 例文：私はスポーツチュームでテニスをします。(我在运动中心打网球。)\n\n- スポーツチュームに (方向副词)：向运动中心\n  - 例文：私は友達と一緒にスポーツチュームに行きます。(我和朋友一起去运动中心。)\n\n- スポーツチュームを (对象副词)：把运动中心作为对象\n  - 例文：私たちはスポーツチュームを利用して健康を保つために運動をします。(我们利用运动中心来保持健康。)', NULL, 0, NULL, 'src/main/resources/MP3/1720173412103.mp3');
INSERT INTO `word_list` VALUES (283, 31, ' サイクリング ', ' skating', '1. 词性：名词 (名詞)\n2. 词义：自転車に乗って走ること。自転車を利用した運動。\n3. 例句：\n   - 私は每週サイクリングをします。\n   - サイクリングが大好きです。\n\n变形及其词义：\n- サイクリスト (サイクリスト): 自転車の乗り手。自転車選手。\n  - 例句：彼は優れたサイクリストだ。\n- サイクリングアセンブラー (サイクリングアセンブラー): 自転車の組立工。自転車の調整師。\n  - 例句：彼女は才能を発揮して、サイクリングアセンブラーとなった。\n- サイクリングマップ (サイクリングマップ): 自転車用の路線図。\n  - 例句：出発前に必ずサイクリングマップを確認する。\n- サイクリングショップ (サイクリングショップ): 自転車を売り、修理する店舗。\n  - 例句：新しい自転車を買うためにサイクリングショップに行った。', NULL, 0, NULL, 'src/main/resources/MP3/1720173412403.mp3');
INSERT INTO `word_list` VALUES (284, 32, ' 料理', 'dish', '1.词性：名詞（名词）\n2.词义：食物、菜肴、烹饪、料理方法\n3.例句：\n   - 私は中華料理が好きです。(我喜欢中国菜。)\n   - 彼女は家庭料理が上手です。(她擅长做家常菜。)\n\n变形及其词义：\n- 料理人（りょうりにん）：厨师，例句：彼は有名な料理人です。(他是一位有名的厨师。)\n- 料理店（りょうりてん）：餐馆，例句：近くに新しい料理店が開いた。(附近开了一家新的餐馆。)\n- 料理科（りょうりか）：烹饪专业，例句：私の妹は学校の料理科を選びました。(我的妹妹选择了学校的烹饪专业。)\n- 料理教室（りょうりきょうしつ）：烹饪课程，例句：今度の土曜日、私は料理教室に参加します。(这个星期六，我将参加一个烹饪课程。)', NULL, 0, NULL, 'src/main/resources/MP3/1720173412687.mp3');
INSERT INTO `word_list` VALUES (285, 32, ' 食事指導', 'dietary guidance', '1.词性：名詞\n2.词义：食事指導は、健康のために食事を取る方法や内容を教えること。また、その指導をする人。\n3.例句：私は最近、營養士のアドバイスを受けています。食事指導により、健康に貢献できました。\n4.变形及其词义：\n   - 食事指導者（しょくじしどうしゃ）：食事指導をする人。例：私は大学で食事指導者として活動しています。\n   - 食事指導法（しょくじしどうほう）：食事指導に関連する法律。例：新しい食事指導法が成立しました。\n   - 食事指導的（しょくじしどうてき）：食事指導に関連する性質や特徴。例：この本は食事指導的な知識を提供しています。', NULL, 0, NULL, 'src/main/resources/MP3/1720173412964.mp3');
INSERT INTO `word_list` VALUES (286, 32, ' 食材', 'ingredient', '1.词性：名词\n2.词义：食材是指用于烹饪的各种原料，包括蔬菜、肉类、海鲜、豆类、谷物等。\n3.例句：\n- このレシピではどんな食材が必要ですか？这个食谱需要哪些食材？\n- 食材を買う前に、冷藏庫をチェックしてほしい。在购买食材之前，请先检查一下冰箱。\n\n变形及其词义：\n- 食材たる（名词）：表示“作为食材的”，例如：食材たる野菜（作为食材的蔬菜）\n- 食材とする（动词）：表示“将……视为食材”，例如：この果物を食材とする（将这种水果视为食材）\n- 食材にする（动词）：表示“使……成为食材”，例如：この肉を食材にする（使这块肉成为食材）', NULL, 0, NULL, 'src/main/resources/MP3/1720173413309.mp3');
INSERT INTO `word_list` VALUES (287, 32, ' 食事枠', 'meal time', '1. 词性：名词\n2. 词义：饮食时间、用餐时间段\n3. 例句：\n   - 私の食事枠は朝8時から午前9時までです。(我的饮食时间是上午8点到9点。)\n   - 学校にいるとき、食事枠は必ず守らなくてはなりません。(在学校时，必须遵守饮食时间。)\n\n变形及其词义：\n- 食事枠に (在饮食时间段内)：この店は食事枠にしか開かない。(这家店只在饮食时间段内营业。)\n- 食事枠を (按照饮食时间段)：私は毎日食事枠を守っています。(我每天都按照饮食时间段进食。)\n- 食事枠が (饮食时间段是)：明日の食事枠は何時から始まりますか？(明天的饮食时间段从什么时候开始？)', NULL, 0, NULL, 'src/main/resources/MP3/1720173413621.mp3');
INSERT INTO `word_list` VALUES (288, 32, ' 食事代行', 'catering', '1.词性：名词\n2.词义：代替别人吃饭的行为。\n3.例句：\n   - 私は忙しくて友達に食事代行を頼んだ。\n   - (我太忙了，所以请朋友代为吃饭。)\n\n4.变形及其词义：\n   - 食事代行する（动词）：进行食事代行的行为。\n     - 例：私は友達に食事代行してもらった。\n   - 食事代行について（关于食事代行的介词短语）：关于食事代行。\n     - 例：食事代行について詳しく説明します。\n   - 食事代行をする（使役态）：让别人进行食事代行。\n     - 例：社長は秘書に食事代行をさせた。\n   - 食事代行ができる（可能态）：能够进行食事代行。\n     - 例：私は忙しくて食事代行ができない。\n   - 食事代行を受ける（接受食事代行）：接受别人的食事代行。\n     - 例：私は忙しくて食事代行を受けたいと思う。', NULL, 0, NULL, 'src/main/resources/MP3/1720173413904.mp3');
INSERT INTO `word_list` VALUES (289, 32, ' 食事支援', 'meal support', '1.词性：名词\n2.词义：食物援助，餐饮支持\n3.例句：\n   - 私は食事支援のためにこの组织に参加しました。(我为了食物援助加入了这个组织。)\n   - 灾害が起きたとき、食事支援が非常に重要です。(当灾害发生时，食物援助非常重要。)\n\n变形及其词义：\n- 食事支援をする (提供食物援助)\n   例句：私たちは灾区の住民に食事支援をしました。(我们为灾区的居民提供了食物援助。)\n- 食事支援について (关于食物援助)\n   例句：食事支援について详しく说明してください。(请详细解释一下食物援助。)\n- 食事支援の (食物援助的)\n   例句：食事支援の活动を始めましょう。(让我们开始食物援助的活动吧。)', NULL, 0, NULL, 'src/main/resources/MP3/1720173414245.mp3');
INSERT INTO `word_list` VALUES (290, 32, ' 食卓', 'table', '1.词性：名詞\n2.词义：食事を取るための、食器や料理が置かれる卓。また、食事を取る場所。\n3.例句：\n- 家族と一緒に食卓を囲んでいる。\n- 新しい家には大きい食卓があった。\n\n4.变形及其词义：\n例：本を食卓に置く。\n- 食卓に（位置）：食卓の上に置く。- 食卓で（手段）：食卓を用いて食事を取る。例：友達と一緒に食卓で晩飯を取る。\n- 食卓から（起点）：食卓から何かを取り出す。例：果物を食卓から取り出す。', NULL, 0, NULL, 'src/main/resources/MP3/1720173414525.mp3');
INSERT INTO `word_list` VALUES (291, 32, ' 食事管理', 'meal management', '1.词性：名词\n2.词义：食物管理，饮食管理\n3.例句：\n- 私は食事管理をするために、健康な食材を選ぶことに気をつけています。\n  (我为了饮食管理，注意选择健康的食材。)\n- 食事管理は健康の維持に重要です。\n  (饮食管理对于维持健康很重要。)\n\n变形及其词义：\n- 食事管理する (动词)：进行饮食管理\n  例文：私は毎日食事管理をしています。(我每天都在进行饮食管理。)\n\n- 食事管理に関心を持つ (短语)：关心饮食管理\n  例文：最近、私は食事管理に関心を持っています。(最近，我很关心饮食管理。)\n\n- 食事管理が上手い (形容词)：擅长饮食管理\n  例文：彼女は食事管理が上手いので、健康です。(她很擅长饮食管理，所以很健康。)', NULL, 0, NULL, 'src/main/resources/MP3/1720173414807.mp3');
INSERT INTO `word_list` VALUES (292, 32, ' 食事品質', 'food quality', '1. 詞性：名詞\n2. 詞義：食事の品質、食品の良し。\n3. 例句：このレストランでは、食事品質が高くて、たくさんの人が来ます。\n       あなたは、食事品質について心配していますか？\n4. 變形とその意味：\n   - 食事品質的に (副詞的用法)：この食堂は食事品質的に優れています。\n   - 食事品質的な (形容詞的用法)：彼女は常に食事品質的な食材を選びます。\n   - 食事品質的だ (形容動詞的用法)：この店の料理は食事品質的だ。', NULL, 0, NULL, 'src/main/resources/MP3/1720173415193.mp3');
INSERT INTO `word_list` VALUES (293, 32, ' 食事療法', 'diet therapy', '1. 词性：名詞（名词）\n2. 词义：食事療法とは、健康を維持したり、病気の予防や治療に食事の取り入れ方を工夫すること。主に糖尿病、高血压などの生活習慣病に対処するときに利用されます。\n3. 例句：最近、医者によって食事療法を勧められたので、私も野菜をたくさん食べ始めました。\n   例句：彼女は糖尿病を抱えているので、常に食事療法を実践しています。\n\n变形及其词义：\n- 食事療法的（形容词型）：关于食事疗法的，例句：食事療法的な方法を紹介します。\n- 食事療法に関する（动词型）：与食事疗法有关，例句：食事療法に関する研究が進んでいます。\n- 食事療法について（副词型）：关于食事疗法，例句：食事療法について説明します。', NULL, 0, NULL, 'src/main/resources/MP3/1720173415465.mp3');
INSERT INTO `word_list` VALUES (294, 32, ' 食事習慣', 'eating habits', '1. 词性：名詞\n2. 词义：飲食の習慣、食事の作法。\n3. 例句：私の食事習慣は朝8時に朝ご飯を食べることです。\n4. 变形及其词义：\n   - 食事（しょくじ）の後：食事のあと、用膳後。例：食事の後、ティーはいつも昼寝をする。\n   - 食事（しょくじ）前：食事の前、用膳前。例：食事の前、私は手を洗う。\n   - 食事（しょくじ）中：食事の最中、用餐中。例：今、私は食事中です。', NULL, 0, NULL, 'src/main/resources/MP3/1720173415793.mp3');
INSERT INTO `word_list` VALUES (295, 32, ' 食べ放題', 'all', '1. 词性：名詞\n2. 词义：食べ放題は、料金が一定で、食べるだけ食べられるような飲食店のことを指します。\n3. 例句：私たちは近くの食べ放題に行きました。\n\n变形：無\n\n1. 词性：形容動詞\n2. 词义：自由に食べることを許可する状態を表します。\n3. 例句：この店では、お客様に食べ放題のサービスを提供しています。', NULL, 0, NULL, 'src/main/resources/MP3/1720173416098.mp3');
INSERT INTO `word_list` VALUES (296, 32, ' 炊事', 'cooking', '1.词性：名词\n2.词义：料理を作ること。炊事の器具。\n3.例句：\n- 炊事をする前に食材を用意しなければなりません。\n- この炊事機能がいいですね。\n\n变形及其词义：\n- 炊事中 (名词)：料理を作っている状態。\n  - 例句：炊事中、お邪魔しないでください。\n- 炊事場 (名词)：料理を作る場所。\n  - 例句：新しい家は炊事場が広くて便利です。\n- 炊事器 (名词)：料理を作る器具。\n  - 例句：最近、炊事器が壊してしまいました。', NULL, 0, NULL, 'src/main/resources/MP3/1720173416387.mp3');
INSERT INTO `word_list` VALUES (297, 32, ' 食事文化', 'food culture', '1. 词性：名词（名詞）\n2. 词义：食事文化通常指的是与饮食相关的习俗、礼节和传统。它涵盖了食物的准备、消费方式以及与进餐相关的社会行为规范。\n3. 例句：\n   - 日本の食事文化は世界的に有名です。\n   - (日本的食事文化世界闻名。)\n   - この地域の食事文化には独自の特徴があります。\n   - (这个地区的食事文化有其独特的特征。)\n\n变形及词义：\n- 食事文化に関する (关于食事文化)：指与食事文化相关的事物或信息。\n  - 例句：食事文化に関する本を読んで、新しい知識を得ました。\n  - (读了关于食事文化的书，我获得了新的知识。)\n\n- 食事文化を (将食事文化)：表示对食事文化的动作或处理。\n  - 例句：私たちは食事文化を研究しています。\n  - (我们正在研究食事文化。)\n\n由于“食事文化”是一个名词，它本身并没有动词或形容词等变形。但是可以通过与其他词语的组合来扩展其意义，如上所示。', NULL, 0, NULL, 'src/main/resources/MP3/1720173416660.mp3');
INSERT INTO `word_list` VALUES (298, 32, ' 食事教育', 'nutrition education', '1. 词性：名词\n2. 词义：食事教育是指通过食物和饮食方式的教育，以培养健康的饮食习惯和营养知识。\n3. 例句：\n   - 子供たちには食事教育を実施する必要があります。 (孩子们需要接受食事教育。)\n   - 学校では食事教育を取り入れています。 (学校已经引入了食事教育。)\n\n变形及其词义：\n- 食事教育について (关于食事教育)\n   - 例文：食事教育について、先生が説明してください。 (请老师解释一下食事教育。)\n\n- 食事教育を受ける (接受食事教育)\n   - 例文：私たちは小さい頃から食事教育を受けています。 (我们从小时候就开始接受食事教育。)\n\n- 食事教育を行う (进行食事教育)\n   - 例文：この学校では食事教育を行っています。 (这所学校正在进行食事教育。)\n\n- 食事教育を強化する (加强食事教育)\n   - 例文：最近、食事教育を強化する必要があると言われています。 (最近有人说需要加强食事教育。)\n\n- 食事教育に関心を寄せる (关注食事教育)\n   - 例文：多くの人々は食事教育に関心を寄せています。 (许多人对食事教育表示关注。)', NULL, 0, NULL, 'src/main/resources/MP3/1720173416989.mp3');
INSERT INTO `word_list` VALUES (299, 32, ' 調理', 'cooking', '1.词性：名詞\n2.词义：調理のこと。料理を作ること。また、調理する方法。\n3.例句：母は家で調理をしている。私は中華料理の調理に詳しい。\n\n变形及其词义：\n1. 動詞「調理する」：料理を作ること。\n   例句：私は毎日自分で調理をします。\n2. 名詞「調理師」：料理人。\n   例句：彼は有名な調理師です。\n3. 名詞「調理場」：料理を作る場所。\n   例句：新しい家は大きな調理場を持っています。', NULL, 0, NULL, 'src/main/resources/MP3/1720173417318.mp3');
INSERT INTO `word_list` VALUES (300, 32, ' 料理人', 'chef', '1.词性：名词\n2.词义：厨师，料理人。\n3.例句：\n- このレストランの料理人は本場のフランス人です。\n  （这家餐厅的厨师是地道的法国人。）\n- 彼女は将来、料理人になることを夢見ています。\n  （她梦想着将来成为一名厨师。）\n\n变形及词义：\n- 料理人さん（料理人さん）：对厨师的尊称。\n  例：お願いします、料理人さんが来てください。\n  （请问能让厨师过来一下吗？）\n\n- 料理人たち（料理人達）：指多位厨师。\n  例：このホテルの料理人たちは世界中から集まっています。\n  （这家酒店的厨师团队来自世界各地。）\n\n- 料理人になる（料理人になる）：成为厨师的动作或过程。\n  例：高校を卒業して、彼は料理人になる夢を続けました。\n  （高中毕业后，他继续追求成为厨师的梦想。）\n\n- 料理人である（料理人である）：表示身份或状态。\n  例：彼は有名なグルメショーの料理人である。\n  （他是一家著名美食餐厅的厨师。）\n\n- 料理人について（料理人について）：关于厨师。\n  例：今度の特集は、活跃中の若手料理人についてです。\n  （这次的特辑是关于活跃的年轻厨师的。）\n\n以上是基于“料理人”这个词的基本用法和常见的变形。在日语中，名词的变形通常通过添加不同的助词或后缀来实现，以表达不同的语义关系或敬意程度。', NULL, 0, NULL, 'src/main/resources/MP3/1720173417554.mp3');
INSERT INTO `word_list` VALUES (301, 32, ' 食事安全', 'food safety', '无法从大模型获取数据，请联系管理员！', NULL, 0, NULL, 'src/main/resources/MP3/1720173417881.mp3');
INSERT INTO `word_list` VALUES (302, 32, ' 食器', 'utensil', '无法从大模型获取数据，请联系管理员！', NULL, 0, NULL, 'src/main/resources/MP3/1720173418247.mp3');
INSERT INTO `word_list` VALUES (303, 32, ' 食事', 'meal', '无法从大模型获取数据，请联系管理员！', NULL, 0, NULL, 'src/main/resources/MP3/1720173418497.mp3');
INSERT INTO `word_list` VALUES (304, 4, ' 우유 ', ' 牛奶', '1. 词性：名词\n2. 词义：指一种白色的乳制品，通常用于烹饪或直接食用。\n3. 例句：1) 我每天早上都会喝一杯牛奶。2) 这家餐厅的奶酪蛋糕很好吃。\n\n4. 变形及其词义：\n   - 变形1：cheese（奶酪）\n     例句：1) 我喜欢在早餐时吃一片奶酪面包。\n   - 变形2：milk product（乳制品产品）\n     例句：1) 这个超市有很多不同的乳制品产品可供选择。', NULL, 0, NULL, 'src/main/resources/MP3/1720785485169.mp3');
INSERT INTO `word_list` VALUES (305, 4, ' 국수 ', ' 面条', '1. 词性：名词\n2. 词义：面条，一种面食\n3. 例句：我喜欢吃面条。\n\n变形及其词义：\n- 面条：一种面食\n- 面条汤：面条煮成的汤', NULL, 0, NULL, 'src/main/resources/MP3/1720785485696.mp3');
INSERT INTO `word_list` VALUES (306, 4, ' 생선 ', ' 海鲜', '1. 词性：名词\n2. 词义：指一种常见的淡水鱼类，也称为“生鱼”。\n3. 例句：1) 我今天吃了一条鲈鱼。2) 这道菜里加了一条鲈鱼。\n\n变形及其词义：\n- 1. 生鱼（shen yú）： 指一种常见的淡水鱼类，也称为“生鱼”。\n- 2. 鲈（lú）： 指一种淡水鱼类，也称为“鲈鱼”。\n- 3. 鲈鱼（lú yú）： 指一种淡水鱼类，也称为“鲈”。', NULL, 0, NULL, 'src/main/resources/MP3/1720785486116.mp3');
INSERT INTO `word_list` VALUES (307, 4, ' 양파 ', ' 洋葱', '1. 词性：名词\n2. 词义：指洋葱这种植物的种子，也指洋葱这种植物本身。\n3. 例句：我喜欢吃新鲜的洋葱。\n\n4. 变形及词义：\n   - 形式：洋葱头\n     例句：他的头发像洋葱头一样黑。\n   - 形式：洋葱皮\n     例句：洋葱的皮很脆，容易破开。', NULL, 0, NULL, 'src/main/resources/MP3/1720785486547.mp3');
INSERT INTO `word_list` VALUES (308, 4, ' 토마토 ', ' 番茄', '1. 词性：名词\n2. 词义：指番茄植物的果实，通常为红色或黄色，味道酸甜可口。\n3. 例句：1) 我喜欢吃这个红色的番茄。2) 这个番茄看起来很新鲜。\n\n变形及其词义：\n1. 形态：番茄（名词）\n   例句：1) 我喜欢吃新鲜的番茄。\n\n2. 番茄酱（名词）\n   例句：1) 我正在做番茄酱炒饭。\n\n3. 番茄派（名词）\n   例句：1) 这家餐厅的招牌菜是番茄派。', NULL, 0, NULL, 'src/main/resources/MP3/1720785486965.mp3');
INSERT INTO `word_list` VALUES (309, 4, ' 떡 ', ' 面包', '1. 词性：名词\n2. 词义：一种由面粉、酵母和水混合制成的食品，通常烤熟后食用。\n3. 例句：我喜欢吃面包。\n\n变形及其词义：\n- 面包干：一种经过烘烤的面包，口感酥脆。\n- 法棍面包：一种法国风格的长条形面包，外皮酥脆，内馅丰富。\n- 吐司：一种用高筋面粉发酵制成的面包，口感松软。\n- 土司：一种用高筋面粉发酵制成的面包，口感松软，外皮有纹理。', NULL, 0, NULL, 'src/main/resources/MP3/1720785487365.mp3');
INSERT INTO `word_list` VALUES (310, 4, ' 국화 ', ' 果酱', '1. 词性：名词\n2. 词义：韩国的一种传统甜点，通常由糖浆、水果和坚果制成。\n3. 例句：我喜欢吃韩国的果酱蛋糕。\n\n变形及其词义：\n- 果酱蛋糕（kimchi jam cake）：一种韩国的传统甜点，由果酱、糖浆、鸡蛋和面粉制成。\n- 果酱冰淇淋（kimchi jam ice cream）：一种韩国的传统甜点，由果酱、奶油和糖制成。', NULL, 0, NULL, 'src/main/resources/MP3/1720785487767.mp3');
INSERT INTO `word_list` VALUES (311, 4, ' 한국 요리 ', ' 韩国料理', '1. 词性：名词\n2. 词义：韩国料理\n3. 例句：韩国料理是一种具有独特风味的亚洲美食。\n\n变形及其词义：\n- 한국요리 (Korean cuisine)：韩国料理，一种具有独特风味的亚洲美食。', NULL, 0, NULL, 'src/main/resources/MP3/1720785488195.mp3');
INSERT INTO `word_list` VALUES (312, 4, ' 양말 ', ' 奶酪', '1. 词性：名词\n2. 词义：奶酪\n3. 例句：这个奶酪很好吃。\n\n变形及其词义：\n- 奶酪片：一种薄片状的奶酪，可以切成小块食用。\n- 奶酪酱：一种用奶酪制成的酱料，通常用于烹饪中增加味道。', NULL, 0, NULL, 'src/main/resources/MP3/1720785488581.mp3');
INSERT INTO `word_list` VALUES (313, 4, ' 밥 ', ' 饭', '1. 词性：名词\n2. 词义：指一种食物，通常作为一顿饭的主食。\n3. 例句：我今天晚上吃了一碗热腾腾的饭。\n\n变形及其词义：\n- 形式1：饭食（名词）\n   例句：这道菜的主要食材是米饭和各种蔬菜。\n\n- 形式2：饭菜（名词）\n   例句：我喜欢在晚饭时吃一些清淡的饭菜。', NULL, 0, NULL, 'src/main/resources/MP3/1720785488991.mp3');
INSERT INTO `word_list` VALUES (314, 4, ' 과일 ', ' 水果', '无法从大模型获取数据，请联系管理员！', NULL, 0, NULL, 'src/main/resources/MP3/1720785489402.mp3');
INSERT INTO `word_list` VALUES (315, 4, ' 음료 ', ' 饮料', '1. 词性：名词\n2. 词义：饮料\n3. 例句：我喜欢吃冰镇可乐。\n\n变形及其词义：\n- 可乐：一种碳酸饮料，味道酸甜可口。\n- 汽水：一种含糖的碳酸饮料，口感清爽。', NULL, 0, NULL, 'src/main/resources/MP3/1720785489781.mp3');
INSERT INTO `word_list` VALUES (316, 4, ' 꿀 ', ' 蜂蜜', '1. 词性：名词\n2. 词义：一种由蜜蜂采集花粉制成的甜液体，通常用于烹饪和食用。\n3. 例句：蜂蜜是一种非常健康的食品，可以用来制作蜂蜜柠檬水、蜂蜜面包等美食。\n\n变形及其词义：\n- 蜂蜜糖浆：一种由蜂蜜和糖混合而成的饮料。\n- 蜂蜜蜜糖：一种由蜂蜜和蜜糖混合而成的甜点。\n- 蜂蜜柠檬水：一种将蜂蜜和柠檬汁混合而成的饮品。', NULL, 0, NULL, 'src/main/resources/MP3/1720785490212.mp3');
INSERT INTO `word_list` VALUES (317, 4, ' 고기 ', ' 肉', '1. 词性：名词\n2. 词义：肉类食品，通常指未经加工的肉或肉制品。\n3. 例句：我喜欢吃烤鸭，因为它是一道美味的肉菜。\n\n变形及其词义：\n- 烤肉：一种烹饪方式，将肉类放在炭火上烤熟。\n- 牛肉干：一种经过脱水处理的牛肉制品，可以作为零食食用。\n- 猪肉干：一种经过脱水处理的猪肉制品，可以作为零食食用。', NULL, 0, NULL, 'src/main/resources/MP3/1720785490625.mp3');
INSERT INTO `word_list` VALUES (318, 4, ' 채소 ', ' 蔬菜', '1. 词性：名词\n2. 词义：蔬菜\n3. 例句：这个菜是新鲜的蔬菜，口感很好。\n\n变形及其词义：\n- 蔬菜：这种蔬菜味道鲜美，营养丰富。', NULL, 0, NULL, 'src/main/resources/MP3/1720785491014.mp3');
INSERT INTO `word_list` VALUES (319, 4, ' 빵 ', ' 饼干', '1. 词性：名词\n2. 词义：一种由面粉、糖和油脂制成的食品，通常在烤制时会加入一些香料。\n3. 例句：我喜欢吃饼干，因为它们很美味。\n\n变形及其词义：\n1. 饼干 - 一种由面粉、糖和油脂制成的食品，通常在烤制时会加入一些香料。\n2. 饼干盒 - 用于存放饼干的容器。\n3. 饼干店 - 出售饼干的商店。\n4. 饼干卷 - 一种将饼干卷起来的零食。\n5. 饼干夹心 - 一种将饼干夹在两层蛋糕之间的甜点。', NULL, 0, NULL, 'src/main/resources/MP3/1720785491519.mp3');
INSERT INTO `word_list` VALUES (320, 4, ' 음식 ', ' 食物', '1. 词性：名词\n2. 词义：食物\n3. 例句：这个餐厅的食物非常好吃。\n\n变形及其词义：\n- 음식 (Noun): 食物\n- 요리 (Noun): 烹饪方法', NULL, 0, NULL, 'src/main/resources/MP3/1720785491993.mp3');
INSERT INTO `word_list` VALUES (321, 4, ' 김치 ', ' 泡菜', '1. 词性：名词\n2. 词义：泡菜是一种韩国的传统食品，以大白菜为主要原料，经过发酵、腌制等工艺制作而成。\n3. 例句：泡菜是韩国人最喜欢的传统食品之一，口感酸辣可口。\n\n变形及其词义：\n- 泡菜（n）： 韩国传统的一种食品，以大白菜为原料，经过发酵、腌制等工艺制作而成。\n- 泡菜（adj）： 韩国传统的一种食品，以大白菜为原料，经过发酵、腌制等工艺制作而成。\n- 泡菜（v）： 韩国传统的一种食品，以大白菜为原料，经过发酵、腌制等工艺制作而成。', NULL, 0, NULL, 'src/main/resources/MP3/1720785492457.mp3');
INSERT INTO `word_list` VALUES (322, 4, ' 고구마 ', ' 土豆', '1. 词性：名词\n2. 词义：土豆是一种常见的蔬菜，味道甜美，营养丰富。\n3. 例句：我喜欢吃烤土豆，它的味道非常美味。\n\n变形及其词义：\n- 形式1：potato（复数）\n  - 词义：土豆的复数形式。\n  - 例句：The potatoes are ready to be cooked.\n\n- 形式2：potatoes（单数）\n  - 词义：土豆的单数形式。\n  - 例句：I have a bunch of potatoes in the kitchen.', NULL, 0, NULL, 'src/main/resources/MP3/1720785492897.mp3');
INSERT INTO `word_list` VALUES (323, 4, ' 커스터드 아이스크림 ', ' 冰淇淋', '1. 词性：名词\n2. 词义：一种由冰淇淋和奶油制成的甜点，通常在夏季食用。\n3. 例句：我喜欢吃冰淇淋，尤其是草莓口味的。\n\n变形及其词义：\n- 冰淇淋（yīng xīn lí）：一种由冰淇淋和奶油制成的甜点，通常在夏季食用。\n- 奶油冰淇淋（yáng rú yīng xīn lí）：一种由奶油和冰淇淋制成的甜点，通常在夏季食用。', NULL, 0, NULL, 'src/main/resources/MP3/1720785493375.mp3');
INSERT INTO `word_list` VALUES (324, 33, ' 양파', '苹果', '1. 词性：名词\n2. 词义：苹果\n3. 例句：\n   - 我喜欢每天早上吃一个苹果。(나는 매일 아침에 한 사과를 먹는 것을 좋아해요.)\n   - 她给我买了一箱新鲜的苹果。(그녀는 나에게 신선한 사과 한 상자를 사줬어요.)\n\n变形及其词义：\n1. 變形：양파잡이 (摘苹果的人)\n   - 例句：나는 양파잡이가 되고 싶어요. (我想成为摘苹果的人。)\n\n2. 變形：蘋果汁 (苹果汁)\n   - 例句：나는 매일 아침에 蘋果汁를 마시고 있어요. (我每天早上都喝苹果汁。)\n\n3. 變形：蘋果樹 (苹果树)\n   - 例句：우리 집 근처에는 많은 蘋果樹들이 있어요. (我们家附近有很多苹果树。)\n\n4. 變形：蘋果糖 (苹果糖)\n   - 例句：나는 사과를 사지만 사과껌은 좋아하지 않아요. (我喜欢吃苹果，但不喜欢苹果糖。)', NULL, 1, NULL, 'src/main/resources/MP3/1720785493783.mp3');
INSERT INTO `word_list` VALUES (325, 33, ' 포도', '葡萄', '1. 词性：名词\n2. 词义：葡萄（指一种水果）\n3. 例句：\n   - 나는 포도를 좋아해요. (我喜欢葡萄。)\n   - 이 포도는 맛있어요. (这个葡萄很好吃。)\n\n4. 变形及其词义：\n   - 포도즈 (potazo) - 葡萄干\n     例句：이 포도즈는 건강하고 신기해요. (这个葡萄干既健康又好吃。)\n   - 포도맛 (potam) - 葡萄味\n     例句：이 음식은 포도맛이 있어요. (这个食物有葡萄味。)\n   - 포도주 (podoju) - 葡萄酒\n     例句：이 红酒은 포도주로 만들었어요. (这红酒是用葡萄酒制作的。)', NULL, 0, NULL, 'src/main/resources/MP3/1720785494192.mp3');
INSERT INTO `word_list` VALUES (326, 33, ' 수박', '西瓜', '1. 词性：名词\n2. 词义：西瓜\n3. 例句：\n   - 한국에서는 수박을 가장 좋아하는 과일이다. (韩国人最喜欢吃的水果是西瓜。)\n   - 여름에는 수박을 먹으면 더욱 기운나는데요. (夏天吃西瓜会更加提神哦。)\n\n变形：\n- 수박이 (西瓜的)\n  - 例句：수박이는 과일입니다. (西瓜是一种水果。)\n- 수박을 (吃西瓜)\n  - 例句：저는 수박을 먹습니다. (我吃西瓜。)\n- 수박을 먹었어요 (已经吃了西瓜)\n  - 例句：저는 수박을 먹었어요. (我已经吃了西瓜。)\n- 수박을 맛있게 먹었어요 (好好地吃了西瓜)\n  - 例句：저는 수박을 맛있게 먹었어요. (我好好地吃了西瓜。)', NULL, 0, NULL, 'src/main/resources/MP3/1720785494590.mp3');
INSERT INTO `word_list` VALUES (327, 33, ' 에어팬', '电风扇', '1. 词性：名词\n2. 词义：电风扇\n3. 例句：\n   - 나는 에어팬을 켜서 더 涼爽해지길 바래요. (Naneun eoppalleul cheoeseo deo coolsaghajigibbeoryeo.) - 我想让电风扇打开，变得更凉爽。\n   - 에어팬은 따뜻하게 맑아요. (Eoppalleun dwadduhage malgyayo.) - 电风扇很温暖又干净。\n\n变形及其词义：\n1. 에어팬을 (eoppalleul) - 电风扇（名词）\n   - 에어팬을 켜세요. (Eoppalleul cheoseyeo.) - 请打开电风扇。\n2. 에어팬이 (eoppalli) - 电风扇（名词）\n   - 에어팬이 고장났어요. (Eoppalli gojangnan-esseoyo.) - 电风扇坏了。\n3. 에어팬한 (eoppalhan) - 有电风扇的\n   - 이 책상은 에어팬한 거예요. (I chaegsaneun eoppalhan geoyeyo.) - 这个书桌是有电风扇的。\n4. 에어팬으로 (eoppalleuro) - 用电风扇的方式\n   - 에어팬으로 놀아보세요. (Eoppalleuro nolhaboseyo.) - 用电风扇玩吧。\n5. 에어팬을 굴리다 (eoppalleul golgilda) - 修理电风扇\n   - 에어팬을 굴리러 가요. (Eoppalleul golgireoreo gayo.) - 我去修理电风扇了。', NULL, 0, NULL, 'src/main/resources/MP3/1720785495040.mp3');
INSERT INTO `word_list` VALUES (328, 33, ' 사과', '橙子', '1. 词性：名词 (Noun)\n2. 词义：苹果 (Apple)\n3. 例句：\n   - 사과를 먹고 싶어요. (I want to eat an apple.)\n   - 그 사과는 맛있어요. (That apple is delicious.)\n\n变形及其词义：\n1. 사과가 맛있어요. (The apple is tasty.)\n2. 사과를 읍어요. (I am eating an apple.)\n3. 사과를 주세요. (Please give me an apple.)\n4. 사과를 살피었어요. (I peeled the apple.)\n5. 사과를 씻어요. (I washed the apple.)\n6. 사과를 切片해요. (I cut the apple into slices.)\n7. 사과를 먹었어요. (I have eaten the apple.)\n8. 사과를 사세요. (Buy an apple.)\n9. 사과를 聞いて欲しいです. (I want to smell the apple.)\n10. 사과를 보여주세요. (Show me the apple.)', NULL, 0, NULL, 'src/main/resources/MP3/1720785495407.mp3');
INSERT INTO `word_list` VALUES (329, 33, ' 프라다', '冰箱', '1. 词性：名词\n2. 词义：冰箱\n3. 例句：\n   - (우리 집에는) 프라다가 있어요. (我们家有冰箱。)\n   - (아침에는) 프라다에서 음식을 뽑아서 드세요. (早上从冰箱里取出食物吃。)\n\n变形及其词义：\n1. 变形：프라다를 (冰箱)\n   - 例句：(아침에는) 프라다를 열어서 음식을 뽑아서 드세요. (早上打开冰箱取出食物吃。)\n\n2. 变形：프라다에 (在冰箱里)\n   - 例句：(우리 집의) 프라다에는 많은 음식이 있어요. (我们家的冰箱里有很多食物。)\n\n3. 变形：프라다로 (用冰箱)\n   - 例句：(음식을) 프라다로 냅니다. (把食物放进冰箱里。)\n\n4. 变形：프라다에서 (从冰箱里)\n   - 例句：(음식을) 프라다에서 꺼내써요. (从冰箱里取出食物。)\n\n5. 变形：프라다에 넣기 (放进冰箱)\n   - 例句：(음식을) 프라다에 넣습니다. (把食物放进冰箱里。)\n\n6. 变形：프라다를 열다 (打开冰箱)\n   - 例句：(아침에는) 프라다를 열어서 음식을 뽑아서 드세요. (早上打开冰箱取出食物吃。)', NULL, 0, NULL, 'src/main/resources/MP3/1720785495828.mp3');
INSERT INTO `word_list` VALUES (330, 33, ' 갈비', '米饭', '1. 词性：名词\n2. 词义：指一种用肉、蔬菜等材料包裹在米饭中的韩国传统食品。\n3. 例句：\n- 나는 갈비를 먹고 싶어요. (我想吃烤肉。)\n- 그녀는 자신이 만든 갈비를 주었다. (她把自己做的烤肉送给了我。)\n\n变形及其词义：\n1. 갈비를 먹다 (吃烤肉)\n   例句：나는 갈비를 먹고 싶어요. (我想吃烤肉。)\n2. 갈비를 챙기다 (带烤肉)\n   例句：그녀는 자신이 만든 갈비를 주었다. (她把自己做的烤肉送给了我。)\n3. 갈비를 구워서 드세요 (烤烤肉给我吃)\n   例句：친구에게 갈비를 구워서 드려요. (给朋友烤烤肉吃。)\n4. 갈비를 삶입니다 (包烤肉)\n   例句：이것은 내가 삶인 갈비입니다. (这是我包的烤肉。)\n5. 갈비를 구운 뒤에 떡을 넣으면 더 好吃합니다. (把烤肉和饭一起炒会更好吃。)\n   例句：갈비를 구운 뒤에 떡을 넣으면 더 好吃합니다. (把烤肉和饭一起炒会更好吃。)', NULL, 0, NULL, 'src/main/resources/MP3/1720785496194.mp3');
INSERT INTO `word_list` VALUES (331, 33, 'ssss', '空调', '1. 词性：名词\n2. 词义：空调是一种用于调节室内温度和湿度的装置，通过循环制冷或制热来提供舒适的环境。\n3. 例句：\n   - 我家的空调坏了，需要修理一下。 (My home air conditioning is broken and needs to be repaired.)\n   - 在夏天，空调是不可或缺的电器之一。 (In the summer, air conditioning is one of the indispensable appliances.)\n\n变形及其词义：\n1. 变形：空调机 (air conditioning unit)\n   - 词义：空调机的简称，指代空调设备本身。\n   - 例句：我需要买一个新的空调机来替换旧的。 (I need to buy a new air conditioning unit to replace the old one.)\n\n2. 变形：空调房间 (air-conditioned room)\n   - 词义：指装有空调设备的室内空间。\n   - 例句：这家酒店的所有房间都安装了空调。 (All the rooms in this hotel are air-conditioned.)\n\n3. 变形：空调系统 (air conditioning system)\n   - 词义：由多个组件组成的用于控制室内温度和湿度的完整系统。\n   - 例句：这个大楼的空调系统需要进行定期维护。 (The air conditioning system of this building needs regular maintenance.)\n\n4. 变形：空调技术 (air conditioning technology)\n   - 词义：涉及空调设备的制造、安装、维修和管理等方面的技术和知识。\n   - 例句：随着科技的进步，空调技术不断更新和改进。 (With the advancement of technology, air conditioning technology is constantly updated and improved.)\n\n请注意，以上变形和例句都是基于英文的，因为韩语中可能没有对应的专业术语或常见表达方式。', NULL, 0, NULL, 'src\\main\\resources\\sound\\1721312997869.mp3');
INSERT INTO `word_list` VALUES (332, 33, ' 컵밥', '便当', '1. 词性：名词\n2. 词义：便当盒\n3. 例句：\n   - 컵밥을 가지고 여행을 떠나요. (带便当去旅行。)\n   - 컵밥에는 냉면， 김밥， 양념장과 국수가 들어있습니다. (便当中有冷面、石锅拌饭、酱油和汤。)\n\n变形及其词义：\n1. 컵밥揭开(kunkabgeulchim) - 打开便当盒\n2. 컵밥을 꺾으세요(kunkabgeulgateoyeoseyo) - 关闭便当盒\n3. 컵밥에 물이 있나요？(kunkabgeimeulmiinanoyo) - 便当盒里有水吗？\n4. 컵밥에 사과가 있나요？(kunkabgeisagagainanoyo) - 便当盒里有苹果吗？\n5. 컵밥에 두 챙이 있나요？(kunkabgeidoeppiinanoyo) - 便当盒里有两个勺子吗？\n6. 컵밥을 비웁니다(kunkabgeulbiunnida) - 清洗便当盒\n7. 컵밥을 파손했어요(kunkabgeulpaseonhaeseoyo) - 便当盒弄坏了\n8. 컵밥을 재구입하세요(kunkabgeuljaeguibhaeseoyo) - 重新购买便当盒\n9. 컵밥을 선물해주세요(kunkabgeulseongmulhaejuseyo) - 送便当盒作为礼物\n10. 컵밥을 샀어요(kunkabgeulsaseoyo) - 买了便当盒', NULL, 0, NULL, 'src/main/resources/MP3/1720786150179.mp3');
INSERT INTO `word_list` VALUES (333, 33, ' 스마트폰', '智能机', '1. 词性：名词\n2. 词义：智能机（智能手机）\n3. 例句：\n- 나는 스마트폰을 사지 않습니다. (我不喜欢买智能手机。)\n- 이 스마트폰은 높은 컴퓨터性能을 가지고 있어요. (这款智能手机具有高性能。)\n\n变形及其词义：\n1. 形容词形式：스마트폰의 (智能手机的)\n   示例：스마트폰의 화면은 아주 크고 멋있어요. (智能手机的屏幕非常大且漂亮。)\n2. 动词形式：스마트폰을 사다 (购买智能手机)\n   示例：나는 明日 스마트폰을 사러 갈게요. (我明天去买智能手机。)\n3. 副词形式：스마트폰에 (智能手机上)\n   示例：내 정보는 스마트폰에 들어있어요. (我的信息在智能手机上。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786164604.mp3');
INSERT INTO `word_list` VALUES (334, 33, ' 컴퓨터', '电脑', '1. 词性：名词 (Noun)\n2. 词义：电脑 (Computer)\n3. 例句：\n   - 나는 컴퓨터를 사서 공부하고 있습니다. (I bought a computer to study.)\n   - 이 컴퓨터는 성능이 좋습니다. (This computer has good performance.)\n\n变形及其词义：\n1. 变形：컴퓨터 제품 (Computer product)\n   - 词义：电脑产品 (Computer product)\n   - 例句：이 컴퓨터 제품은 비싼 것 같지만 효율적입니다. (This computer product seems expensive but efficient.)\n\n2. 变形：컴퓨터 소프트웨어 (Computer software)\n   - 词义：电脑软件 (Computer software)\n   - 例句：이 컴퓨터에는 맥 OS라는 소프트웨어가 설치되어 있습니다. (This computer has macOS installed as software.)\n\n3. 变形：컴퓨터 硬件 (Computer hardware)\n   - 词义：电脑硬件 (Computer hardware)\n   - 例句：이 컴퓨터의 하드웨어는 최신입니다. (The hardware of this computer is up-to-date.)\n\n4. 变形：컴퓨터 모니터 (Computer monitor)\n   - 词义：电脑显示器 (Computer monitor)\n   - 例句：이 컴퓨터의 모니터는 화면이 아주 크고 밝습니다. (The monitor of this computer is very large and bright.)\n\n5. 变形：컴퓨터 키보드 (Computer keyboard)\n   - 词义：电脑键盘 (Computer keyboard)\n   - 例句：이 컴퓨터의 키보드는 打字을 잘 할 수 있습니다. (The keyboard of this computer is good for typing.)', NULL, 0, NULL, 'src/main/resources/MP3/1720786165151.mp3');
INSERT INTO `word_list` VALUES (335, 33, ' 딸기', '草莓', '1. 词性：名词\n2. 词义：草莓\n3. 例句：\n   - 딸기는 맛있습니다. (草莓很好吃。)\n   - 우리는 딸기를 먹었어요. (我们吃了草莓。)\n\n变形及其词义：\n1. 딸기가 (草莓的) - 词义：表示草莓的所有格形式，指草莓属于某个人或物体。\n   - 例句：그 딸기가 맛있었어요. (那个草莓很好吃。)\n\n2. 딸기를 (草莓) - 词义：表示草莓作为宾语的形式，指进行动作的对象是草莓。\n   - 例句：나는 딸기를 좋아합니다. (我喜欢草莓。)\n\n3. 딸기이다 (是草莓) - 词义：表示草莓的陈述形式，用于说明某物是草莓。\n   - 例句：이것은 딸기입니다. (这是草莓。)\n\n4. 딸기로 (用草莓) - 词义：表示使用草莓作为工具或手段的形式，指通过草莓来完成某个动作。\n   - 例句：딸기로 새우갈비를 만들었어요. (我用草莓做了草莓酱。)\n\n请注意，以上例句中的韩文仅供参考，可能存在一定的语法不准确之处。', NULL, 0, NULL, 'src/main/resources/MP3/1720786165713.mp3');
INSERT INTO `word_list` VALUES (336, 33, ' 바나나', '香蕉', '1. 词性：名词\n2. 词义：香蕉\n3. 例句：\n   - 我喜欢香蕉。(나는 바나나를 좋아해요.)\n   - 她给我买了一串香蕉。(그녀는 나에게 바나나 씨앗을 사줬어요.)\n\n变形及其词义：\n1. 形容词：바나나색 (香蕉色) - 词义：像香蕉一样的黄色\n   - 这件衣服是香蕉色的。(이 옷은 바나나색이에요.)\n2. 动词：바나나를 먹다 (吃香蕉) - 词义：吃香蕉的动作\n   - 我喜欢吃香蕉。(나는 바나나를 좋아해요.)\n3. 名词：바나나汁 (香蕉汁) - 词义：由香蕉榨取的汁液\n   - 我想喝香蕉汁。(나는 바나나汁를 마시고 싶어요.)\n4. 副词：바나나처럼 (像香蕉一样) - 词义：表示某种方式或程度与香蕉相似\n   - 这个颜色像香蕉一样。(이 색상은 바나나처럼이에요.)', NULL, 0, NULL, 'src/main/resources/MP3/1720786166257.mp3');
INSERT INTO `word_list` VALUES (337, 33, ' 칫솔', '勺子', '1. 词性：名词\n2. 词义：勺子\n3. 例句：칫솔을 섭취하세요. (请用勺子吃饭。)\n\n变形及其词义：\n- 칫솔(勺子)\n- 칫솔을(用勺子)\n- 칫솔에(在勺子上)\n\n例句：\n1. 칫솔에 식이 있습니다. (勺子上有食物。)\n2. 칫솔을 사지 않으면 별로 골드림입니다. (不使用勺子的话，不太方便。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786166810.mp3');
INSERT INTO `word_list` VALUES (338, 33, ' 멜론', '芒果', '1. 词性：名词 (Noun)\n2. 词义：芒果树 (Mango tree)\n3. 例句：\n   - 멜론은 맑은 색이고 뚜껑씌어요. (Mangos are green in color and have a fuzzy exterior.)\n   - 우리 집 바로 오른쪽에 멜론이 있어요. (There is a mango tree right next to our house.)\n\n变形及其词义：\n1. 멜론이나 (Mangoes) - 名词 (Noun)，指多个芒果 (mangoes)\n   - 멜론이나 하나 가지고 오세요. (Bring one mango, please.)\n\n2. 멜론汁 (Mango juice) - 名词 (Noun)，指芒果汁 (mango juice)\n   - 내가 아침에는 멜론汁를 마시는 것을 좋아해요. (I like to drink mango juice in the morning.)\n\n3. 멜론얼음 (Mango ice cream) - 名词 (Noun)，指芒果冰淇淋 (mango ice cream)\n   - 여름에는 멜론얼음을 먹는 것이 최고야！ (Eating mango ice cream in summer is the best!)\n\n4. 멜론탕 (Mango porridge) - 名词 (Noun)，指芒果粥 (mango porridge)\n   - 멜론탕은 너무 맛있어요. (Mango porridge is very delicious.)\n\n5. 멜론삼계탕 (Mango trifle) - 名词 (Noun)，指芒果三层蛋糕 (mango trifle)\n   - 다음에는 멜론삼계탕을 먹고 싶어요. (I want to eat mango trifle next time.)', NULL, 0, NULL, 'src/main/resources/MP3/1720786167355.mp3');
INSERT INTO `word_list` VALUES (339, 33, ' 휴대전화', '手机', '1. 词性：名词\n2. 词义：手机（移动电话）\n3. 例句：\n   - 나는 휴대전화를 샀어요. (Naneun hyeotaejeonhwareul saeyo.) - 我买了一部手机。\n   - 휴대전화에 문자를 보내세요. (Hyeotaejeonhware meonjaleul boneuseyo.) - 请给手机发个短信。\n\n4. 变形及其词义：\n   - 휴대전화를 켜다 (hyeotaejeonhwareul cheolda) - 打开手机\n     - 잠기고 있는 휴대전화를 켜세요. (Jakgigo issneun hyeotaejeonhwareul cheolsseyo.) - 请把关闭的手机打开。\n   - 휴대전화를 끄다 (hyeotaejeonhwareul kkeuda) - 关闭手机\n     - 잠겨 있는 휴대전화를 끄세요. (Jagyeo issneun hyeotaejeonhwareul kkeusseo.) - 请把开着的手机关闭。\n   - 휴대전화를 연결하다 (hyeotaejeonhwareul yeollyeonghada) - 连接手机\n     - 휴대전화와 台式电脑을 연결해 주세요. (Hyeotaejeonhware wa deuksibeutiseteoul yeollyeonghae jusseo.) - 请将手机和台式电脑连接起来。\n   - 휴대전화를 통화하다 (hyeotaejeonhwareul tonghaeda) - 打电话\n     - 이것은 무엇인가요？ 휴대전화로 말씀해주세요. (Igeoseun mueosingayo? Hyeotaejeonhwarero malsseumhaejusseo.) - 这是什么东西？请用电话告诉我。\n   - 휴대전화에 알람을 설정하다 (hyeotaejeonhware e alareul seulchihada) - 设置手机铃声\n     - 나의 휴대전화에는 내가 좋아하는 노래가 알람입니다. (Naneun hyeotaejeonhwareneun naega joahaneun noraga alareimnida.) - 我的手机铃声是我喜欢的歌。', NULL, 0, NULL, 'src/main/resources/MP3/1720786167919.mp3');
INSERT INTO `word_list` VALUES (340, 33, ' 비닐', '杯子', '1. 词性：名词\n2. 词义：杯子\n3. 例句：\n   - 我喜欢用这个비닐喝咖啡。 (I like to drink coffee with this cup.)\n   - 请你拿一个비닐给我倒水。 (Please pass me a cup to pour water.)\n\n变形及其词义：\n1. 变形：비닐이\n   词义：杯子的复数形式，表示多个杯子。\n   例句：\n   - 这些비닐이都是我新买的。 (These cups are all new.)\n\n2. 变形：비닐을\n   词义：杯子的宾格形式，表示动作的对象是杯子。\n   例句：\n   - 请帮我拿一下비닐을。 (Please pass me the cup.)\n\n3. 变形：비닐에\n   词义：表示在杯子里或杯子上的动作。\n   例句：\n   - 把牛奶倒到비닐에。 (Pour milk into the cup.)\n\n4. 变形：비닐中去\n   词义：表示从杯子中取出或倒出的动作。\n   例句：\n   - 请把这个杯子里的水倒在비닐中去。 (Please pour the water from this cup into the sink.)', NULL, 0, NULL, 'src/main/resources/MP3/1720786168499.mp3');
INSERT INTO `word_list` VALUES (341, 33, ' 망고', '木瓜', '1. 词性：名词\n2. 词义：木瓜，一种水果\n3. 例句：\n- 我喜欢喝木瓜牛奶。(나는 망고우유를 좋아해요.)\n- 这个木瓜看起来很新鲜。(이 망고는 새롭다고 생각합니다.)\n\n变形及其词义：\n- 形容词：망고색 (manggo-sal, 木瓜色) - 指类似于木瓜的黄色或橙色\n  例句：她的连衣裙是漂亮的木瓜色。(그녀의 드레스는 아름답은 망고색입니다.)\n\n- 动词：망고지다 (manggojida, 使成木瓜状) - 将某物弄成木瓜的形状\n  例句：她把面团揉成木瓜状。(그녀는 국수를 망고처럼 만들었습니다.)\n\n- 名词：망고가락 (manggogagak, 木瓜梗) - 指木瓜树上的枝条\n  例句：这个花园里有很多木瓜梗。(이 정원에는 많은 망고가락이 있습니다.)\n\n- 名词：망고슬라이드 (manggosalade, 木瓜沙拉) - 由木瓜和其他水果或蔬菜制成的沙拉\n  例句：我喜欢吃凉拌木瓜沙拉。(나는 망고슬라이드를 좋아해요.)', NULL, 0, NULL, 'src/main/resources/MP3/1720786169030.mp3');
INSERT INTO `word_list` VALUES (342, 33, ' 노래방', 'KTV', '1. 词性：名词\n2. 词义：노래방（no-rae-bang）是韩国语中的词汇，意为“KTV”或“卡拉OK房间”，是一种娱乐场所，人们可以在里面唱歌。\n3. 例句：\n   - 우리는 이번 주 끝나고 노래방에 가서 춤을 추다. (uri-neun i-beon jug-nago no-rae-bang-e ga-seo chum-eul chug-da.) - 我们这个周末去KTV跳舞。\n   - 노래방에서 친구들과 노래를 부르면 좋아요. (no-rae-bang-e-seo chin-gu-deul-gwa nor-eul bu-leo-myeon joh-a-yo.) - 在KTV和朋友们一起唱歌真开心。\n\n4. 变形及其词义：\n   - 노래방에 (no-rae-bang-e) - 在KTV里\n     例句：노래방에서 놀자. (no-rae-bang-e-seo nol-ja.) - 在KTV里玩。\n   - 노래방에서 (no-rae-bang-e-seo) - 从KTV里\n     例句：노래방에서 나왔습니다. (no-rae-bang-e-seo na-wasseubnida.) - 从KTV出来了。\n   - 노래방에서 노래를 (no-rae-bang-e-seo nor-eul) - 在KTV里唱歌\n     例句：노래방에서 노래를 불러요. (no-rae-bang-e-seo nor-eul bul-leo-yo.) - 在KTV里点歌。\n   - 노래방에서 춤을 (no-rae-bang-e-seo chum-eul) - 在KTV里跳舞\n     例句：노래방에서 춤을 추세요. (no-rae-bang-e-seo chum-eul chug-sseuo.) - 在KTV里跳个舞吧。', NULL, 0, NULL, 'src/main/resources/MP3/1720786169588.mp3');
INSERT INTO `word_list` VALUES (343, 33, ' 국수', '面条', '1. 词性：名词 (Noun)\n2. 词义：面条 (Noodles)\n3. 例句：\n   - 침묵한 국수를 먹었다. (I ate the silent noodles.)\n   - 우리는 국수를 좋아해요. (We like noodles.)\n\n变形及其词义：\n1. 국수를 쌉니다 (Kuksu-reul jjimnia) - 泡面 (Boil noodles)\n   - 국수를 쌉니다. (Kuksu-reul jjimnia.) - I boiled the noodles.\n\n2. 국수를 캣핑합니다 (Kuksu-reul kkappinghabnida) - 炒面 (Stir-fry noodles)\n   - 국수를 캣핑합니다. (Kuksu-reul kkappinghabnida.) - I stir-fried the noodles.\n\n3. 국수를 깎습니다 (Kuksu-reul gatjipsseumnida) - 煮面 (Boil and drain noodles)\n   - 국수를 깎습니다. (Kuksu-reul gatjipsseumnida.) - I boiled and drained the noodles.\n\n4. 국수를 비벼습니다 (Kuksu-reul bibatjipsseumnida) - 拌面 (Mix noodles)\n   - 국수를 비벼습니다. (Kuksu-reul bibatjipsseumnida.) - I mixed the noodles.\n\n5. 국수를 파입니다 (Kuksu-reul papimnida) - 捞面 (Dip noodles)\n   - 국수를 파입니다. (Kuksu-reul papimnida.) - I dipped the noodles.', NULL, 0, NULL, 'src/main/resources/MP3/1720786170129.mp3');
INSERT INTO `word_list` VALUES (344, 34, ' 고마워요 ', ' 谢谢', '1. 词性：动词\n2. 词义：表示感激、感谢的意思，相当于汉语中的“谢谢”或“非常感谢”。\n3. 例句：\n- 고마워요， 친구야. (谢谢，朋友啊。)\n- 이것도 고마워요. (这个也谢谢你。)\n\n变形及其词义：\n1. 고마워 (고마워요的简写形式)\n   - 词义：表示感谢或感激的意思。\n   - 例句：고마워， 맛있었어요. (谢谢，很好吃。)\n\n2. 감사합니다 (gamsahabnida)\n   - 词义：表示感谢或感激的意思，比고마워更正式。\n   - 例句：감사합니다， 잘 顽張해주셨습니다. (谢谢，你做得很好。)\n\n3. 谢谢 (xièxiè)\n   - 词义：表示感谢或感激的意思，是汉语中表示感谢的常用词语。\n   - 例句：谢谢你的帮助。(Thank you for your help.)', NULL, 0, NULL, 'src/main/resources/MP3/1720786170697.mp3');
INSERT INTO `word_list` VALUES (345, 34, ' 안녕히 계세요， 잘 생각해주세요 ', ' 再见，请多保重', '1. 词性：动词\n2. 词义：告别，告别时说的话\n3. 例句：안녕히 계세요，잘 생각해주세요（再见，请多保重）\n\n4. 词性：名词\n5. 词义：母亲说的告别话\n6. 例句： motherText= 再见，请多保重\n\n7. 词性：形容词\n8. 词义：没有语法错误，没有拼写错误\n9. 例句：grammer=null, spell=null\n\n10. 词性：数字\n11. 词义：状态，0表示未学习\n12. 例句：state=0\n\n13. 词性：无\n14. 词义：难度未知\n15. 例句：difficulty=null\n\n16. 词性：文件路径\n17. 词义：音频文件路径\n18. 例句：mp3Path=H:\\EduPlatForm\\src\\main\\resources\\MP3\\1720786171337.mp3', NULL, 0, NULL, 'src/main/resources/MP3/1720786171337.mp3');
INSERT INTO `word_list` VALUES (346, 34, ' 미안해요 ', ' 对不起', '1. 词性：形容词\n2. 词义：表示道歉或请求原谅的词语，相当于汉语中的“对不起”。\n3. 例句：\n   - 미안해요， 잘못했어요. (对不起，我做错了。)\n   - 친구에게 물이 났을 때 미안해요라고 말합니다. (当水洒在朋友身上时，会说一句对不起。)\n\n变形及其词义：\n1. 对不起 (mi an hae yo) - 表示道歉或请求原谅的词语。\n2. 抱歉 (byeong-shin) - 表示歉意或道歉的词语。\n3. 不好意思 (bul-seu-bap-neun-de) - 表示因为自己的过失而感到不好意思或道歉的词语。\n4. 对不住 (dwi-eop-seop-ni-da) - 表示因为自己的错误而向对方道歉的词语。\n5. 请原谅 (jeon-hyang-hae-bo-reum-ni-da) - 表示请求对方原谅自己的错误或过失的词语。\n\n例句：\n1. 미안해요， 잘못했어요. (对不起，我做错了。)\n2. 친구에게 물이 났을 때 미안해요라고 말합니다. (当水洒在朋友身上时，会说一句对不起。)\n3. 죄송합니다， 이것은 내가 잘못한 것입니다. (抱歉，这是我做错的事情。)\n4. 이것은 내가 잘못해서 미안해요. (这是我的错误，我很抱歉。)\n5. 이것은 내가 잘못했습니다. 당신의 손상을 진정하게 미안해요. (这是我的错误，我真的很抱歉弄伤了您。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786171899.mp3');
INSERT INTO `word_list` VALUES (347, 34, ' 좋아해요 ', ' 喜欢', '1. 词性：动词\n2. 词义：喜欢，喜爱\n3. 例句：\n   - 我喜欢这个电影。(나는 이 영화를 좋아해요.)\n   - 她喜欢唱歌。(그녀는 노래를 좋아해요.)\n\n变形及其词义：\n1. 形容词形式：좋은 (好的)\n   例句：这是一本好书。(이것은 좋은 책입니다.)\n\n2. 副词形式：좋아졌어 (变得更好了)\n   例句：他最近唱得越来越好了。(그는 최근에는 더욱 좋아졌어요.)\n\n3. 名词形式：취향 (喜好)\n   例句：了解你的喜好是很重要的。(당신의 취향을 알고 있다는 것은 매우 중요합니다.)\n\n4. 助词形式：좋아하고 (喜欢并做某事)\n   例句：我喜欢读书和旅行。(나는 책을 읽고 여행을 좋아해요.)\n\n5. 感叹词形式：좋아해요！ (表示喜欢或赞同)\n   例句：这道菜真好吃！(이 정식은 맛있어요！)', NULL, 0, NULL, 'src/main/resources/MP3/1720786192780.mp3');
INSERT INTO `word_list` VALUES (348, 34, ' 안녕히 계세요， 또 뵙겠습니다 ', ' 再见，下次见', '1. 词性：问候语\n2. 词义：再见，下次见\n3. 例句：안녕히 계세요 (再见)\n   또 뵙겠습니다 (下次见)\n\n变形及其词义：\n1. 안녕히 계세요 - 再见\n2. 또 뵙겠습니다 - 下次见\n3. 안녕히 계세요， 또 뵙겠습니다 - 再见，下次见\n4. 안녕히 계세요？ - 再见吗？\n5. 안녕히 계세요， 잘 가요！ - 再见，一路顺风！\n6. 안녕히 계세요， 또 뵙겠습니다. 잘 가요！ - 再见，下次见。一路顺风！', NULL, 0, NULL, 'src/main/resources/MP3/1720786193513.mp3');
INSERT INTO `word_list` VALUES (349, 34, ' 사랑해요 ', ' 我爱你', '1. 词性：动词\n2. 词义：表示爱或喜欢\n3. 例句：\n- 사랑해요， 나는 당신을 사랑해요.（我爱你，我爱你。）\n- 나는 그사람을 사랑해요.（我喜欢那个人。）\n\n变形及其词义：\n1. 사랑하다 (saranghaeda) - 动词，表示爱或喜欢\n   例句：나는 당신을 사랑합니다.（我爱你。）\n2. 사랑한다 (saranghanda) - 动词，过去式，表示曾经爱过或喜欢过\n   例句：나는 그사람을 사랑했었어요.（我曾经喜欢过那个人。）\n3. 사랑할 것이다 (saranghal geosi da) - 动词，将来时，表示将要爱或喜欢\n   例句：나는 앞으로 당신을 사랑할 거예요.（我将会爱你。）\n4. 사랑하고 싶다 (saranghago sipda) - 动词，想要表达爱或喜欢的意愿\n   例句：나는 당신을 사랑하고 싶어요.（我想要爱你。）', NULL, 0, NULL, 'src/main/resources/MP3/1720786194024.mp3');
INSERT INTO `word_list` VALUES (350, 34, ' 안녕히 계세요， 꼭 연락주세요 ', ' 再见，一定要联系我', '1. 词性：问候语\n2. 词义：表示告别时的礼貌用语，意为“再见”或“再会”\n3. 例句：\n- 안녕히 계세요. (再见，请保重。)\n- 꼭 연락주세요. (一定要联系我。)\n\n变形及其词义：\n1. 안녕히 가세요. (再见，请走好。)\n2. 안녕히 계십시오. (再见，请慢走。)\n3. 안녕히 마세요. (再见，请休息。)\n\n1. 안녕히 계세요. (再见，请保重。)\n2. 안녕히 계십시오. (再见，请慢走。)\n3. 안녕히 마세요. (再见，请休息。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786194543.mp3');
INSERT INTO `word_list` VALUES (351, 34, ' 잘 자요 ', ' 晚安', '1. 词性：形容词\n2. 词义：晚安，睡个好觉\n3. 例句：\n   - 晚上回家后，妈妈对我说：“잘 자요。”（晚上回家后，妈妈对我说：“晚安。”）\n   - 睡前我给朋友发了条短信：“잘 자요。”（睡前我给朋友发了条短信：“晚安。”）\n\n变形及词义：\n1. 变形：副词形式 - 잘 (好好地)\n   词义：适当地，恰当地\n   例句：\n     - 好好学习，好好工作。（好好学习，好好工作。）\n     - 好好照顾自己。（好好照顾自己。）\n\n2. 变形：动词形式 - 자요 (睡觉)\n   词义：进入睡眠状态\n   例句：\n     - 已经很晚了，你该睡觉了。（已经很晚了，你该睡觉了。）\n     - 我昨晚睡得很香。（我昨晚睡得很香。）\n\n请注意，以上例句均为韩文表达。', NULL, 0, NULL, 'src/main/resources/MP3/1720786195148.mp3');
INSERT INTO `word_list` VALUES (352, 34, ' 안녕히 계세요， 많이 드세요 ', ' 再见，多多关照', '1. 词性：问候语\n2. 词义：表示告别时的祝福和关心，相当于中文的“再见”和“多多关照”\n3. 例句：\n   - 안녕히 계세요， 많이 드세요. (再见，多多关照。)\n   - 친구들과 모임을 끝내고 안녕히 계세요. (和朋友聚会结束，再见。)\n\n变形及其词义：\n1. 안녕히 - 副词，表示友好地、亲切地告别，相当于中文的“友好地”、“亲切地”\n   - 例句：안녕히 가세요. (请友好地离开。)\n\n2. 계세요 - 动词短语，表示告别时说的话语，相当于中文的“再见”\n   - 例句：저는 이제 계세요. (我现在要走了，再见。)\n\n3. 많이 - 副词，表示程度，相当于中文的“很多”、“频繁”\n   - 例句：많이 책을 읽어요. (多读书。)\n\n4. 드세요 - 动词短语，表示请求对方做某事，相当于中文的“请”、“麻烦”\n   - 例句：물이 口渴해서 마시지 않도록 드세요. (请不要喝水，我口渴了。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786195789.mp3');
INSERT INTO `word_list` VALUES (353, 34, ' 안녕히 계세요 ', ' 再见', '1. 词性：形容词\n2. 词义：表示“好的”或“顺利的”，用于告别时表示祝愿对方一切顺利。\n3. 例句：\n- 안녕히 계세요. (Annyeonghee gayeseyo.) - 再见，祝你一切顺利。\n- 우리 다음에 만나요. (Uli daeumeun manameyo.) - 我们下次见。\n\n变形及其词义：\n1. 안녕하세요 (annyeonghaseyo) - 你好，用于问候时表示你好。\n2. 안녕히 계세요 (annyeonghee gayeseyo) - 再见，用于告别时表示祝福对方一切顺利。\n3. 안녕히 가세요 (annyeonghee gaseyo) - 安好，用于祝福对方平安离开。\n4. 안녕히 올 것을 (annyeonghee oll geoseul) - 请保重，用于告别时表示希望对方保重身体。\n5. 안녕히 마세요 (annyeonghee maseyo) - 晚安，用于晚上道别时表示祝对方晚安。\n6. 안녕히 보세요 (annyeonghee boseyo) - 再见，用于告别时表示祝福对方一切顺利。', NULL, 0, NULL, 'src/main/resources/MP3/1720786196353.mp3');
INSERT INTO `word_list` VALUES (354, 34, ' 안녕히 계시지만 ', ' 虽然要分别，但祝你一切顺利', '1. 词性：形容词\n2. 词义：表示祝福或道别的话语，相当于中文的“再见”\n3. 例句：\n   - 안녕히 계세요. (再见)\n   - 이젠 별거 없이 안녕히 계세요. (现在没有其他事情了，再见。)\n\n变形及词义：\n1. 안녕히 가세요. (再见)\n2. 안녕히 계시구요. (再见)\n3. 안녕히 마세요. (再见)\n4. 안녕히 갑시다. (再见)\n5. 안녕히 자세요. (晚安，再见)\n6. 안녕히 모세요. (晚安，再见)\n7. 안녕히 서세요. (晚安，再见)\n8. 안녕히 오세요. (晚安，再见)\n9. 안녕히 떠나세요. (晚安，再见)\n10. 안녕히 가세요 잘 자. (晚安，再见，好好休息)', NULL, 0, NULL, 'src/main/resources/MP3/1720786196875.mp3');
INSERT INTO `word_list` VALUES (355, 34, ' 안녕하세요 ', ' 你好', '1. 词性： greeting（问候）\n2. 词义： 你好 (Hello in Korean)\n3. 例句：\n   - 안녕하세요. (Annyeonghaseyo.) - 你好。\n   - 안녕하세요？ (Annyeonghaseyo?) - 你好吗？\n\n变形及其词义：\n1. 안녕히 계세요. (Annyeonghee gyeseyo.) - 再见。\n2. 안녕하십니까？ (Annyeonghaseyo?) - 你好吗？\n3. 안녕하지만... (Annyeonghaseyo...) - 虽然你好...\n4. 안녕하고 계세요. (Annyeonghago gyeseyo.) - 再见。\n5. 안녕하십니다. (Annyeonghaseyo.) - 您好。\n6. 안녕하세요， 어서오세요？ (Annyeonghaseyo, eoseooseoyo?) - 你好，你来了吗？\n7. 안녕하세요， 이름이 무엇인가요？ (Annyeonghaseyo, imeoni museunigayo?) - 你好，你叫什么名字？\n8. 안녕하세요， 어디에 있어요？ (Annyeonghaseyo, eodie isseoyo?) - 你好，你在哪里？\n9. 안녕하세요， 누구예요？ (Annyeonghaseyo, nugugeoyo?) - 你好，你是谁？\n10. 안녕하세요， 잘 자요？ (Annyeonghaseyo, jal jjayou?) - 你好，晚安。', NULL, 0, NULL, 'src/main/resources/MP3/1720786197489.mp3');
INSERT INTO `word_list` VALUES (356, 34, ' 안녕히 계세요， 행복하세요 ', ' 再见，祝你幸福', '1. 词性：问候语\n2. 词义：表示告别时使用的一种礼貌用语，用于表达对别人的祝福和祝愿。相当于中文的“再见”或“拜拜”。\n3. 例句：\n   - 안녕히 계세요， 행복하세요.（再见，祝你幸福。）\n   - 친구들과 모임을 나갔습니다. 안녕히 계세요.（和朋友聚会结束了，再见。）\n\n变形及其词义：\n1. 안녕히 가세요 - 表示离开时的告别语，相当于中文的“再见”或“拜拜”。\n   - 例句：저는 여기서 떠나겠습니다. 안녕히 가세요.（我要离开了，再见。）\n\n2. 안녕히 오세요 - 表示欢迎归来时的问候语，相当于中文的“欢迎回来”或“你回来了”。\n   - 例句：어디에서 갔는지 오래간만이야. 안녕히 오세요.（你去哪了，好久不见。欢迎回来。）\n\n3. 안녕히 마세요 - 表示晚上睡觉前的告别语，相当于中文的“晚安”或“睡个好觉”。\n   - 例句：이봐도 별거 아니야. 안녕히 마세요.（没什么事了，晚安。）\n\n4. 안녕히 계세요 - 表示长时间分别时的告别语，相当于中文的“再见”或“再会”。\n   - 例句：여름방학이 끝나고 시즌을 시작할게요. 안녕히 계세요.（暑假结束了，新学期开始了。再见。）', NULL, 0, NULL, 'src/main/resources/MP3/1720786198145.mp3');
INSERT INTO `word_list` VALUES (357, 34, ' 감사합니다 ', ' 谢谢', '1. 词性：形容词\n2. 词义：感谢的，感激的\n3. 例句：\n   - 감사합니다， 谢谢。\n   - 저는 당신의 도움을 받았습니다. 감사합니다. 我受到了您的帮助，非常感谢。\n\n变形及其词义：\n1. 變形：감사하다 (词义：表示感谢)\n   - 例句：감사합니다， 谢谢。\n2. 變形：감사를 說듯하다 (词义：表示感谢的样子)\n   - 例句：그는 이것을 주었어서 진심으로 감사를 說듯했다. 他给了我这个，所以真诚地表示感谢了。\n3. 變形：감사의 마음을 느끼다 (词义：感受到感激之情)\n   - 例句：나는 그들의 도움에 대해 깊은 감사의 마음을 느끼고 있다. 我对他们的帮助感到非常感激。\n4. 變形：감사한 것이다 (词义：感激之事)\n   - 例句：그는 그것을 주셨어서 나는 그것이 감사한 것이다. 他给了我那个，所以我认为这是一件感激的事情。', NULL, 0, NULL, 'src/main/resources/MP3/1720786198711.mp3');
INSERT INTO `word_list` VALUES (358, 34, ' 안녕 ', ' 再见', '1. 词性：动词\n2. 词义：再见\n3. 例句：안녕하세요 (再见)\n\n变形及其词义：\n- 안녕히 (再见)\n- 안녕히계세요 (再见)\n- 안녕하십니까 (再见)\n- 안녕하세요 (再见)', NULL, 0, NULL, 'src/main/resources/MP3/1720786199272.mp3');
INSERT INTO `word_list` VALUES (359, 34, ' 죄송해요 ', ' 抱歉', '1. 词性：形容词\n2. 词义：表示道歉或请求原谅的词语。\n3. 例句：\n- 죄송해요， 잘 가셨어요. (对不起，你走了。)\n- 이것은 죄송합니다. (这是我的错。)\n\n变形及其词义：\n1. 죄송하다 (词义：感到抱歉，表示歉意)\n   - 例句：나는 미안해요. (我很抱歉。)\n2. 죄송한다 (词义：表示对错误或过失的忏悔)\n   - 例句：나는 내가 잘못했어요. (我知道我做错了。)\n3. 죄송스러운 (词义：令人感到抱歉的、可怜的)\n   - 例句：그 사람은 죄송스러운 상황에 처했어요. (那个人陷入了令人感到抱歉的境地。)\n4. 죄송히다 (词义：感到惭愧或羞耻)\n   - 例句：나는 자신을 죄송하고 있어요. (我感到自己很惭愧。)\n5. 죄송스러운 것 (词义：令人感到抱歉的事物)\n   - 例句：이 사건은 죄송스러운 일입니다. (这是一件令人感到抱歉的事情。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786199836.mp3');
INSERT INTO `word_list` VALUES (360, 34, ' 잘 되살아요 ', ' 保重', '1. 词性：形容词\n2. 词义：表示祝愿对方身体健康、康复。\n3. 例句：\n- 祝你早日康复，잘 되살아요！ (祝你早日康复，好好恢复吧！)\n- 听到你生病的消息，我希望你能好好照顾自己，잘 되살아요！ (听到你生病的消息，我希望你能好好照顾自己，早日康复！)\n\n变形及其词义：\n1. 잘 자 (好好睡) - 表示祝愿对方晚安、好好休息。\n   例句：晚上早点休息，好好睡觉，잘 자！ (晚上早点休息，好好睡觉，晚安！)\n\n2. 잘 먹어 (好好吃) - 表示祝愿对方用餐愉快、吃得好吃。\n   例句：希望你今天能享受美食，好好吃一顿，잘 먹어！ (希望你今天能享受美食，好好吃一顿，吃得好吃！)\n\n3. 잘 가세요 (慢走) - 表示祝愿对方离开时平安。\n   例句：再见，一路平安，잘 가세요！ (再见，一路平安，慢走！)', NULL, 0, NULL, 'src/main/resources/MP3/1720786200417.mp3');
INSERT INTO `word_list` VALUES (361, 34, ' 안녕히 가세요 ', ' 请慢走', '1. 词性：动词\n2. 词义：请慢走，告别时的礼貌用语\n3. 例句：안녕히 가세요. (请慢走。)\n\n变形及词义：\n1. 안녕히 (词义：请慢走)\n   - 例句：안녕히 계세요. (请慢走。)\n\n2. 가세요 (词义：请走)\n   - 例句：저는 여기를 떠나야 합니다. 안녕히 가세요. (我要离开了。请慢走。)\n\n3. 가십시오 (词义：请走)\n   - 例句：이제 일이 끝났습니다. 가십시오. (工作结束了。请走。)\n\n4. 가지마세요 (词义：请不要走)\n   - 例句：더 얼마 있을까요？ 가지마세요. (还有多久？请不要走。)\n\n5. 가지 마세요 (词义：请不要走)\n   - 例句：이것도 필요한가요？ 가지 마세요. (这个也需要吗？请不要走。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786200947.mp3');
INSERT INTO `word_list` VALUES (362, 34, ' 안녕하십니까 ', ' 你好吗', '1. 词性：问候语\n2. 词义：你好，用于表示问候或打招呼。\n3. 例句：\n   - 안녕하십니까？ (Annyeonghaseyo?) - 你好吗？\n   - 안녕하세요！ (Annyeonghaseyo!) - 你好！\n\n变形及词义：\n1. 안녕히 계세요 (Annyeonghi gyesseoyo) - 再见，用于告别时表示友好和礼貌。\n   - 例句：안녕히 계세요， 또 만나요！ (Annyeonghi gyesseoyo, dwae mannayo!) - 再见，下次再见！\n\n2. 안녕하십니까？ (Annyeonghashimnikka?) - 可以用于询问对方是否还好，也可以用于打招呼。\n   - 例句：어제 일이 잘 지내셨어요？ 안녕하십니까？ (Eojeilli ja jinallayesseoyo? Annyeonghashimnikka?) - 你昨天过得好吗？你好吗？\n\n3. 안녕하십니까？ (Annyeonghashimnikka?) - 可以用于询问对方是否还好，也可以用于打招呼。\n   - 例句：안녕하십니까？ 이것은 무엇입니까？ (Annyeonghashimnikka? Igeos-eun mueosimnika?) - 你好，这是什么？\n\n4. 안녕하세요 (Annyeonghashayo) - 你好，用于正式场合或与陌生人打招呼。\n   - 例句：안녕하세요， 네가 무엇을 물어보십니까？ (Annyeonghashayo, nega mueoseul mullobosimnikka?) - 你好，你想问什么？\n\n5. 안녕하십니까？ (Annyeonghashimnikka?) - 可以用于询问对方是否还好，也可以用于打招呼。\n   - 例句：안녕하십니까？ 저는 김수영입니다. (Annyeonghashimnikka? Jeoneun Kim Suyoung-imnida.) - 你好，我是金秀英。', NULL, 0, NULL, 'src/main/resources/MP3/1720786201552.mp3');
INSERT INTO `word_list` VALUES (363, 36, ' 운동화', '运动鞋', '1. 词性：名词\n2. 词义：运动鞋\n3. 例句：\n   - 나는 운동화를 샀어요. (我买了运动鞋。)\n   - 이 운동화는 비싼데， 편한구만 해요. (这双运动鞋很贵，但是很舒适。)\n\n变形及其词义：\n1. 운동화가 (运动鞋的)\n   - 例句：운동화가 신는 것을 좋아해요. (我喜欢穿运动鞋。)\n2. 운동화를 (运动鞋的)\n   - 例句：운동화를 잡고 나갑니다. (拿着运动鞋出发吧。)\n3. 운동화에 (在运动鞋上)\n   - 例句：운동화에 맴드가 생기면 안 돼요. (运动鞋上有磨损就不行。)\n4. 운동화로 (用运动鞋)\n   - 例句：운동화로 운동하세요. (用运动鞋运动吧。)\n5. 운동화를 챙기다 (穿着运动鞋)\n   - 例句：운동화를 챙기다 놀러오세요. (穿着运动鞋来玩吧。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786202151.mp3');
INSERT INTO `word_list` VALUES (364, 36, ' 놀이', '游戏', '1. 词性：名词\n2. 词义：游戏\n3. 例句：\n   - 我喜欢玩游戏。 (나는 게임을 좋아해요.)\n   - 我们一起玩个游戏吧。 (우리 같이 게임을 玩하자구요.)\n\n变形及其词义：\n1. 变形：놀이 (游戏， noun)\n   例句：周末我经常和朋友一起做各种游戏。 (주말에는 나는 친구들과 다양한 게임을 하기도 합니다.)\n\n2. 变形：遊び (游戏， noun)\n   例句：孩子们在公园里玩得很开心，他们喜欢玩各种游戏。 (어린이들은 公園에서 매우 기쁘게 즐겼습니다. 그들은 다양한 게임을 좋아해요.)\n\n3. 变形：게임 (游戏， noun)\n   例句：这个游戏非常有趣，我每天都玩。 (이 게임은 매우 즐거운데， 나는 매일 즐겨玩了呢.)', NULL, 0, NULL, 'src/main/resources/MP3/1720786202619.mp3');
INSERT INTO `word_list` VALUES (365, 36, ' 침대', '床', '1. 词性：名词\n2. 词义：床\n3. 例句：침대(침대) - 이것은 침대입니다. (이것은 베개입니다.)\n\n4. 变形及其词义：\n   - 침대(침대) - 이것은 침대입니다. (이것은 베개입니다.)\n   - 침대(침대) - 이것은 침대입니다. (이것은 베개입니다.)', NULL, 0, NULL, 'src/main/resources/MP3/1720786203198.mp3');
INSERT INTO `word_list` VALUES (366, 36, ' 활동', '活动', '1. 词性：动词\n2. 词义：活动、运动\n3. 例句：\n- 我喜欢参加各种课外活动。(나는 다양한 교과activity를 참여하는 것을 좋아해요.)\n- 健康的身体需要经常进行运动。(건강한 몸은 정상적인 activity가 필요합니다.)\n\n变形及其词义：\n- 활동 (活动): 指参与某种活动或运动的行为，如课外活动、体育锻炼等。\n- 활동 (动作): 指身体或物体所做出的运动或变化，如跳舞、打球等。\n- 활동 (作用): 指事物所产生的效果或影响，如药物的作用、机器的运作等。\n- 활동 (行为): 指人或动物所表现出来的动作或举止，如礼貌的行为、动物的活动等。\n\n例句：\n- 他喜欢参加各种各样的活动。(그는 다양한 activity에 참여하는 것을 좋아해요.)\n- 她每天早上都进行一些简单的运动。(그녀는 매일 早上 activity를 시작합니다.)\n- 这种药有镇静的作用。(이 약은 鎮靜 activity가 있습니다.)\n- 他的行为举止很有礼貌。(그의 behavior는 매우 禮貌합니다.)', NULL, 0, NULL, 'src/main/resources/MP3/1720786203729.mp3');
INSERT INTO `word_list` VALUES (367, 36, ' 운동教練', '运动教练', '1. 词性：名词\n2. 词义：운동教練指的是负责指导和教授运动的教练员。\n3. 例句：\n- 운동教練는 학생들에게 운동을 가르쳐준다. (运动教练向学生们教授运动。)\n- 그는 운동教練이며， 여러 국제대회에서 명성을 떨친 적이 있습니다. (他是运动教练，曾在多个国际比赛中赢得声誉。)\n\n4. 变形及其词义：\n- 운동 (运动) - n. 体育运动或活动\n  例句：나는 매일 아침 운동을 하기로 했습니다. (我决定每天早晨进行运动。)\n- 指導 (指导) - v. 给予指导或指示\n  例句：선생님은 학생들에게 공부를 指導합니다. (老师给学生们指导学习。)\n- 가르치다 (教) - v. 教授或传授知识、技能等\n  例句：이 학교에서는 영어를 가르칠 수 있는 사람이 필요합니다. (这所学校需要能够教授英语的人。)\n- 지도 (指导) - n. 指导或引导\n  例句：이 책은 초등학생들의 학업을 지도하는 책입니다. (这本书是指导小学生学业的书。)\n- 교육 (教育) - n. 教导和培养人的过程\n  例句：교육은 사람의 개발과 발전에 중요한 역할을 합니다. (教育在人的发展和进步中起着重要的作用。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786204242.mp3');
INSERT INTO `word_list` VALUES (368, 36, ' 체력', '体力', '1. 词性：名词\n2. 词义：体力，健康状况\n3. 例句：\n   - 체력이 좋다. (体力好。)\n   - 운동을 하면 체력이 뛰어나고 건강해진다. (做运动可以使体力变好，变得健康。)\n\n变形及其词义：\n1. 체력을 높이다 (提高体力)\n   - 친구들과 같이 운동하면 체력을 높일 수 있다. (和朋友一起运动可以提高体力。)\n\n2. 체력이 低下する (体力下降)\n   - 커피를 너무 마시면 체력이 低下한다. (喝咖啡太多会导致体力下降。)\n\n3. 체력을 소모하다 (消耗体力)\n   - 운동에서는 체력을 소모하게 된다. (运动中会消耗体力。)\n\n4. 체력을 回复する (恢复体力)\n   - 오래 자는 것은 체력을 回复하는 방법이다. (长时间睡觉是恢复体力的方法。)\n\n5. 체력이 급속하게 감소한다 (体力急剧下降)\n   - 비상 상황에서는 체력이 급속하게 감소할 수 있다. (紧急情况下，体力可能会急剧下降。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786204751.mp3');
INSERT INTO `word_list` VALUES (369, 36, ' 운동선수', '运动选手', '1. 词性：名词\n2. 词义：运动选手\n3. 例句：\n   - 운동선수는 매일 아침부터 저녁까지 운동을 합니다. (运动选手从早到晚都在运动。)\n   - 그는 운동선수로서 국제 competiton에 출전했습니다. (他作为运动选手参加了国际比赛。)\n\n变形及其词义：\n1. 운동 - 运动\n   - 词义：进行身体活动以提高健康水平或竞技能力的行为。\n   - 例句：나는 운동을 좋아해요. (我喜欢运动。)\n\n2. 선수 - 选手\n   - 词义：参加比赛或竞争的人。\n   - 例句：이번 대회에서는 우리 학교의 선수들이 모두 출전했습니다. (这次比赛中，我们学校的所有选手都参加了。)\n\n3. 운동선수 - 运动选手\n   - 词义：从事体育运动并参加比赛或竞争的人。\n   - 例句：그는 탁구 선수가 되고 싶어요. (他想要成为一名乒乓球选手。)\n\n4. 운동선수 - 运动员\n   - 词义：从事体育运动并参加比赛或竞争的人。\n   - 例句：그는 축구선수로서 국제 competiton에 출전했습니다. (他作为一名足球运动员参加了国际比赛。)\n\n5. 운동선수 - 选手运动员\n   - 词义：从事体育运动并参加比赛或竞争的人。\n   - 例句：이번 대회에서는 우리 학교의 選手运动员이 모두 출전했습니다. (这次比赛中，我们学校的所有选手运动员都参加了。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786205244.mp3');
INSERT INTO `word_list` VALUES (370, 36, ' 운동기구', '运动器材', '1. 词性：名词\n2. 词义：运动器材\n3. 例句：\n   - 我喜欢在健身房使用各种运动器材锻炼身体。\n   - 这家商店有各种各样的运动器材供顾客选择。\n\n变形及其词义：\n1. 운동기구 (运动器材) - noun (名词)\n2. 운동화 (运动鞋) - noun (名词)\n   - 我需要一双新的运动鞋来参加马拉松比赛。\n3. 운동복 (运动服) - noun (名词)\n   - 这件运动服非常适合我在户外运动时穿着。\n4. 운동관 (体育馆) - noun (名词)\n   - 我们学校的体育馆里有篮球场和羽毛球场。\n5. 운동화 (运动袜) - noun (名词)\n   - 这双运动袜非常舒适，适合跑步时穿着。\n6. 운동액 (运动饮料) - noun (名词)\n   - 我通常在锻炼后喝一些运动饮料来补充能量。\n7. 운동화 (运动帽) - noun (名词)\n   - 这款运动帽可以保护我免受阳光的照射。\n8. 운동화 (运动包) - noun (名词)\n   - 我需要一个大的运动包来装我的运动装备。\n9. 운동화 (运动手套) - noun (名词)\n   - 这些运动手套可以保护我的手免受寒冷天气的伤害。\n10. 운동화 (运动眼镜) - noun (名词)\n    - 这款运动眼镜可以防止阳光刺眼并保护我的眼睛。', NULL, 0, NULL, 'src/main/resources/MP3/1720786205803.mp3');
INSERT INTO `word_list` VALUES (371, 36, ' 운동액세서리', '运动配件', '1. 词性：名词\n2. 词义：运动配件（指用于运动时所使用的辅助物品，如运动鞋、运动服等）\n3. 例句：\n- 운동액세서리를 사지 않으면 운동을 할 수 없습니다. (如果不买运动配件就无法进行运动。)\n- 이 운동액세서리는 비싼 편입니다. (这款运动配件很贵。)\n\n变形及其词义：\n1. 운동액세서리 -> 운동액세서리를 (运动配件 -> 买运动配件)\n   - 例句：운동액세서리를 사지 않으면 운동을 할 수 없습니다. (如果不买运动配件就无法进行运动。)\n\n2. 운동액세서리 -> 운동액세서리가 (运动配件 -> 运动配件是)\n   - 例句：이 운동액세서리는 비싼 편입니다. (这款运动配件很贵。)\n\n请注意，以上例句均为韩文表达。', NULL, 0, NULL, 'src/main/resources/MP3/1720786206329.mp3');
INSERT INTO `word_list` VALUES (372, 36, ' 운동장', '运动场', '1. 词性：名词\n2. 词义：运动场，指供人们进行体育运动的场地。\n3. 例句：\n   - 우리 학교에는 운동장이 있습니다. (我们学校有一个运动场。)\n   - 放学后，我喜欢去运动场打篮球。\n\n变形及其词义：\n1. 운동장(运动场) - 指供人们进行体育运动的场地。\n   - 例句：우리 학교에는 운동장이 있습니다. (我们学校有一个运动场。)\n\n2. 운동장(运动场) - 泛指供人们进行各种活动或聚会的场所。\n   - 例句：이번 방학에는 친구들과 운동장에서 놀아볼 거예요. (这个假期我和朋友约好在运动场玩耍。)\n\n3. 운동장(运动场) - 比喻为竞争激烈的环境或领域。\n   - 例句：그의 전문은 정치가 아니라， 정치적 운동장에서의 군중을 조종하는 것입니다. (他的专业不是政治学，而是控制政治舞台上的人群。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786206933.mp3');
INSERT INTO `word_list` VALUES (373, 36, ' 움직임', '移动', '1. 词性：動詞\n2. 词义：移动\n3. 例句：움직임(移动)\n\n变形及其词义：\n- 이동(이동): 이동하다(移动中)\n- 이동하다(이동中): 이동하다(移动中)\n- 이동하는(이동中): 이동하는(正在移动)\n- 이동하는(正在移动): 이동하는(正在移动)', NULL, 0, NULL, 'src/main/resources/MP3/1720786207615.mp3');
INSERT INTO `word_list` VALUES (374, 36, ' 운동員', '运动员', '1. 词性：名词\n2. 词义：운동員指的是参与运动的人，通常指职业或业余的运动员。\n3. 例句：\n   - 이번 주기왕은 운동員입니다. (这个周冠军是运动员。)\n   - 그는 탁구 운동員로 유명합니다. (他以乒乓球运动员而闻名。)\n\n变形及其词义：\n1. 운동 - 活动、运动\n   - 例句：나는 매일 아침에 운동을 합니다. (我每天早晨都进行运动。)\n\n2. 員 - 成员、人员\n   - 例句：이 팀의 원소는 몇 명인가요？ (这个团队的成员有多少人？)\n\n3. 운동장 - 运动场、操场\n   - 例句：우리 학교는 큰 운동장이 있습니다. (我们学校有一个大的操场。)\n\n4. 운동화 - 运动鞋\n   - 例句：나는 운동화를 사지 않으면 안 돼요. (我不穿运动鞋不行。)\n\n5. 운동관 - 体育馆\n   - 例句：우리 학교의 운동관은 대담하고 깔끔합니다. (我们学校的体育馆很大气又干净。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786208113.mp3');
INSERT INTO `word_list` VALUES (375, 36, ' 근육', '肌肉', '1. 词性：名词\n2. 词义：肌肉（指人或动物体内的组织，主要功能是提供力量和运动）\n3. 例句：\n   - 그는 근육을 빌려서 물건을 들고 다닌다. (他依靠肌肉扛着东西走路。)\n   - 운동을 하면 근육이 더 강해진다. (做运动可以使肌肉变得更强壮。)\n\n变形及其词义：\n1. 形容词形式：근육한 (肌肉发达的)\n   例句：그는 근육한 모습으로 다녀석들에게 힘입어준다. (他以肌肉发达的样子给女孩子们施加了压力。)\n\n2. 动词形式：근육을 만들다 (锻炼肌肉)\n   例句：나는 매일 아침 운동을 하여 근육을 만든다. (我每天早晨运动来锻炼身体。)\n\n3. 名词形式：근육의 모양 (肌肉的形状)\n   例句：그의 근육의 모양은 매우 고화력적이었다. (他的肌肉形状非常有力量感。)\n\n4. 副词形式：근육이라 (肌肉般地)\n   例句：그는 근육이라 움직이는 인간형 로봇을 개발했다. (他开发了一种像肌肉一样活动的仿人体机器人。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786208660.mp3');
INSERT INTO `word_list` VALUES (376, 36, ' 운동보조機器', '运动辅助设备', '1. 词性：名词\n2. 词义：运动辅助设备\n3. 例句：운동보조기계（运动辅助设备）\n\n4. 变形及词义：\n- 1) 운동보조장비 (运动辅助设备)\n- 2) 운동보조장비(들) (运动辅助设备)', NULL, 0, NULL, 'src/main/resources/MP3/1720786209256.mp3');
INSERT INTO `word_list` VALUES (377, 36, ' 운동관', '体育馆', '1. 词性：名词\n2. 词义：指供人们进行体育活动或比赛的场所，通常是一个室内建筑。\n3. 例句1：나는 운동관에서 춤을 추구해요. (我喜欢在体育馆里跳舞。)\n4. 例句2：우리 모임은 매주 수요일에 운동관에서 합니다. (我们每周三在体育馆聚会。)\n\n变形及其词义：\n1. 운동장 (运动场) - 指供人们进行体育活动的室外场地。\n   例句：어린이들은 운동장에서 춘기를 타요. (孩子们在运动场上踢足球。)\n\n2. 체육관 (体育馆) - 指供人们进行体育活动或比赛的室内场所。\n   例句：내가 가장 좋아하는 운동은 스포츠웨이버즈입니다. (我最喜欢的运动是室内攀岩。)\n\n3. 풋볼장 (篮球场) - 指供人们进行篮球运动的场地。\n   例句：우리 학교의 풋볼장은 매우 넓습니다. (我们学校的篮球场很大。)\n\n4. 網球場 (网球场) - 指供人们进行网球运动的场地。\n   例句：나는 매일 저녁에 網球場에서 춤을 추구합니다. (我每天晚上在网球场跳舞。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786209779.mp3');
INSERT INTO `word_list` VALUES (378, 36, ' 운동시리즈', '运动系列', '1. 词性：名词\n2. 词义：运动系列（指一系列相关的体育运动或活动）\n3. 例句：\n   - 我喜欢看这个运动系列的节目。(나는 이 운동시리즈의 프로그램을 좋아해요.)\n   - 这个运动系列包括了足球、篮球和排球。(이 운동시리즈에는 축구， 농구와 탁구가 포함되어 있습니다.)\n\n变形及其词义：\n1. 运动系列 (운동시리즈) - 指一系列相关的体育运动或活动。\n2. 运动系列 (운동시리즈) - 指一系列相关的体育用品或设备。\n3. 运动系列 (운동시리즈) - 指一系列相关的体育赛事或比赛。\n4. 运动系列 (운동시리즈) - 指一系列相关的体育训练或练习。\n5. 运动系列 (운동시리즈) - 指一系列相关的体育规则或指导。\n6. 运动系列 (운동시리즈) - 指一系列相关的体育文化或传统。\n7. 运动系列 (운동시리즈) - 指一系列相关的体育健康或保健。\n8. 运动系列 (운동시리즈) - 指一系列相关的体育娱乐或休闲。\n9. 运动系列 (운동시리즈) - 指一系列相关的体育教育或培训。\n10. 运动系列 (운동시리즈) - 指一系列相关的体育科学或研究。\n\n例句：\n1. 我喜欢看这个运动系列的节目。(나는 이 운동시리즈의 프로그램을 좋아해요.)\n2. 这个运动系列包括了足球、篮球和排球。(이 운동시리즈에는 축구， 농구와 탁구가 포함되어 있습니다.)\n3. 这个运动系列的产品都很受欢迎。(이 운동시리즈의 제품은 모두 인기있습니다.)\n4. 这个运动系列的赛事吸引了很多观众。(이 운동시리즈의 경기는 많은 시청자들을 유치했습니다.)\n5. 这个运动系列的训练项目很有挑战性。(이 운동시리즈의 트레이닝 프로그램은 도전성이 넘습니다.)\n6. 这个运动系列的规则很严格。(이 운동시리즈의 규칙은 엄격합니다.)\n7. 这个运动系列的传统文化很丰富。(이 운동시리즈의 전통문화는 귀중하습니다.)\n8. 这个运动系列的保健方法很有效。(이 운동시리즈의 건강관리 방법은 효과적입니다.)\n9. 这个运动系列的娱乐节目很有趣。(이 운동시리즈의 예능 프로그램은 재미있습니다.)\n10. 这个运动系列的教育培训课程很有帮助。(이 운동시리즈의 교육 과정은 도움이 됩니다.)', NULL, 0, NULL, 'src/main/resources/MP3/1720786210327.mp3');
INSERT INTO `word_list` VALUES (379, 36, ' 스트레스', '压力', '1. 词性：名词\n2. 词义：压力，紧张，焦虑\n3. 例句：\n   - 숨을 막이는 스트레스를 받았다. (承受了喘不过气来的压力。)\n   - 고시를 끝내고 나서는 스트레스가 큽니다. (考完试后感到压力很大。)\n\n变形及其词义：\n1. 形容词形式：스트레잡한 (stressful)\n   - 例句：어려운 과제에 대해 스트레잡했습니다. (因为困难的课题而感到压力。)\n\n2. 动词形式：스트레스하다 (to stress)\n   - 例句：모의고사에 스트레스를 받았습니다. (模拟考试让我感到压力。)\n\n3. 副词形式：스트레스로 (stressfully)\n   - 例句：스트레스로 일하면 건강이 나빠질 수 있습니다. (紧张地工作可能会影响健康。)\n\n4. 名词形式：스트레스 관리 (stress management)\n   - 例句：스트레스 관리는 건강하고 행복한 삶을 살기 위한 중요한 역할을 합니다. (压力管理在维持健康快乐的生活方面起着重要的作用。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786210894.mp3');
INSERT INTO `word_list` VALUES (380, 36, ' 운동', '运动', '1. 词性：名词\n2. 词义：运动\n3. 例句：(1) 운동은 헬스장에서 하는 것입니다. (在健身房里做的一件事。)\n   (2) 운동으로 건강을 유지합니다. (通过运动来保持健康。)\n\n4. 变形：운동선수， 운동선생님， 운동선， 운동带\n   - 운동선수： 축구나 야구 등의 운동선수입니다. (足球和棒球等的运动选手。)\n   - 운동선생님： 운동을 하는 사람입니다. (做运动的人。)\n   - 운동선： 운동을 하는 장소입니다. (做运动的场所。)\n   - 운동带： 운동을 하는 데 사용하는 물질입니다. (用于做运动的物质。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786211524.mp3');
INSERT INTO `word_list` VALUES (381, 36, ' 연습', '练习', '1. 词性：動詞\n2. 词义：연습 (练习)\n3. 例句：나는 매일 연습을 해야 합니다. (我需要每天练习。)\n\n变形及其词义：\n1. 연습하다 (练习中)\n   例句：그는 연습하고 있어요. (他正在练习。)\n2. 연습한 (练习过)\n   例句：많은 사람이 이미 연습한 적이 있어요. (很多人都已经练习过了。)', NULL, 0, NULL, 'src/main/resources/MP3/1720786212112.mp3');
INSERT INTO `word_list` VALUES (382, 36, ' 운동복', '运动服', '1. 词性：名词\n2. 词义：运动服（指用于进行体育运动的服装）\n3. 例句：\n   - 우리는 운동복을 입고 축구를 해요. (We wear sportswear and play soccer.)\n   - 이 운동복은 어떤 옷이에요？ (What kind of clothing is this sportswear?)\n\n变形及其词义：\n1. 운동화 (sport shoes) - 运动鞋\n   - 例句：나는 운동화를 신고 있어요. (I am wearing sport shoes.)\n2. 운동대 (sports bag) - 运动包\n   - 例句：내 운동대에 스포츠 장갑과 휴지가 들어있어요. (My sports bag has sports gear and a towel inside.)\n3. 운동기구 (sports equipment) - 运动器材\n   - 例句：이 운동場에는 다양한 운동기구가 있어요. (This sports field has various sports equipment.)\n4. 운동선수 (athlete) - 运动员\n   - 例句：그는 국제 운동선수이에요. (He is an international athlete.)\n5. 운동관 (gymnasium) - 健身房\n   - 例句：나는 매주 자요일에 운동관에 가요. (I go to the gymnasium every Tuesday.)', NULL, 0, NULL, 'src/main/resources/MP3/1720786212790.mp3');
INSERT INTO `word_list` VALUES (383, 37, ' Poisson ', ' 鱼', '1. 词性：Poisson 是名词。\n2. 词义：鱼。\n3. 例句：\n   - J\'aime manger du poisson. (我喜欢吃鸡鱼。)\n   - Le poisson est un aliment très sain. (鱼是一种非常健康的食物。)\n\n变形及其词义：\n- Poissonner (动词): 钓鱼，捕鱼。\n  - Exemple: Ils vont poissonner le week-end prochain. (他们下周末要去钓鱼。)\n- Poissonnier (名词): 渔夫；卖鱼的人。\n  - Exemple: Le poissonnier vendra des poissons frais au marché.  - Exemple: La poissonière a vendu tout son stock avant midi.- Poissonière (名词): 渔妇；卖鱼的女人。\n (渔夫会在市场卖新鲜的鱼。)\n (这位卖鱼的女士在中午前就卖光了她的存货。)', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1723521587110.mp3');
INSERT INTO `word_list` VALUES (384, 37, ' Oiseau ', ' 鸟', '1. 词性：名词\n2. 词义：鸟\n3. 例句：\n- J\'ai vu un oiseau qui volait dans le ciel.（我看到一只鸟在天空中飞翔。）\n- oiseaux, pl.\n变形及其词义，每个变形一个例句：\n（鸟的复数形式）\n- J\'ai vu des oiseaux sur l\'arbre.- Le chanteur a une voix d\'oiseau.（这位歌唱家有一副悦耳的歌喉。）\n（我看到树上有几只鸟。）\n- oiseler, adj.（与鸟有关的）\n- Cette œuvre d\'art est très oiseler.（这件艺术品与鸟有关。）\n- oiseleur, adj.（捕鸟的）\n- Le marais est un excellent endroit pour oiseleur.（这个沼泽地是捕鸟的好地方。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (385, 37, ' Aigle ', ' 鹰', '1. 词性：\nAigle 是名词。\n\n2. 词义：\nAigle 的意思是“鹰”。\n\n3. 例句：\n- L\'aigle est un oiseau de proie très impressionnant.\n- Le petit aigle apprend à voler sous la supervision de ses parents.\n\n4. 变形及其词义和例句：\n\n  - L\'aiglon commence à sortir des œufs après quelques semaines d\'incubation.\n\n- Aigleur (词义：鹰猎者)\n- Aiglon (词义：小鹰)\n  - Le chasseur qui pratique l\'aiglerie est connu sous le nom d\'aigleur.\n\n- Aiguille (词义：针，指南针)\n  - Prenez soin de ne pas piquer vos doigts avec une aiguille.\n  - La flèche sur ma carte est mon aiguille pour trouver le nord.\n\n注：Aigle 没有其他变形，上述的 \"aiguille\" 是同音异意词，与 \"aigle\" 的意思不同。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (386, 37, ' Lapin ', ' 兔子', '1. 词性：\nLe lapin est un nom masculin (名词，阳性).\n\n2. 词义：\nIl signifie \"兔子\" en français.\n\n3. 例句：\n- Voici un joli lapin brun. (这是一只漂亮的棕色兔子。)\n (小兔子吃掉了我花园里所有的胡萝卜。\n  - Cette douce fille est très lapine.- Lapine (形容词): qui ressemble à un lapin, qui a des qualités du lapin.)\n\n变形及其词义和例句：\n- Le petit lapin a mangé toutes les carottes de mon jardin. (这个温柔的女孩非常像兔子。)\n\n- Lapiner (动词): comporter de façon timide ou sans audace.\n  - Il a l\'air un peu lapiner quand il parle devant le groupe. (他在小组前面讲话时看起来有点胆怯。)\n\n注意：在法语中，“lapiner”是动词形式，表示“表现得像兔子一样胆小”，而“lapine”作为形容词并不常用，且在日常对话中很少会用到。通常，我们使用“lapin”来指代兔子本身。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (387, 37, ' Hibou ', ' 喜鹊', '1. 词性：名词\n2. 词义：猫头鹰\n3. 例句：\n   - J\'ai vu un hibou dans le parc. (我在公园里看到了一只猫头鹰。- Hiboux (名词，复数形式): 猫头鹰们\n)\n\n变形及其词义：\n)\n   - Le hibou est considéré comme un oiseau de nuit. (猫头鹰被认为是一种夜间鸟类。  - Les hiboux sont des oiseaux mystérieux. (猫头鹰们是神秘的鸟类。)\n- Hiboulette (名词，小称形式): 小猫头鹰\n  - La hiboulette a émergé de sa cavité. (小猫头鹰从它的巢穴中出来了。)\n- Hibouler (动词，由名词衍生的动词): 发出猫头鹰般的叫声\n  - Le fou qui hibleule dans la nuit. (那个疯子在夜晚发出猫头鹰般的叫声。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (388, 37, ' Vache ', ' 奶牛', '1. 词性：名词\n2. 词义：母牛，奶牛\n3.- Je vais acheter du lait de vache.\n 例句：\n- La vache est un animal domestique.\n  - 我去买一些牛奶。\n\n  - 母牛是一种家畜。\n变形及其词义：\n- vaches（复数）： 母牛们\n  - Les vaches sont gras dans le pâturage.\n   - 牧场里的母牛们在吃草。\n- vacher (m) : 养牛者，牧牛人\n  - Le vacher mûre ses vaches tous les jours.\n   - 牧牛人每天都会挤牛奶。', NULL, 0, NULL, NULL);
