INSERT INTO `word_list` VALUES (390, 37, ' Bovin ', ' 牛', '1. 词性：名词\n2. 词义：牛（动物）\n3. 例句：Le bovin est un animal domestique très important dans certaines cultures agricoles. （牛是在某些农业文化中非常重要的家畜。）\n4. 变形及其词义：\n   - Bovine（形容词）：与牛相关的，例如：La lait bovine est riche en calcium. （牛奶富含钙质。）\n   - Bovins（复数形式）：指多只牛，例如：Les bovins graissent dans la pâture. （牛群在草地上吃草。）\n   - Bovaine（名词，用于诗歌或文学中）：母牛，例如：Une bovaine paisiblement rumine sous l\'arbre. （一只母牛在树下平静地反刍。）\n\n请注意，法语单词的变形和用法可能根据具体语境有所不同，以上提供了基础的变形和例句。', NULL, 0, NULL, NULL);
