INSERT INTO `word_list` VALUES (396, 37, ' Canard ', ' 鸭', '1. 词性：\nLe mot \"canard\" est un nom masculin.\n\n2. 词义：\nIl signifie \"duck\" en anglais.\n\n3. 例句：\n- Le canard nage dans le lac. (The duck swims in the lake.)\n- J\'ai vu un canard bleu hier. (I saw a blue duck yesterday.)\n\n变形及其词义：\n- Canari (masculin): Un canari est une espèce de canard, souvent utilisé comme petit animal domestique. Exemple: Nous avons un canari qui vient souvent chez nous. (We have a canary that often comes to our house.)\n- Canarie (féminin): Une canarie est un oiseau appartenant à la famille des fringillidés, connu pour sa belle voix. Exemple: Ma sœur a une canarie qui chante très joli. (My sister has a canary that sings very beautifully.)\n- Canarier (masculin): Un canarier est une personne qui élevé des canaries. (My uncle is a canary breeder and owns several canaries.) Exemple: Mon oncle est un canarier et possède plusieurs canaries.', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (397, 37, ' Chien ', ' 狗', '1. 词性：名词\n2. 词义：狗\n3. 例句：\n- J\'ai un chien. (我有一只狗。)\n- Le chien est mon meilleur ami. (狗是我最好的朋友。)\n\n变形及其词义：\n- Chienne (阴性形式，表示母狗)\n  - La chienne est mon meilleur ami. (母狗是我最好的朋友。)\n- Chiens (复数形式，表示多只狗)\n  - Il y a des chiens dans le parc. (公园里有狗。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (398, 37, ' Mouton ', ' 羊', '1. 词性：\nMouton 是名词。\n\n2. 词义：\n在法语中，\"mouton\" 的意思是“绵羊”，指的是这种动物。\n\n3. 例句：\n- Le mouton broute la pelouse.（绵羊在啃食草地。）\n- J\'ai vu un mouton blanc dans le champ.（我在田野里看到了一只白色的绵羊。）\n\n变形及其词义和例句：\n\n- Moutons (复数形式)：\n   词义：多只绵羊\n   例句：Les moutons sont en train de manger l\'herbe.（绵羊们正在吃草。）\n\n- Moutonnier (男性职业者)：\n   词义：牧羊人\n   例句：Le moutonnier surveille ses troupeaux tout le jour.（牧羊人整天都在照看他的羊群。）\n\n- Moutonne (女性或儿童)：\n   词义：母绵羊或小绵羊\n   例句：La petite moutonne est très mignonne.（这只小绵羊很可爱。）\n\n请注意，法语中的单词变形可能因地区和使用情况而有所不同，以上提供的是标准用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (399, 37, ' Coq ', ' 公鸡', '1. 词性：Le mot \"coq\" est un nom masculin.\n2. 词义：\"Coq\" signifie \"rooster\" en anglais.\n3. 例句：\n- Le coq chante le jour à l\'aube. (The rooster crows at dawn.)\n- Le coq était fier et disputait avec les autres oiseaux. (The rooster was proud and argued with the other birds.)\n\n变形及其词义：\n- Coq (nom): Rooster, adult male chicken.\n    Exemple: J\'ai un coq qui chante très tôt le matin. (I have a rooster that crows very early in the morning.)\n\n- Coque (féminin): Hen, adult female chicken.\n    Exemple: La coque pond quand elle dépose des œufs. (The hen clucks when she lays eggs.)\n\n- Coqs (pluriel masculin): Roosters, multiple adult male chickens.\n    Exemple: Il y avait trois coqs dans le jardin. (There were three roosters in the garden.)\n\n- Coques (pluriel féminin): Hens, multiple adult female chickens.\n    Exemple: Le fermier a acheté dix coques pour augmenter sa production d\'œufs. (The farmer bought ten hens to increase his egg production.)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (400, 37, ' Bébé de bœuf ', ' 小牛', '1. 词性：名词（nom）\n2. 词义：小牛，犊牛（un jeune boeuf, généralement jusqu\'à six mois）\n3. 例句：\n   - Le bébé de bœuf joue avec son père dans le pâturage.\n   - Nous avons acheté un bébé de bœuf pour augmenter notre troupeau.\n\n变形及其词义：\n- Bébé (名词)：婴儿，小孩\n   - Cette maman est très proche de son bébé.\n- De (介词)：表示来源、属于等概念\n   - Il vient de la France.\n- Bœuf (名词)：牛肉，牛（成年的）\n   - J\'aime manger de la viande de bœuf.\n- Boeuf (形容词)：像牛一样的，强壮的\n   - Il est très boeuf quand il veut faire attention à sa santé.', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1723611181471.mp3');
INSERT INTO `word_list` VALUES (401, 37, ' Cheval ', ' 马', '1. 词性：\nCheval 是名词。\n\n2. 词义：\nCheval 意为“马”。\n\n3. 例句：\n- J\'ai acheté un cheval pour mon fils. (我为我的儿子买了一匹马。)\n- Le cheval est considéré comme l\'un des meilleurs animaux de compagnie. (马被认为是最好的伴侣动物之一。)\n\n变形及其词义和例句：\n- Chevalier (骑士)：Un chevalier vaillant peut inspirer des sentiments de respect et d\'admiration. (勇敢的骑士能激发尊重和钦佩之情。)\n- Chevalière (女骑士)：La chevalière a montré son courage en bataillant contre les ennemis. (女骑士在与敌人作战时展现了她的勇气。)\n- Chevaux (马的复数形式)：Il a fallu construire un grand écurie pour loger tous ses chevaux. (他不得不建造一个大马厩来容纳他所有的马。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (402, 37, ' Lion ', ' 狮子', '1. 词性：名词\n2. 词义：狮子\n3. 例句：Le lion est un animal sauvage.（狮子是一种野生动物。）\n\n变形及其词义：\n- Lionne（雌狮）\n例句：La lionne est plus grande que le lion.（雌狮比雄狮更大。）\n- Lionnaires（勇敢的人）\n例句：Les lionnaires sont connus pour leur courage.（勇士们以他们的勇气而闻名。）', NULL, 0, NULL, NULL);
