INSERT INTO `word_list` VALUES (405, 38, ' Arbuste ', ' 灌木', '1. 词性：\nArbuste 是名词。\n\n2. 词义：\nArbuste 的意思是灌木丛或灌木。\n\n3. 例句：\n- Il a planté des arbustes le long du mur. (他沿着墙种植了灌木。)\n- L\'arbuste est trop grand pour le pot. (这个灌木对于花盆来说太大了。)\n\n变形及词义：\n- Arbustant, e [形容词]：多灌木的\n  - Exemple : La zone est arbustante et riche en faune sauvage. (这个区域灌木丛生且野生动物丰富。)\n- Arbustiste [名词]：园艺师，专门从事灌木栽培的人\n  - Exemple : L\'arbustiste a conseillé de tailler les arbustes pour qu\'ils gardent leur beauté. (园艺师建议修剪灌木以保持它们的美观。)', NULL, 0, NULL, NULL);
