INSERT INTO `word_list` VALUES (408, 38, ' Arbre de pamplemousse ', ' 柠檬树', '1. 词性：名词\n2. 词义：柚子树\n3. 例句：\n   - J\'ai planté un arbre de pamplemousse dans mon jardin. (我在花园里种了一棵柚子树。)\n   - Les fleurs de l\'arbre de pamplemousse ont une odeur agréable. (柚子树的花闻起来很香。)\n\n变形及其词义和例句：\n- Pamplemousse (名词，柚子)：J\'aime le goût du pamplemousse. (我喜欢柚子的味道。)\n- Pamplemousse (形容词，柚子味的)：J\'adore les boissons pamplemousse. (我喜欢喝柚子味的饮料。)\n- Pamplemoussier (名词，种植柚子的人)：Le pamplemoussier s\'occupe de la culture des arbres de pamplemousse. (种植柚子的人负责照顾柚子树。)', NULL, 0, NULL, NULL);
