INSERT INTO `word_list` VALUES (418, 38, ' Lavande ', ' 薰衣草', '1. 词性：名词\n2. 词义：薰衣草\n3. 例句：\n   - J\'adore le parfum de la lavande. (我喜欢薰衣草的香味。)\n   - Lavande est une plante médicinale très appréciée. (薰衣草是一种非常受欢迎的药用植物。)\n\n变形及其词义：\n- Lavandière (名词，女性，种植薰衣草的人)\n   - Cette lavandière a une ferme de lavande. (这个种植薰衣草的女人有一个薰衣草农场。)\n- Lavandier (名词，男性，种植薰衣草的人)\n   - Le lavandier a fait du savon de lavande. (这个种植薰衣草的男人做了薰衣草肥皂。)\n- Lavandais (形容词，与薰衣草相关的)\n (薰衣草田有一种宜人的香味。   - Les champs lavandais ont une odeur agréable.)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (419, 38, ' Arbre de chene ', ' 柳树', '1. 词性：名词\n2. 词义：橡树\n3. 例句：\n   - L\'arbre de chene est très grand. (橡树非常大。)\n   - Il a planté un arbre de chene dans sa cour. (他在院子里种了一棵橡树。)\n\n变形及其词义和例句：\n- Chêne (名词，橡树)：Ce chêne est très ancien. (这棵橡树非常古老。)\n- Chenes (名词复数，橡树们)：Les chenes sont des arbres robustes. (橡树是强壮的树木。)\n- De chêne (形容词，橡木制的)：Il a une table de chêne. (他有一张橡木桌子。)\n- Du chêne (部分冠词+名词，一些橡树)：Nous avons planté du chêne autour de la maison. (我们在房子周围种了一些橡树。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (420, 38, ' Arbre de sapin ', ' 枫树', '1. 词性：名词\n2. 词义：松树（圣诞树）\n3. 例句：\n   - Nous avons coupé notre arbre de Noël dans la forêt.\n   - L\'arbre de sapin était décoré avec des ornements multicolores.\n\n变形及其词义，每个变形一个例句：\n- Arbreaux (形容词)：关于树的；例句：Les oiseaux se cachent parmi les arbraux.\n- Arbris (名词)：小树丛；例句：Il s\'est caché derrière un arbris.\n- Arbrant (形容词)：产树的；例句：Cette région est arbrante, avec de nombreux pins et sapins.', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (421, 38, ' Arbre ', ' 树', '1. 词性：名词\n2. 词义：树\n3. 例句：\n   - Il y a beaucoup d\'arbres dans le parc. (公园里有很多树。)\n   - Les arbres ont besoin d\'eau pour grandir. (树需要水才能生长。)\n\n变形及其词义：\n- arbre (m.): 树（单数）\n- arbres (mpl.): 树（复数）\n- arbrer (v.): 种树\n- arboral (adj.): 树木的，关于树的\n- arboriculture (n.f.): 造林学，植树学\n\n例句：\n- Je vais planter un arbre dans le jardin. (这所学校提供造林学课程。- Cette école propose des cours d\'arboriculture. (种树是一种愉快的消遣。)\n- L\'arbrer est un passe-temps agréable. (我要在花园里种一棵树。)\n)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (422, 38, ' Arbre de cerisier ', ' 樱桃树', '1. 词性：名词\n2. 词义：樱桃树\n3. 例句：\n   - J\'ai planté un arbre de cerisier dans le jardin.（我在花园里种了一棵樱桃树。）\n   - Les oiseaux se reposent souvent sur l\'arbre de cerisier.（鸟儿们经常在樱桃树上休息。）\n\n变形及其词义和例句：\n- Cérisse（樱桃，名词）：J\'ai mangé une cérisse.（我吃了一颗樱桃。）\n- Cérisan（樱桃色的，形容词）：Elle porte une robe cérisan.））\n- Cériser（樱桃园，名词）：（她穿着一件樱桃色的裙子。Nous allons faire une randonnée dans le cériser.（我们去樱桃园散步。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (423, 39, ' Temps ', ' 温度', '1. 词性：名词\n2. 词义：时间，时刻\n3. 例句：\n   - Il est temps de partir. (现在是时候离开了。)\n   - Nous avons passé un temps agréable ensemble. (我们一起度过了愉快的时光。)\n\n变形及其词义：\n1. Temps (名词) - 时间，时刻\n   - Exemple: J\'ai besoin de temps pour réfléchir. (我需要时间思考。)\n\n2. Temps (形容词) - 时间的，时刻的\n   - Exemple: Une journée parfaite, tout le temps ensoleillé. (完美的一天，阳光明媚。)\n\n3. Temps (副词) - 有时，偶尔\n   - Exemple: Je suis temps en temps à la plage. (我偶尔去海滩。)\n\n4. Temps (动词) - 花费时间，度过时间\n   - Exemple: Elle a passé du temps à lire cet ouvrage. (她花了很多时间阅读这本书。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (424, 39, ' Humidité ', ' 湿度', '无法从大模型获取数据，请联系管理员！', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (425, 39, ' Température maximum ', ' 最高气温', '1. 词性：名词\n2. 词义：最高温度；最热点\n3. 例句：\n   - Quelle est la température maximum prévue pour cette journée?\n     (今天预计的最高温度是多少？)\n   - Le thermomètre indique une température maximum de 35 degrés.\n     (温度计显示最高温度为35度。)\n\n变形及其词义：\n- Température（原形，名词）：温度\n  - Il y a une différence notable entre la température de la mer et celle de la terre.\n    (海洋和陆地的温度之间有明显的差异。)\n\n- Tempérer（动词）：调节温度；使温和\n  - Il faut tempérer la chauffe pour éviter que la sauce ne cuise.\n    (需要调节热度以避免酱汁烧焦。)\n\n- Tempérant（形容词）：温和的；适度的\n  - Cette méthode est très tempérante et ne nuit pas à l\'environnement.\n    (这种方法非常温和，对环境无害。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (426, 39, ' Vent ', ' 风', '1. 词性： 名词\n2. 词义： 风；空气；气氛；趋势\n3. 例句： \n   - Il y a beaucoup de vent ce soir. (今晚风很大。)\n   - Le vent de changement est en train de bouleverser l\'industrie. (变革之风正在颠覆这个行业。)\n\n变形及词义：\n- Ventilateur (名词): 通风器，风扇\n   - J\'ai acheté un ventilateur pour la chambre. (我给房间买了一个风扇。)\n- Ventilation (名词): 通风\n   - La ventilation du local est insuffisante. (这个地方的通风不足。)\n- Venteuset (名词): 风向标\n   - Le venteuset indique le nord. (风向标指向北方。)\n- Ventoyant (形容词): 顺风的\n   - Le voyage sera plus rapide si le vent est ventoyant. (如果风是顺风的话，旅行会更快。)\n\n请注意，法语单词的拼写和语法可能会根据上下文有所变化。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (427, 39, ' Ombre ', ' 阴影', '1. 词性：名词\n2. 词义：阴影、影子；隐蔽处，暗处；幽灵，鬼魂。\n3. 例句：\n   - La lumière du soleil formait une ombre sur le sol.（太阳的光在地面上形成了一个影子。）\n   - Il est resté dans l\'ombre pour éviter d\'être vu.（他留在暗处以避免被看见。）\n\n变形及其词义和例句：\n- 阴性形式：Ombreuse（阴暗的，多阴影的）\n  例句：Cette allée est très ombreuse, même durant le jour.（这条小径即使在白天也很阴暗。）\n- 动词形式：Ombré（使成荫，遮阴）\n  例句：Les arbres ombrent la maison toute l\'après-midi.（树木整个下午都给房子遮阴。）\n- 过去分词：Ombrage（有阴影的，有树荫的）\n  例句：Ce coin ombrage est idéal pour prendre un petit repos.（这个有阴影的角落是休息的理想之地。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (428, 39, ' Vitesse du vent ', ' 风速', '1. 词性：名词短语\n2. 词义：风速\n3. 例句：\n   - La vitesse du vent était tellement forte qu\'elle a détruit tous les arbres de la côte. (风速如此之大，以至于它摧毁了海岸上所有的树。)\n   - Il est important de contrôler la vitesse du vent pour s\'assurer que le parapente se comporte correctement. (控制风速很重要，以确保降落伞正确运作。)\n\n变形及其词义和例句：\n- Vitesse (名词，速度): \n   - Cette voiture peut atteindre une vitesse de 200 km/h. (这辆车可以达到每小时200公里的速度。)\n\n- Vent (名词，风): \n   - Le vent soufflera fort cette nuit. (今晚风会很大。)\n\n- Du (部分冠词，用来表示所谈论的事物属于听话者已知的一类事物): \n   - Tu as besoin de plus de pain ? (你还需要更多的面包吗？)\n\n请注意，\"Vitesse du vent\" 这个短语中的 \"du\" 是 \"de\" 和 \"le\" 结合的缩合形式，用于男性名词前。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (429, 39, ' Neige ', ' 雪', '1. 词性：\nNeige 是名词。\n\n2. 词义：\n- 雪，降雪\n\n3. 例句：\n- Il neige beaucoup en hiver ici.（这里冬天下很多雪。）\n- La neige a recouvert la route de fond en comble.（雪把路完全覆盖了。）\n\n变形及其词义：\n- Neiger（动词）：降雪\n  - Il neige souvent en décembre.（十二月经常下雪。）\n  \n- Neigeuse（形容词）：多雪的\n  - Cette année est très neigeuse.（今年非常下雪。）\n\n- Neigeur（名词）：降雪的人或事物（不常用）\n  - Les conditions météorologiques sont favorables pour un neigeur.（气象条件有利于降雪。）\n\n请注意，\"Neigeur\" 这个形式不太常见，而且在现代法语中几乎不被使用。常见的相关名词形式是 \"neige\" 来指代雪本身。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (430, 39, ' Nuit ', ' 夜', '1. 词性：名词（Nom）\n2. 词义：\n   - 夜晚，晚上\n   - 黑夜\n3. 例句：\n   - \"Il était tard quand il arriva chez lui, la nuit était déjà tombée.\"\n     (他到家时已经很晚了，夜幕已经降临。)\n   - \"La nuit, le silence règne dans la campagne.\"\n     (夜晚，乡村里一片寂静。)\n\n变形及其词义：\n- Nuits (复数形式)：多个夜晚\n  - \"J\'ai passé de belles nuits en vacances.\"\n    (我在假期度过了美好的夜晚。)\n- Nocturne (形容词)：夜间的，夜晚的\n  - \"Le concert nocturne a attiré des milliers de spectateurs.\"\n    (夜间音乐会吸引了成千上万的观众。)\n- Noctambule (名词)：梦游者\n  - \"Le docteur a diagnostiqué que l\'enfant était un noctambule.\"\n    (医生诊断这个孩子是个梦游者。)\n- Nocturne (名词)：夜景画，夜曲\n  - \"Vincent van Gogh a peint plusieurs nocturnes impressionnantes.\"\n    (文森特·梵高画了几幅令人印象深刻的夜景画。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (431, 39, ' Température minimum ', ' 最低气温', '1. 词性：名词短语\n2. 词义：最低温度\n3. 例句：\n   - La température minimum enregistrée à Paris cette nuit est de 5°C. (今晚巴黎记录的最低温度是5摄氏度。)\n   - Il est important de surveiller la température minimum pour protéger les plantes durant l\'hiver. (在冬天，监控最低温度以保护植物是很重要的。)\n\n变形及其词义：\n- Température（名词）：温度\n  - La température varie selon les saisons. (温度随着季节的变化而变化。)\n- Minimum（形容词/名词）：最小的，最低限度\n  - C\'est le minimum que tu peux faire. (这是你能做的最少的事。)\n  - Nous avons atteint le minimum requis pour commencer. (我们达到了开始所需的最低要求。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (432, 39, ' Pollution atmosphérique ', ' 空气污染', '1. 词性：\nPollution atmosphérique 是名词短语。\n\n2. 词义：\nPollution atmosphérique 指的是大气中的污染，通常由工业排放、汽车尾气、燃烧化石燃料等人类活动引起，包括各种污染物如二氧化硫、氮氧化物、颗粒物、碳化合物和重金属等。\n\n3. 例句：\n- La pollution atmosphérique est un problème majeur pour la santé publique. (大气中的污染对公共健康是一个主要问题。)\n- Il est urgent de réduire la pollution atmosphérique pour préserver l\'environnement. (减少大气污染以保护环境是当务之急。)\n\n变形及其词义：\n- Polluer (动词): 引起污染。例：Les usines polluent les rivières en émittant des déchets toxiques. (工厂通过排放有毒废料污染河流。)\n- Polluant (形容词或名词): 污染的；污染物。例：Les substances polluantes sont souvent la cause de graves problèmes de santé. (污染物质常常是严重健康问题的原因。)\n- Pollution (名词): 污染。例：La réduction de la pollution est un objectif mondial. (减少污染是一个全球目标。)\n\n请注意，法语中“Pollution atmosphérique”作为一个专有名词短语，一般不进行变形。上述变形和例句是基于单词“polluer”和“pollution”的常见用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (433, 39, ' Chaud ', ' 热', '1. 词性：形容词\n2. 词义：热的，温暖的；热情的，热烈的\n3. 例句：\n   - Cette eau est trop chaude pour me baigner.（这水太热了，我无法洗澡。）\n   - Il a un cœur chaud et généreux.（他有一颗热情而慷慨的心。）\n\n变形及其词义：\n- Chaude（f.）：热的，温暖的；热情的，热烈的（阴性形式）\n   - Cette chaude soirée a créée une ambiance chaleureuse.（这个温暖的夜晚营造了一种亲切的氛围。）\n\n- Chauder（verb）：变热\n   - La température commence à chauder.（温度开始上升。）\n\n- Chaudron（noun）：大锅\n   - Mets tous les légumes dans le chaudron et fais cuire.（把所有的蔬菜放进大锅里煮。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (434, 39, ' Froid ', ' 冷', '1. 词性：形容词\n2. 词义：寒冷的，冷的；冷淡的\n3. 例句：\n   - Il fait froid dehors.（外面很冷。）\n   - Sa réaction était un peu froide.（她的反应有点冷淡。）\n\n变形及其词义：\n- Froidement（副词）：冷漠地，冷淡地\n  - Il m\'a regardé froidement.（他冷漠地看着我。）\n- Froideur（名词）：寒冷，冷淡\n  - Il y a une froideur dans cette chambre.（这间房间很冷。）\n- Froider（动词）：使冷，变冷\n  - La soupe a froidé.（汤变冷了。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (435, 39, ' Radiation ', ' 辐射', '1. 词性：名词\n2. 词义：辐射，放射；发射，传播\n3. 例句：\n   - Le radiation du soleil peut causer des cicatrices. （太阳的辐射可能导致晒伤。）\n   - La radiation de la télévision influence la culture. （电视的传播影响着文化。）\n\n4. 变形及其词义：\n   - Radiation（原形）：辐射，放射；发射，传播\n     例句：La radiation cosmique est un phénomène complexe. （宇宙辐射是一个复杂的现象。）\n   - Radié（过去分词）：被辐射的，被放射的\n     例句：Les aliments radiés sont souvent considérés comme dangereux pour la santé. （被辐射的食物通常被认为是对健康有害的。）\n   - Radiateur（衍生名词）：散热器，暖气片\n     例句：Il y avait un radiateur dans chaque chambre. （每个房间里都有一个暖气片。）\n   - Radier（动词）：删除，清除；辐射，放射\n     例句：Il a radié toutes les informations sensibles du système. （他删除了系统中所有敏感的信息。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (436, 39, ' Pluie ', ' 雨', '1. 词性：名词\n2. 词义：雨，降雨\n3. 例句：Il pleut souvent en été dans cette région.（夏天这个地区经常下雨。）\n\n变形及词义：\n- Pluieuse (形容词) - 多雨的：Ce pays est très pluvieux en hiver.（这个国家冬天很湿润。）\n- Pluriel (名词) - 复数形式，表示多次降雨或多场雨：Nous avons eu des pluies légères toute la journée.（我们整天都有轻微的雨。）\n- Pluie (动词) - 下雨：Si il pleut demain, nous annulons le match de football.（如果明天下雨，我们就取消足球比赛。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (437, 39, ' Transparence de l\'atmosphère ', ' 大气透明度', '1. 词性：名词\n2. 词义：透明度，清晰\n3. 例句：La transparence de l\'atmosphère permet une vue panoramique sur la montagne.（大气的透明度使得山景一览无余。）\n\n4. 变形及词义：\n- Transparent（形容词）：透明的\n  - 例句：Les verres transparents permettent une lumière naturelle dans la maison.（透明的玻璃让自然光进入屋内。）\n- Transparence（名词）：透明度\n  - 例句：Il est important de maintenir la transparence dans les relations commerciales.（在商业关系中保持透明度很重要。）\n- Transparenter（动词）：使透明\n  - 例句：Le gouvernement a commité des efforts pour transparenter ses opérations financières.（政府致力于使其财务运作更加透明。）\n- Transparencement（副词）：透明地\n  - 例句：Cette pièce a été construite avec des matériaux transparents, permettant un espace lumineux.（这个房间使用了透明材料建造，使得空间明亮。）\n- Transparencent（形容词）：半透明的\n  - 例句：Les rideaux transparencents assurent une luminosité douce dans la pièce.（半透明的窗帘确保了房间内柔和的光线。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (438, 39, ' Lumière ', ' 光', '1. 词性：名词\n2. 词义：光，光线；照明；灯；智慧，知识\n3. 例句：\n   - La lumière du jour pénétre dans la pièce.（日光穿透了房间。）\n   - Il y avait une lumière qui brillait dans la nuit.（在夜晚有一束光在闪烁。）\n\n变形及其词义：\n- Lumineuse（形容词）：发光的，明亮的\n  - Cette lampe électrique est très lumineuse.（这盏电灯非常亮。）\n- Luminaire（名词）：灯具，照明设备\n  - Les luminaires de la route étaient toutes en fonctionnement.（路上的灯具都在运作。）\n- Eclairer（动词）：照亮，使明亮\n  - Le soleil éclairait la forêt.（太阳照亮了森林。）\n- Ombre（名词）：阴影，影子\n  - L\'ombre de l\'arbre cachait le soleil.（树的影子遮挡了阳光。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (439, 39, ' Météo ', ' 天气', '1. 词性：\nMétéo 是名词。\n\n2. 词义：\n- 天气，气候\n- 气象学\n\n3. 例句：\n- Quel temps fait-il dehors? J\'espère que la météo sera bonne pour le week-end.\n  （外面天气怎么样？我希望周末的天气会好。）\n- Je consulte souvent la météo avant de partir en vacances.\n  （在出发去度假之前，我经常查看天气预报。）\n\n变形及词义：\n- Météorologue（气象学家）：专门研究气象学的科学家。\n  - Mon frère est météorologue, il prédit souvent les orages.\n    （我的兄弟是气象学家，他经常预测暴风雨。）\n\n- Météorologie（气象学）：研究大气状态和大气现象的科学。\n  - L\'université où j\'étudie offre un programme en météorologie.\n    （我就读的大学有一个气象学课程。）\n\n- Météorologique（气象的）：与气象或气象学有关的。\n  - Les variations météorologiques ont un impact significatif sur l\'agriculture.\n    （气象变化对农业有重大影响。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (440, 39, ' Jour ', ' 天', '1. 词性：\nLe mot \"jour\" en français est un nom masculin (nom).\n\n2. 词义：\n- Temps durant lequel la Terre tourne sur elle-même une fois, soit 24 heures.\n- Période allant du lever du jour à l\'aube du lendemain.\n- Lumière, clarté.\n\n3. 例句：\n- Aujourd\'hui est un beau jour. (今天是美好的一天。)\n- Il a passé sept jours en vacances. (他度过了七天的假期。)\n\n变形及其词义和例句：\n- Journal (nom): Jour par jour, tous les jours. Exemple: Lire un journal quotidien. (阅读日报。)\n- Journée (nom): Une période de temps désignée comme une journée; la partie de la journée consacrée à un certain travail ou activité. Exemple: Une journée très agréable. (非常愉快的一天。)\n- Journer (verbe): Travailler pendant une journée. Exemple: Les ouvriers ont journé pendant huit heures. (工人们工作了八小时。)\n\n请注意，以上提供的是法语单词“jour”的基本用法和一些常见变形。在实际应用中，这些单词和表达方式可能有更多的细节和语境相关的用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (441, 39, ' Soleil ', ' 太阳', '1. 词性：\nLe soleil est un nom masculin (名词，阳性).\n\n2. 词义：\n- 天体：太阳\n- 阳光\n- 日光\n- 白天\n- 中心人物，核心\n\n3. 例句：\n- En hiver, le soleil ne paraît que pendant peu de temps. (冬天，太阳出现的时间很短。)\n- Nous avons passé la journée à la plage pour profiter de la lumière du soleil. (我们花了一天时间在海滩上享受阳光。)\n\n变形及其词义和例句：\n- Soleillé(e) (形容词) - 被阳光照射的\n  - Cette chambre est très soleillée. (这个房间阳光很充足。)\n- Soleiler (动词) - 曝晒于阳光下\n  - Il aime se soleiler dans le jardin. (他喜欢在花园里晒太阳。)\n- Soleilné(e) (形容词) - 经常晒太阳的\n  - Les gens soleilnés ont souvent une peau brune. (经常晒太阳的人通常皮肤是棕色的。)\n\n请注意，法语中的变形取决于性别和单复数，以上列出的是一些基本形式。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (442, 39, ' Pression atmosphérique ', ' 气压', '1. 词性：名词\n2. 词义：大气压力\n3. 例句：\n   - La pression atmosphérique est mesurée en héctopascals (hPa).\n   - Le baromètre indique la pression atmosphérique actuelle.\n\n变形及其词义：\n- Pression（名词）：压力\n  - Exemple: Il y a une haute pression qui dominera la région pendant les prochains jours.\n\n- Atmosphérique（形容词）：大气的\n  - Exemple: Les changements climatiques ont un impact significatif sur l\'atmosphère atmosphérique.\n\n- Atmosphère（名词）：大气，气氛\n  - Exemple: L\'atmosphère de la soirée était très chaleureuse et conviviale.\n\n请注意，\"Pression atmosphérique\" 是一个名词短语，而不是一个单一的可变形法语单词。因此，我们只能提供组成这个短语的各个单词的变形和词义。', NULL, 0, NULL, NULL);
