INSERT INTO `word_list` VALUES (873, 81, ' 雲', '云', '1. 词性：名詞（名词）\n2. 词义：雲（くも）是指天空中漂浮的水蒸气凝结成的白色或灰色的物体。通常在天气变化时可见，如晴朗、多云或下雨天。\n3. 例句：\n   - あの山の上には雲がたくました。（那座山顶被云覆盖了。）\n   - 空を飛んでいる雲は白くてきれいですね。（飘在空中的云真白，也很漂亮呢。）\n\n变形及词义：\n- 雲が（连用形）：用于连接其他词语，表示动作的对象。\n  - 例句：空に浮かぶ雲が流れている。（漂浮在天空中的云正在流动。）\n\n- 雲だ（连体形）：用于修饰名词，表明所属或属性。\n  - 例句：青い空に浮かぶ白い雲だ。（漂浮在蓝天上的是白色的云。）\n\n- 雲に（副词的に形）：表示方向、对象、目的等。\n  - 例句：私は空を見て、雲に夢を託そうと思った。（我看着天空，想将梦想寄托给云。）\n\n- 雲を（宾格）：表示动作的直接对象。\n  - 例句：子供たちは公園で雲を追いかけて遊んでいる。（孩子们在公园里追逐着云玩耍。）\n\n- 雲と（并列形）：用于列举或并列。\n  - 例句：空に浮かぶのは雲と霞です。（漂浮在天空的是云和霞。）\n\n请注意，以上变形并非日语中所有可能的变形，而是一些常见的变形示例。每个变形的词义与原词“雲”的基本意义相关联，但根据句子结构和语境有所不同。', NULL, 1, NULL, 'src\\main\\resources\\sound\\1721313028535.mp3');
INSERT INTO `word_list` VALUES (874, 81, ' 雷', '打雷', '1. 词性：名詞\n2. 词义：雷、雷电\n3. 例句：\n   - 雷が鳴る。（ thunder rumbles）\n   - 夏は雷が多い。（ Summer has a lot of thunder.）\n\n变形及词义：\n- 雷雨（らいう）： thunderstorm\n  - 例句：明日は雷雨の予報だ。（ Tomorrow is forecasted to have a thunderstorm.）\n- 雷電（らいでん）： thunder and lightning\n  - 例句：昨夜の雷電は怖かった。（ Last night\'s thunder and lightning were scary.）', NULL, 1, NULL, 'src\\main\\resources\\sound\\1721313029358.mp3');
