INSERT INTO `word_list` VALUES (880, 81, ' 天気予報', '天气预报', '1. 词性：名词\n2. 词义：天气预报\n3. 例句：\n   - 今朝の天気予報を聞いたから、今日は晴れるそうだ。\n     (听了今天早上的天气预报，今天好像会是个晴天。)\n   - 天気予報によると、明日から雨が降り出すそうです。\n     (根据天气预报，明天开始要下雨了。)\n\n变形及其词义：\n- 天気予報について (关于天气预报)\n  - 例文：天気予報について話し合わなくちゃ。\n    (我们得讨论一下天气预报。)\n- 天気予報を見る (看天气预报)\n  - 例文：每朝、新聞を買ってから天気予報を見るのが習慣です。\n    (每天早上买报纸后看天气预报是我的习惯。)\n- 天気予報を信じる (相信天气预报)\n  - 例文：私は天気予報を信じません。\n    (我不相信天气预报。)', NULL, 1, NULL, 'src\\main\\resources\\sound\\1721313032970.mp3');
INSERT INTO `word_list` VALUES (881, 81, ' 雾', '雾', '1.词性：名詞\n2.词义：地面近傍で気温が低く、多量の水分を含んだ空気中に水蒸気が冷凝して生じる小さい水滴または氷晶の集合体。視界を悪くする。\n3.例句：\n- 今朝、家の前に霧がかかっていた。\n- 霧が晴れたら、美しい景色が見えるだろう。\n\n4.变形及其词义：\n- 霧立ち（きりだち）：霧が生じること。例：冬の夜に霧が立ちます。\n- 霧深い（きりふかい）：霧が濃厚で見通しが悪い状態。例：霧が深く、前も見えない。\n- 霧吹き（きりぶき）：霧が流れ出ること。例：朝の冷たさにより、湖面から霧が吹き出した。', NULL, 1, NULL, NULL);
INSERT INTO `word_list` VALUES (882, 81, ' 気温', '气温', '1. 词性：名词\n2. 词义：気温（きおん）是指大气的温度，通常用来描述天气的冷暖程度。\n3. 例句：\n   - 今日の気温はどのぐらいですか？\n   - （今天气温多少度？）\n   - 冬になると、気温が下がります。\n   - （冬天到了，气温会下降。）\n\n关于気温的变形及其词义：\n\n- 気温計（きおんけい）：名词，指测量气温的仪器，即温度计。\n  - 例句：外の気温を知りたい時は、気温計を見ることができます。\n     （想知道外面的气温时，可以看温度计。）\n\n- 気温変化（きおんへんか）：名词，指气温的变化。\n  - 例句：最近、気温変化が激しくて、服を着替えるのが大変です。\n     （最近气温变化剧烈，换衣服很麻烦。）\n\n- 低気温（てきおん）：名词，指低温状态。\n  - 例句：冬山では、低気温が続くことがあります。\n     （在雪山上，有时会持续低温。）\n\n- 高気温（こうきおん）：名词，指高温状态。\n  - 例句：夏は高気温が続くので、水を飲むことが重要です。\n     （夏天会持续高温，所以喝水很重要。）\n\n以上是“気温”的一些基本用法和变形，每个变形都带有其特定的词义和用法。希望这些信息对你有所帮助！', NULL, 1, NULL, 'src\\main\\resources\\sound\\1721313039173.mp3');
INSERT INTO `word_list` VALUES (950, 4, ' 팥 ', ' 胡椒', '1. 词性：\n팥은 명사입니다. (名词)\n\n2. 词义：\n- 담쟁이나 딱따라 만든 것. （由竹子或木头制成的）\n- 딱따가로 제조된 물품. （用竹子制成的物品）\n- 딱따를 열어서 사용하는 것들의 약자. （用竹子制作的物品的统称）\n\n3. 例句：\n- 저는 친환에서 팥을 살리고 있습니다. (我在厨房里用筷子吃饭。)\n- 팥이 군데록 좋은 것 같아요. (筷子看起来很结实。)\n\n变形及其词义与例句：\n- 팥 막기： 把竹子劈开做成筷子的动作。\n  - 예： 나는 딱따을 막아 팥을 만들었어요. (我把竹子劈开做了筷子。)\n  \n- 팥 세우기： 挑选好的竹子来制作筷子。\n  - 예： 우리는 좋은 딱따를 세워 팥을 만들었어요. (我们挑选了好的竹子来制作筷子。)\n\n- 팥 짜기： 用刀削整竹子，使其变成筷子形状的过程。\n  - 예： 나는 딱따을 째고 팥을 만들었어요. (我用刀削整竹子，制作了筷子。)\n\n注意：韩语中的“팥”主要指的是筷子，而它的变形通常涉及到制作筷子的不同步骤。由于“팥”本身是一个名词，它没有动词形态的变化，所以这里提供的变形是与之相关的动词形态，描述与筷子制作相关的动作。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (951, 4, ' 새우 ', ' 沙参', '1. 词性：\n- 새우는 명사 (名词)입니다.\n\n2. 词义：\n- 새우는 \"新闻\"를 뜻하며， \"消息\", \"信息\", \"报道\" 뿐만 아니라 \"新闻节目\" 또한 포함됩니다.\n\n3. 例句：\n- 새우를 보고 싶습니다. (我想看新闻。)\n- 오늘의 새우에는 중요한 報道이 있었습니다. (今天的新闻中有重要的报道。)\n\n變形及其词义：\n- 새우로： 副词，用于表示“以新闻的形式”或“通过新闻”。\n  - 새우로 알าм익을 받았다. (我通过新闻得知了那个消息。)\n\n- 새우성： 名词，指新闻性或新闻价值。\n  - 이 사건은 커지шن 새우성을 가지고 있다. (这个事件具有很高的新闻价值。)\n\n- 새우편： 名词，指一条新闻或新闻报道的一部分。\n  - 이 새우편은 사회적으로 중요한 것입니다. (这则新闻对社会来说很重要。)\n\n- 새우보도： 名词，指新闻报道的行为或过程。\n  - 새우보도는 정확하게 사실을 전달해야 합니다. (新闻报道应该准确地传达事实。)', NULL, 0, NULL, NULL);
