INSERT INTO `word_list` VALUES (956, 4, ' 계란 ', ' 桔子', '1. 词性：\n- 体词（名词）\n- 依存词（助词）\n\n2. 词义：\n- 体词：柿子，番茄\n- 依存词：表示比较的对象或标准\n\n3. 例句：\n- 体词：앞에서 계란이 많이 있어요. (前面有很多柿子。)\n- 依存词：이 사람보다 그 사람은 더 잘해요. (比起那个人，这个人做得更好。)\n\n变形及其词义：\n- 가嫌（名词）：柿子树\n  - 가嫌이 아래엇다. (柿子树下很凉快。)\n- 곶（名词）：番茄\n  - 곶를 많이 먹어요. (我吃了很多番茄。)\n- 나嫌（名词）：西红柿\n  - 나嫌을 씀하면 좋아요. (用西红柿比较好。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (957, 4, ' 볼т ', ' 面包', '1. 词性：\n- 볼т는 이름 (名词)입니다.\n\n2. 词义：\n- 주로 \"귀찮은 감정\" 또는 \"불편한 감정\"을 의미합니다.\n\n3. 例句：\n- 나는 그 사람에게 대한 볼트를 느껴 보인다. (我对那个人感到厌烦。)\n- 이 책은 너무 볼트하고， 읽을 수 없었습니다. (这本书太无聊了，我读不下去。)\n\n變形 및 해씨：\n- 볼트하�ра (动词): 볼트할 것을 의미합니다.\n  - 그 사람의 행동으로서 나는 볼트하였다. (那个人的行为让我感到厌烦。)\n\n- 볼트하다 (形容词): 볼트일 것을 의미합니다.\n  - 이 책은 너무 볼트하다. (这本书太无聊了。)\n\n- 볼트한 (形容词): 볼트지만 좋은 것을 의미합니다.\n  - 그 영화는 볼트한 것이지만， 우�여하지 않았다. (那部电影虽然有些无聊，但并不难看。)', NULL, 0, NULL, NULL);
