INSERT INTO `word_list` VALUES (960, 4, ' 삼겹살', '三文鱼片', '1. 词性：名词\n2. 词义：三重杀（指在体育比赛中，一名运动员连续三次击败对手）\n3. 例句：\n   - 이 선수는 삼겹살에 성공했습니다. (这位选手成功地实现了三重杀。)\n   - 그가 삼겹살을 이루고 있어 팀의 승리를 확정했습니다. (他成功完成了三重杀，为球队的胜利奠定了基础。)\n\n变形及词义：\n- 삼겹살하다 (动词): 进行三重杀\n  - 예： 그 선수는 삼겹살하고 있었다. (那位选手正在进行三重杀。)\n- 삼겹살한 (形容词): 完成三重杀的\n  - 예： 삼겹살한 선수들은 탁시를 받았다. (完成三重杀的选手们获得了奖杯。)\n\n以上是基于您提供的“三重杀”这一概念的解释和例句。需要注意的是，“삼겹살”并不是一个常见的韩语词汇，所以这里假设它是一个专有名词或术语，用于特定的情境或领域。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (961, 4, ' 쌀가지', '炒饭', '1. 词性：名詞\n2. 词义：釘子\n3. 例句：\n   - 쌀가지를 막다. (钉上钉子。)\n   - 쌀가지로 굽기를 붙이다. (用钉子固定画框。)\n\n变形及其词义：\n- 쌀： 钉子的材料，如铁钉、木钉等。\n  - 쌀을 사용하여 굽기를 붙인다. (使用钉子固定画框。)\n- 가지： 指小的钉子，通常用于精细的工作。\n  - 가지로 책장에 깃끗하게 굽기를 붙인다. (用小钉子整齐地固定在书架上。)\n- 쌀고리： 指较大的钉子，常用于建筑或重型工作。\n  - 쌀고리로 침대의 밑부를 정固有하게 붙인다. (用大钉子牢固地固定床底。)', NULL, 0, NULL, NULL);
