INSERT INTO `word_list` VALUES (964, 4, ' 닭꺼리', '烤鸡腿', '1. 词性：名词\n2. 词义：鸡笼，笼子（用于装鸡等家禽的容器）\n3. 例句：\n   - 닭꺼리에 닭을 넣어 잠자리를 줍니다. (把鸡放进鸡笼里，让它们睡觉。)\n   - 우리 집에는 닭꺼리가 두 개있어요. (我们家有两个鸡笼。)\n\n变形及其词义：\n- 닭꺼리(单数形式)：一个鸡笼\n  - 예쁜 닭꺼리를 만들어야 합니다. (需要做一个漂亮的鸡笼。)\n\n- 닭꺼리들(复数形式)：多个鸡笼\n  - 닭꺼리들을 정리하고 청소해야 합니다. (需要整理并清洁这些鸡笼。)\n\n- 닭꺼리에(处所形式)：在鸡笼里\n  - 닭꺼리에 닭이 수시가 나嗳哟. (鸡在鸡笼里下蛋了。)\n\n目前没有发现其他变形。韩语中名词的变形相对有限，通常涉及单复数的变化或与介词的结合使用。', NULL, 0, NULL, NULL);
