INSERT INTO `word_list` VALUES (966, 4, ' 떡국', '年糕汤', '1. 词性：名词\n2. 词义：年糕，米糕\n3. 例句：\n   - 나는 떡국을 좋아합니다. (我喜欢年糕。)\n   - 떡국이 많이 있어요. (这里有很多年糕。)\n\n变形及其词义：\n- 떡국이 (年糕的定语形式)：年糕的\n   - 떡국이 칼국수를 좋아해요. (我喜欢辣炒年糕。)\n- 떡국에 (年糕的副词形式)：年糕\n   - 나는 떡국에 많이 먹어요. (我吃了很多年糕。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (967, 4, ' 삼다주', '参鸡汤', '1. 词性：\n- 삼다주 是韩国的地名，因此其作为专有名词（固有名词）。\n\n2. 词义：\n- 삼다주： 指的是位于韩国的一个地方名称。\n\n3. 例句：\n- 나는 삼다주에서 살아요. (我住在三多住)\n- 삼다주는 어딘가 이름이 좋아요？ (你喜欢三多住的哪里？)\n\n变形及其词义：\n- 由于\"삼다주\"是一个地名，它没有变形。地名通常保持原样不变，不涉及动词或形容词那样的变形。\n\n每个变形一个例句：\n- 如上所述，\"삼다주\"作为一个地名，不存在变形。因此没有额外的例句提供。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (968, 4, ' 탕수', '糖水', '1. 词性：\n탕수 - 名词\n\n2. 词义：\n- 灯台\n- 灯塔\n- 烛台\n- 灯座\n\n3. 例句：\n- 이 빛이 좋은 곳에 탕수를 세우세요. (请在这个光线好的地方放置一个灯台。)\n- 해안에 탕수가 많이 있어 야경을 지켜줍니다. (海边有很多灯塔，可以帮助船只夜间导航。)\n\n变形及词义：\n- 탕수는 - 灯台的（所有格形式）\n  - 그 탕수는 빛이 아주 밝은 것입니다. (那个灯台的光非常亮。)\n- 탕수로 - 作为灯台（副词形式）\n  - 탕수로 설치된 빛은 매우 중요합니다. (作为灯台设置的灯光非常重要。)\n- 탕수를 - 把灯台（宾格形式）\n  - 암컷에서 탕수를 봐요. (从灯塔上看灯台。)\n\n请注意，韩语中名词通常没有像英语那样的复数形式或复杂的时态变化。名词的变形主要涉及与动词结合时的助词使用，以表达不同的语法关系。上述例句展示了如何将“탕수”（灯台）与不同的助词结合来表达所有格、副词和宾格关系。', NULL, 0, NULL, NULL);
