INSERT INTO `word_list` VALUES (1000, 98, ' 메イン스토리 ', ' 主线故事', '1. 词性：\n- 메イン스토리 (Main Story) 是一个名词短语。\n\n2. 词义：\n- 主要故事，主线剧情。\n\n3. 例句：\n- 이 애니멀한 메イン스토리가 영화의 흥미를 더하는 것입니다.\n  - 这个迷人的主线剧情增加了电影的吸引力。\n- 小説의 메イン스토리는 완벽하게 구성되어 있습니다.\n  - 小说的主线剧情构成得非常完美。\n\n4. 变形及其词义和例句：\n- 메イN스토리： 名词原形，表示“主要故事”或“主线剧情”。\n  - 예고에서 알려진 메인스토리가 이 영화에 대한 기대를 느껴게 해요.\n    - 预告片中透露的主线剧情使人们对这部电影充满期待。\n\n- 메INSTORY: 错误形式，通常不使用这种缩写形式。\n\n- 메IN스토RИ： 错误形式，通常不使用这种缩写形式。\n\n- 메IINSTORY: 错误形式，通常不使用这种缩写形式。\n\n- 메IIN스TОRY: 错误形式，通常不使用这种缩写形式。\n\n- 메IИN스TORY: 错误形式，通常不使用这种缩写形式。\n\n- 메IİN스TORY: 错误形式，通常不使用这种缩写形式。\n\n- 메IIIN스TORY: 错误形式，通常不使用这种缩写形式。\n\n由于\"메イNス토리\"是外来词（英文 \"Main Story\"）的音译，在韩语中没有变形的概念。因此，除了原形外，没有其他变形形式。它作为一个固定短语被使用，不像动词或形容词那样有变形。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1001, 98, ' 부스 ', ' 老板（游戏中的最终敌人）', '1. 词性：\n부스는 이름（名词）입니다.\n\n2. 词义：\n부스는 \"风格\" 또는 \"气氛\"를 의미합니다.\n\n3. 例句：\n- 그 쇼핑몰은 특별한 구성 부스가 있습니다.\n- 이 작은 셀프로우보고， 좋은 부스를 냈겠어요.\n\n变形及其词义：\n- 부시 (noun): 风格，气氛的另一种表达方式。\n  - 예： 이 방에는 특별한 부시가 있습니다.\n\n- 부스적 (adjective): 描述有某种风格或气氛的。\n  - 예： 그 곡은 부스적인 멜로디가 있습니다.\n\n- 부스를 낼 (verb): 采取或表现出某种风格或气氛。\n  - 예： 웨이브 컴퓨터의 디자인에서 새로운 부스를 낼 것이 좋습니다.\n\n注意：韩语中的单词变形可能不遵循英语中常见的规则，上述变形是假设性的，用于展示如何在不同语境中使用该单词。实际上，“부스”这个词在韩语中并没有直接的变形形式，它通常作为一个独立的名词使用。', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1724065371797.mp3');
INSERT INTO `word_list` VALUES (1002, 98, ' 單機 ', ' 单机', '1. 词性：名詞（Noun）\n2. 词义：단기（单机）\n3. 例句：\n   - 이 컴퓨터는 단기로 설정되어 있습니다.（这台电脑被设置为单机。）\n   - 단기 모드로 사용하면 안정성이 높습니다.（使用单机模式的话，稳定性更高。）\n\n变形及其词义：\n- 단기화（单机化）：使成为单机的过程或状态\n  - 컴퓨터를 단기화 시져 요청을 받았습니다.（我们收到了将电脑单机化的请求。）\n\n以上是根据给定的要求进行的解析和推导，每个部分都清晰地展示了词性、词义和相关例句。由于“單機”在韩语中主要用作名词，并且没有常见的动词或其他形式的变形，所以只提供了一种变形形式。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1003, 98, ' MP ', ' 魔法值', '1. 词性：\nMP (엠피) - 名词（Noun）\n\n2. 词义：\nMP - 通常指“议员”（Member of Parliament）的缩写，也可以指其他含义，如“音乐播放器”（Music Player）等，根据上下文而定。\n\n3. 例句：\n- 그는 국회의 중요한 MP이다. (He is an important MP in the parliament.)\n- 이 핸드폰에는 MP 기능이 있어요. (This phone has an MP function.)\n\n变形及其词义和例句：\n- MPing - 没有这个变形，因为MP是缩写词，不适用进行时态变化。\n- MPed - 没有这个变形，因为MP是缩写词，不适用过去时态变化。\n- MPer - 表示拥有或使用MP的人，例如音乐播放器的用户。\n  - MPer가 音楽을 듣고 있어요. (The MPer is listening to music.)\n\n请注意，由于MP是一个缩写词，它并没有像动词那样有复杂的变形。在韩语中，名词通常不会有变形，除非与其他词汇结合形成复合词或派生词。', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1724065387573.mp3');
INSERT INTO `word_list` VALUES (1004, 98, ' 콘솔 ', ' 控制台', '1. 사전：\n2. 뜻： 콘솔 - 키， 길이， 긴다.\n3. 예문：\n   - 이 나무는 콘솔이 너무 깁니다. (这棵树的树干太长了。)\n   - 그 사람의 손가락 콘솔이 정말 긴다. (那个人的手指真的很长。)\n\n변형 및 뜻：\n- 콘솔에： 在...的长度上（副词）\n  - 예문：이 길이 콘솔에 10미터입니다. (这条路的长度是10米。)\n\n- 콘솔이： 长度是...的（形容词）\n  - 예문：이 책이 콘솔이 5살입니다. (这本书的长度是5厘米。为长度（动词）\n  - 예문：이 벽지는 콘솔을 3미터로 설치되었습니다.)\n\n- 콘솔을： 以... (这幅壁画的长度设置为3米。)\n\n- 콘솔으로： 用...作长度（介词）\n  - 예문：이 화장대를 콘솔으로 2미터로 만들어 주세요. (请把这张桌子做成2米长。)', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1724065391428.mp3');
INSERT INTO `word_list` VALUES (1005, 98, ' FPS ', ' 第一人称射击游戏', '1. 사절：\n2. 의미： FPS는 컴퓨터 또는 비디오 게임에서 Frames Per Second(초당 프레임 수)를 의존하여 화면 업데이트의 속도를 나타낼 때 사용되는 약어입니다.\n3. 예句：\n   - 이 게임은 FPS가 60에 도달합니다.\n   - FPS가 높으면 게임의 화면이 부드러우고， 부드러운 효과를 보여줍니다.\n\n변형 사용法：\n   - FPS로： FPS로 측정하면 이 컴퓨터의 성능이 좋은 것을 알 수 있습니다.\n   - FPS를： FPS를 높이면 더 부드러운 그래픽을 享有할 수 있습니다.\n   - FPS가： FPS가 높으면 게임의 플레이 품질이 좋아지는 것을 볼 수 있습니다.', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1724065396968.mp3');
INSERT INTO `word_list` VALUES (1006, 98, ' HP ', ' 生命值', '无法从大模型获取数据，请联系管理员！', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1007, 98, ' 레벨 ', ' 等级', '1. 词性：\n- 레벨은 명사입니다. (level is a noun.)\n2. 词义：\n- 레벨의 기본적인 의미는 \"수준\" 또는 \"단계\"입니다. (The basic meaning of level is \"standard\" or \"stage.\"\n3. 例句：\n- 그의 영어 능력은 중급 레벨입니다. (His English ability is at an intermediate level.)\n- 이 과题의 난이도는 고급 레벨입니다. (The difficulty of this problem is at an advanced level.)\n\n變形(變形) 及其词义和例句：\n- 레벨적 (leveled): 완벽하게 조정된 상태， \"leveled state.\"\n  - 책장에서 레벨적으로 정리하십시오. (Please arrange the bookshelves in a leveled manner.)\n- 레벨링 (leveling): 평활화하는 것， \"leveling.\"\n  - 건물의 레벨링 작업이 완료되었습니다. (The leveling work of the building has been completed.)\n- 레벨납殊 (level difference): 두 점이나 객체 사이의 수준 차이， \"level difference.\"\n) (There is a significant level difference in the stats of these two teams.  - 이 두 팀의 스탯은 크게 레벨납殊가 있습니다.', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1008, 98, ' NPC ', ' 非玩家角色', 'NPC (Near Perfect Crystal) 是用于描述半导体材料中晶体质量的术语，在韩语中通常直接借用英文缩写。以下是关于NPC的词性、词义以及例句的详细解释：\n\n1. 词性：外来词（汉字词）\n2. 词义：NPC 在游戏领域指非玩家控制的角色（Non-Player Character），在半导体领域指接近完美晶体（Near Perfect Crystal）。\n\n3. 例句：\n- 游戏中的例句：커머스에서 NPC를 통해  quest를 开始하세요. (在商城通过NPC开始任务。)\n- 半导体领域的例句：이 半導体 재료는 NPC로 分类되어 있습니다. (这种半导体材料被分类为NPC。)\n\n变形及其词义和例句：\n- NPCs: 非玩家控制的角色们（复数形式）\n (在游戏世界中与NPCs互动。)\n\n以上信息提供了NPC在韩语中的常见使用方式和相关例句，但由于NPC主要作为英文缩写使用，在韩语中并没有广泛的变形。- NPCing: 无此变形，因为NPC是缩写词，不适用于进行变形。\n  - 게임 세계에서 NPCs와 상호 작용합니다.', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1009, 98, ' 스포츠 ', ' 体育', '1. 词性：\n스포츠는 한국어에서는 이름(noun)입니다.\n\n2. 词义：\n스포츠의 뜻은 \"运动\" 또는 \"体育运动\"입니다.\n\n3. 例句：\n- 나는 주말에 스포츠를 하는 것을 좋아합니다. (周末我喜欢做运动。)\n- 스포츠를 통해 건강한 тело를 지키는 방법 중 하나입니다. (通过运动是保持健康身体的方法之一。)\n\n变形及其词义和例句：\n- 스포츠 팬： 스포츠를 지AnchorSupporter爱好支持者\n  - 그는 춤돌 스포츠 팬입니다. (他是狂热的足球运动爱好者。)\n- 스포츠 장치： 스포츠를 위해 사용되는 장비体育器材\n)\n- 스포츠 선수： 스포츠 경기에 참가하는 선수运动员\n- 스포츠 이벤트： 스포츠 관련 이벤트体育事件\n  - 彼女房有卓越的体操运动技巧。)\n  - 세계컵은 크리암 스포츠 이벤트입니다.  - 춤돌을 玩需要特殊的体育器材。每个派生词都给出了一个例句，用以说明其用法。  - 그는 우루과イana是一位著名的足球运动员。)\n (世界杯是最大的体育事件。)\n- 스포츠 완craft技巧在运动中\n\n以上是根据给出的模式，用韩语对“스포츠”一词进行的词性、词义以及相关例句的展示。', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1724065403349.mp3');
INSERT INTO `word_list` VALUES (1010, 98, ' RPG ', ' 角色扮演游戏', '1. 词性：\nRPG（Role-Playing Game）在韩语中通常被归类为外来语，具体是英语缩写的直接借用。\n\n2. 词义：\nRPG在韩语中指的是“角色扮演游戏”，是一种电子游戏类型，玩家扮演角色并在虚构世界中进行冒险。\n\n3. 例句：\n- RPG 게임에 많이 살펴요. (我常玩RPG游戏。)\n- 최근 RPG 게임을 많이 해요. (我最近经常玩RPG游戏。)\n\n变形及其词义和例句：\n- RPG ゲー즈 (RPG Games): 指具体的RPG游戏作品。\n  - RPG ゲー즈를 좋아합니다. (我喜欢RPG游戏。)\n\n- RPG 플레이어 (RPG Player): 指玩RPG游戏的玩家。\n  - RPG 플레이어는 그들의 세계에 immersive하게 빠짐을 경험합니다.- RPG 스토리 (RPG Story): 指RPG游戏的故事情节。\n (RPG故事可能难以理解。)\n\n因此“RPG”这个词在韩语中通常就是以英文形式出现，而不一定会有韩文的变形。  - RPG 스토리가 이해하기 어려울 수 있습니다. (RPG玩家会沉浸式地体验他们的世界。)\n\n以上是基于RPG这个术语在韩语中的常见用法和相关变形。需要注意的是，韩语中对于电子游戏相关的术语很多时候会直接借用英文词汇，', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1011, 98, ' PVP ', ' 玩家对战', '1. 사질：\n2. 의이： PVP는 플레이어 병렬 배틀의 약자로， 두 명의 플레이어가 상대 경기를 하는 ゲー미에서 일반적으로 사용되며， \"Player vs Player\"의 약자로 사용됩니다.\n3. 예시： 그는 PVP 모드에서 우수한 성능을 보여줍니다.\n4. 변형체와 의미：\n   - PVPing (Present Participle): 현재 PVP를 идて 있다.\n     예시： 그는 PVPing 중입니다.\n   - PVPed (Past Participle): PVP를 한 적이 있다.\n   - PVPer (Noun): PVP를 玩하는 사람.\n     예시： 그는 PVP에 성공적으로 PVPed했습니다.\n     예시： 그는 우수한 PVPer입니다.', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1012, 99, ' 声優 ', ' 配音演员', '.词1性：名詞\n2.词义：声優とは、映画、テレビアニメなどの音响制作で、キャラクターやナレーの声を出す人。また、無線で放送される番組の司会者や、広告の旁白をする人も含まれる。\n3.例句：彼女は小さい頃から声優になることを夢見ていた。最近、あの有名なアニメの主人公の声を出している声優が大ヒットしている。\n\n变形及其词义：\n声優になる - 成为声优\n例句：彼は高校を卒業して、声優になることを目指している。\n声優育成 - 培养声优\n例句：最近、多くの声優育成学校が設立されている。\n声優界 - 声优界\n例句：彼女は若い頃から声優界に活躍している。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1013, 99, ' 3D ', ' 三维', '1.词性：名词（名詞）\n2.词义：三次元的、立体的\n3.例句：\n- 最近のゲームは3D表示が一般的です。\n- 3D映画を見るために特殊な眼镜をかけます。\n\n变形及其词义：\n- 3D化（さんどくか）：变成三维的过程或状态\n  - 例文：このアニメは3D化されています。\n- 3Dモデリング（さんどくもでりんぐ）：创建三维模型的活动\n  - 例文：私は趣味で3Dモデリングをやっています。\n- 3D印刷（さんどくいんしょ）：一种可以打印出立体物体的技术\n  - 例文：最新の3D印刷技術を利用して、家を建てることが可能になりました。\n\n以上是关于“3D”的基本用法和其相关变形，以及各自的意义和例句。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1014, 99, ' プロダクション ', ' 制作', '1.词性：名詞\n2.词义：制作、生産。特に、映画やテレビ番組の撮影製作を指します。\n3.例句： \n   - この映画は日本でプロダクションされました。\n   - 新しい番組のプロダクションが始まりました。\n\n变形及其词义，每个变形一个例句：\n\n- プロデューサー（名词）：制作人。\n  例：彼は有名な映画プロデューサーです。\n\n- プロデュース（名词）：制作过程、制作方式。\n  例：このアニメのプロデュースは非常に複雑です。\n\n- プロデュート（名词）：产品、作品。\n  例：このCDは彼女の最新のプロデュートです。\n\n注意：以上单词的变形并非日语中常见的变形方式，而是根据原词“プロダクション”的含义和语境进行的合理拓展。在实际使用中，这些单词可能并不常见或标准。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1015, 99, ' 2D ', ' 二维', '1.词性：形容词（形容動詞）\n2.词义：二次元的，二维的\n3.例句：\n   - このアニメは2Dで描かれています。这部动画是2D绘制的。\n   - 2Dゲームは昔から好きです。我一直喜欢2D游戏。\n\n变形及其词义：\n- 2Dな（连体形）：用于修饰名词，表示“具有2D特征的”\n  例：2Dな画像を作りたいです。我想制作2D图像。\n- 2Dに（连用形）：用于表示目的或结果，常与动词结合使用\n  例：このソフトは2Dにして使えます。这个软件可以用于2D。\n- 2Dと（终止形）：用于结束句子，表示断定\n  例：この映像は2Dと判断されます。这个影像被判断为2D。\n- 2Dだ（连体形+助动词だ）：强调是2D的\n  例：私が作成したのは2Dだ。我制作的是2D的。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1016, 99, ' エフェクト ', ' 特效', '1.词性：名詞\n2.词义：効果、影響、作用\n3.例句：\n- 新藥のエフェクトを調べる。\n- 政府の政策によるエフェクトが大きい。\n\n变形及其词义：\n- エフェクトする（動詞）：影響を与える、効果をもたらす\n例句：この新しい訓練法は選手のパフォーマンスをエフェクトしました。\n- エフェクト的（形容詞）：関係している、影響を受ける\n例句：この問題はエフェクト的な点で議論する必要があります。\n- エフェクト的に（副詞）：影響を受けるように、効果的に\n例句：政府はエフェクト的に景気对策を取りました。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1017, 99, ' 音楽 ', ' 音乐', '1. 词性：名词\n2. 词义：音乐\n3. 例句：\n   - 音楽が好きです。(我喜欢音乐。)\n   - 彼は音楽家である。(他是音乐家。)\n\n变形及其词义：\n- 音楽的（おんがくてき）： 形容词，意为“音乐的”。例句：音楽的な才能を持つ。(拥有音乐方面的才能。)\n- 音楽に関係する（おんがくにかんけいする）： 动词短语，意为“与音乐有关”。例句：この活動は音楽に関係しています。(这个活动与音乐有关。)\n- 音楽を作る（おんがくをつくる）： 动词短语，意为“创作音乐”。例句：彼女は自分の音楽を作りました。(她创作了自己的音乐。)\n- 音楽を聴く（おんがくをキック）： 动词短语，意为“听音乐”。例句：私は每日音楽を聴きます。(我每天都听音乐。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1018, 99, ' 背景 ', ' 背景', '1.词性：名词\n2.词义：背景，环境\n3.例句：\n  - この絵の背景は山です。这幅画的背景是山。\n  - 彼の成功には苦労した背景があります。他的成功背后有着辛勤的努力。\n\n变形及其词义：\n- 背景色（背景色）：背景颜色\n  - このウェブサイトの背景色は青です。这个网站的背景色是蓝色。\n- 背景音（背景音）：背景声音\n  - 映画には恐怖の雰囲気を出そうとする背景音が流れています。电影中流淌着旨在营造恐怖氛围的背景音。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1019, 99, ' ファンサイズ ', ' 粉丝尺寸', '1. 词性：名詞\n2. 词义：ファンサイズとは、通常、スポーツに関連して使用される外来語であり、特定のスポーツ団体や個人が多くのファン（アナグリフト）を持つことを指します。\n3. 例句：\n   - チーズファンサイズが世界中から集まっています。\n   - 彼女はロンドンの有名なファンサイズの一員です。\n\n变形及词义：\n- ファンサイズ（原形）：多数のファンを指しているスポーツ団体や個人。\n  - 例句：チーズファンサイズが世界中から集まっています。\n\n- ファンサイズだ（連体形）：多数のファンを持っていることを示している。\n  - 例句：チーズは有名なファンサイズだ。\n\n- ファンサイズです（終止形）：自分が多数のファンを持っていることを明言している。\n  - 例句：私たちのチーズはファンサイズです。\n\n- ファンサイズになった（連用形）：他の語に接続して使われる。\n  - 例句：チーズがファンサイズになった時、大きな成功を收めました。\n\n- ファンサイズという（引用形）：他の語句と組み合わせて使う場合。\n  - 例句：チーズは「ファンサイズ」という名前で知られています。\n\n以上の例文はすべて日本語で書かれています。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1020, 99, ' 色彩设计 ', ' 色彩设计', '1. 词性：名词（名詞）\n2. 词义：色彩设计是指对图像各部分之间的配色对比程度的调整，包括明暗对比程度、冷暖对比程度、饱和度对比程度的调整。\n3. 例句：\n   - 色彩设计は重要です。色彩设计很重要。\n   - 彼女は色彩设计に詳しいです。她对色彩设计很精通。\n\n变形及其词义：\n- 色彩设计家（さいかせんけいか）：从事色彩设计工作的人。例句：色彩设计家はこの作品を完成させました。色彩设计师完成了这个作品。\n- 色彩设计学（さいかせんけいがく）：研究色彩设计的学科。例句：色彩设计学は面白いです。色彩设计学很有趣。', NULL, 1, NULL, NULL);
INSERT INTO `word_list` VALUES (1021, 99, ' アニメージュ ', ' 动画杂志', '1. 词性：名詞（名词）\n2. 词义：アニメージュは、「アニメ」という日本の動画形式に関連した芸術的な表現やスタイルを指します。\n3. 例句：\n   - 今度のアニメージュ展覧会では、多くの新作が披露されました。\n   - 彼はアニメージュに熱中しており、自分の作品にもその影響があると言います。\n\n变形とその意味：\n- アニメージャ（アニメージュの語幹＋フランス語の女性語尾）： 通常、アニメージュと同様に使用されます。\n   - 例句：アニメージャの世界を深く掘り下げる本が最近出版されました。\n\n他の派生語や関連語彙は、具体的には存在しません。アニメージュ自体が比較的に特殊な概念で、直接的な派生語や複合語は見当たらないです。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1022, 99, ' キャラクター ', ' 角色', '1. 词性：名词\n2. 词义：角色、人物\n3. 例句：\n   - この小説のキャラクターはとても魅力的です。\n   - （这部小说的角色非常有魅力。）\n   - 新しいゲームのキャラクターを作りました。\n   - （我制作了新游戏的角色。）\n\n变形及其词义和例句：\n- キャラクターな（连体形）：作为角色的，例句：彼は優れたキャラクターな俳優です。\n- キャラクターだ（连体形）：是角色，例句：彼女は今度の映画のキャラクターだ。\n- キャラクターに（副词的用法）：像角色一样，例句：彼はキャラクターにそれを演じました。\n- キャラクターと（格助词的用法）：作为角色，例句：彼女は新しい映画のキャラクターとして選ばれました。\n- キャラクターで（副词的用法）：以角色身份，例句：彼は新しいドラマのキャラクターで出演します。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1023, 99, ' 脚本 ', ' 剧本', '1.词性：名詞（名词）\n2.词义：劇の台本や放送・映画の原稿。脚本。剧本，底稿。\n3.例句： \n   - 新しい劇の脚本を書き始めた。开始写一部新剧的剧本。\n   - 脚本に従って演技をする。按照剧本进行表演。\n\n所有的变形及其词义：\n\n- 脚本家（屏幕作家）：劇の脚本を作成する人。例文：「彼は有名な脚本家である。」他是一个有名的编剧。\n- 脚本読み（读剧本）：脚本を読んで内容を理解すること。例文：「今週、新しい脚本の読みを行う予定です。」这周计划进行新剧本的读演。\n- 脚本作成（编写剧本）：劇の脚本を作成すること。例文：「脚本作成はそれほど簡単じゃない。」编写剧本并不是那么简单。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1024, 99, ' 原画 ', ' 关键帧', '1. 词性：名词\n2. 词义：原画（げんが）指的是动画、漫画等作品中的原始画作，即未经编辑或修改的最初画面。\n3. 例句：\n   - このアニメの原画は非常に細やかで、見事だ。\n   - 原画を修正するという仕事は大変ですね。\n\n变形及其词义：\n- 原画（げんが）：如上所述，指动画、漫画等的原始画作。\n- 原画家（げんがか）：专门制作原画的人，即原画师。\n\n例句：\n- 原画（げんが）：この原画が完成したら、次は色彩設計を進めます。\n- 原画家（げんがか）：彼女は有名な原画家で、多くの作品を手がけています。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1025, 99, ' アニメ ', ' 动画', '1.词性：名詞\n2.词义：アニメは、日本のアニメーションの略称であり、通常はテレビアニメや劇場版アニメを指します。\n3.例句：\n- 最近見ているアニメは何ですか？\n- 子供の頃からアニメが好きでした。\n\n變形とその意味：\n- アニメック（名詞）：アニメのファン\n例文：彼女は有名なアニメックです。\n- アニメ的（形容詞）：アニメに関連している\n例文：彼の部屋にはアニメ的なポスターがたくさん貼ってあります。\n- アニメ化（動詞）：原作をアニメーションにします。\n例文：この小説は来年度アニメ化予定です。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1026, 99, ' CG ', ' 计算机图形', '1. 词性：名詞（名词）\n2. 词义：コンピューグラフィックス、CGの略。映像制作で使用される、電子的に作成された画像や動画。特に、実際に撮影した映像と組み合わせて使用されることが多い。\n3. 例句：\n   - 最近のアニメはCGが多く使われている。\n   - CG技術の発展により、映画の見た目はますます美しくなってきている。\n\n变形及其词义：\n- CG的：形容詞型（形容词），CG的、与CG有关的。例：CG的な特殊効果。\n- CG化：动词型，使成为CG、用CG制作。例：実景をCG化する。\n- 非CG：名詞型（名词），不是CG的、与CG无关的。例：非CGの映像制作手法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1027, 99, ' ストーイ ', ' 故事板', '1. 词性：名词\n2. 词义：故事\n3. 例句：\n   - この本にはストーイがたくさん書いてある。\n   - 彼女は子供たちにストーイをかたくらながら寝やすみをしてもらう。\n4. 变形及其词义：\n   - ストーイ（原形）：故事\n   - ストーイを（宾格）：故事\n   - ストーイに（与格）：关于故事\n   - ストーイで（工具格）：用故事\n   - ストーイと（并列）：和故事一起\n   - ストーイだ（断定）：是故事\n   - ストーイが（主格）：故事\n   - ストーイを（宾格）：故事\n   - ストーイに（与格）：关于故事\n   - ストーイで（工具格）：用故事\n   - ストーイと（并列）：和故事一起\n   - ストーイだ（断定）：是故事\n   - ストーイが（主格）：故事', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1028, 99, ' キャラデザイン ', ' 角色设计', '1. 词性：名词\n2. 词义：角色设计\n3. 例句：\n   - 「キャラクターデザインは芸術であり、創造力を必要とする。」 - 角色设计是一门艺术，需要创造力。\n   - 「新しいゲームのキャラクターデザインに取り組む。」 - 我们致力于新游戏的角色设计。\n\n变形及其词义：\n- 「キャラクター」(名词): 角色\n  - 例句：「新しいキャラクターが今作に追加された。」 - 新角色被添加到了这部作品里。\n\n- 「デザイン」(名词): 设计\n  - 例句：「このデザインは現代的であり、魅力的です。」 - 这个设计是现代的且富有魅力。\n\n目前没有发现「キャラデザイン」有其他变形或衍生词。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1029, 99, ' 制作 ', ' 制作', '1.词性：動詞\n2.词义：作り出すこと。また、作ること。\n3.例句：\n- 私は今度のプロジェクトを制作します。\n- 彼女は自分の首飾りを制作しています。\n\n制作の变形：\n- 制作中 (制作中): 制作が進行中であることを示す。\n  - 例文： 今、新しい映画の制作中です。\n- 制作する (制作する): 制作を行うことを示す。\n  - 例文： 私たちは明日から新しい商品を制作します。\n- 制作済み (制作済み): 制作が終了していることを示す。\n  - 例文： この本はもう制作が終わっています。\n- 制作に失敗する (制作に失敗する): 制作が成功しなかったことを示す。\n  - 例文： 初めてのアルバイトで制作に失敗しました。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1030, 99, ' 監督 ', ' 导演', '1. 詞性：名詞\n2. 詞義：監督、導演、指導者。特に映画や演劇、放送番組などの制作進行を取りまとめる職務をいう。\n3. 例句：新しい映画の監督になった彼は、自分の作品に対して非常に厳格である。\n       最近のテレビ番組は、有名な監督の手によって制作されている。\n\n变形及词义：\n- 監督する（動詞）：指導すること。例文：「監督が新しいアイディアを実現させるために、チームメンバーに厳しく指示した。」\n- 監督的（形容詞）：関連している様子。例文：「その映画は監督的な視点から作られており、多くの人に好かれている。」\n- 被監督者（名詞）：指導を受ける人。例文：「被監督者は監督の指示に従って、仕事を進める。」', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1031, 99, ' マンガ ', ' 漫画', '1. 词性：名词\n2. 词义：漫画，连环画\n3. 例句：\n   - 私は子供のころからマンガが好きです。(我从小就喜欢看漫画。)\n   - 彼女は自分のストーイについてのマンガを書いています。(她正在写关于自己的爱情故事的漫画。)\n\n变形及其词义：\n- マンガな (形容词): 与漫画有关的，例如：マンガなスタイル(漫画风格)\n  - 例句：彼の绘はマンガなスタイルをしています。(他的画风是漫画风格的。)\n- マンガだ (断定助动词): 是漫画，例如：これは本物のマンガだ。(这是真正的漫画。)\n  - 例句：この作品は本当にマンガだ。(这部作品真的是漫画。)\n- マンガと (并列助词): 和漫画一起，例如：新聞とマンガを買う。(买报纸和漫画。)\n  - 例句：週末には新聞とマンガを買いに行く。(周末去买报纸和漫画。)\n- マンガを (宾格助词): 把漫画，例如：友達にマンガを貸した。(把漫画借给了朋友。)\n  - 例句：弟は私のマンガを見て欲しい。(弟弟想看看我的漫画。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1032, 100, ' 運動 ', ' undō ', '1. 詞性：名詞（名词）\n2. 詞義：運動は体育活動や体の動きを指します。\n3. 例句：\n   - 私は每朝少しの運動をすることを楽しみにしています。\n   - 運動会は来週行われます。\n4. 变形とその意味：\n   - 運動員（うんどういん）：競技者、アスリート。\n      例句：彼は才能あふれる運動員です。\n   - 運動服（うんどうふく）：体育のための衣服。\n      例句：新しい運動服を買った。\n   - 運動場（うんどうじょう）：体育のための広場。\n      例句：学校の運動場で走って遊んだ。\n   - 運動鞋（うんどうげつ）：体育のための靴。\n      例句：新しい運動鞋を購入した。\n   - 運動会（うんどうかい）：学校や会社で開催される体育の大会。\n      例句：今年の運動会は雨のため中止になりました。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1033, 100, ' 水 ', ' mizu ', '1.词性：名词\n2.词义：水，水分，雨水等液体状态的物质。\n3.例句：\n   - この瓶には水が入っています。(这个瓶子里有水。)\n   - 雨で外は濡れています。(外面因为下雨都湿了。)\n\n水的变形及其词义和例句如下：\n\n- 水る (みずる):动词，表示浸水或被水淋湿的状态。\n  - 例文：雨で服が水ってしまいました。(衣服被雨淋湿了。)\n\n- 水着 (みずぎ):名词，指游泳时穿的泳装。\n  - 例文：夏休みには海で水着をきるつもりです。(暑假打算去海边穿泳衣游泳。)\n\n- 水色 (みずいろ):名词，指一种类似浅蓝色或天蓝色的颜色。\n  - 例文：彼女は水色のサンガーレ茲を履いています。(她穿着一双水色的丝袜。)\n\n- 水玉 (みずたま):名词，指水滴或水珠。\n  - 例文：朝、窓ガラスに小さな水玉がついていました。(早上窗户玻璃上附着小水珠。)\n\n- 水回り (みずまわり):名词，指水域或水面。\n  - 例文：湖泊の水回りは広くてきれいです。(湖泊的水面宽阔且美丽。)\n\n以上是“水”的一些基本形态变化及其用法示例，每个变形都有其独特的意义和用途。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1034, 100, ' 肝臓 ', ' kanzō ', '1. 词性：名词\n2. 词义：肝脏\n3. 例句：\n   - 肝臓が病んでいる。(我的肝脏生病了。)\n   - 肝臓は体内の解毒器官である。(肝脏是体内的解毒器官。)\n\n变形及词义：\n- 肝臓の（肝脏的）\n   - 肝臓の機能を保つために、酒を控えるべきだ。(为了保护肝脏的功能，应该控制饮酒。)\n- 肝臓に（在肝脏里）\n   - 藥物は肝臓に集約されており、そこで解毒される。(药物集中在肝脏里，并在那里被解毒。)\n- 肝臓を（把肝脏）\n   - 医者は患者の肝臓を検査した。(医生检查了患者的肝脏。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1035, 100, ' 飲食 ', ' inshoku ', '1.词性：名詞\n2.词义：飲食は、食事を取ること。また、食べ物や飲み物のこと。\n3.例句：\n- 私は每朝、健康のためにいつもあきらめていない飲食を取ります。\n- その店では、多くの種類の飲食が提供されています。\n\n变形&词义：\n- 飲食する（动词）：食事を取る。\n  - 例句：私は每日三回飲食します。\n- 飲食物（名词）：食べ物や飲み物。\n  - 例句：スーパンには多種の飲食物が揃えています。\n- 飲食店（名词）：飲食を提供する店舗。\n  - 例句：街角に新しい飲食店が開いています。', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1724078906283.mp3');
INSERT INTO `word_list` VALUES (1036, 100, ' 骨密度 ', ' kotsuseimitsu ', '1.词性：名词\n2.词义：骨密度是指骨骼中矿物质的含量，通常用来衡量骨骼的健康状况。\n3.例句：\n  - 骨密度が低いと骨折する可能性が高くなる。\n    - 骨密度低的话，骨折的可能性就会增加。\n  - 骨密度を測定することは、骨粗鬆症の早期発見に役立ちます。\n    - 测定骨密度有助于早期发现骨质疏松症。\n\n变形及其词义：\n- 骨密度計（骨密度计）：用来测量骨密度的仪器。\n  - 骨密度計を使用して、患者の骨密度を測定しました。\n    - 我们使用了骨密度计来测量患者的骨密度。\n- 骨密度低減（骨密度减少）：指骨密度下降的情况。\n  - 骨密度低減は骨粗鬆症のリスクファクターである。\n    - 骨密度减少是骨质疏松症的风险因素之一。', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1724078913499.mp3');
INSERT INTO `word_list` VALUES (1037, 100, ' 血压 ', ' ketsueki ', '1.词性：名詞（名词）\n2.词义：血压，即血管中血液对血管壁的压力。\n3.例句：\n- 私の血圧は高い。（我的血压很高。）\n- 医者は毎日の血圧を測るために来ました。（医生每天都来测血压。）\n\n变形及其词义：\n- 血圧計（けっかつけい）：血压计，用来测量血压的仪器。\n  - 例句：先生が血圧計を使って、私の血圧を測りました。\n- 高血圧（こうけっかつ）：高血压，血压异常升高的病症。\n  - 例句：高血圧は生活習慣病の一種です。\n- 低血圧（ていけっかつ）：低血压，血压异常降低的病症。\n  - 例句：運動後に低血圧になる傾向があります。', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1724078918734.mp3');
INSERT INTO `word_list` VALUES (1038, 100, ' 胃 ', ' i ', '1. 词性：名词（名詞）\n2. 词义：胃，指人体消化系统中位于食道与小肠之间的器官。\n3. 例句：\n   - 私の胃が痛い。(我的胃疼。)\n   - 胃を温めるためにお茶を飲む。(为了暖胃而喝茶。)\n\n变形及其词义：\n- 胃がよい (形容词用法，意为“胃口好”或“消化能力强”)\n   - 例文：最近、胃がよくなって、何でも食べられます。(最近胃口变好了，什么都能吃。)\n   \n- 胃潰瘍 (合成词，表示“胃溃疡”)\n   - 例文：胃潰瘍で入院している友達を訪ねたいと思う。(我想去看望因胃溃疡住院的朋友。)\n\n请注意，日语中单词“胃”本身不发生变形，但可以和其他词汇组合形成新的词语来表达相关的概念或状态。上述提供的是包含“胃”这一概念的衍生表达方式和用例。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1039, 100, ' 疲劳 ', ' hiroē ', '1. 词性：名词\n2. 词义：疲劳、累\n3. 例句：\n   - 今日は疲れた。 (今日はつかれた。) - 今天我很累。\n   - 長い一日を終えて、彼は大きく疲れた。 (ながいいちにちをおわりて、かれはおおきくつかれた。) - 漫长的一天结束后，他感到非常疲惫。\n\n变形及其词义：\n- 疲れる (つかれる)：动词，感到疲劳\n  - 例句：長い一日が疲れています。 (ながいいちがつかれています。) - 漫长的一天让我感到疲倦。\n- 疲れませう (つかれませう)：形容词，形容人或事物显得疲劳\n  - 例句：あの人は疲れませうようだ。 (あのひとはつかれませうようだ。) - 那个人看起来很累。\n- 疲れさ (つかれさ)：名词，疲劳的程度或状态\n  - 例句：疲れさが身にしみる。 (つかれさがみにしみる。) - 感觉到身体的疲劳。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1040, 100, ' 1健康 ', ' kenkō ', '1. 词性：名词（名詞）\n2. 词义：健康、健壮\n3. 例句：\n   - 健康が第一です。 - 健康是最重要的。\n   - 彼女は健康のために運動を始めた。 - 她为了健康开始运动。\n\n变形及其词义：\n- 健康になる（动词）：变得健康\n  - 私は最近健康になりました。 - 我最近变得健康了。\n- 健康である（形容词）：健康的\n  - 彼は健康である人だ。 - 他是一个健康的人。\n- 健康を保つ（动词）：保持健康\n  - 毎日運動することで、私は健康を保っています。 - 我通过每天运动来保持健康。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1041, 100, ' 体重 ', ' taijū ', '1. 词性：名词（名詞）\n2. 词义：体重，即人或动物的重量。\n3. 例句：\n   - 私の体重は60キロです。(我的体重是60公斤。)\n   - 最近、体重が増えてきました。(最近体重增加了。)\n\n变形及其词义，每个变形一个例句：\n- 体重計（たいじゅうけい）：体重计，用来测量体重的工具。\n  例：体重を測る前に、体重計を零点にしなくちゃいけません。(在测体重之前，必须将体重计调至零点。)\n  \n- 体重を測る（たいじゅうをそくる）：测量体重。\n  例：昨日、病院で体重を測りました。(昨天在医院测量了体重。)\n\n- 体重制限（たいじゅうせいげん）：重量限制，通常用于体育竞技中对参赛者体重的限制。\n  例：この競技には体重制限があります。(这项比赛有体重限制。)\n\n以上是基于“体重”这一名词的一些基本用法和相关变形。日语中单词的变形通常涉及复合词的构成或者动词、形容词等其他词类的变化，但对于名词“体重”来说，主要的变形是通过与其他词汇组合来表达更具体的概念。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1042, 100, ' 体温 ', ' taion ', '1. 词性：名词\n2. 词义：体温，即生物体内的温度。\n3. 例句：\n   - 私の体温は常に36.5度です。 (我的体温通常是36.5度。)\n   - 医者は患者の体温を測定しました。 (医生测量了患者的体温。)\n\n变形及其词义：\n- 体温計（たいおんけい）：体温计，用于测量体温的工具。\n  - 例句：体温計を使って、彼女の体温を測定しました。 (我用体温计测量了她的体温。)\n- 高体温（こうたいおん）：高体温，指体温高于正常范围。\n  - 例句：最近、高体温が続くことがあります。 (最近，我经常有高体温的情况。)\n- 低体温（ていたいおん）：低体温，指体温低于正常范围。\n  - 例句：冬に入ると、低体温になる傾向があります。 (进入冬天后，容易出现低体温的情况。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1043, 100, ' 免疫 ', ' men\'eki ', '1. 词性：名词\n2. 词义：免疫，指生物体对特定病原体的抵抗能力。\n3. 例句：\n   - 私の免疫系は強くないので、病気に弱い。\n   - このワクチンは新型インフルエンザに対して免疫を与えます。\n\n变形及其词义：\n- 免疫性（いんむけい）：指生物体具有的免疫特性。\n  - 例句：この研究は免疫性の獲得機構を明らかにした。\n- 免疫薬（いんむやく）：指用于增强免疫力的药物。\n  - 例句：冬に入る前に免疫薬を取る習慣があります。\n- 免疫療法（いんむりょうほう）：指通过增强或恢复免疫系统功能来治疗疾病的方法。\n  - 例句：最近、免疫療法が癌治療で注目を集めています。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1044, 100, ' 精神 ', ' seishin ', '1. 词性：名词\n2. 词义：精神、心灵、意志\n3. 例句：\n   - 彼は精神が強い。 (かれはせいしんがつよい。) - 他的精神很坚强。\n   - 精神を出してやろう。 (せいしんをだしてやろう。) - 拿出点精神来，加油吧。\n\n变形及其词义：\n- 精神的 (せいしんてき) - 形容词，形容与精神相关的事物。\n   - 精神的な訓練をする。 (せいしんてきなくんれんをする。) - 进行精神上的训练。\n\n- 精神に (せいしんに) - 副词，表示在精神上。\n   - 精神に支えられている。 (せいしんにささえられている。) - 在精神上得到支持。\n\n- 精神付け (せいしんづけ) - 名词，指给予精神鼓励或支持。\n   - 彼女に精神付けをする。 (かのじょにせいしんづけをする。) - 给她精神上的支持。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1045, 100, ' 心臓 ', ' shinzou ', '1.词性：名詞\n2.词义：心臓（しんぞう）是指人和脊椎动物的内脏之一，是循环系统的一部分，主要功能是泵血，为身体各部分提供氧气和营养物质，同时将废物运送到排泄系统。\n3.例句：\n   - 私の心臓がたまります。（我的心臓疼。）\n   - 心臓移植は高度な医療技術です。（心脏移植是一项高难度的医疗技术。）\n\n变形及其词义：\n- 心臓がい（しんぞうがい）：指对心脏有好处的，有益于心脏的。\n  - この健康補助食品は心臓がい効果を持っています。\n    （这种健康补充品具有益心脏的效果。）\n  \n- 心臓にいい（しんぞうにいい）：对心脏有益，对心脏好的。\n  - 運動は体にとても心臓にいいです。\n    （运动对身体特别是心脏非常有益。）\n\n- 心臓のこたえ（しんぞうのこたえ）：关于心脏的事情或问题。\n  - 心臓のこたえについて、専門家に相談する必要があります。\n    （关于心脏的问题，有必要咨询专家。）\n  \n请注意，由于日语的语法结构，单词的变形和用法会根据上下文而有所不同。以上提供的是一些基本的变形和例句，实际应用中可能会有更多的变化。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1046, 100, ' 血液 ', ' ketsueki ', '1.词性：名词\n2.词义：血液，即人或动物体内的液体组织，主要用于输送营养、氧气和废物等。\n3.例句：\n  - この検査では、血液からのDNAを分析します。 (这个检查会分析血液中的DNA。)\n  - 彼女は血液型がA型です。 (她的血型是A型。)\n\n变形及其词义：\n- 血液さい (血色素)：血液中的红色素，主要负责氧气的运输。\n  例文：血液さいによる検査で、貧血が診断された。 (通过血色素检查，被诊断出了贫血。)\n\n- 血液净化 (血浄化)：一种医疗手段，用于清除血液中的有害物质。\n  例文：重篤な中毒状態を救命するため、血液浄化療法を施行した。 (为了救治严重的中毒状态，实施了血液净化疗法。)\n\n- 血液循環 (血液循环)：血液在体内循环的过程，包括动脉循环和静脉循环。\n  例文：運動を続けば、血液循環がよくなる。 (持续运动可以让血液循环变好。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1047, 100, ' 肺 ', ' fuku ', '1. 词性：名词\n2. 词义：肺臓。呼吸器官の一つで、气体交换を行うための脏器。\n3. 例句：\n   - 私は寒さで肺が痛んでいます。 (我因为寒冷而感到肺部疼痛。)\n   - 彼は长年の间に打たれていたため、肺が弱くなってしまいました。 (他由于长期吸烟，导致肺部变得虚弱。)\n\n变形及其词义：\n- 肺がない (没有肺)：表示某人或某物没有肺部。\n  - 例文：この机械は人间と同じ机能を持ちますが、肺がないので、呼吸が必要ありません。 (这台机器拥有与人类相同的功能，但没有肺部，所以不需要呼吸。)\n\n- 肺が悪い (肺部不好)：表示某人的肺部健康状况不佳。\n  - 例文：最近、私の肺が悪くて、たくさんの痰が出ている。 (最近我的肺部状况不好，有很多痰。)\n\n- 肺が丈夫 (肺部强壮)：表示某人的肺部健康状况良好。\n  - 例文：运动を続けば、肺も丈夫になるでしょう。 (如果持续运动，肺部也会变得更加强壮。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1048, 100, ' 血糖 ', ' keikin ', '1.词性：名詞\n2.词义：血糖は、血液中の葡萄糖のことを指します。\n3.例句：\n- 血糖値が高いため、医者に相談しました。\n- 朝食前に血糖を測定しましょう。\n4.变形及其词义：\n- 血糖値（けっきょうち）：血糖の度数。例：血糖値が上昇しています。\n- 血糖レベル（けっきょうれいぶる）：血糖のレベル。例：血糖レベルを下げるために運動をする必要があります。\n- 血糖管理（けっきょうかんり）：血糖の管理。例：糖尿病患者は血糖管理を行う必要があります。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1049, 100, ' 腸 ', ' chō ', '1.词性：名詞\n2.词义：動物の体の中の食べ物を消化するための長い管状の器官。\n3.例句：\n- 私の腸が痛くて、病院に行って診断したい。\n- この野菜は腸内环境を整える効果がある。\n\n腸の変形とその意味、例文：\n- 腸がよい（形容詞）：腸が丈夫である。\n 例文：彼は腸がよいので、何でも食べられる。\n- 腸炎（名詞）：腸が炎症を起こす病気。\n 例文：私は近日中に腸炎を患い、病院に入院した。\n- 腸詰まり（名詞）：腸が悪くなって痛む状態。\n 例文：昨夜お酒を飲んで、今朝から腸詰まりを抱いている。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1050, 100, ' 腎臓 ', ' jinnzō ', '1.词性：名词\n2.词义：肾脏\n3.例句：\n   - 腎臓が痛い。(我的肾疼。)\n   - 腎臓の機能を保つためには、水をよく飲むこと。(为了保持肾脏的功能，应该多喝水。)\n\n变形及其词义：\n- 腎臓の（連体形）：关于肾脏的\n  - 例文：腎臓の健康を維持するための方法。(维持肾脏健康的方法。)\n  \n- 腎臓を（動詞目的語構文）：肾脏\n  - 例文：医者は腎臓を調べた。(医生检查了肾脏。)\n\n- 腎臓が（描写文・存在文）：肾脏\n  - 例文：彼は腎臓が悪くなった。(他的肾脏变坏了。)\n\n- 腎臓に（動作の相手・来る方向）：对肾脏\n  - 例文：腎臓に影響を与える。(对肾脏产生影响。)\n\n- 腎臓で（動作・状態の場所）：在肾脏\n  - 例文：腎臓で発生した病気。(发生在肾脏的疾病。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1051, 100, ' 睡眠 ', ' shuiminn ', '1. 词性：名词\n2. 词义：睡眠、睡觉\n3. 例句：\n   - 毎晩10時になると、必ず睡眠する。(まいばんじゅうじになると、かならずしんみんする。)（每天晚上到了10点，我一定会去睡觉。）\n   - 睡眠不足は体に悪い。(しんみんぶそくはからだにわるい。)（睡眠不足对身体不好。）\n\n变形及其词义和例句：\n- 睡眠 (しんみん)：名词，表示睡眠、睡觉。\n   - 例句：子供の成長には十分な睡眠が必要です。(こどものせいちょうにはじゅうぶんなしんみんがひつようです。)（孩子的成长需要充足的睡眠。）\n\n- 睡眠中 (しんみんちゅう)：名词，表示正在睡觉的状态。\n   - 例句：彼女は睡眠中で、呼び起こしても反応がない。(かのじょはしんみんちゅうで、よびおこしてもはんのうがない。)（她正在睡觉，叫醒她也没有反应。）\n\n- 睡眠不足 (しんみんぶそく)：名词，表示睡眠不足的状态。\n   - 例句：最近の睡眠不足が頭痛を引き起こした。(さいきんのしんみんぶそくがずつうをひきおこした。)（最近的睡眠不足引起了头痛。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1053, 101, ' 닷닷 ', ' 鸭', '1. 词性：\n닷닷（dab-dab）是一个韩语中的副词，通常用来描述动作的连续或频繁发生。\n\n2. 词义：\n它表示“连续地”或“不断地”。\n\n3. 例句：\n- 나는 책을 닷닷 읽었다. (我连续不断地读书。)\n- 우리는 닷닷 웃어 왔다. (我们不断地笑着来了。)\n\n变形及其词义：\n\n1. 닷닷하다（dab-dab hada）- 动词形式，表示“连续做某事”。\n   - 나는 책을 닷닷히 읽었다. (我不断地读书。)\n\n2. 닷닷히（dab-dab hi）- 形容词形式，表示“连续的”或“不断的”。\n   - 우리는 닷닷히 웃았다. (我们连续地笑了。)\n\n3. 닷닷이라（dab-dab ira）- 名词形式，表示“连续”或“不断”。\n   - 이 책은 닷닷이라 읽을 수 있다. (这本书可以连续读。)\n\n以上是关于“닷닷”的词性、词义以及例句的解析。', NULL, 1, NULL, 'src\\main\\resources\\MP3\\1724085341493.mp3');
INSERT INTO `word_list` VALUES (1054, 101, ' 닭 ', ' 鸡', '1. 词性：名詞(Noun)\n2. 词义：鸡\n3. 例句：\n   - 닭이 꺾어 나왔다. (鸡开始下蛋了。)\n   - 닭에게는 몸이 좋아지고， 가슴이 좋은 것이 좋다. (对鸡来说，身体好，心脏好才是好的。)\n\n变形及其词义：\n- 닭이 (鸡的)：表示属于鸡的，用于修饰名词。\n  - 닭이 품 (鸡的羽毛)\n- 닭으로 (像鸡一样)：表示比喻，像鸡那样。\n  - 그 사람은 닭으로 소리웠다. (那个人像鸡一样叫了。)\n- 닭이라는 (所谓的鸡)：表示指代，所谓的鸡。\n  - 닭이라는 애완동물은 수학을 배우고 있다. (所谓的鸡正在学习数学。)', NULL, 1, NULL, 'src\\main\\resources\\MP3\\1724085616737.mp3');
INSERT INTO `word_list` VALUES (1055, 101, ' 사자 ', ' 狮子', '1. 사자\n2. 词性：名词\n3. 词义：沙子\n4. 例句：\n- 얼마나 많은 사자가 있어요？ (这里有多少沙子？)\n- 해변에는 많은 사자가 있어요. (海边有很多沙子。)\n\n变形及词义：\n- 사라져요： 动词，意为“变成沙子”\n  - 예쁘게 사라져요！ (变得漂亮如沙！)\n- 사라진다： 形容词，意为“像沙子一样”\n  - 이 친구의 피부는 사라진다 느낌입니다. (这个朋友的皮肤感觉像沙子一样。)\n- 사라질 수 없어요： 短语，意为“无法变成沙子”\n  - 이 물체는 사라질 수 없어요. (这个物体无法变成沙子。)', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1724085625229.mp3');
INSERT INTO `word_list` VALUES (1056, 101, ' 닭갈 ', ' 鸵鸟', '1. 词性：名词\n2. 词义：鸡冠\n3. 例句：\n- 닭갈이 좋아요. (我喜欢鸡冠。)\n- 닭갈은 닭의 부위입니다. (鸡冠是鸡的一部分。)\n\n变形及其词义：\n- 닭갈(名): 鸡冠\n- 닭갈이(主格): 鸡冠（主语）\n- 닭갈을(宾格): 鸡冠（宾语）\n- 닭갈에(处所格): 在鸡冠上\n- 닭갈에서(从格): 从鸡冠开始\n- 닭갈으로(工具格): 用鸡冠\n- 닭갈과(并列): 和鸡冠一起\n\n例句：\n- 닭갈이 좋아요. (我喜欢鸡冠。) - 主格\n- 닭갈을 살펴보세요. (请打开鸡冠。) - 宾格\n- 닭갈에 앉기를 합니다. (他在鸡冠上坐下。) - 处所格\n- 닭갈에서 시작하세요. (从鸡冠开始。) - 从格\n- 닭갈으로 채우세요. (请用鸡冠填满。) - 工具格\n- 닭갈과 함께 즐겨요. (和鸡冠一起享受。) - 并列', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1057, 101, ' 해돋이 ', ' 海豚', '1. 词性：\n해돋이（海地）是名词。\n\n2. 词义：\n海地，即Haiti，是一个国家的名字。\n\n3. 例句：\n- 나는 해돋이에서 왔습니다. (我来自海地。)\n- 해돋이는 중美洲의 국가입니다. (海地是中美洲的国家。)\n\n变形及其词义和例句：\n- 해돋인 (海地人)：指来自海地的人。\n  - 그는 해돋인일 것 같아요. (他看起来像是海地人。)\n- 해돋어 (海地语)：指海地的官方语言，即海地克里奥尔语。\n  - 저는 해돋어를 배우고 있습니다. (我正在学习海地语。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1058, 101, ' 멧례 ', ' 蝴蝶', '1. 词性：名词(Noun)\n2. 词义：泡沫，肥皂泡\n3. 例句：\n   - 멧례가 나렸요. (泡沫破了。)\n   - 욕수를 깨아서 멧례이 나났어요. (洗衣服时产生了泡沫。)\n\n变形及其词义和例句：\n- 动词形式：멧론하다 (产生泡沫)\n  - 욕수를 洗うと 멧론하고 있어요. (洗衣服时会产生泡沫。)\n- 形容词形式：멧론한 (有泡沫的)\n  - 이 세탁소는 멧론한 욕수 liquid로  famoust for. (这家洗衣店以有泡沫的洗衣液而闻名。)\n- 副词形式：멧론론해 (泡沫般地)\n  -  children love to play with bubbles, making them float around the room 멧론론해. (孩子们喜欢玩泡泡，让它们像泡沫一样在房间里飘浮。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1059, 101, ' 고양이 ', ' 猫', '1. 词性：名词\n2. 词义：猫\n3. 例句：\n   - 고양이가 나섭에 눌리고 있어요. (猫在院子里睡觉。)\n   - 나는 고양이를 좋아합니다. (我喜欢猫。)\n\n变形及其词义：\n- 고양이： 猫（单数）\n  - 고양이가 나섭에 눌리고 있어요. (猫在院子里睡觉。)\n- 고양이들： 猫们（复数）\n  - 저는 고양이들을 좋아해요. (我喜欢猫们。)\n- 고양이옷： 猫毛（指猫的毛发）\n  - 고양이옷이 골급하면 꾸림을 주세요. (如果猫毛过敏，请给我药。)\n- 고양이돌： 猫头鹰（另一种动物，与猫无关，但名称中含有“猫”字）\n  - 고양이돌이 야간 소리나요. (猫头鹰在晚上叫。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1060, 101, ' 돈 ', ' 鹿', '1. 词性：\n- 돈 (名詞)\n\n2. 词义：\n- 돈은 「貨幣」， 「金錢」를 의미합니다.\n\n3. 例句：\n- 엄마가 나에게 돈을 주었어요. (妈妈给了我钱。)\n- 이 책을 사는데 돈이 부족하네요. (买这本书的钱不够。)\n\n变形及其词义：\n- 돈이 - 「金钱的」(所有格形式)\n  - 예： 이 책을 사기위한 돈이 부족하다. (买这本书的金钱不够。)\n- 돈을 - 「金钱」(宾格形式)\n  - 예： 친구에게 돈을 대여했어요. (我向朋友借了钱。)\n- 돈이 - 「金钱」(主格形式)\n  - 예： 나의 돈이 좀 더 있어요. (我的金钱更多一些。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1061, 101, ' 개 ', ' 狗', '1. 词性：名词\n2. 词义：狗\n3. 例句：\n   - 나는 앞에서 개를 봤어요. (我在前面看到了一只狗。)\n   - 그 집에는 백 개의 개가 있습니다. (那家里有一百只狗。)\n\n变形及词义：\n- 개섯 (gaechu): 狗肉，例句：나는 개섯을 볼 수 없어요. (我不能吃狗肉。)\n- 개아지 (gaeaji): 小狗，例句：새로 Born 된 개아지가 깜빠르고 可愛하합니다. (新生的小狗活泼又可爱。)\n- 개떡 (gaeduk): 狗骨头，例句：개떡이 앞으로 나온 것을 봤어요. (我看到了一个狗骨头在前面出现。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1062, 101, ' 홍鱼 ', ' 鲸鱼', '1. 词性：\n홍어(洪鱼) - 名词\n\n2. 词义：\n\"洪鱼\"在韩语中指的是一种鱼类，通常是指大型的、生活在海洋中的鱼类，比如金枪鱼或者鲭鱼。\n\n3. 例句：\n- 나는 앞에서 홍어를 많이 먹었습니다. (我从前经常吃洪鱼。)\n- 홍어는 우리 국가에서 相儅히 인기 있는  Seafood 입니다. (洪鱼在我们国家是相当受欢迎的海鲜。)\n\n变形及其词义和例句：\n- 홍어를 먹다 (吃洪鱼)：나는 어제 홍어를 먹었습니다. (我昨天吃了洪鱼。)\n- 홍어 sashimi (洪鱼刺身)：나는 홍어 sashimi를 좋아합니다. (我喜欢洪鱼刺身。)\n- 新鮮한 홍어 (新鲜的洪鱼)：저는 市場에서 新鮮한 홍어를 구매고  came. (我在市场买了新鲜的洪鱼回来。)\n\n请注意，\"洪鱼\"这个词在韩语中并不是一个常见的词汇，上述信息是基于对\"洪鱼\"这个词的直接翻译和解释。在不同的语境中，可能需要根据具体的鱼类进行适当的调整。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1063, 101, ' 북악어 ', ' 北极熊', '1. 词性：名词\n2. 词义：苹果\n3. 例句：\n   - 나는 북악어를 좋아합니다. (我喜欢苹果。)\n   - 이 사과에 북악어가 많습니다. (这个季节有很多苹果。)\n\n变形及其词义：\n- 북악 (名词，苹果树)\n  - 나의 家에는 북악이 있습니다. (我家有苹果树。)\n- 북악 (副词，非常)\n  - 이 영화는 북악 좋아요. (这部电影非常好看。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1064, 101, ' 빛론 ', ' 犀牛', '1. 词性：\n- 빛론 (名詞)\n\n2. 词义：\n- 빛론의 意味는 \"光線\" 또는 \"照明\"입니다.\n\n3. 例句：\n- 1. 컴퓨터 화면이 太暗了，我需要更多的照明。 (컴퓨터 화면이 너무 어두워서 더 많은 빛을 필요하게 합니다.)\n- 2. 摄影师使用特殊的灯光来创造氛围。 (사진찍기는 특별한 빛을 사용하여 分为를 만듭니다.)\n\n变形及其词义：\n- 빛론에 (在照明中) - 照明 환경에 있다.\n- 예： 그는 빛론에서 사진을 찍고 있습니다. (他在照明环境中拍照。)\n\n- 빛론하다 (照明) - 照明를 제공하다.\n- 예： 권장에서 커다媛 빛론을 제공하십시오. (请在晚上提供足够的照明。)\n\n- 빛론되다 (被照明) - 照明을 받다.\n- 예： 이 장소가 잘 빛론되어 있어 사진찍기가 좋은 환경을 제공합니다. (这个场地被良好照明，为摄影师提供了良好的环境。)', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1724119360980.mp3');
INSERT INTO `word_list` VALUES (1065, 101, ' 암돌이 ', ' 蚂蚁', '1. 암돌이 - 词性：名词\n2. 암돌이 - 词义：南瓜\n3. 例句：\n- 나는 암돌이를 좋아합니다. (我喜欢南瓜。)\n- 암돌이는 가십이 좋습니다. (南瓜味道很好。)\n\n变形及其词义：\n- 암돌 - 词义：南瓜的简称，通常用于口语中。\n  - 암돌을 살께요. (请给我一个南瓜。)\n- 암돌 별 - 词义：南瓜种子。\n  - 암돌 별이 좋은 음식입니다. (南瓜种子是好食物。)\n- 암돌 汤 - 词义：南瓜汤。\n  - 암돌 汤을 만들어 주세요. (请做南瓜汤。)', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1724119292394.mp3');
INSERT INTO `word_list` VALUES (1066, 101, ' 병아리 ', ' 斑马', '1. 词性：\n- 병아리 (病癌) 是名词。\n\n2. 词义：\n- 병아리 (病癌) 指的是“癌症”或“恶性肿瘤”。\n\n3. 例句：\n- 그는 병아리로 고혀졌다. (他因癌症去世了。)\n- 병아리에 대한 치료는 어려울 수 있습니다. (癌症的治疗可能会很困难。)\n\n变形及词义：\n- 병아리는 (病癌는) - 癌症的，表示所属关系，用于修饰名词：병아리는 환자가 多웠다. (癌症患者增加了。)\n- 병아리이拉 (病癌이拉) - 癌症的，用于修饰动词或形容词：병아리이拉 치료를 받았다. (接受了癌症治疗。)\n- 병아리로 (病癌로) - 用癌症方式，表示方式或手段：병아리로 사망을 얼마나 느껴지도 모른다. (不知道有多少人会因癌症而死。)\n- 병아리에 (病癌에) - 对于癌症，表示目的或方向：병아리에 대한 연구는 중요하다. (对癌症的研究很重要。)\n\n请注意，韩语中的词汇变形通常涉及词尾的变化以适应不同的语法结构，而“병아리”作为一个名词，其本身并没有像动词那样有多种变形。上面提供的是一些常见的与“병아리”结合的词尾变化示例，用于展示如何在句子中使用这个词。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1067, 101, ' 돼지 ', ' 猪', '1. 词性：\n돼지 - 名词（Noun）\n\n2. 词义：\n\"猪\"，指的是动物猪。\n\n3. 例句：\n- 앞에서 돼지가 한 마리 있어요. (前面有一头猪。)\n- 나는 돼지를 좋아하지 않습니다. (我不喜欢猪。)\n\n变形及其词义和例句：\n- 돼지의 - 猪的（Possessive form of 돼지）\n  - 예쁜 돼지의 이름은 무엇인가요？ (漂亮的猪叫什么名字呢？)\n\n- 돼지들 - 猪们（Plural form of 돼지）\n  - 돼지들이 곧 꺼서 있어요. (猪们快要出来了。)\n\n- 돼지같이 - 像猪一样（Adverbial form expressing manner）\n  - 그는 돼지같이 밥을 먹었습니다. (他像猪一样吃饭。)\n\n- 돼지님 - 猪先生/猪小姐（Honorific form for a pig, used humorously or in children\'s stories）\n  - 돼지님， 당신이 좋아하는 것은 무엇인가요？ (猪先生/小姐，你喜欢什么呢？)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1068, 101, ' 야즈 ', ' 猴子', '1. 词性：\n- 名詞\n\n2. 词义：\n- 야즈는 영어로 \"yogurt\"를 뜻하며， 酸味가 강한 유체 급식품을 의미합니다.\n- 在韩语中，“야즈”是英语单词“yogurt”的对应词汇，指的是一种具有强烈酸味的液体食品。\n\n3. 例句：\n- 나는 야즈를 좋아합니다. (我喜欢酸奶)\n- 야즈는 건강이 좋은 음식입니다. (酸奶是一种健康的食物)\n\n4. 变形及词义：\n- 變形： 야즈하다 (动词形式，意为“制作酸奶”)\n  - 예： 우리는 家で 야즈를 만들어요. (我们在家做酸奶)\n- 變形： 야즈色 (形容词形式，描述与酸奶相关的颜色或特质)\n  - 예： 그 옷은 야즈色이에요. (那件衣服是酸奶色的)\n- 變形： 야즈적 (形容词形式，形容与酸奶相关的属性或特点)\n  - 예： 이 음료는 야즈적인 풍味을 가지고 있어요. (这种饮料有酸奶特有的风味)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1069, 101, ' 범죄 ', ' 豹', '1. 词性：名词\n2. 词义：犯罪\n3. 例句：\n   - 그는 범죄를 犯한 후， 사랑을 받았다. (他犯了罪后，受到了惩罚。)\n   - 범죄를 벌cher하고 싶은 사람들이 많습니다. (有很多人想预防犯罪。)\n\n变形及其词义：\n- 범죄자 (犯罪者)：犯有罪行的人\n  - 그 사람은 범죄자입니다. (那个人是犯罪者。)\n- 범죄행위 (犯罪行为)：指犯罪的行为\n  - 그것은 범죄행위입니다. (那是犯罪行为。)\n- 범죄율 (犯罪率)：表示犯罪发生的频率或比例\n  - 지역의 범죄율이 상승하면 사회적인 문제가 발생할 수 있습니다. (地区的犯罪率上升可能会导致社会问题的发生。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1070, 101, ' 닭고甡 ', ' 企鹅', '1. 词性：\n- 닭고甡（tiāng gāo shēng）是一个汉字词，由四个汉字组成：田（tián），高（gāo），生（shēng）。\n\n2. 词义：\n- 该词没有直接对应的韩语单词或短语，因为“田高生”并不是一个常见的中文词汇或短语。如果这是一个特定的名字、术语或者是某种特定领域的用语，那么需要更多的上下文来确定其确切含义。在缺乏具体上下文的情况下，我们无法给出一个准确的词义。\n\n3. 例句：\n- 由于“田高生”不是一个已知的韩语词汇或短语，因此无法提供相关的例句。\n\n关于变形及其词义和例句，由于“田高生”本身并不是一个标准的韩语词汇，所以它没有变形。通常，韩语中的词汇变形涉及到动词、形容词等词类的活用，而“田高生”作为一个外来词或专有名词，并不适用于这些规则。\n\n如果您能提供更多关于“田高生”这个词的背景信息或者它是如何被使用的上下文，我或许能够提供更准确的解释和帮助。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1071, 101, ' 갑생기 ', ' 青蛙', '1. 词性：动词\n2. 词义：开始，着手\n3. 例句：\n- 심았다 늦지않이라 갑생기를 해요. (为了不迟到，我们开始出发吧。)\n- 프로젝트를 갑생하고 나서 그 이후의 계획을 논의할 수 있어요. (开始项目后，我们可以讨论接下来的计划。)\n\n变形及其词义和例句：\n- 갑생시다 (开始做某事)\n  - 예쁜 일을 갑생십시다. (开始做一项困难的工作。)\n- 갑생았다 (已经开始)\n  - 책을 읽기 위해 갑생았어요. (为了读书，已经准备好了。)\n- 갑생히다 (帮助开始)\n  - 친구가 심사를 갑생히고 있어요. (朋友正在帮助进行审查。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1184, 101, ' 독수리', '袋鼠', '1. 词性：\n- 名詞\n\n2. 词义：\n- 독수리（獨島）： 独岛，位于韩国和日本之间的一个岛屿。\n\n3. 例句：\n- 독수리는 한국의 領土입니다. (独岛是韩国的领土。)\n- 독수리에 관한 절대적인 주장은 무엇게 변하지 않습니다. (关于独岛的绝对主张永远不会改变。)\n\n变形及其词义：\n- 독수리가 (独岛+가): 表示主语是独岛时使用的形式。\n  - 독수리가 한국의 領土입니다. (独岛是韩国的领土。)\n\n- 독수리나 (独岛+나): 表示包括独岛在内的情况或选择。\n  - 독수리나 周辺의 Island를 탐安ни다. (探索独岛及其周边的岛屿。)\n\n- 독수리를 (独岛+를): 表示动作的对象是独岛时使用的形式。\n  - 독수리를 방衛하는 것이 중요합니다. (保卫独岛很重要。)\n\n以上是根据韩语语法结构进行的简单变形和解释，实际上在日常使用中，独岛的名称“독수리”通常直接作为名词使用，并不经常进行变形。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1185, 101, ' 뼈쥐', '甲壳虫', '1. 词性：名词\n2. 词义：疲劳，疲倦\n3. 例句：\n   - 일하다 늦어서 완전히 뼈쥐를 끓어요. (工作到很晚，我感到非常疲劳。)\n   - 이 주는 많은 일로 뼈쥐가 나왔어요. (这周因为有很多工作要做，我感到很累。)\n\n变形及其词义：\n- 뼈쥐： 名词，疲劳，疲倦\n  - 예술을 보면 뼈쥐를 치고 싶어요. (看艺术展览可以消除疲劳。)\n- 뼈쥐： 动词，感到疲劳\n  - 휴가를 얼마나 받아야 뼈쥐를 안 해요？ (需要休息多久才不会感到疲劳呢？)\n- 뼈쥐： 形容词，疲倦的\n  - 밤에 늦게 잠을 잤 后， 오늘 날이 뼈쥐한 것 같아요. (昨晚睡得很晚，今天感觉很累。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1186, 101, ' 늑', '驴', '1. 词性：\n- 늑은 한국어 명사입니다. (늑是韩语名词。)\n\n2. 词义：\n- 늑의 가장 일반적인 뜻은 \"곡\" 또는 \"군\"입니다. (늑最常用的意思是“曲”或“军”。)\n- 또한， \"이름\" 또는 \"칭질\"의 뜻도 있습니다. (另外，也有“名字”或“称号”的意思。)\n- 또， \"담\" 또는 \"담기\"의 뜻을 갖습니다. (还有“装”或“装载”的意思。)\n\n3. 例句：\n- 이 곡(늑)은 아주 예쁘게 되었습니다. (这首曲子做得很好听。)\n- 군(늑)에서 벗어나면 안 심할 수 있습니다. (离开军队后可能不习惯。)\n\n变形及其词义和例句：\n- 늑으로： 表示方式或手段，意为“通过”或“用”。\n  - 이 문제를 해결하기 위해서는 이런 방식(늑)으로 처리해야 합니다. (为了解决这个问题，需要以这种方式处理。)\n- 늑이： 表示所属关系，意为“的”。\n  - 그 군(늑)이 사람들은 모두 탈락했습니다. (那个军队的人们全部都撤退了。)\n- 늑에： 表示方向或目的地，意为“到”或“向”。\n  - 군(늑)에 가기 위해서는 무엇样的 준비를 해야 합니까？ (去军队需要做什么样的准备？)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1187, 101, ' 뼈룡', '恐龙', '1. 词性：名词\n2. 词义：云彩、云朵\n3. 例句：\n   - 밤에는 별이 많고， 낮에는 뼈룡이 많습니다. (晚上星星很多，早上云彩很多。)\n   - 밤 바람이 안 吹어도 뼈룡이 나빠지고 있어요. (即使没有风，云彩也在缓缓移动。)\n\n变形及其词义：\n- 뼈루（云）： 名词，指云或云状物。\n   - 예쁘게 뿌리는 뼈루입니다. (是漂亮地漂浮的云。)\n- 뼈림（云彩）： 名词，指天空中的云彩。\n   - 밤 바람과 함께 느낌이 좋은 뼈림입니다. (和晚风一起感觉很好的云彩。)\n- 뼈림하다（多云）： 形容词，描述天气多云。\n   - 오늘 날씨는 뼈림하다. (今天天气多云。)\n- 뼈대（云海）： 名词，指像海洋一样广阔的云层。\n   - 산봉에서 볼 수 있는 뼈대는 정말 풍경이 아름답습니다. (在山顶上能看到的云海真是风景如画。)\n- 뼈돌（云烟）： 名词，指烟雾缭绕的样子。\n   - 새벽에 왕자를 보면 뼈돌이 잘 보입니다. (清晨去田野的话，可以看到云烟。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1188, 101, ' 빙어', '企鹅', '1. 词性：\n- 빙어(名) - 名词\n\n2. 词义：\n- 빙어 - 冰，冰块\n\n3. 例句：\n- 나는 새벽에 커지고， 육쌈에서 빙어를 꺼났다. (我在凌晨醒来时，从冰箱里拿了冰块。)\n- 가십 날 밖에 빙어가 많이 있었습니다. (昨天外面有很多冰块。)\n\n变形及其词义和例句：\n- 빙(名) - 冰，冰块\n  - 빙은 아름다워요. (冰很美丽。)\n- 빙류(名) - 冰淇淋\n  - 나는 빙류를 좋아합니다. (我喜欢吃冰淇淋。)\n- 빙화(动) - 冰冻，结冰\n  - 어느 날， 강이 빙화했습니다. (有一天，河流结冰了。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1189, 101, ' 벗', '鲸鱼', '1. 词性：\n- 벗（kkeut）是一个韩语的名词。\n\n2. 词义：\n- 벗（kkeut）在韩语中主要有两个常用词义：\n  - 表示“角、角落”的意思，用于指代物体的尖角或角落。\n  - 表示“疙瘩、结”的意思，用于指代皮肤上的小肿块或结节。\n\n3. 例句：\n- 커플에 벗이 있어요. (房间里有一个角落。)\n- 허리 앞쪽에 벗이 나타나요. (胳膊前面起了一个疙瘩。)\n\n变形及其词义，每个变形一个例句：\n- 벗을（kkeuteul）：表示“角、角落”的复数形式，用于指代多个角或角落。\n  - 커플에 벗들이 있어요. (房间里有多个角落。)\n\n- 벗이（kkeuti）：表示“疙瘩、结”的形容词形式，用于描述某个地方有疙瘩或结。\n  - 허리 앞쪽이 벗이 나타났어요. (胳膊前面起了疙瘩。)\n\n- 벗으로（kkeuteureuro）：表示“用角、角落”的方式，用于描述使用角或角落进行某种动作或状态。\n  - 커플을 벗으로 지나가요. (穿过房间的角落。)\n\n- 벗이라는（kkeutiraeneun）：表示“被称为角、角落”的意思，用于描述某个地方或物体被命名为角或角落。\n  - 그 곳은 벗이라는 곳입니다. (那个地方被称为角落。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1190, 101, ' 암어', '鳄', '1. 词性：名词\n2. 词义：烟，烟雾\n3. 例句：\n   - 암어가 많이 나온다. (烟冒得很多。)\n   - 彼는 암어를 吸う. (他抽烟。)\n\n变形及其词义：\n- 암： 烟，烟雾\n  - 암이 늦어지다. (烟雾变浓了。)\n- 암으로： 作为烟，以烟的形式\n  - 폐기물은 암으로 버리고 있다. (垃圾被烧成烟了。)\n- 암의： 关于烟的，属于烟的\n  - 암의 위험성을  Emphasize 하다. (强调烟的危险性。)\n- 암을： 把烟，将烟\n  - 암을 밀어내요. (把烟放出来。)\n- 암으로서： 作为烟，以烟的方式\n  - 암으로서 空気을 pollute 하다. (以烟的形式污染空气。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1191, 101, ' 뼈렁이', '海星', '1. 词性：\n- 뼈： 名词，表示“骨头”或“核心、精髓”。\n- 렁이： 名词，表示“骨头”的口语表达。\n\n2. 词义：\n- 뼈： 主要指动物的硬质骨架部分，也可比喻事物的中心或基础。\n- 렁이： 同“뼈”，但更常用于口语中，指骨头。\n\n3. 例句：\n- 뼈： 육류는 뼈이 어려温에서 제Outside로 나왔다. (肉类在低温下会结冰。)\n- 렁이： 앞으로 그 사람의 렁이를 밟지 않겠다. (我以后再也不会相信那个人了。)\n\n变形及其词义：\n- 뼈을 가지고： 持有骨头，比喻支持或维护某事的核心。\n  - 그 팀은 우리 팀보다 더 많은 뼈을 가지고 있어. (那个队比我们队有更多的骨干。)\n\n- 뼈을 넘어： 超越骨头，比喻深入到事物的本质。\n  - 이 문제를 해결하기 위해서는 뼈을 넘어야 한다. (为了解决这个问题，我们需要深入了解其本质。)\n\n- 뼈이 뚫다： 骨头断了，比喻非常严重的失败或挫折。\n  - 그 프로젝트는 돌아가기 전까지 뼈이 뚫었다. (那个项目在结束之前遭遇了重大挫折。)\n\n- 렁이가 쳐진다： 骨头碎了，比喻事情完全崩溃或失败。\n  - 그 사람의 이曄한 친철로 렁이가 쳐진다. (他因为朋友的背叛而心碎。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1192, 101, ' 멧담', '海豚', '1. 词性：名词（Noun）\n2. 词义：\n   - 主要意思是指“心情”，“感觉”，或“气氛”。\n   - 在特定语境下，也可以指代某种特定的情绪状态。\n3. 例句：\n   - 나는 이제 멧담이 좋아지면서 잘 잤다.（我现在心情变好了，所以睡得很好。）\n   - 그는 곁에 있어도 좋은 멧담을 주는 사람일 것 같아.（他即使在旁边也能给人好心情。）\n\n变形及其词义：\n- 멧담이： 心情，感觉的形容词形式，表示“令人感觉良好的”。\n  - 멧담이 군데로 가요.（去让人心情愉快的地方吧。）\n- 멧담하다： 动词形式，意味着“使心情变好”或“感觉良好”。\n  - 이 음악은 나를 멧담하게 해요.（这音乐让我感到心情愉快。）\n- 멧담이라는： 形容词形式，用于形容某事或某物给人带来好心情。\n  - 멧담이라는 겨울샘 풀이에 行钾.（去一个叫做心情愉快的咖啡馆。）\n- 멧담이 것： 名词形式，直接指“好心情”的状态或事物。\n  - 그는 나의 멧담이 것이었다.（他是我心情愉快的原因。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1193, 101, ' 뼈올리', '章鱼', '1. 词性：\n- 뼈올리（kulli）是韩语中的一个动词。\n\n2. 词义：\n- 主要意思是“滚动”。在更广泛的语境中，可以指物体沿表面滚动，也可以比喻某事物或情况的发展、变化。\n\n3. 例句：\n- 땅에서 뿌리를 뼈릴 수 있어요. (在地面上可以滚球。)\n- 사건이 빨리 뼈겨지면， 문제가 더 serious하게 될 수 있습니다. (如果事件迅速发酵，问题可能会变得更加严重。)\n\n变形及其词义：\n- 原型：뼈리（kulli），意为“滚动”，用于描述物体的移动方式。\n- 被动形：뼈리는（kullineun），表示被滚动的状态。\n- 使动形：뼈리시키다（kullishikida），意为“使...滚动”。\n- 完成态：뼈렸（kulleosseotda），表示已经滚动了。\n- 计划态：뼈려고 한다（kulligo haneunda），表示打算滚动。\n\n每个变形的例句：\n- 被动形例句：땅에 뿌리가 뼈리는 것을 보았어요. (我看到球在地面上滚动。)\n- 使动形例句：아기를 좌측으로 뼈리시켜 주세요. (请把孩子往左边滚动一下。)\n- 完成态例句：나는 땅에서 뿌리를 뼈렸어요. (我在地面上滚过球了。)\n- 计划态例句：앞으로 헤어라서를 높이고 뼈려고 합니다. (我打算以后提高头发并尝试卷发。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1304, 104, ' 비행기 ', ' 飞机', '1. 词性：名词\n2. 词义：飞机\n3. 例句：\n   - 저는 첫 탈격에 비행기를 타고 가요. (这是我第一次坐飞机去旅行。)\n   - 비행기가 하늘을 черпаpussleo 가요. (飞机在天空中飞翔。)\n\n变形及其词义：\n- 비행： 动词，飞行\n  -  example: 새로우를 비행시키면 좋습니다. (让海鸥飞行比较好。)\n- 비행장： 名词，飞行员\n  -  example: 그는 우리 국가의 최고 비행장입니다. (他是我国最优秀的飞行员。)\n- 비행기사： 名词，空姐\n  -  example: 비행기사가 택시트에 서식을 줍니다. (空姐在座位上分发餐食。)', NULL, 1, NULL, 'src\\main\\resources\\MP3\\1724122143415.mp3');
INSERT INTO `word_list` VALUES (1305, 104, ' 승객 ', ' 乘客', '1. 词性：\n- 승객（胜格）是一个名词。\n\n2. 词义：\n- 主要指在比赛、竞赛或任何形式的对决中获胜的一方，即“胜利者”。\n\n3. 例句：\n- 이 경기에서 우리 팀이 승객이 되었어요. (在这场比赛中我们队成了胜利者。)\n- 그는 마스터 챔피언 대회의 승객입니다. (他是大师锦标赛的胜利者。)\n\n变形及其词义和例句：\n- 승객은： 是“승객”的尊敬形式，用于需要对胜利者表示尊敬的场合。\n  - 예， 그 선수가 이번 대회의 승객은입니다. (是的，那位选手是这次大赛的胜利者。)\n\n- 승객이라는： 表示“被称为胜利者的”，用于描述某人或某物被认为是优胜者的情况。\n  - 우리 팀은 이번 경기의 승객이라는 팀입니다. (我们队是这次比赛被称为胜利者的队伍。)\n\n- 승객으로： 表示“作为胜利者”，强调某人的身份或角色是胜利者。\n  - 그는 승객으로 인정되었습니다. (他作为胜利者被认可了。)\n\n请注意，韩语中的名词一般不变形，所以“승객”这个词本身没有变形。上述提供的是与“승객”相关的表达方式，而不是“승객”这个词本身的变形。', NULL, 1, NULL, 'src\\main\\resources\\MP3\\1724122157050.mp3');
INSERT INTO `word_list` VALUES (1306, 104, ' 이용권 ', ' 通行证', '1. 词性：名詞\n2. 词义：利用券、优惠券\n3. 例句：\n   - 이용권을 사용하면 가맹 할수 있어요. (使用优惠券可以便宜一些。)\n   - 새로운 이용권이 발행되었어요. (新的优惠券已经发行了。)\n\n变形及词义：\n- 이용 (動詞): 利用、使用\n   - 이용하세요！ (请使用！)\n- 권 (名詞): 券、票\n   - 꽃권을 구입했어요. (我买了花券。)', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1724167833407.mp3');
INSERT INTO `word_list` VALUES (1307, 104, ' 버스 ', ' 巴士', '1. 词性：\n버스 - 名詞（Noun）\n\n2. 词义：\n- 公共汽车（Bus）\n- 巴士（Bus）\n- 公交车（Bus）\n\n3. 例句：\n- 버스를 타고 가요.（我坐公交车去。）\n- 버스 정류장에서 하나 잡아요.（在公交车站等一下。）\n\n变形及其词义：\n- 버스에（介词，表示乘坐公交车）：버스에 타고 가요.（我坐公交车去。）\n- 버스로（副词，表示通过公交车）：버스로 가요.（我通过公交车去。）\n- 버스를（动词，表示乘坐公交车）：버스를 타요.（我乘坐公交车。）', NULL, 1, NULL, NULL);
INSERT INTO `word_list` VALUES (1308, 104, ' 지하철 ', ' 地铁', '1. 词性：\n- 名词 (명사)\n\n2. 词义：\n- 地下铁，地铁\n\n3. 例句：\n- 지하철에 타고 가요. (我要坐地铁去。)\n- 지하철 역이 어디인가요？ (地铁站在哪里？)\n\n变形及其词义：\n- 没有特定的变形。韩语中“지하철”是一个固有名词，通常不会进行变形。', NULL, 1, NULL, NULL);
INSERT INTO `word_list` VALUES (1309, 104, ' 경로 ', ' 路线', '1. 词性：\n- 경로는 명사(noun)입니다.\n\n2. 词义：\n- 주요 뜻： \"path\", \"route\", \"way\"\n- 추가 뜻： \"method\", \"manner\", \"procedure\"\n\n3. 例句：\n- 이 책에서 수학의 기본 경로를 배우십시오. (Learn the basic path of mathematics from this book.)\n- 그는 살아 나서 골고칠 수 있는 길을 찾았습니다. (He found a way to survive after struggling hard.)\n\n變形 및 뜻：\n- 경로하다 (verb): follow a route or path; 예： 이 길을 Strictly follow this road.\n- 경로성 (adjective): pertaining to a method or procedure; 예： 경로성 문제 The problem related to the method.\n- 경로를 찾다 (phrasal verb): find a way or method; 예： 해결 방법을 찾아야 합니다. We need to find a solution.', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1310, 104, ' 탑승 ', ' 登机', '1. 词性：动词\n2. 词义：搭乘，乘坐（通常用于交通工具）\n3. 例句：\n   - 앞에 탑승하는 사람이 많습니다. (前面有很多人在搭乘。)\n   - 버스를 탑승하고 가壮시로 갔어요. (我搭乘公交车去了壮市。)\n\n变形及其词义：\n- 탑승하다 (基本形态，动词原形)：乘坐，搭乘\n  - 예쁜 날 좋아， 지하철을 탑승하다 보이에요. (天气好的话，我想去坐地铁。)\n- 탑승한다 (过去时态)：曾搭乘\n  -  yestoday,  subwaypike 93  deo  ppare  se yo. (昨天我搭乘了地铁9号线去机场。)\n- 탑승해야 합니다 (义务或建议形态)：应该搭乘\n  -  yeongeunhaji  aninde,  taxireul  ppare  se yo. (时间紧迫，我们应该打车去。)\n- 탑승했다 (完成体)：已搭乘\n  -  yeongwonheye  ppare  se yo. (我已经搭乘了去机场的大巴。)\n- 탑승하게 되요 (假定形态)：假如搭乘\n  -  yeogiseoneun  ppare  se yo. (如果明天下雨，我就搭公交去。)\n\n注意：韩语中的动词变形和例句需要根据上下文和具体语法结构来适当调整，上述提供的是一些基本形态和常见用法。', NULL, 1, NULL, NULL);
INSERT INTO `word_list` VALUES (1311, 104, ' 도로 ', ' 道路', '1. 词性：\n도로는 명사 (名词)입니다.\n\n2. 词义：\n- 陸地의 이동 경로를 나타낼 때 사용하는 言葉입니다.\n- 친구가 주어진 정보에 따르면， \"도로\"는 \"路\"를 뜻하며， \"公路\"를 의미합니다.\n\n3. 例句：\n- 이 도로를 따라서면 그곳으로 갈 수 있습니다.\n- 도로는 여기서부터 시작되고 끝이 몇 킬로 멀리 있습니다.\n\n變形：\n- 도로가 (動詞形): 이 도로가 이미 세우셨습니다.\n- 도로에 (助詞): 우리는 도로에 오신 것을 기대합니다.\n- 도로에서 (副詞): 도로에서 봤는 적이 없습니다.', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1724122196084.mp3');
INSERT INTO `word_list` VALUES (1312, 104, ' 교통률 ', ' 交通灯', '1. 词性：名词（Noun）\n2. 词义：交通量，指的是一定时间内通过某一地点的交通工具数量。\n3. 例句：\n   - (1) 이 지역의 교통률이 특히 많습니다. (这个地区的交通量特别大。)\n   - (2) 새로운  bride 를 열어서 교통률을 느리게 하는 것이 좋아보입니다. (我认为开放新的道路以减缓交通量会比较好。)\n\n变形及其词义：\n- 교통량（交通量）：同“交通量”，表示数量的概念。\n  - 예) 규모가 크기 때문에 이 지역의 교통량은 매우 많습니다. (由于规模大，这个地区的交通量非常多。)\n\n- 교통류（交通流）：指交通流动的状态或特性。\n  - 예) 이곳의 교통류가 흐르고， 따뜻하게 합니다. (这里的交通流很顺畅，没有拥堵。)\n\n- 교통자（交通者）：参与交通的人或车辆。\n  - 예) 교통자들이 정착하고 안정적인 여행을 얻기 위해서 이 길을 건설하였습니다. (为了交通者能够安全且平稳地旅行，建造了这条路。)\n\n请注意，韩语中单词的变形和词义可能会根据上下文有所不同，上述解释是基于一般情况。', NULL, 1, NULL, NULL);
INSERT INTO `word_list` VALUES (1313, 104, ' 승차 ', ' 上车', '1. 词性：名词\n2. 词义：胜利；成功。\n3. 例句：\n   - 우리 팀은 이번 경기에서 승차를 맞추었다. (我们队在这次比赛中取得了胜利。)\n   - 그는 사랑의 승차를 歡담하고 있다. (他沉浸在爱情的胜利中。)\n\n变形及其词义：\n- 승리 (动词)：赢得，获胜。\n  - 우리 팀은 이번 경기를 승리했다. (我们队赢得了这次比赛。)\n- 승리하다 (动词)：赢，战胜。\n  - 우리는 어려움을 승리하고 있다. (我们正在战胜困难。)\n- 승리한 (形容词)：胜利的，成功的。\n  - 우리 팀은 승리한 결과를 보이고 있다. (我们队展现了一个胜利的结果。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1314, 104, ' 도로공사 ', ' 道路工程', '1. 词性：\n도로공사 - 名词（noun）\n\n2. 词义：\n- 道路工程（road construction）\n- 公路工程（highway engineering）\n\n3. 例句：\n- 새로운 도로공사가 진행되고 있어요. (有一个新的道路工程正在进行。)\n- 이 지역의 도로공사는 끝나서 그 곳에 대한 이용자의 不滿이 많습니다. (这个地区的公路工程结束后，那里的使用者有很多不满。)\n\n变形及其词义：\n- 도로공사에 참여하면서 신뢰感을 느껴요. (参与道路工程时增加了信任感。)\n- 도로공사를 완료하고 나서 그 곳은 더욱 편리해졌습니다. (完成道路工程后，那里变得更方便了。)\n- 도로공사를 통과하면 이미 새로운 도로가 만들어졌습니다. (通过道路工程，已经建了一条新路。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1315, 104, ' 급행 ', ' 快行', '1. 词性：名词\n2. 词义：急行，快走\n3. 例句：\n   - 그는 급행해서 버스를 �想念했다. (他快步走着，错过了公交车。)\n   - 급행하면 기쁘지 않아요. (走得太快并不好。)\n\n变形及词义：\n- 급행히다 (动词)：快速行走\n   例句：彼は急いで学校に向かっています。(他正快速地朝学校走去。)\n\n- 급행한다 (形容词)：快速的，迅速的\n   例句：그는 급행한 애тitude로 문제를 처리합니다. (他以迅速的态度处理问题。)\n\n- 급행을 하다 (动词短语)：进行快速行走\n   例句：우리는 급행을 해야 합니다. (我们需要快速行走。)\n\n- 급행으로 (副词短语)：快速地\n   例句：그는 급행으로 가요. (他会快速地去。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1316, 104, ' 지点 ', ' 地点', '1. 词性：名词\n2. 词义：时期，时候\n3. 例句：\n   - 이 지点에는 흐리고 춥다. (这个时候很冷而且多风。)\n   - 그 지点부터 彼女와 우정을 맺었습니다. (从那个时候开始，他和她就确定了关系。)\n\n变形及词义：\n- 지点에 (在...时候)：表示具体的时间点或时期。\n  - 例句：지点에 봄길 보면 꽃들이 전혀 늘어나요. (在春天的时候，花朵都盛开了。)\n\n- 지点이 (是...时候)：用于强调某个特定的时间或时期。\n  - 例句：이 지点이 우리 첫 만남일 때였습니다. (那是我们初次见面的时候。)\n\n- 지点에서 (从...时候起)：表示从某个时间点或时期开始。\n  - 例句：학교에 입장한 지点에서 우리는 좋은 친구가 되었습니다. (从进入学校的时候起，我们就成为了好朋友。)\n\n- 지点까지 (到...时候为止)：表示直到某个时间点或时期。\n  - 例句：앞으로 지点까지 우리는 같이 Archive를 열심히 합시다. (从现在到那个时候为止，我们会一起努力开设档案馆。)', NULL, 1, NULL, NULL);
INSERT INTO `word_list` VALUES (1317, 104, ' 택시 ', ' 出租车', '1. 词性：\n- 택시： 名詞(noun)\n\n2. 词义：\n- 암묵적인 이상， 이상하다(vague suspicion, to suspect)\n\n3. 例句：\n- 그는 나를 택시하고 있어요. (He has a vague suspicion of me.)\n- 이 사건에 대한 택시가 많습니다. (There are many suspicions about this case.)\n\n變形及其词义：\n- 택시하다： 動詞(verb), 이상하다(to suspect)\n  - 그는 나를 택시하고 있어요. (He is suspecting me.)\n\n- 택시적： 形容詞(adjective), 이상하다(suspicious)\n  - 그는 택시적인 모습을 보여요. (He shows a suspicious attitude.)\n\n- 택시지： 名詞(noun), 이상(suspicion)\n  - 그는 나에게 택시지를 느껴요. (He has a suspicion towards me.)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1318, 104, ' 하차 ', ' 下车', '1. 词性：\n하차는 명사(名词)입니다.\n\n2. 词义：\n- 첫 번째의 의 의미를 갖추는 것， 또는 시작되는 것을 나타낼 때 사용합니다.\n- 「初」를 의미합니다.\n- 「最初」를 의미합니다.\n\n3. 例句：\n- 이 책은 우리 학교의 첫 번째 사전입니다.\n- 그는 우리 팀의 첫 번째 선수입니다.\n\n變形：\n- 하： 「初」를 의미합니다. (예： 이 책은 우리 학교의 첫 本입니다.)\n- 차： 「初」를 의미합니다. (예： 그는 우리 팀의 첫 名입니다.)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1319, 104, ' 정류장 ', ' 车站', '1. 词性：名词\n2. 词义：操场，运动场\n3. 例句：\n   - 저는 정류장에서 축구를 합니다. (我在操场上踢足球。)\n   - 어린 아이들은 정류장에서 놀리고 있습니다. (孩子们在操场上玩耍。)\n\n变形及词义：\n- 정류장으로 (作为操场)\n  - 이 공원은 정류장으로 사용됩니다. (这个公园被用作操场。)\n- 정류장에 (在操场)\n  - 우리는 정류장에 볼링을 합니다. (我们在操场上打篮球。)\n- 정류장에서 (从操场)\n  - 우리는 정류장에서 시작하고 왔습니다. (我们从操场开始来的。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1320, 104, ' 慢行 ', ' 慢行', '1.词性：\n慢行的韩语单词是 \"느리다\" (neolida)，它是一个动词。\n\n2.词义：\n- 慢行：表示行动或处理事情的速度较慢。\n- 缓慢：形容速度不快或动作不迅速。\n\n3.例句：\n- 이 길은 느리다， 그래서 우리는 더 빠르게 가야 합니다. (这条路很堵，所以我们得快点走。)\n- 그 사람은 생각이 느리다， 그래서 질문에 답을 나久旱未雨呢. (那个人思维迟钝，所以回答问题需要很长时间。)\n\n变形及词义：\n- 느리다的原型就是\"느리다\"，没有其他变形形式。在韩语中，动词通常通过添加后缀来形成不同的时态或语态，但\"느리다\"本身作为一个动词，并没有特殊的变形形式来表示不同的词义。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1321, 104, ' 주유소 ', ' 加油站', '1. 词性：名词\n2. 词义：加油站，加油所\n3. 例句：\n   - 저는 주유소에서 앞범으로 주유를 받았어요. (我在加油站加了满箱油。)\n   - 우리 차는 주유소에 가야 하고， 그래서 급히 빨리 출발해요. (我们的车需要去加油站，所以我们得快点出发。)\n\n变形及其词义：\n- 주유 (动词): 加油，填充燃料\n   - 예쁜 여행을 위해 차를 주유해야 합니다. (为了长途旅行，我们需要给车加油。)\n\n- 주유소에 (介词+名词): 在加油站\n   - 팬ت지t 주유소에 도착하면 앞범으로 주유할 수 있어요. (一到加油站就可以加满油。)\n\n韩语中“주유소”主要用作名词，表示“加油站”，没有其他常见变形。上述提供的“주유”作为动词使用，意为“加油”，而“주유소에”是结合了介词和名词的表达，用来说明地点。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1322, 104, ' 하탄 ', ' 行李', '1. 词性：名詞\n2. 词义：闲暇，空闲时间；假期，休假\n3. 例句：\n   - 이 봄학기는 절약한 하탄이 있었다. (这个春季学期有短暂的假期。)\n   - 그는 하탄 시간에 책을 읽어 수학을 자극해야 합니다. (他需要在假期期间读书来提高数学能力。)\n\n變形及其词义和例句：\n- 하탄期（名词）：假期期间\n  - 하탄기간에 가족과 함께 여행을 떠나요？ (假期期间你和家人一起去旅行吗？)\n\n- 休暇（名词）：休假，休息时间\n  - 이 주م Pero는 休暇로 친국에 가서 친절한 날들을 보낼 것이라고 합니다. (这周Pero因为休假去肯尼亚享受温暖的时光。)\n\n- 休闲（名词）：休闲活动\n  - 周末에는 농구를  play 하는 것을 含め rest Activity 사용할 수 있습니다. (周末可以包括打篮球作为休闲活动。)\n\n韩语单词“하탄”主要表示闲暇或假期的时间，其变形包括指特定时间段的“하탄期”，同义词“休暇”用于描述休假或休息时间，而“休闲”则是指休闲活动。这些词汇在日常会话中常用来讨论与休息和娱乐相关的主题。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1323, 104, ' 기차 ', ' 火车', '1. 词性：\n- noun (명사)\n\n2. 词义：\n- 火车 (huǒchē)\n\n3. 例句：\n- 나는 옛날에 기차를 타고 여행을 떴다. (我过去常坐火车旅行。)\n- 기차는 이 시간이 가장 좋은 교통 수단입니다. (火车是这个时间段最好的交通工具。)\n\n变形及词义：\n- 기차： 火车 (huǒchē)\n- 기차를 타다： 坐火车 (zuò huǒchē)\n- 기차 타기： 乘火车 (chéng huǒchē)\n- 기차 승차： 上火车 (shàng huǒchē)\n- 기차 하차： 下火车 (xià huǒchē)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1352, 104, ' 도시 ', ' 渡口', '1. 词性：\n도시（都市）是名词。\n\n2. 词义：\n- 城市，城镇\n\n3. 例句：\n- 이 도시에는 많은 사람들이 살고 있습니다. (这个城市里居住着许多人。)\n- 도시 생활이 싫어하면 곰곰이나 농부가 좋습니다. (如果你不喜欢城市生活，那么山村或者农村会更适合你。)\n\n变形及其词义：\n- 都市化 (도시화): 城市化，指城市扩张或发展的过程。\n  - 예층의 도시화는 농림을 축소시키고， 인구를 都会로 이동시킨 것으로 인식합니다. (预计的城市化将减少农田面积，并促使人口向城市迁移。)\n\n- 都市的 (도시적): 与城市相关的，形容词形式。\n  - 도시적인 환경에서 생活泼躍한 사람들을 볼 수 있습니다. (你可以在都市的环境中看到活跃的人们。)\n\n韩语例句提供了单词“도시”的词性、常用词义和两个例句，以及它的变形“都市化”和“都市的”各自的词义和例句。这些例句展示了如何在实际语境中使用这些词汇。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1353, 104, ' 버스정류소 ', ' 公交站', '1. 词性：名词\n2. 词义：公交车站\n3. 例句：\n   - 저는 버스정류소에서 버스를 타고 가요. (我在公交车站等公交车。)\n   - 버스정류소가 너무 멀리 있어요. (公交车站离得太远了。)\n\n变形及其词义：\n- 버스： 名词，意为“公交车”\n  - 예쁜 버스를 타고 가요. (我坐公交车去。)\n- 정류소： 名词，意为“车站”\n  - 지하철 정류소가 어디인가요？ (地铁站在哪里？)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1354, 104, ' 항구 ', ' 港口', '1. 词性：名词\n2. 词义：港口，口岸\n3. 例句：\n   - 이 섬에는 항구가 두 개가 있습니다. (这个岛上有两个港口。)\n   - 항구에서 출発하면 어딘가를 갈 수 있을까？ (从港口出发能去哪里？)\n\n变形及其词义：\n- 항： 港，指港口的简称。\n  - 예쁜 항이 있어요. (有个不错的港口。)\n- 구： 口，通常用于合成词中表示入口或部分。\n  - 입구로에서 사람이 많습니다. (入口处人很多。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1355, 104, ' 도로명 ', ' 路名', '1.词性：\n도로명（道路名）是名词。\n\n2.词义：\n- 道路的名称\n- 街道的名字\n- 路名\n\n3.例句：\n- 이 지역의 도로명이 무엇게 변했어요？ (这个地区的路名有什么变化吗？)\n- 귀하는 이 도로명을 알고 있습니까？ (您知道这条路的名字吗？)\n\n变形及其词义：\n- 도로： 道路，路\n   - 예쁜 도로입니다. (是一条漂亮的路。)\n- 명칭： 名称，名字\n   - 그 사람의 명칭은 무엇인가요？ (那个人的名字是什么？)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1356, 104, ' 획득 ', ' 票务', '1. 词性：名词（名詞）\n2. 词义：获得，收获\n3. 例句：\n   - 철학적인 성과를 획득하는 것이 중요합니다. (在学术上取得成就是重要的。)\n   - 彼女と의 사랑은 그의 人生中最も 宝貴한 획득입니다. (与她的爱情是他一生中最宝贵的收获。)\n\n变形及其词义：\n- 획득하다（动词）：获得，得到\n   - 그는 대학에서 우수한 성적을 획득하였다. (他在大学里取得了优异的成绩。)\n- 획득자（名词）：获得者，得主\n   - 小説 大赏의 획득자가 trophy를 받았다. (小说大奖的得主领取了奖杯。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1357, 104, ' 탄수 ', ' 航班', '1. 词性：\n- 탄수는 명사 (名词)이며， 동사 (动词)로도 사용됩니다.\n\n2. 词义：\n- 명사로서는 \"糖水\"를 의미하며， 동사로서는 \"用甜言蜜语哄骗\"을 의미합니다.\n\n3. 例句：\n- mingtiao:\n  - 나는 커피에 탄수를 추가해요. (我在咖啡里加糖水。)\n- dongtiao:\n  - 그는 여자들을 탄수로 춤ч鹑고 있었습니다. (他用甜言蜜语欺骗了女人们。)\n\n變形及其词义：\n- 탄： noun for \"sugar\"\n  - 나는 커피에 탄을 추가해요. (我在咖啡里加糖。)\n\n- 수： noun for \"water\"\n  - 나는 물고기를 수에 담아요. (我把鱼放在水里。)\n\n- 탄수： noun for \"sugar water\" or verb for \"to sweet talk\"\n  - 나는 커피에 탄수를 추가해요. (我在咖啡里加糖水。)\n  - 그는 여자들을 탄수로 춤ч鹑고 있었습니다. (他用甜言蜜语欺骗了女人们。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1358, 104, ' 급행도 ', ' 快行道', '1. 词性：名词\n2. 词义：程度，浓度，密度，强度\n3. 例句：\n   - 이 커피는 급행도가 너무 강하다. (这杯咖啡的浓度太高了。)\n   - 이 액자의 급행도는 어릴 수 있어요？ (这药水的剂量可以调节吗？)\n\n变形及词义：\n- 급행： 动词，意为“浓缩”，“加强”\n  - 예리를 급행해야 합니다. (需要加强管理。)\n- 급행된： 形容词，意为“浓缩的”，“加强的”\n  - 급행된 커피를 暍많이 좋습니까？ (你喜欢喝浓咖啡吗？)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1359, 104, ' 편도 ', ' 便道', '1. 词性：名词\n2. 词义：方便，便利，容易\n3. 例句：\n   - 이 책이 편도하다 (这本书很容易读)\n   - 편도한 방법을 따라서 문제를 해결하였다 (按照简单的方法解决了问题)\n\n变形及其词义：\n- 편하다 (形容词)：简单，容易\n  - 이 문제는 편하다 (这个问题很简单)\n- 편안하다 (形容词)：舒适，安逸\n  - 이 옷은 편안하다 (这件衣服很舒适)\n- 편의하다 (形容词)：方便，便利\n  - 이 곳에 살고 있다면 편의하다 (如果住在这里会很方便)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1360, 104, ' 지하철역 ', ' 地铁站', '1. 词性：\n지하철역 - 名词 (Noun)\n\n2. 词义：\n- 地下铁站（Subway station）\n- 地铁站（Metro station）\n\n3. 例句：\n- 이 지하철역에서 버스를 타고 가요. (在这个地铁站坐公交车去。)\n- 지하철역에는 여러 선로의 열차가 이루어지고 있습니다. (地铁站由多条线路的列车组成。)\n\n变形及其词义和例句：\n- 지하철 - 地铁 (Subway)\n  - 지하철에 타고 갈 것입니다. (我将乘地铁去。)\n\n- 철 - 铁 (Iron/Station)\n  - 철은 강한 재료입니다. (铁是一种坚硬的材料。)\n  - 철로는 지하철역이 많습니다. (这条线上有很多地铁站。)\n\n- 역 - 站 (Station)\n  - 공항이나 기차역， 버스역을 모두 \'역\'라고 합니다. (机场、火车站和公交车站都被称为“站”。)\n  - 앞 정류장에서 버스를 타고 가요. (在前面的公交站坐车去。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1361, 104, ' 버스정류장', '公交车站', '1. 词性：名词\n2. 词义：汽车站、巴士站\n3. 例句：\n   - 버스정류장에서 버스를 타고 가요. (在汽车站乘公交。)\n   - 버스정류장에 도착하면 곧 우리 집이 볼 수 있어요. (到达汽车站后，很快能看到我们的家。)\n\n变形及词义：\n- 버스： 名词，意为“巴士”或“公交车”。\n  - 그는 버스로 通学합니다. (他乘公交车上学。)\n- 정류장： 名词，意为“车站”或“站点”。\n  - 지하철 정류장에서 내ра앙을 놓았어요. (我在地铁站放了一个包。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1362, 104, ' 급행선', '快行线', '1. 词性：名词\n2. 词义：紧急情况；突发状况；紧急事件\n3. 例句：\n   - 급행선이 발생하면 즉각 처리해야 합니다. (如果发生紧急情况，需要立即处理。)\n   - 급행선에 대한 지원을 빠르게 제공해야 합니다. (应迅速提供针对紧急情况的支持。)\n\n变形及其词义和例句：\n- 没有特定的变形形式。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1363, 104, ' 도로명所', '道路标志', '1. 词性：名词\n2. 词义：道路名称、路名\n3. 例句：\n   - 이 지역에서 가장 ش姝蒙的 도로명은 어떻게 되나요？ (在这个地区，最有名的路名是什么？)\n   - 우리 집에는 새로운 도로명이 豎立되었습니다. (我们家有了一个新的路名。)\n\n变形及其词义：\n- 도로명을 (道路名称的宾格形式)：用于需要宾格的动词后，表示“把路名”或“将路名”。\n   - 예를 들어， 우리는 신규 아파트의 도로명을 정의하고 있습니다. (例如，我们正在为新公寓定道路名称。)\n\n- 도로명이 (道路名称的主格形式)：用作主语时使用。\n   - 우리 동네의 도로명이 모두 변경되었습니다. (我们街区的所有路名都改变了。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1364, 104, ' 수입桥', '入口桥', '1. 词性：\n- 수입桥 (su-ib kyo) 是名词。\n\n2. 词义：\n- 수입桥主要指的是一种桥梁类型，通常是指小型的、用于过河或其他水体的桥梁。\n\n3. 例句：\n- 이 질대는 수입橋를 건설하고 있습니다. (这个村子正在建设一座数入桥。)\n- 그 곳에 있는 수입橋가 편하게 지나칠 수 있어요. (那里的数入桥很容易就能走过去。)\n\n变形及词义：\n- 수입 (su-ib): 名词，指进入或输入的动作，但在此上下文中，它作为“数入桥”的一部分，不单独使用。\n- 例句： 컴퓨터에 데이터를 수입합니다. (将数据输入到计算机中。)\n\n- 桥 (kyo): 名词，意为桥梁。\n- 例句： 그 강을 건널 때 새로운 교가 필요해요. (要过那条河时需要一座新桥。)\n\n请注意，\"数入桥\"作为一个整体词汇，在韩语中并没有其他明显的变形，因为它是一个特定的名词，而不是由多个独立意义的词组合而成的复合词。每个组成部分（如“数入”和“桥”）可以有自己的意义和用法，但它们组合在一起时，特指一种桥梁类型。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1365, 104, ' 도로교통', '道路交通', '1. 词性：\n도로교통(道路交通)是名词。\n\n2. 词义：\n- 主要指与道路有关的交通活动，包括车辆行驶、交通规则、交通安全等。\n- 也可以指涉及道路交通的设施、设备和相关服务。\n\n3. 例句：\n- 나는 새로운 도로교통 규정을 배우고 있어요. (我正在学习新的道路交通规则。)\n- 도로교통이 흐르다 놓으면 여행은 어려워지니까 하고 생각합니다. (如果道路交通状况不好，我认为旅行会变得困难。)\n\n变形及其词义和例句：\n- 도로교통에 관한 (关于道路交通的):\n  - 词义：涉及或与道路交通相关的。\n  - 예句： 도로교통에 관한 정보를 많이 얻었어요. (我获得了许多关于道路交通的信息。)\n\n- 도로교통 시스템 (道路交通系统):\n  - 词义：指的是一个地区或国家的道路交通网络和管理系统。\n  - 예句： 도로교통 시스템을 개선하는 것은 중요하다. (改善道路交通系统很重要。)\n\n请注意，韩语单词的变形通常不改变原有单词的基本含义，而是通过结合其他词汇来扩展或具体化其意义。以上提供的例句均为韩语表达。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1366, 104, ' 주유', '加油', '1. 词性：名词（Noun）\n2. 词义：\n   - 油，燃料\n   - 石油\n3. 例句：\n   - 차는 주유를 채우십시오. (请给车加满油。)\n   - 주유가 곧 끝나요. (油快用完了。)\n\n变形及其词义：\n- 주유기：加油机，加油站\n  - 주유기에 가서 주유를 채웠어요. (我去了加油站加油。)\n- 주유하다：加油，动词形态\n  - 차를 주유해야 합니다. (需要给车加油。)\n- 주유소：加油站，小店\n  - 주유소에서 편의 store에 가서 사과�을 살았어요. (我在加油站的便利店买了零食。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1367, 104, ' 항공기', '航海器', '1. 词性：名詞（noun）\n2. 词义：飛行機（airplane）\n3. 例句：\n   - 항공기가 蒼空を切っています。 (The airplane is cutting through the blue sky.)\n   - 明後日에 항공기로 出張하고 있습니다. (I will be traveling by airplane for business the day after tomorrow.)\n\n变形及词义：\n- 항공： 飞行（flight, to fly）\n  - 예쁜 항공사는 우리 나라의 영鉴이며 질서는 세계 수준이며， 그들의 성과는 우리 나라의 발전을 향해 많은 黄献을 한 것이라는 것으로 인정되어야 합니다.\n    (Excellent pilots are the pride of our country and their skills are world-class; it should be acknowledged that their achievements have made significant contributions to the development of our nation.)\n\n- 기： 機器、工具（machine, tool）\n  - 컴퓨터는 현대 사회에서 굉장히 중요한 기衅입니다.\n    (Computers are extremely important tools in modern society.)\n\n请注意，韩语单词“항공기”是一个合成词，由“항공”（飞行）和“기”（机器/工具）组成，直接指代“飛行機”（airplane）。上述提供的变形和词义是基于将合成词拆分成单独的部分来说明的。在实际应用中，“항공”和“기”作为独立的词汇拥有各自的含义和用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1368, 78, ' 랩 ', ' 拉丁舞', '1. 词性：\n- 랩(ram) 是韩语中的一个名词，通常用于表示某种特定的空间或场所。\n\n2. 词义：\n- 主要词义为“房间”、“室”或“屋子”。\n\n3. 例句：\n- 이 빈 랩에는 책장이 있어요. (这个空房间里有书架。)\n- 우리가 살고 있는 랩은 어딜 크게요？ (我们住的房间有多大？)\n\n变形及其词义与例句：\n- 랩으로 (rameuro): 以“房间”为单位，例如：책장을 랩으로 갖다 놓았어요. (我按房间分了书架。)\n- 랩 안 (ram an): 在房间里，例如：나는 랩 안에 있어요. (我在房间里。)\n- 랩 밖 (ram bak): 房间外，例如：랩 밖에는 풀이 있어요. (房间外有个池子。)\n\n请注意，以上信息基于对韩语的一般理解，并可能根据不同地区或语境有所变化。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1369, 78, ' 캐리어 ', ' 摇摆舞', '1. 词性：名詞\n2. 词义：\n   - 小的或中型的商店，通常出售食品、饮料等。\n   - 特指咖啡店或类似的休闲场所。\n3. 例句：\n   - 저는 커피를 좋아하므로 주변의 캐리어에서 많이 去了。(我喜欢咖啡，所以经常去附近的咖啡店。)\n   - 친구들과 함께 캐리어에 가서 약간 차話하고 싶습니다. (我想和朋友们一起去咖啡店聊一会儿。)\n\n變形及其词义：\n- 캐리어man（男性店员）：在咖啡店里工作的男性员工。\n  - 캐리어man이라는 친구가 있어요. (我有一个朋友是咖啡店的员工。)\n\n- 캐리어man（女性店员）：在咖啡店里工作的女性员工。（注：这里使用同一个词来指代男女店员，但通过上下文可以区分性别）\n  - 캐리어man은 우리 캐리어의 멋지는 사람입니다. (我们的咖啡店员工非常出色。)\n\n请注意，韩语中没有直接对应“café”一词的变形，上述变形是基于假设情景创造的，实际上并不存在这样的用法。通常来说，“캐리어”这个词在韩语中不会像其他语言那样有复杂的变形，而是作为一个独立的名词使用。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1370, 78, ' 풋캠프 ', ' 霹雳舞', '1. 词性：\n- 풋캠프 (Punchamp) - 通常用作名词。\n\n2. 词义：\n- 主要指“拳头”或“拳打”，也可以泛指任何形式的打击或冲击。\n\n3. 例句：\n- 그는 벌이에 풋캠프를 瀟灑하게 뿌리셨다. (他潇洒地挥了一拳向墙壁。)\n- 풋캠프가 바람에 빠질 수 있다. (拳头能破风。)\n\n变形及词义：\n- 풋캠프ing (Punchamping) - 表示正在进行拳击动作的状态。\n  - 그는 헬스кember를 풋캠프ing 한다. (他正在拳击练习沙袋。)\n\n- 풋캠프ed (Punchamped) - 表示已经被拳击过的状态。\n  - 그는 상대방을 풋캠프ed 했다. (他已经拳击过对手了。)\n\n请注意，\"풋캠프\"在韩语中不是一个标准词汇，上述内容是基于假设的构词和用法来编写的。在实际应用中，可能需要根据具体语境调整词义和用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1371, 78, ' 힘춤 ', ' 力量舞', '1. 词性：\n힘춤 - 名词 (Noun)\n\n2. 词义：\n- 力量的消耗，努力\n- 劳累，疲劳\n- 劲头，干劲\n\n3. 例句：\n- 이 일을 하면서 힘춤이 많이 나왔다. (做这项工作感到很劳累。)\n- 힘춤을 daràsǒ yagihaey yo. (我需要休息一下来恢复体力。)\n\n变形及其词义和例句：\n- 힘춤에 - 在努力中\n  - 힘춤에 daràsǒ geureohkeu iyagihaey yo. (我在努力中，稍后说。)\n\n- 힘춥 - 努力地，用力地\n  - 그 사람은 힘춥 공부한다. (那个人学习很努力。)\n\n- 힘내 - 努力，尽力\n  - 이 사람은 힘내 살고 있다. (这个人生活得很努力。)\n\n请注意，韩语单词“힘춤”主要表示劳累或努力的状态，而其变形则侧重于描述努力的行为或状态。以上提供的例句均为韩语表达。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1372, 78, ' 란 ', ' 伦巴舞', '1. 词性：依存词（助词）\n2. 词义：表示推测或假设的转折，相当于“如果”。\n3. 例句：\n   - 나는 란 그 사람이 찾고 있어요. (我如果是那个人在找。)\n   - 란 내가 그 일을 할 수 있다면... (如果我能做那件事...)\n\n变形及其词义：\n- 란가 (如果)：用于假设条件的开始，表达“如果”的意思。\n  - 란가 夏天来临时，我们就去海边。(여름이 오면， 우리는 해변으로 가요.)\n- 란似的 (像似的)：表示相似或类似。\n  - 他的表情就像看到了鬼一样。(그의 표정은 귀를 보았덧에 닮았다.)\n- 램 (语气词)：用于口语中，表示轻微的假设或推测。\n  - 这件衣服怎么样？我觉得挺适合你的。(이 옷은 어떻게？ 나는 너에 잘 맞을 것 같아.)\n\n请注意，韩语中的依存词通常与句子的其他部分结合使用，单独使用时可能不符合语法规则。以上例句均为正确用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1373, 78, ' 풍ра미 ', ' 芭蕾舞', '1. 词性：名词\n2. 词义：风格，样式，类型\n3. 例句：\n   - 이 옷은 어떤 풍ра미인가요？ (这件衣服是什么样的风格？)\n   - 그는 사람에게 좋은 풍ра미를 보여주고 있습니다. (他给人展示了好的风格。)\n\n变形及词义：\n- 풍ра미하다 (动词)：具有风格，表现出风格\n  - 예의 풍ра미를 가지고 있어요. (拥有优雅的风格。)\n- 풍ра미적 (形容词)：风格的，样式的\n  - 풍ра미적인 옷을 입고 싶습니다. (我想穿有风格的衣服。)\n- 풍ра미형 (名词)：风格型，样式型\n  - 이 옷은 풍ра미형이 좋은데요. (这件衣服的样式很好。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1374, 78, ' 캡짱 ', ' 街舞', '1. 词性：名词\n2. 词义：胶囊\n3. 例句：\n   - 약국에서 캡짱을 구입하고 가셨습니다. (我在药店买了胶囊。)\n   - 이 캡짱은 몇 번 일으면 좋겠어요？ (这种胶囊一天吃几次比较好？)\n\n变形及词义：\n- 캡짱이 (胶囊剂)：一种药物形式，指将药物装入胶囊中制成。\n  - 약품 중 캡짱이가 最喜欢的一种形态。)\n- 캡짱형 (胶囊型)：形容某物形状像胶囊。\n  - 이 캡짱형 디자인의 지姍姗来迟。)\n- 캡짱화 (胶囊化)：将某物转化为胶囊形式的过程。\n  - 이 약품을 캡짱화하면 복용 便宜。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1375, 78, ' 밴드 ', ' 现代舞', '1. 词性：\n- **Noun (名词)**: 밴드 (band)\n\n2. 词义：\n- **乐队**：通常指演奏音乐的团体，可以是摇滚、流行等各种风格的。\n\n3. 例句：\n- **이 밴드는 우리 학교의 가장  Renowned band입니다.** (这个乐队是我们学校最著名的乐队。)\n- **밴드가 공연를 합니다.** (乐队在演出。)\n\n4. 变形及其词义与例句：\n- **变形不适用于此词，因为“밴드”是一个名词，没有动词形态或其他形式的变形。**\n\n以上是关于韩语单词“밴드”（band）的基本用法和信息。由于“밴드”作为名词，主要指代乐队或类似音乐组合，并没有复杂的变形或多种语义层面的变化，所以它的使用相对直接且专一。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1376, 78, ' 춤을 이해하다 ', ' 理解舞蹈', '1. 词性：\n- 动词 (동사)\n\n2. 词义：\n- 跳舞，舞蹈\n\n3. 例句：\n- 나는 춤을 좋아합니다. (我喜欢跳舞。)\n- 그는 춤을 잘 하는 것이 좋습니다. (他擅长跳舞。)\n\n4. 变形及词义：\n- 춤을 이해하다： 跳舞\n- 춤을 이해한다： 跳舞了（完成时态）\n- 춤을 이해하지 않다： 不跳舞\n- 춤을 이해하면： 如果跳舞\n- 춤을 이해하기： 跳舞的动作或状态\n\n5. 每个变形的例句：\n- 나는 춤을 이해하고 있습니다. (我正在跳舞。)\n- 그는 춤을 이해하고 왔습니다. (他来之前跳了舞。)\n- 나는 춤을 이해하지 않습니다. (我不跳舞。)\n- 춤을 이해하면 느껴지는 않습니다. (如果跳舞就不会感到无聊。)\n- 춤을 이해하는 것이 좋습니다. (跳舞是件好事。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1377, 78, ' 춤을 表하다 ', ' 表演舞蹈', '1. 词性：动词\n2. 词义：跳舞，表演舞蹈\n3. 例句：\n   - 그는 느낌이 좋아 춤을 表하다. (他感觉很好，所以跳舞。)\n   - 공연에서 그녀는 우롱하게 춤을 表허다. (她在表演中优雅地跳舞。)\n\n变形及其词义：\n- 춤을 表하다 - 基本形，表示现在或未来的动作。\n- 춤을 表해요 - 用于口语或对等关系中，表示礼貌的陈述。\n   - 예쁜 음악가 들어 춤을 表해요. (听着美妙的音乐跳舞。)\n- 춤을 表할 - 用于计划或将要发生的动作。\n   - 나는 내일 춤을 表할 계획이에요. (我计划明天跳舞。)\n- 춤을 表했다 - 过去式，表示动作已经发生。\n   - 지난 Friday night, 나는 클럽에서 춤을 表었다. (上周五晚上，我在俱乐部跳了舞。)\n- 춤을 表HandleCoding - 表示尝试做某事或做过某事。\n   - 저는 여전히 춤을 表HandleCoding고 있어요. (我仍然在尝试跳舞。)\n- 춤을 表炀가 - 表示请求或命令。\n   - 이번 춤첩에서 당신도 함께 춤을 表炀가. (这次舞会上你也一起来跳舞吧。)\n\n请注意，韩语动词的变形根据语境和对话者之间的关系有所不同，上述提供的是一些常见的变形和用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1378, 78, ' 춤을 창작하다 ', ' 创新舞蹈', '1. 词性：动词\n2. 词义：创作舞蹈\n3. 例句：\n   - 그는 새로운 춤을 창작하고 있습니다. (他正在创作新的舞蹈。)\n   - 이 춤을 창작하는 데 많은 시간이 필요했다. (创作这个舞蹈需要很多时间。)\n\n变形及词义：\n- 춤을 창작하다： 创作舞蹈（原形）\n- 춤을 창작하： 创作舞蹈（动词词干）\n- 춤을 창작한다： 创作了舞蹈（完成时态）\n- 춤을 창작하지： 创作舞蹈（动词词干+接续助词）\n- 춤을 창작할： 将要创作舞蹈（将来时态）\n- 춤을 창작하겠： 创作舞蹈（意愿或计划）\n\n每个变形的例句：\n- 그는 새로운 춤을 창작하고 있습니다. (他正在创作新的舞蹈。)\n- 춤을 창작하는 데 많은 시간이 필요했다. (创作这个舞蹈需要很多时间。)\n- 그는 새로운 춤을 창작한다. (他创作了新的舞蹈。)\n- 춤을 창작하지 않으면， 아무것도 변화가 없어요. (如果不创作舞蹈，就没有任何变化。)\n- 나는 다음에서 춤을 창작할 계획이에요. (我计划下次创作舞蹈。)\n- 나는 춤을 창작하겠습니다. (我将创作舞蹈。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1379, 78, ' 춤을 연기하다 ', ' 练习舞蹈', '1. 词性：动词\n2. 词义：跳舞\n3. 例句：\n   - 나는 춤을 연기하다. (我在学跳舞。)\n   - 그는 춤을 연기하고 있어요. (他在学习跳舞。)\n\n变形及其词义：\n- 춤이다： 跳舞（基本形态）\n  - 나는 춤을 춤이다. (我在跳舞。)\n- 춤을 듣다： 听舞蹈音乐\n  - 나는 춤을 듣고 있어요. (我在听舞蹈音乐。)\n- 춤을 보다： 看舞蹈表演\n  - 나는 춤을 보고 있어요. (我在看舞蹈表演。)\n- 춤을 배우다： 学习跳舞\n  - 나는 춤을 배우고 있어요. (我在学习跳舞。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1380, 78, ' 춤을 완성하다 ', ' 完成舞蹈', '1. 词性：动词\n2. 词义：完成舞蹈，使舞蹈完美。\n3. 例句：\n   - 그는 춤을 완성하다 노력했습니다. (他努力地完成了舞蹈。)\n   - 우리는 춤을 완성하고 있어요. (我们正在完成舞蹈。)\n\n变形及其词义：\n- 춤을 완성하다： 原形，表示完成舞蹈的动作。\n  - 그는 춤을 완성하다 노력했습니다. (他努力地完成了舞蹈。)\n- 춤을 완성하다： 进行时态，表示正在进行完成舞蹈的动作。\n  - 우리는 춤을 완성하고 있어요. (我们正在完成舞蹈。)\n- 춤을 완성한다： 过去时态，表示已经完成了舞蹈的动作。\n  - 그는 춤을 완성한다 것이었습니다. (他已经完成了舞蹈。)\n- 춤을 완성할까： 疑问句形式，询问是否要完成舞蹈。\n  - 춤을 완성할까요？ (你要完成舞蹈吗？)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1381, 78, ' 춤을 분석하다 ', ' 分析舞蹈', '1. 词性：动词\n2. 词义：跳舞，舞蹈\n3. 例句：\n   - 나는 요즘 멋지게 춤을 분석하고 있어요. (我最近在努力学习跳舞。)\n   - 그는 춤을 분석하는 것이 좋아서， 다양한 클럽에 가서 학습을 해요. (他喜欢跳舞，所以去各种俱乐部学习。)\n\n变形及词义：\n- 춤을 분석하다： 原形，意为“跳舞，舞蹈”。\n- 춤을 분석했다： 过去式，意为“跳了舞”。\n- 춤을 분석할 수 있다： 可能态，意为“能跳舞”。\n- 춤을 분석하기： 动名词，意为“跳舞的行为”。\n- 춤을 분석하다： 命令形，意为“跳舞！”(用于命令或请求)\n\n每个变形的例句（用韩语）：\n- 나는 요즘 멋지게 춤을 분석하고 있어요. (原形)\n- 어제 춤을 분석었어요？ (过去式)\n- 이 춤은 Anyone도 춤을 분석할 수 있어요. (可能态)\n- 춤을 분석하는 것이 나의 취미입니다. (动名词)\n- 이제 우리 함께 춤을 분석하라！ (命令形)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1382, 78, ' 춤을 作成하다 ', ' 创作舞蹈', '1.词性：动词（동사）\n2.词义：跳舞，舞蹈，舞动，制作，创建，形成。\n3.例句：\n- 춤을 作成하다 - 制作舞蹈\n- 춤을 作成하다 - 创建舞蹈\n4.变形及其词义：\n- 춤을 作成한다 - 制作了舞蹈\n- 춤을 作성하다 - 创建了舞蹈\n- 춤을 作성한다 - 创建了舞蹈\n- 춤을 제작하다 - 创作了舞蹈\n- 춤을 제작한다 - 创作了舞蹈\n- 춤을 제작하다 - 创作了舞蹈\n- 춤을 제작한다 - 创作了舞蹈', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1383, 78, ' 춤을 사용하다 ', ' 使用舞蹈', '1. 词性：\n- 춤을 사용하다 是一个动词短语，由名词“춤”（舞蹈）和动词“사용하다”（使用）构成。\n\n2. 词义：\n- 춤을 사용하다 的常用词义是“跳舞”或“使用舞蹈”。\n\n3. 例句：\n- 1) 그는 춤을 사용하여 감정을 표현했다. (他通过跳舞来表达情感。)\n- 2) 춤을 사용하면서 힘이 나섭니다. (通过跳舞可以消耗能量。)\n\n4. 变形及词义：\n- 춤을 사용하는： 现在进行时态，表示正在使用舞蹈。\n  - 예) 그는 춤을 사용하고 있어요. (他正在跳舞。)\n\n- 춤을 사용한： 过去时态，表示已经使用过舞蹈。\n  - 예) 그는 춤을 사용했어요. (他跳了舞。)\n\n- 춤을 사용하지： 否定形式，表示不使用舞蹈。\n  - 예) 그는 춤을 사용하지 않아요. (他不跳舞。)\n\n- 춤을 사용할： 将来时态，表示将要使用舞蹈。\n  - 예) 그는 춤을 사용할 것이라고 합니다. (他说他要跳舞。)\n\n请注意，以上例句均为韩语，并展示了如何根据不同的时态和语气变化使用“춤을 사용하다”。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1384, 78, ' 춤을 배우다 ', ' 学习舞蹈', '1. 词性：动词\n2. 词义：学习跳舞\n3. 例句：\n   - 나는 춤을 배우고 있어요. (我正在学习跳舞。)\n   - 그는 춤을 배우다 것을 믿어 안 해요. (他不相信他能学会跳舞。)\n\n变形及词义：\n- 춤을 배웠다 (过去式，学会了跳舞)\n   - 나는 춤을 배웠어요. (我学会了跳舞。)\n- 춤을 배워요 (敬语形式，学习跳舞)\n   - 先生， 저희 춤을 배워요. (老师，我们学习跳舞。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1385, 78, ' 춤을 멋지하다 ', ' 美化舞蹈', '1. 词性：动词\n2. 词义：跳舞跳得好，舞姿优美。\n3. 例句：\n   - 그는 춤을 멋지게 합니다.（他跳舞跳得很好。）\n   - 춤을 멋지하다 사람이 좋아요.（我喜欢跳舞跳得好的人。）\n\n变形及其词义：\n- 춤을 멋지게 하다（原形）：跳舞跳得好，舞姿优美。\n  - 그는 춤을 멋지게 합니다.（他跳舞跳得很好。）\n- 춤을 멋지게 해요（敬语形式）：跳舞跳得好，舞姿优美。\n  - 先生， 춤을 멋지게 해요.（老师，您跳舞跳得很好。）\n- 춤을 멋지게 하다（陈述式）：跳舞跳得好，舞姿优美。\n  - 그는 춤을 멋지게 합니다.（他跳舞跳得很好。）\n- 춤을 멋지게 해라（命令式）：请跳舞跳得好，舞姿优美。\n  - 춤을 멋지게 해라.（请跳舞跳得好。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1482, 105, '14 juillet', '国庆日', '1. 词性：日期表达\n2. 词义：7月14日，法国国庆日\n3. 例句：\n   - Nous célébrerons la fête nationale le 14 juillet. (我们将在7月14日庆祝国庆。)\n   - Le 14 juillet, les rues de Paris sont animées par des parades et des feux d\'artifice. (7月14日，巴黎的街道上会有游行和烟火表演。)\n\n变形及词义：\n- 14ème juillet (十四日七月): 指7月的第14天，非特定年份。\n  - Exemple: La fête est prévue pour le 14ème juillet. (庆祝活动预定在7月14日举行。)\n- Le quartorze juillet (7月14日): 强调“第14”这个数词。\n  - Exemple: Les Français rassemblent souvent en famille le quartorze juillet. (法国人经常在7月14日这天家庭团聚。)\n- Juillet quatorzième (7月14日): 以另一种方式表达同一个日期。\n  - Exemple: On a organisé une soirée au chateau pour le juillet quatorzième. (我们在7月14日晚在城堡举办了一场晚会。)\n\n这些表达都是指7月14日这个特定的日期，通常与法国国庆日相关联。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1483, 105, 'Ascension', '耶稣升天节', '1. 词性：名词\n2. 词义：上升，升高；耶稣升天节\n3. 例句：\n   - L\'ascension de la température a fait ressentir le changement de saison. (温度的上升让人感受到了季节的变化。)\n   - Nous célébrons l\'Ascension de Notre Seigneur chaque année. (我们每年都会庆祝耶稣升天节。)\n\n变形及其词义：\n- Ascendre (动词原形)：上升，升高\n  - Le gaz d\'éclairage ascend vers le plafond. (照明气体上升到天花板。)\n- Ascendant (形容词)：上升的，升高的\n  - Les prix sont en réalité descendant plutôt que ascendant. (价格实际上是下降而不是上升。)\n- Ascenseur (名词)：电梯\n  - J\'ai pris l\'ascenseur pour aller à la quatrième étage. (我乘电梯去了四楼。)\n- Ascensionnel (形容词)：与上升有关的\n  - Les indices ascensionnels ont attiré l\'attention des investisseurs. (上升指数吸引了投资者的注意。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1484, 105, 'Bastille Day', '巴士底日', '1. 词性：名词\n2. 词义：法国国庆日，即7月14日，纪念1789年巴士底狱的攻克。\n3. 例句：Nous célébrons toujours la Fête de la Bastille avec beaucoup d\'enthousiasme. (我们总是满怀热情地庆祝巴士底日。)\n\n变形及词义：\n- Bastille（原形）：巴士底狱，位于巴黎的历史监狱，其攻克象征着法国大革命的开始。\n  - 例句：La prise de la Bastille a éveillé le peuple français à la lumière de la liberté. (巴士底狱的攻陷唤醒了法国人民对自由的认识。)\n  \n- Bastillader：作为形容词时，意指与巴士底狱或其攻占相关的事物。\n  - 例句：C\'est une époque bastilladaire, riche en histoire. (这是一个充满历史的巴士底时期。)\n\n- Bastilleur：名词，指参与攻占巴士底狱的人。\n  - 例句：Les bastilleurs ont été salués comme héros du peuple. (巴士底狱的攻占者被人们视为英雄。)\n\n注意：法语中“Bastille Day”直接称为“la Fête de la Bastille”，而上述变形和词义主要围绕“Bastille”这个名词展开，因为“Bastille Day”在法语中是一个固定短语，不涉及变形。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1485, 105, 'Noël', '圣诞', '1. 词性：名词\n2. 词义：圣诞节，耶稣诞生日\n3. 例句：\n   - Noël est une fête chrétienne qui célèbre la naissance de Jésus-Christ. (圣诞节是一个庆祝耶稣诞生的基督教节日。)\n   - Bonne fête de Noël! (圣诞快乐！)\n\n变形及其词义：\n- Noël (名词): 圣诞节，耶稣诞生日\n  - Le Noël est une période de festivités et de réunions familiales. (圣诞节是一段充满庆祝和家庭团聚的时光。)\n\n- Noëliste (名词): 圣诞物品或装饰品的收集者\n  - Il est un passionné de Noël, un véritable noëliste. (他是一个热爱圣诞节的人，一个真正的圣诞收藏家。)\n\n- Noëllique (形容词): 与圣诞节有关的\n  - Les décorations noëlliques sont très colorées et lumineuses. (圣诞装饰非常丰富多彩且闪亮。)\n\n请注意，\"Noël\" 这个单词在法语中主要用作名词，表示圣诞节，而它的变形形式如 \"noëliste\" 和 \"noëllique\" 分别表示圣诞物品的收集者和与圣诞节相关的形容词。上述例句均为法语句子。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1486, 105, 'Toussaint', '万圣节', '1. 词性：\nToussaint 是名词。\n\n2. 词义：\nToussaint 主要指“万圣节”或“诸圣节”，这是基督教传统中纪念已故圣人的节日，通常在11月1日。\n\n3. 例句：\n- Nous célébrerons Toussaint cette année à la maison, car le temps sera trop mauvais pour sortir.\n  (我们今年将在家里庆祝万圣节，因为天气会太糟糕，不宜外出。)\n- Les enfants se réjouiront pendant Toussaint car ils aiment à voir les fantaisies des déguiseurs.\n  (孩子们在万圣节期间将会很高兴，因为他们喜欢看各种奇装异服的装扮者。)\n\n变形及其词义：\n- Toussaint 没有直接的变形，因为它是一个专有名词。但与之相关的词汇可以是形容词 \"toussaint\"（与节日有关的），或者作为姓氏使用。\n\n额外例句（使用相关词汇）：\n- Cette église a une cérémonie spéciale pour Toussaint, où les fidèles célèbrent tous les saints.\n  (这座教堂有一个特别的万圣节仪式，信徒们在此纪念所有的圣人。)\n- M. Toussaint est notre nouvel agent de police, et il commencera son service le 1er novembre.\n  (图森先生是我们新来的警察，他将于11月1日开始服役。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1487, 105, '8 mai', '欧洲胜利日', '1. 词性：\nLe mot \"8 mai\" est un nom, spécifiquement une date.\n\n2. 词义：\n\"8 mai\" signifie le huitième jour du mois de mai.\n\n3. 例句：\n- Nous avons planifié une réunion le 8 mai. (On a planifié une réunion le 8 mai.)\n- Le mariage aura lieu le 8 mai prochain. (Le mariage se déroulera le 8 mai prochain.)\n\n变形及其词义：\n- Mai (nom masculin): Le mois de mai. Exemple: Il fait beau en mai.\n- Mais (adverbe): Signifie \"but\" ou \"however\". Exemple: J\'aime le chocolat, mais je ne peux pas en manger trop.\n- Août (nom masculin): Le huitième mois de l\'année, suivant immédiatement mai. Exemple: Les vacances d\'été commencent en juillet et finissent en août.\n\n注意：直接使用\"mai\"和\"août\"作为变形可能不太准确，因为它们指的是不同的月份。然而，按照请求，我提供了与“5月”相关的词汇及其用法。如果需要其他类型的变形（比如动词的时态变化等），通常\"8 mai\"这样的名词短语不会有变形，因为它指的是一个具体的日期。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1488, 105, 'Fête de la Victoire', '胜利日', '1. 词性：\nFête de la Victoire 是一个名词短语。\n\n2. 词义：\nFête de la Victoire 指的是“胜利日”，通常是指第二次世界大战结束后欧洲的庆祝活动，尤其是法国在5月8日庆祝的节日。\n\n3. 例句：\n- La Fête de la Victoire est un jour public en France où on célèbre la fin de la Seconde Guerre mondiale.\n（胜利日是法国的公共假日，用来庆祝第二次世界大战的结束。）\n- Les Français célèbrent la Fête de la Victoire avec des manifestations militaires et civiles.\n（法国人通过军事和民间游行庆祝胜利日。）\n\n变形及词义：\n由于 Fête de la Victoire 是一个专有名词短语，它没有变形。但是，如果我们考虑单独的词：\n\n- Fête: 名词，意为“节日”或“庆祝”。\n  - Nous voudrions vous inviter à notre fête d\'anniversaire.\n  （我们想邀请您参加我们的生日派对。）\n\n- Victoire: 名词，意为“胜利”。\n  - Cette victoire est l\'aboutissement d\'un long travail.\n  （这次胜利是长期努力的结果。）\n\n请注意，\"Fête de la Victoire\" 作为一个固定短语，通常不会拆分其组成部分来使用。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1489, 105, '1er novembre', '诸圣节', '1. 词性：\n- **nom** (名词)\n\n2. 词义：\n- 十一月一日。\n\n3. 例句：\n- 1er novembre, j\'ai fini mon livre préféré. (十一月一日，我读完了我最喜欢的书。)\n- Nous célébrons la Toussaint le 1er novembre. (我们在十一月一日庆祝万圣节。)\n\n变形及其词义和例句：\n- **premier** (形容词，第一的)\n  - C\'est le premier jour de novembre. (这是十一月的第一天。)\n\n- **novembre** (名词，十一月)\n  - Le novembre est un mois froid. (十一月是一个寒冷的月份。)\n\n注意：法语中日期通常以“日 + 月”的形式表示，如 \"1er novembre\" 表示 \"十一月一日\"。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1490, 105, 'Pâques', '复活节', '1. 词性：Pâques 是名词。\n2. 词义：Pâques 主要指复活节，基督教纪念耶稣基督复活的节日。\n3. 例句：\n   - Nous fêterons Pâques en famille cette année. (我们今年将和家人一起庆祝复活节。)\n   - Les chocolats sont souvent donnés aux enfants pendant la période de Pâques. (巧克力经常在复活节期间送给孩子们。)\n\n变形及其词义：\n- Pâques (名词): 如上所述，指复活节。\n  - Je partirai pendant les vacances de Pâques. (我会在复活节假期期间离开。)\n- Pascale (形容词): 与复活节有关的，或形容复活节期间的事物。\n  - Les traditions pascales varient d\'une région à l\'autre. (复活节的传统因地区而异。)\n- Paquer (动词): 指庆祝复活节。\n  - Ils vont paquer au sud de la France cette année. (他们今年将在法南庆祝复活节。)\n\n注意：虽然“Paquer”和“Pascale”在理论上是可能的变形，但在现代法语中很少使用这些形式。通常，人们会使用“Pâques”这个名词形式来表达相关概念。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1491, 105, 'Fête du Travail', '劳动节', '1. 词性：名词\n2. 词义：劳动节，国际劳动节。\n3. 例句：Nous célébrons la Fête du Travail avec un week-end en famille. (我们与家人一起庆祝劳动节周末。)\n\n4. 变形及其词义和例句：\n   - Travailler（动词）：工作，劳动。\n     Exemple：Il travaille beaucoup pour réussir dans sa carrière. (他为了在职业上成功而努力工作。)\n   - Travailleur/Travailleuse（名词）：工作者，劳动者。\n     Exemple：Les travailleurs ont le droit à des conditions de travail respectueuses. (工作者有权享有尊重的工作条件。)\n   - Travaux（名词）：工程，工作，活动。\n     Exemple：Les travaux de rénovation de la ville commenceront bientôt. (城市的翻新工程将很快开始。)\n   - Travail（名词）：工作，劳动；困难，辛苦。\n     Exemple：Cette œuvre exige beaucoup de travail. (这项工作需要大量的劳力。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1492, 105, 'Saint Nicolas', '圣尼古拉斯节', '1. 词性：Saint Nicolas 是一个专有名词（nom propre）。\n2. 词义：Saint Nicolas 指的是圣尼古拉斯，他是一位在多个文化中被纪念的圣人，特别是在法国和说法语的国家，通常与儿童保护者的形象相关联。\n3. 例句：Les enfants ont écrit à Saint Nicolas pour leur demander des cadeaux à Noël.（孩子们给圣尼古拉斯写信，向他请求圣诞礼物。）\n4. 变形及词义：作为一个专有名词，Saint Nicolas 没有变形。但可以提到相关的表达方式或节日名称，例如 \"La fête de Saint Nicolas\"（圣尼古拉斯节）。\n5. 例句：\"La fête de Saint Nicolas\" est une célébration traditionnelle où les enfants espèrent recevoir des cadeaux mystérieux.（“圣尼古拉斯节”是一个传统庆祝活动，孩子们希望收到神秘的礼物。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1493, 105, 'Épiphanie', '主显节', '1.词性：\nÉpiphanie 是名词。\n\n2.词义：\n- 主显节，基督教传统中纪念耶稣诞生后首次显现给三智者的节日。\n- 突然的领悟或理解。\n\n3.例句：\n- Nous célébrerons l\'Épiphanie le 6 janvier. (我们将在1月6日庆祝主显节。)\n- J\'ai eu une épiphanie en regardant le tableau, comprenant maintenant son sens profond. (看着这幅画，我有了顿悟，现在理解了它的深刻含义。)\n\n变形及其词义和例句：\n- Adjectif : épique (史诗般的，宏大的)\n  - Cette œuvre littéraire est vraiment épique. (这部文学作品真是史诗般宏大。)\n\n- Verbe : épiphaniser (使显现，使明了)\n  - La lumière du jour épiphanise les détails de la sculpture. (日光让雕塑的细节显得清晰。)\n\n请注意，虽然 \"épiphaniser\" 是一个动词形式，但在实际使用中不太常见，而且 \"épique\" 作为形容词时与原名词的含义有所不同。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1494, 105, 'Fête de la Marié', '圣母升天节', '1. 词性：名词\n2. 词义：结婚纪念日\n3. 例句：\n   - Cette année, nous célébrerons la fête de la marié de nos parents. (今年，我们将庆祝我们父母的结婚纪念日。)\n   - Pour leur fête de la marié， ils ont organisé un voyage en Europe. (为了他们的结婚纪念日，他们组织了一次欧洲之旅。)\n\n变形及其词义：\n- fêter (动词): 庆祝\n   - Nous fêtons la fête de la marié de nos parents chaque année. (我们每年都会庆祝我们父母的结婚纪念日。)\n- fêtard (名词): 庆祝者\n   - Les fêtards commencent à arriver pour la cérémonie. (庆祝者们开始到达参加仪式。)\n- fêtif (形容词): 节日的，喜庆的\n   - Ils ont préparé un repas fêtif pour leur anniversaire. (他们为他们的周年纪念日准备了一顿喜庆的餐点。)\n- fêtique (形容词): 与庆祝有关的，盛大的\n   - La fête de la marié était une soirée fêtique avec des vins de qualité et des mets exquis. (结婚纪念日是一次盛大的晚会，有优质的葡萄酒和精美的食物。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1495, 105, 'Fête des Pères', '父亲节', '1. 词性：名词短语\n2. 词义：父亲节，用于庆祝和感谢父亲的节日。\n3. 例句：\n   - Pour la Fête des Pères, j\'ai achete un cadeau pour mon père. (为了父亲节，我给我的父亲买了一个礼物。)\n   - On va dîner ensemble pour célébrer la Fête des Pères. (我们将一起用餐来庆祝父亲节。)\n\n变形及其词义：\n- Fête - 名词，表示“节日”或“庆祝活动”。\n  - Exemple: La fête de Noël est une grande célébration dans le pays. (圣诞庆典在这个国家是一个大型的庆祝活动。)\n- Pères - 名词（复数形式），表示“父亲们”。\n  - Exemple: Les pères ont organisé un match de foot pour le week-end prochain. (父亲们为下一个周末组织了一场足球赛。)\n\n注：法语单词“Fête des Pères”本身作为一个固定搭配表达特定节日，没有其他常见的变形。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1496, 105, 'Pentecôte', '复活节后的星期一', '1. 词性：Pentecôte 是名词。\n\n2. 词义：Pentecôte 主要指基督教的复活节后的第五十天，即圣灵降临节或五旬节。\n\n3. 例句：\n   - C\'est le Pentecôte cette année, on va faire des récoltes spéciales à l\'église.\n     (今年是五旬节，我们打算在教堂进行特别的收获仪式。)\n   - Le Pentecôte, j\'ai envie de visiter la campagne.\n     (五旬节那天，我想去乡下游玩。)\n\n变形及其词义和例句：\n- Pentecostal(e): 形容词，与五旬节有关的。\n   - Il y a des cérémonies pentecostales qui sont très touchantes.\n     (有一些五旬节的仪式非常感人。)\n\n- Pentecot(euse): 名词，指庆祝五旬节的人。\n   - Le groupe de pêcheurs de Pentecot(euse) organisait une fête pour célébrer leur récolte.\n     (五旬节的捕鱼小组组织了一个节日来庆祝他们的收获。)\n\n注：法语中通常使用 \"Pentecot(euse)\" 而不是 \"*Pentecostal(e)\" 来指代庆祝五旬节的人。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1497, 105, 'Armistice', '休战纪念日', '1. 词性：\nArmistice 是名词。\n\n2. 词义：\n- 休战，停战；\n- 临时协议，暂时的和解。\n\n3. 例句：\n- Les deux pays ont signé un armistice pour une période de trois semaines. (两个国家签署了为期三周的停战协议。)\n- L\'armistice a permis aux civils de retrouver leurs familles. (休战让平民得以与家人团聚。)\n\n变形及其词义和例句：\n- Armistique（形容词）：与停战有关的。\n  - L\'accord armistique a été signé par les deux parties. (双方签署了停战协议。)\n- Armistement（名词）：停战的行为或状态。\n  - Le pays a demandé un armistement avec son adversaire. (该国请求与其对手停战。)\n\n注：法语中通常不会直接从名词派生形容词，\"armistique\" 这个形容词的使用并不常见，更多情况下会使用其他方式来表达相关概念，例如通过短语 \"relatif à l\'armistice\" 来表达与停战有关的意思。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1498, 105, 'Jour de l\'An', '元旦', '1. 词性：名词\n2. 词义：新年的第一天，即元旦。\n3. 例句：\n   - Nous fêtons le Jour de l\'An avec nos proches. (我们与亲人一起庆祝元旦。)\n   - Le Jour de l\'An est une occasion pour reflechir à nous sommes et nos projets. (元旦是反思自己和计划的好时机。)\n\n变形及其词义：\n- Journée de l\'An: 元旦这一天，名词。\n  - Exemple : Nous avons prévu de passer la journée de l\'An au village. (我们计划在村里度过元旦这一天。)\n- Journalier de l\'An: 元旦报纸，特指元旦发行的纪念性或特殊内容的报纸，名词。\n  - Exemple : Le journal journalier de l\'An contient souvent des revues annuelles et des articles spéciaux. (元旦报纸通常包含年度回顾和特别文章。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1499, 105, 'Assomption', '圣母升天节', '1. 词性：\nAssomption 是一个名词。\n\n2. 词义：\n- Assomption 可以指加拿大魁北克省的一个城市名，即“阿斯姆普特翁”。\n- 在更普遍的用法中，它可以指代任何形式的“假定”或“假设”，尽管这个意义在法语中不太常见。\n\n3. 例句：\n- J\'aimerais visiter l\'Assomption un jour. (我有一天想去参观阿斯姆普特翁。)\n- Il y a des suppositions qui ne sont pas fondées sur la réalité. (有一些假设并非基于现实。)\n\n变形及词义：\n- Assumptive（形容词）： 与“假定”有关的，通常用于形容某种理论或想法是基于假设的。\n  - Cette théorie reste assumptive et n\'a pas encore été confirmée par la recherche. (这个理论仍然是假设性的，尚未通过研究得到确认。)\n\n- Assumption（名词，英语形式）： 同Assomption，表示“假定”或指加拿大的城市名。\n  - L\'assumption que tout ira bien est une façon de voir optimiste. (一切都会好起来的假设是一种乐观的看法。)\n\n请注意，\"Assomption\" 作为“假定”的意义在现代法语中较少使用，而更多用来指代地名。在讨论抽象概念时，法国人可能会选择使用其他词汇，如 \"supposition\" 或 \"hypothèse\"。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1500, 105, 'Halloween', '万圣夜', '1. 词性：\nHalloween 在法语中通常作为名词使用，即 \"Halloween\"。\n\n2. 词义：\nHalloween 在法语中指的是每年10月31日的节日，也被称为“万圣节前夜”，是一个源自西方的庆祝活动，人们在这一天会穿上奇装异服、参加派对、玩恐怖游戏以及“不给糖就捣蛋”。\n\n3. 例句：\n- Nous allons célébrer Halloween ce soir avec des déguisement fantasmagoriques et des réceptions spéciales.（我们今晚将通过奇幻的化妆和特别的招待来庆祝万圣节。）\n- Les enfants sont très excités pour leur prank-or-treat à Halloween.（孩子们对万圣节的“不给糖就捣蛋”活动感到非常兴奋。）\n\n变形及其词义：\n- Halloweeniere（形容词）：与万圣节有关的，例如：Cette usine de bonbons fabriqué des Halloweenieres attractions pour les fêtes d\'Halloween.（这家糖果厂生产与万圣节相关的吸引物，用于万圣节庆典。）\n\n注意：由于“Halloween”是直接借用自英语的单词，在法语中没有传统意义上的词形变化。上述提到的“Halloweeniere”是一种非正式的派生用法，并非标准的变形。在正式的法语语境中，通常会用描述性语言来表达与万圣节相关的事物。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1501, 105, 'Fête des Mères', '母亲节', '1. 词性：名词短语\n2. 词义：母亲节（法语中的“Fête des Mères”直接翻译为“母亲的节日”，类似于英语中的“Mother\'s Day”）\n3. 例句：\n   - Pour la Fête des Mères, j\'ai offert un joli bouquet de fleurs à ma mère.\n     （为了庆祝母亲节，我送给我妈妈一束漂亮的花。）\n   - Les fils et filles préparent souvent des surprises pour leur mère à la Fête des Mères.\n     （儿女们通常会在母亲节为他们的妈妈准备惊喜。）\n\n变形及其词义：\n- Fêter（动词）：庆祝\n   - Exemple: On fêtera la Fête des Mères cette année avec un dîner à la maison.\n     （今年我们将在家里吃晚餐来庆祝母亲节。）\n\n- Fêtard（名词）：庆祝者，参与者\n   - Exemple: Les fêtards ont organisé une fête dans le parc pour célébrer la Fête des Mères.\n     （庆祝者们在公园里组织了一个聚会来庆祝母亲节。）\n\n- Fêté（形容词）：被庆祝的\n   - Exemple: La journée de la Fête des Mères est un moment fêté dans beaucoup de familles.\n     （母亲节这天在许多家庭中是一个被庆祝的时刻。）\n\n注：由于“Fête des Mères”是一个固定搭配的名词短语，它没有直接的变形。上述提供的是相关词汇的变形和用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1502, 106, ' veste ', ' 背心', '1. 词性：名词\n2. 词义：上衣，背心。\n3. 例句：\n   - J\'ai acheté une veste en cuir chez Zara. (我在Zara买了一件皮夹克。)\n   - Il porte une veste noire pour son entretien d\'embauche. (他穿着一件黑色西装去面试。)\n\n变形及其词义和例句：\n- Vestes（复数）： 多件上衣或背心。\n  - Elles ont essayé plusieurs vestes avant de faire un choix. (她们试了好几件上衣才做出选择。)\n- Vêtu（男性过去分词形式）： 穿着。\n  - Il était vêtu d\'un costume à la mode. (他穿着一件时髦的西装。)\n- Vêtue（女性过去分词形式）： 穿着。\n  - Elle était vêtue d\'une robe élegante. (她穿着一条优雅的裙子。)\n- Vestant（现在分词形式）： 正在穿。\n  - Le mannequin est en train de vestant pour la parade des modèles. (模特正在为时装秀试穿衣服。)\n\n以上是根据“veste”这个法语单词的基本用法提供的词性、词义、例句以及其变形和相应的例句。在实际应用中，根据不同语境，这些单词和表达方式可能会有所变化。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1503, 106, ' chaussette ', ' 袜子', '1. 词性：名词\n2. 词义：袜子\n3. 例句：\n   - J\'ai acheté des chaussettes pour l\'hiver. （我买了一些冬天穿的袜子。）\n   - Mets tes chaussettes, il fait froid dehors. （穿上你的袜子，外面很冷。）\n\n变形及其词义：\n- Chaussettes（复数形式）：多双袜子\n  - Je veux trois paires de chaussettes. （我想要三双袜子。）\n- Chaussettier（男性名词）：卖袜子的人\n  - Le chaussettier vendait des chaussettes en soie. （那个卖袜子的人在卖丝绸袜子。）\n- Chaussetière（女性名词）：卖袜子的女性\n  - La chaussetière avait un large choix de modèles. （那位女袜商有很多款式可供选择。）\n- Chausseur（男性名词）：穿袜子的人，这个变形虽然存在但不常用，更常见的是直接用 \"personne qui porte des chaussettes\" 表示穿袜子的人。\n  - Il est rare de voir un chausseur en été. （夏天很少看到有人穿袜子。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1504, 106, ' pantalon ', ' 裤子', '1. 词性：\nPantalon 是名词。\n\n2. 词义：\nPantalon 主要指长裤，无论是休闲的、正式的还是工作用的。\n\n3. 例句：\n- J\'ai acheté un nouveau pantalon pour mon entretien d\'embauche. (我为了工作面试买了一条新裤子。)\n- Il préfère porter des pantalons à pression plutôt que des jeans. (他更喜欢穿西裤而不是牛仔裤。)\n\n变形及词义：\n- Pantalonner (动词): 穿着裤子。\n  - Elle ne pantalonne jamais en été， seulement des jupes. (她夏天从不穿裤子，只穿裙子。)\n\n- Pantalonnage (名词): 裤子的款式或种类。\n  - Le pantalonnage de cette gamme est très varié. (这一系列的裤子款式非常多样。)\n\n- Pantalonière (名词): 女裤。\n  - Cette boutique propose une grande variété de pantalonières. (这家商店提供各种女裤。)\n\n- Pantalonnière (形容词): 与裤子相关的。\n  - Il porte une chemise pantalonnière. (他穿着一条配裤子的衬衫。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1505, 106, ' chemise ', ' 衬衫', '1. 词性：\nChemise 是名词。\n\n2. 词义：\n- 一种简单的、通常没有袖子和领子的衬衫，尤其是作为内衣穿着的。\n- 在历史上或在某些文化中，也指一种长袍或外衣。\n\n3. 例句：\n- Je me suis trempée jusqu\'au corps dans ma chemise. (我全身湿透了，直到我的内衣。)\n- Il est sorti juste avec sa chemise. (他只穿了一件内衣就出去了。)\n\n变形及其词义和例句：\n- Chemise (基本形式): 如上所述，指一种简单的内衣。\n  - Elle porte une chemise blanche. (她穿着一件白色内衣。)\n  \n- Chemises (复数形式): 多件chemise。\n  - Les chemises sont en train de sechés sur le linge. (内衣正在晾衣绳上晾干。)\n\n- Chemiseuse (形容词形式，不常用): 与chemise有关的。\n  - Cette marque spécialise dans la fabrication de chemises de qualité. (这个品牌专门生产高品质的内衣。)\n\n注意：法语中“chemise”一词并没有很多变形，主要使用其名词形式。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1506, 106, ' jupe ', ' 裙子', '1. 词性：名词（nom féminin）\n2. 词义：\n   - jupe principalement : 裙子，连衣裙。\n   - (TLFi) : 长袍（在中世纪时指长袍或长外衣）。\n3. 例句：\n   - Je vais acheter une nouvelle jupe pour le bal.\n     (我打算买一条新裙子去舞会。)\n   - Elle porte une jupe très courte.\n     (她穿着一条非常短的裙子。)\n\n变形及词义：\n- jupon (nom masculin rare) : 一种旧式的男用短裤。\n  - Il a pris son jupon pour aller jouer au football.\n    (他穿上他的短裤去踢足球了。)\n- jupenneuse (adjective féminin) : 穿裙子的。\n  - La jupenneuse dame est entrée dans la salle.\n    (穿裙子的女士走进了大厅。)\n- juperon (nom masculin) : 一种历史上的长袍或大衣。\n  - Le chevalier a vêtu son juperon de cérémonie.\n    (骑士穿上了他的礼服大衣。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1507, 106, ' pull ', ' 毛衣', '1. 词性：\nPull 在法语中通常对应于动词 \"tirer\"。\n\n2. 词义：\nTirer 的基本意思是“拉”，“拖”，“抽取”。\n\n3. 例句：\n- Tu peux tirer la chaise pour que je m\'asseoise. (你可以把椅子拉过来让我坐下。)\n- Il a tiré sa carte de crédit du portefeuille. (他从钱包里抽出信用卡。)\n\n其他变形及词义：\n\n- Tire (现在时第一人称单数): 我拉，我拖，我抽。\n  - Je tire les draps pour les faire sécher. (我把床单拉出来晾干。)\n  \n- Tires (现在时第二人称单数): 你拉，你拖，你抽。\n  - Tu tires le rideau pour laisser entrer le jour. (你拉开窗帘让光线进来。)\n  \n- Tire (现在时第三人称单数): 他/她/它拉，他/她/它拖，他/她/它抽。\n  - Elle tire son manteau parce qu\'il fait froid. (她穿上大衣因为天气变冷了。)\n  \n- Tirions (现在时第一人称复数): 我们拉，我们拖，我们抽。\n  - Nous tirions les bouées pour marquer la route. (我们拉起浮标来标记路线。)\n  \n- Tirez (现在时第二人称复数): 你们拉，你们拖，你们抽。\n  - Vous tirez la langue quand vous êtes nerveuse. (当你紧张时你会咬舌头。)\n  \n- Tirent (现在时第三人称复数): 他们拉，他们拖，他们抽。\n  - Ils tirent des poissons dans le lac. (他们在湖里钓鱼。)\n  \n- Tiré (过去分词): 被拉过，被拖过，被抽过。\n  - Le bateau a été tiré de l\'eau. (船从水里被拉出来了。)\n\n请注意，这些是\"tirer\"的一些基本形式和意义，实际使用中可能有更多情境相关的用法和含义。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1508, 106, ' bijou ', ' 珠宝', '1. 词性：名词（nom masculin）\n2. 词义：珠宝，宝石；小而精致的物品或地方\n3. 例句：\n   - Elle aime accumuler des bijoux de toutes sortes. (她喜欢收集各种各样的珠宝。)\n   - Cette petite boulangerie est un vrai bijou de notre quartier. (这家小面包店是我们街区的一块宝地。)\n\n变形及其词义：\n- Bijoux（复数形式）\n   - 词义：珠宝（多件）\n   - 例句：Il a offert une boîte de bijoux à sa femme pour son anniversaire. (他给妻子送了一个装满珠宝的盒子作为生日礼物。)\n- Bijoueur/Bijouisse（阳性/阴性形式的珠宝爱好者或收藏家）\n   - 词义：珠宝爱好者，珠宝收藏家\n   - 例句：Le bijoueur a acheté une belle bague antique. (这位珠宝收藏家买了一枚漂亮的古董戒指。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1509, 106, ' chaussure ', ' 鞋', '1. 词性：\n   - chaussure 是名词（nom féminin）。\n\n2. 词义：\n   - chaussure 主要指代“鞋子”。\n\n3. 例句：\n   - J\'ai acheté deux paires de chaussures pour l\'hiver. (我买了两双冬天穿的鞋。)\n   - Il porte des chaussures de sport en caoutchouc. (他穿着橡胶底的运动鞋。)\n\n变形及词义：\n\n- Chaussures : 复数形式，指多双鞋子。\n  - Elles ont mis des chaussures de danse pour aller à la fête. (她们穿上了舞鞋去参加派对。)\n\n- Chausser : 动词，意为给...穿鞋或穿鞋。\n  - Vous devez toujours chausser vos enfants des chaussons de pied confortables. (你应该总是给你的孩子们穿舒适的鞋子。)\n\n- Chaussée : 名词，指道路、人行道。\n  - La chaussée était glissante après la pluie. (雨后人行道很滑。)\n\n- Déchausser : 动词，意为脱鞋。\n  - Il a oublié de déchausser avant d\'entrer. (他在进来之前忘记脱鞋了。)\n\n这些变形和词义覆盖了“chaussure”这个单词在法语中的基本用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1510, 106, ' manteau ', ' 大衣', '1. 词性：名词（nom）\n2. 词义：大衣，外套；覆盖物\n3. 例句：\n   - J\'ai acheté un nouveau manteau pour l\'hiver. (我买了一件新大衣过冬。)\n   - Le manteau des montagnes est entierement recouvert de neige. (山的覆盖层完全被雪覆盖了。)\n\n变形及其词义和例句：\n- Manteaux (复数): 大衣，外套们\n   - Mes manteaux sont suspendus dans le vestiaire. (我的大衣们挂在衣帽间。)\n- Mantel (m.): 壁炉台，壁炉架\n   - Le mantel de la cheminée est orné de vaisselles d\'or. (壁炉台上装饰着金制餐具。)\n- Manteler (f.): 壁炉台布\n   - Maman a acheté une nouvelle manteler pour Noël. (妈妈买了一条新的圣诞壁炉台布。)\n- Mantèle (f.): 披肩，斗篷\n   - Elle s\'est enveloppée dans sa mantèle pour aller au concert. (她披上披肩去听音乐会。)\n\n请注意，这些变形和词义可能不完全符合所有地区和语境的使用习惯，但它们提供了基础的理解和用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1511, 106, ' chapeau ', ' 帽子', '1. 词性：\n- Nom masculin (名词，男性)\n\n2. 词义：\n- Un chapeau est un objet qui sert à couvrir la tête pour se protéger de la pluie, du soleil, etc. (帽子是一种用来覆盖头部以保护自己免受雨、太阳等影响的物品。)\n\n3. 例句：\n- Il a oublié son chapeau à la maison. (他忘记把帽子留在家里了。)\n- Mets ton chapeau, il fait froid dehors. (穿上你的帽子，外面很冷。)\n\n变形及其词义和例句：\n- Chapeaux (复数) - Plusieurs accessoires portés sur la tête pour se protéger de la pluie, du soleil, etc. (多个戴在头上的配件，用于保护自己免受雨、太阳等的影响。)\n  - Exemple : Les filles ont tous des chapeaux colorés. (女孩们都戴着彩色的帽子。)\n\n- Chape (动词) - Couvrir quelqu\'un de son chapeau. (用帽子遮住某人。)\n  - Exemple : Elle l\'a chapé avec son grand chapeau noir. (她用她的大黑帽子遮住了他。)\n\n- Chapelet (小词) - Un petit chapeau, souvent de forme plus légère que le chapeau. (一种小帽子，通常比帽子更轻便。)\n  - Exemple : Il préfère porter un chapelet plutôt qu\'un gros chapeau en hiver. (冬天他更喜欢戴一顶小帽子，而不是一个大帽子。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1512, 106, ' collier ', ' 项链', '1. 词性：名词\n2. 词义：项链，颈圈；束缚，枷锁\n3. 例句：\n   - Elle porte un collier de perles. (她戴着一条珍珠项链。)\n   - Le collier du chat était trop serré. (猫的项圈太紧了。)\n\n变形及词义：\n- Collier（名词，复数形式）：项链，颈圈；束缚，枷锁\n   - Les colliers de nos chats sont ornés de belles pendants. (我们猫的项链上装饰着漂亮的吊坠。)\n- Collier（动词，现在分词形式）：给…戴上颈圈；束缚\n   - Il est en train de collier son chien. (他正在给他的狗戴上颈圈。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1513, 106, ' sac ', ' 包', '1. 词性：名词（nom）\n2. 词义：\n   - 包，袋子\n   - 腹，肚子\n3. 例句：\n   - J\'ai un sac plein de livres à porter. (我有一个装满书的包要带。)\n   - Il a mal dans le sac après avoir mangé. (他吃了东西后肚子不舒服。)\n\n变形及其词义和例句：\n- Sac : 如上所述，意为“包”或“腹”。\n- Sacs : 复数形式，意为“包们”或“腹部”。例句：Il range ses sacs pour le voyage. (他为了旅行正在整理他的包。)\n- Saccadé : 形容词，意为“过时的”，“陈旧的”（在非正式用语中）。例句：Cette robe est un peu saccadée, mais elle est encore très chic. (这件连衣裙有点过时了，但它仍然非常时髦。)\n\n请注意，\"saccadé\"这个形容词是非正式用语，可能不适用于正式场合。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1514, 106, ' gant ', ' 手套', '1. 词性：名词\n2. 词义：手套\n3. 例句：\n   - J\'ai froid, j\'ai besoin de mettre des gants. (我冷，我需要戴上手套。)\n   - Il a perdu son gant de ski. (他丢了滑雪手套。)\n\n变形及词义：\n- Gants (复数): 手套们\n  - Exemple: Mets tes gants pour ne pas geler. (穿上你的手套以免冻伤。)\n- Gante (形容词): 有手套的，通常用于形容植物的果实带有类似手套形状的外壳。\n  - Exemple: Les fruits de la plante sont gantes. (这种植物的果实是有手套状外壳的。)\n- Ganterie (名词): 制手套的地方或商店\n  - Exemple: Je vais à la ganterie acheter un nouveau paire de gants de vélo. (我要去手套店买一副新的自行车手套。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1515, 106, ' soutien', 'gorge ', '1. 词性：soutien 是名词。\n\n2. 词义：soutien 主要有两个词义，第一个意思是“支持”，第二个意思是“胸罩”。\n\n3. 例句：\n- Pour le soutien de l\'équipe, c\'est crucial. (对于团队的支持，这至关重要。)\n- Elle a besoin d\'aide pour choisir un soutien convenable. (她需要帮助来选择一个合适的胸罩。)\n\n变形及其词义和例句：\n- soutiennent (动词的第三人称复数现在时形态): 表示“支持”的行为。\n  - Exemple: Les fans soutiennent passionnément leur équipe préférée. (粉丝们热情地支持他们最喜欢的队伍。)\n  \n- soutiens (动词的第二人称复数现在时形态): 表示“你（们）支持”。\n  - Exemple: Vous soutiens le projet? (你支持这个项目吗？)\n\n- soutient (动词的第三人称单数现在时形态): 表示“他/她/它支持”。\n  - Exemple: Il soutient les causes humanitaires. (他支持人道主义事业。)\n\n- soutiendras (动词的未来时第二人称单数形态): 表示将来的“你将支持”。\n  - Exemple: Tu soutiendras ta famille dans le besoin. (在需要的时候，你将支持你的家人。)\n\n- soutienotre (动词的命令式第二人称复数形态): 表示命令或请求“你们支持”。\n  - Exemple: Soutenez notre cause! (支持我们的事业吧！)\n\n注意：soutien作为名词，没有动词的变形，但可以通过相关的动词\"soutenir\"来表达相关的动作和状态。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1516, 106, ' vêtement ', ' 衣服', '1. 词性：\nVêtement 是一个名词。\n\n2. 词义：\n- 衣服，服饰\n- 覆盖物（比喻用法）\n\n3. 例句：\n- J\'ai acheté un nouveau vêtement pour le mariage de ma cousine. (我买了一件新衣服参加表妹的婚礼。)\n- Les vêtements du marin ont été très secs après sa baignade. (水手的衣服在游泳后都干了。)\n\n变形及词义：\n\n- Vêtu (形容词): 穿着的，有关衣服的\n  - Elle porte un vêtu elegant. (她穿着优雅的衣服。)\n\n- Vêtus (名词复数): 衣物\n  - Il a fait la lessive des vêtus sales. (他洗了脏衣服。)\n\n- Vêtir (动词): 给...穿衣\n  - Veuillez vêtir cette robe pour voir si elle vous va. (请穿上这条裙子看看是否适合您。)\n\n- Vêtue (名词，阴性形式): 服装，衣着\n  - Cette mode de vêtue est très populaire en ce moment. (这种衣着风格目前非常流行。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1517, 106, ' robe ', ' 连衣裙', '1. 词性：名词\n2. 词义：长袍，礼服；连衣裙\n3. 例句：\n   - Je préfère porter une robe pour cette soirée.（我更喜欢穿一件礼服参加这个晚会。）\n   - Elle a acheté une belle robe pour son mariage.（她为她的婚礼买了一条漂亮的连衣裙。）\n\n变形及其词义：\n- Robe（名词）：长袍，礼服；连衣裙\n  - Je porte une belle robe pour aller à la fête.（我穿着一条漂亮的连衣裙去参加聚会。）\n\n- Robes（复数名词）：长袍，礼服；连衣裙\n  - Les filles ont mis leurs robes pour l\'événement.（女孩们穿上了她们的连衣裙去参加活动。）\n\n- Robér（动词，不规则变形）：穿长袍，穿礼服\n  - Il robéra une robe noire pour la cérémonie.（他将穿上一件黑色的礼服参加仪式。）\n\n- Robes（动词，复数形式）：穿长袍，穿礼服\n  - Les acteurs robent des habits riches pour la scène.（演员们穿上华丽的服装上台。）\n\n- Robeuse（形容词，女性化形式）：穿着长袍的，穿着礼服的\n  - La robeuse dame est très élegante.（那位穿着礼服的女士非常优雅。）\n\n- Robeur（形容词，男性化形式）：穿着长袍的，穿着礼服的\n  - Le robeur homme a fait beaucoup d\'attention.（那位穿着礼服的男士引起了很多关注。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1518, 106, ' caleçon ', ' 内裤', '1. 词性：\nLe caleçon est un nom masculin (名词，阳性) qui désigne une sorte de pantalon sous-jacent.\n\n2. 词义：\nCaleçon signifie généralement \"sous-vêtement de culotte\", c\'est-à-dire des sous-vêtements qui sont portés sous les vêtements pour protéger la peau et assurer la propreté.\n\n3. 例句：\n- Je me suis trompé dans ma taille, donc mon caleçon est un peu serré.\n- Il a oublié de mettre son caleçon ce matin, il va certainement ressentir le froid toute la journée.\n\n变形及其词义和例句：\n- Caleçons (pluriel): Plusieurs sous-vêtements de culotte. Exemple: Elle a acheté trois paires de caleçons en coton pour l\'hiver.\n- Caleconnier (féminin), Caleconière (masculin): Qui fabrique ou vend des caleçons. Exemple: La caleconière locale propose des modèles de caleçons très confortables.\n- En caleçon: Signifie qu\'on ne porte que des sous-vêtements et pas de vêtements extérieurs. Exemple: Il est sorti en caleçon pour aller au supermarché juste à côté.\n\n注意：法语中的\"caleçon\"通常指的是男士内裤，而女士内裤则用\"slip\"或\"lingerie de culotte\"等词汇表示。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1519, 106, ' short ', ' 短裤', '1. 词性：\nLe mot \"short\" en français est un adjectif.\n\n2. 词义：\n- Court (en taille)\n- Rapide\n\n3. 例句：\n- Il porte une robe short. (Il porte une robe courte.)\n- Il a un peu de temps, donc il parle short. (Il a peu de temps, donc il parle rapidement.)\n\n变形及其词义：\n- Shorter (plus court que) - Exemple: Cette robe est shorter que l\'autre. (Cette robe est plus courte que l\'autre.)\n- Shortest (le plus court) - Exemple: Cette robe est la shortest de toutes. (Cette robe est la plus courte de toutes.)\n- Shortening (raccourcissement) - Exemple: Le shortening de la robe a fait qu\'elle ne va plus à lui. (La raccourcissement de la robe a fait qu\'elle ne va plus à lui.)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1520, 106, ' lunettes de soleil ', ' 太阳镜', '1. 词性：名词\n2. 词义：太阳镜，墨镜\n3. 例句：\n   - Je porte souvent des lunettes de soleil quand je vais à la plage. (我去海滩时经常戴太阳镜。)\n   - Il a oublié ses lunettes de soleil, il va surement avoir mal aux yeux. (他忘了带太阳镜，肯定会眼睛不适。)\n\n变形及词义：\n- 复数形式： lunettes de soleil (太阳镜)\n   例句：Elles ont acheté plusieurs paires de lunettes de soleil pour le voyage. (她们为旅行买了几副太阳镜。)\n- 单数形式： lunette de soleil (一副太阳镜)\n   例句：Il a perdu sa lunette de soleil préférée. (他丢了最喜欢的那副太阳镜。)\n\n注：法语中“lunettes de soleil”通常以复数形式出现，表示“太阳镜”，而其单数形式“lunette de soleil”较少使用，通常指“一副太阳镜”。在日常用语中，人们更习惯用复数形式来表达这一概念。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1521, 106, ' montre ', ' 手表', '1. 词性：名词\n2. 词义：手表；钟表；仪表；显示\n3. 例句：\n   - J\'ai oublié mon montre à la maison. (我忘记把手表留在家里了。)\n   - Il consulta son montre pour voir l\'heure. (他查看了他的手表以确认时间。)\n\n变形及其词义和例句：\n- Montrais (动词montrer的第一人称单数现在时形态)：展示，指示\n  - Je montrais le chemin à cette dame perdue. (我向这位迷路的女士指示道路。)\n- Montrez (动词montrer的命令式第二人称复数形态)：展示，给看\n  - Montrez votre ticket, s\'il vous plaît. (请出示您的票。)\n- Montra (动词montrer的第三人称单数过去分词形态)：被展示\n  - La peinture montra une mer tranquille. (这幅画展示了一片平静的海面。)\n- Montrant (动词montrer的现在分词形态)：正在展示\n  - En montrant ses œuvres, l\'artiste expliquait sa démarche créative. (在展示他的作品时，艺术家解释了他的创作过程。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1522, 107, ' supermarché ', ' 超市', '1.词性：\nLe mot \"supermarché\" en français est un nom masculin.\n\n2.词义：\nIl signifie un grand magasin de libre-service qui vend des produits alimentaires, de ménage, de cosmétiques et parfois des articles de bricolage, de vêtements et de loisirs.\n\n3.例句：\n- J\'achète souvent des produits alimentaires à tout prix à l\'hypermarché car ils sont généralement moins chers.\n- Le supermarché propose des offres spéciales hebdomadaires qui permettent aux consommateurs de réaliser des économies.\n\n变形及其词义：\n- Super marché (masculin singulier) : Un supermarché particulier ou un endroit où l\'on peut faire du shopping.\n  Exemple : Ce supermarché est très bien fourni en produits biologiques.\n\n- Supermarchés (masculin pluriel) : Plusieurs supermarchés.\n  Exemple : Il y a plusieurs supermarchés dans la ville pour satisfaire les besoins alimentaires des habitants.\n\n- De supermarché (déterminant) : Relatif à un supermarché.\n  Exemple : Je me suis rendu compte que le prix du lait était plus bas dans le supermarché que dans le petit commerce.', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1523, 107, ' client ', ' 顾客', '1. 词性：\n- Le nom masculin (阳性名词)\n\n2. 词义：\n- Un individu ou une entreprise qui reçoit des prestations, des services ou des produits d\'un vendeur, d\'un fournisseur ou d\'un praticien (接受卖方、供应商或从业者的服务、服务或产品的个人或企业).\n- En banque, personne qui a un compte chez elle et qui lui fait des virements (在银行中，指在其处拥有账户并进行转账的人).\n\n3. 例句：\n- Notre client a demandé une réduction pour l\'achat de ces articles. (我们的客户要求购买这些商品时给予折扣。)\n- Le client est roi ! (顾客是国王！)\n\n变形及其词义和例句：\n- Cliente (阴性形式): 阴性形式的“客户”。\n  - La cliente a été très satisfaite de la qualité du service. (客户对服务质量非常满意。)\n\n- Clients (复数形式): “客户”的复数形式。\n  - Le restaurant a reçu plusieurs clients cette soirée. (这家餐厅今晚接待了几位顾客。)\n\n- Clientiel (相关名词): 指客户群或客户基础。\n  - La firme a grandement élargi son clientiel grâce à son nouveau produit. (该公司凭借其新产品大幅扩大了客户群。)', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1746613287772.mp3');
INSERT INTO `word_list` VALUES (1524, 107, ' article ', ' 商品', '无法从大模型获取数据，请联系管理员！', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1525, 107, ' produits ', ' 产品', '1. 词性：\n- Produits 是名词，复数形式。\n\n2. 常用词义：\n- Produits 通常指“产品”或“商品”。\n\n3. 例句：\n- J\'aime beaucoup les produits de cette marque. (我非常喜欢这个品牌的产品。)\n- Les produits laitiers sont essentiels dans notre quotidien. (乳制品在我们的日常生活中是必不可少的。)\n\n变形及词义：\n- Produit（单数形式）： 单个产品或商品。\n  - C\'est le produit que j\'ai commandé en ligne. (这是我在网上订购的产品。)\n\n- Produire（动词形式）： 生产，制造。\n  - Cette usine produit des appareils électroniques de qualité supérieure. (这家工厂生产高质量的电子产品。)\n\n- Production（名词，表示行为或过程）： 生产，制造过程。\n  - La production de ce vin requiert des techniques traditionnelles. (这种酒的生产需要传统技术。)\n\n- Producteur（名词，表示人）： 生产者，制造商。\n  - Le producteur de ces vêtements utilise des matières premières durables. (这些衣服的生产者使用耐用的原材料。)\n\n- Productivité（名词，表示能力或水平）： 生产力，生产效率。\n  - L\'amélioration de la productivité a permis une augmentation des bénéfices. (生产力的提高带来了利润的增长。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1526, 107, ' retour ', ' 退货', '1. 词性：\n- retour 是名词。\n\n2. 词义：\n- 返回，归来；回去的动作或事实。\n- 回答，答复（书信、电话等）。\n\n3. 例句：\n- Je prévoyais mon retour à la maison pour dimanche. (我预计周日回家。)\n- J\'attends toujours un retour de son courrier. (我还在等他回信。)\n\n变形及其词义和例句：\n\n- Retourner (动词)：\n  - 词义：翻转，颠倒；重新做；返回，回去。\n  - 例句：Pouvons-nous retourner sur notre décision précédente? (我们可以重新考虑之前的决定吗？)\n\n- Retourné(e) (形容词)：\n  - 词义：翻转的，颠倒的；重新做过的。\n  - 例句：Cette photo est retournée, mets-la debout. (这张照片是倒的，把它正着放。)\n\n- Retournons (命令式)：\n  - 词义：我们返回吧。\n  - 例句：Retournons chez nous, il fait froid. (我们回家吧，天气冷。)\n\n- Retourné (过去分词作形容词)：\n  - 词义：被翻转的，被颠倒的；重新做过的。\n  - 例句：La page était retournée par erreur. (那一页错误地被翻过来了。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1527, 107, ' épicerie ', ' 杂货店', '无法从大模型获取数据，请联系管理员！', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1528, 107, ' magasin ', ' 商店', '1. 词性：名词\n2. 词义：商店，店铺\n3. 例句：J\'achète souvent des produits de beauté dans ce magasin.（我经常在这家商店购买美容产品。）\n\n变形及其词义与例句：\n- Magasinage（名词）： 商品储存。例句：Le magasinage efficace est crucial pour le succès d\'une entreprise.（有效的商品储存对企业的成功至关重要。）\n- Magasinier（名词）： 店员或仓库管理员。例句：Le magasinier a organisé les produits par catégories.（店员按类别组织了产品。）\n\n注意：Magasin 没有动词形式或其他形容词等变形，因为它主要是一个名词。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1529, 107, ' vendeur ', ' 卖家', '1. 词性：\nLe mot \"vendeur\" en français est un nom masculin.\n\n2. 词义：\n\"Vendeur\" signifie \"sell\" en anglais. C\'est une personne qui vend des produits ou des services à d\'autres personnes.\n\n3. 例句：\n- Le vendeur a offert une réduction pour tenter de convaincre le client de faire un achat. (The seller offered a discount to try and convince the customer to make a purchase.)\n- Elle a rencontré un vendeur de cosmétiques en train de vendre des produits dans la rue. (She met a cosmetics salesperson selling products on the street.)\n\nFormes de dérivation et exemples:\n- Vendeur (nom masculin): Le vendeur a vendu trois voitures aujourd\'hui.\n- Venteuse (nom feminin): La venteuse a expliqué les caractéristiques du produit à la cliente.\n- Vente (nom féminin): La vente des produits a été très bonne cette semaine.\n- Vendant (adjectif): Il est vendant des fruits sur le marché.\n- Vendeur (verbe): Je vais vendre mon ordinateur maintenant que j\'ai acheté une nouvelle.', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1530, 107, ' reduction ', ' 折扣', '1. 词性：\n- reduction 是名词（nom féminin）。\n\n2. 词义：\n- la réduction de prix (价格降低)\n- la réduction de vitesse (速度降低)\n- la réduction d\'échelle (规模缩小)\n- la réduction de données (数据缩减)\n\n3. 例句：\n- Il a profité de la réduction de prix pour acheter un ordinateur.\n  (他利用价格降低的机会买了一台电脑。)\n- La réduction de vitesse a permis à l\'agent de contrôle de mieux voir le conducteur.\n  (减速让交警能更好地看清楚司机。)\n\n变形及其词义：\n- reduise (动词，féminin)：减少，降低\n  - Elle a reduisé ses dépenses en super.\n  (她减少了超市的开支。)\n\n- réducteur / réductrice (形容词，masculin/féminin)：用于减少或降低某物的人或工具\n  - Le réducteur de vitesse est essentiel pour la sécurité des véhicules.\n  (速度减速器对车辆安全至关重要。)\n\n- réductif / réductive (形容词，masculin/féminin)：有降低作用的，导致减少的\n  - Une politique réductive peut entraîner des baisses de prix.\n  (紧缩政策可能导致价格下降。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1531, 107, ' caisse ', ' 收银台', '1. 词性：名词\n2. 词义：小木箱，盒子\n3. 例句：\n   - J\'ai trouvé une jolie caisse en bois dans le garage.\n   - Il rangea ses livres dans la caisse pour les transporter plus facilement.\n\n变形及其词义：\n- caissier (名词)：收银员\n  - Le caissier a accepté mon chèque de voyage.\n- caissière (名词)：女收银员\n  - La caissière a réglé ma commande avec méticulosité.\n- caisson (名词)：大箱子，柜子\n  - Les caissons de la bibliothèque contiennent des livres anciens.\n\n注意：法语单词的变形可能会根据具体语境和构词法有所不同。以上提供的是一些常见变形和用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1532, 107, ' prix ', ' 价格', '1. 词性：名词\n2. 词义：价格，费用\n3. 例句：\n   - Le prix de l\'essence a augmenté. (汽油的价格已经上涨了。)\n   - Il a payé un prix élevé pour cette œuvre d\'art. (他为这件艺术品支付了高昂的价格。)\n\n变形及词义：\n- Prix (复数形式): 价格，费用\n   - Les prix des produits alimentaires varient selon la saison. (食品的价格根据季节而变化。)\n- Pricier (形容词): 更贵的\n   - Cette voiture est trop pricier pour moi. (这辆车对我来说太贵了。)\n- Pricieux (形容词): 昂贵的\n   - Ce restaurant est pricieux, mais le service est excellent. (这家餐厅很贵，但服务非常好。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1533, 107, ' vente ', ' 销售', '1. 词性：\n- vente 是名词（nom féminin）。\n\n2. 词义：\n- vente 主要指的是“销售”或“出售”。\n\n3. 例句：\n- Aujourd\'hui, la vente de ces produits a commencé. (今天，这些产品的销售开始了。)\n- J\'ai entendu dire que la vente de ce livre est excellente. (我听说这本书的销量很好。)\n\n变形及词义，每个变形一个例句：\n\n- Vente（名词，阴性）： La vente de ces articles est limitée à une seule par personne. (这些商品的销售每人限购一件。)\n- Ventes（复数形式）： Les ventes annuelles de ce produit ont atteint un nouveau record. (这个产品的年销售量达到了新纪录。)\n- Vendeur（阳性名词）： Le vendeur me a offert un prix spécial pour cette voiture. (卖家为我提供了这辆车的特别价格。)\n- Vendeur（阴性名词）： Cette entreprise cherche des vendeurs expérimentés. (这家公司正在寻找有经验的销售人员。)\n- Vendeuse（阴性名词）： La vendeuse m\'a expliqué les caractéristiques du produit. (女销售员向我解释了产品的特性。)\n- Vendais（形容词，用于修饰男性）： Il est un vendeur professionnel et très vendable. (他是一名专业且很有说服力的销售员。)\n- Vendeuse（形容词，用于修饰女性）： Elle est une vendeuse persuasive et efficace. (她是一位有说服力且高效的女销售员。)\n\n请注意，法语中的性别和单复数会影响单词的形式，上述例句展示了这些变化。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1534, 107, ' achat ', ' 购买', '无法从大模型获取数据，请联系管理员！', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1535, 107, ' boutique ', ' 精品店', '1. 词性：名词\n2. 词义：小商店，精品店\n3. 例句：\n   - Je vais acheter un nouveau jean dans une boutique de vêtements. (我去一家服装店里买一条新牛仔裤。)\n   - Il y avait une boutique de chaussures juste à côté de notre maison. (我们家旁边就有一家鞋店。)\n\n变形及其词义：\n- Bouticqueuse（形容词）：与boutique有关的，形容一个女性经营或工作在boutique。\n  - Elle est bouticqueuse, elle vend des objets en ligne. (她是一个网店卖家，在线销售商品。)\n- Boutiquier（名词）：经营boutique的人。\n  - Le boutiquier de la rue du commerce est connu pour son excellent service. (商业街上的店主因其出色的服务而闻名。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1536, 107, ' livraison ', ' 送货', '1. 词性：\n- Livraison 是名词。\n\n2. 词义：\n- 交付，运送；交货\n\n3. 例句：\n- (1) La livraison de ces produits commencera le mois prochain.（这些产品的交付将于下个月开始。）\n- (2) J\'ai confirmé la date de livraison avec le fournisseur.（我已与供应商确认了交货日期。）\n\n4. 变形及其词义和例句：\n- Livrer（动词）： 交付，传送\n   - Exemple: Le vendeur doit livrer les marchandises le plus tôt possible.（卖家必须尽早交付商品。）\n- Livreur（名词）： 送货员\n   - Exemple: Le livreur est arrivé à l\'heure.（送货员准时到达了。）\n- Livré（形容词）： 交付的，已交付的\n   - Exemple: La commande est déjà livrée.（订单已经交付了。）\n- Livraisonner（动词）： 进行交付\n   - Exemple: Cette société livraisonne des produits de qualité.（这家公司提供高质量的产品。）\n\n请注意，\"livraisonner\" 这个单词在现代法语中并不常见，通常使用 \"effectuer une livraison\" 或 \"livrer\" 来表达类似的意思。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1537, 107, ' marchand de mode ', ' 时装商人', '1. 词性：\nmarchand de mode 是名词短语，由名词 marchand 和名词 mode 组成。\n\n2. 词义：\n这个词组直译为“时尚商人”，通常指从事时尚行业、销售或制造时尚产品的商人。\n\n3. 例句：\n- Elle était très impressionnée par le marchand de mode qui avait organisé la fête. (她对组织派对的时尚商人印象深刻。)\n- Le marchand de mode proposait des conseils sur les tendances de la saison. (这位时尚商人提出了关于季节趋势的建议。)\n\n变形及其词义：\n- marchande de mode（女性形式的时尚商人）： Une marchande de mode qui vend des robes haute couture. (一位销售高级定制服装的女性时尚商人。)\n- marchands de mode（复数形式）： Les marchands de mode se réunissent chaque année pour discuter des nouveautés. (时尚商人们每年聚会讨论新趋势。)\n\n请注意，法语中名词的性别会影响形容词的变化，但在这个短语中，\"mode\" 保持原形不变。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1538, 107, ' solde ', ' 促销', '1.词性： 名词\n2.词义： 余额，平衡，结算\n3.例句： \n- Je voudrais savoir le solde de mon compte bancaire. (我想知道我的银行账户余额。)\n- Il a demandé un solde des ventes pour la semaine dernière. (他要求查看上周的销售总结。)\n\n变形及其词义：\n- Solide (形容词)：坚固的，可靠的\n  - Cette maison est très solide, elle a été construite avec des matériaux de haute qualité. (这栋房子非常坚固，是用高质量的材料建造的。)\n- Solde (动词)：支付，偿还\n  - Il a décidé de solder tous ses dettes avant la fin de l\'année. (他决定在年底前偿还所有债务。)\n- Solde (副词)：完全地，彻底地\n  - Le problème est soldé， tu n\'as plus à te soucier de ça. (问题已经解决了，你不用再担心了。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1539, 107, ' paiement ', ' 支付', '1. 词性：名词\n2. 词义：支付，付款\n3. 例句：\n   - J\'ai effectué le paiement de ma facture en ligne. (我在网上支付了我的账单。)\n   - Le paiement sera effectué à la livraison du produit. (产品交付时将进行付款。)\n\n变形及其词义：\n- payer (动词)：支付\n  - Exemple: Je paye mon appartement par chèque. (我用支票支付我的公寓费用。)\n- payant (形容词)：支付的\n  - Exemple: Un système payant peut être utilisé pour cette transaction. (这种交易可以使用支付系统。)\n- payé (过去分词)：已支付\n  - Exemple: La facture est maintenant payée. (账单现在已支付。)\n- payable (形容词)：可支付的\n  - Exemple: La somme est payable d\'ici quatre semaines. (这笔钱必须在四周内支付。)\n- payeur (名词)：付款人\n  - Exemple: Le payeur a demandé un reçu pour la transaction. (付款人要求为这笔交易开具收据。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1540, 107, ' commande ', ' 订单', '1. 词性：\nCommande 是名词，也可以作为动词使用。\n\n2. 词义：\n- 名词：命令，点（酒菜）\n- 动词：命令，指挥\n\n3. 例句：\n- 名词：J\'ai commandé une nouvelle chaise pour mon bureau. (我为我的办公室订购了一把新椅子。)\n- 动词：Le capitaine commande son équipage avec autorité. (船长权威地指挥着他的船员。)\n\n变形及其词义：\n\n- Commandant (名词)：指挥官\n  - 例句：Le commandant a donné des ordres à ses soldats. (指挥官向他的士兵下达了命令。)\n\n- Commandante (名词)：女指挥官\n  - 例句：La commandante a organisé la mission avec précision. (女指挥官精确地组织了这次任务。)\n\n- Commander (动词)：命令，指挥\n  - 例句：Il commandera le départ de la formation. (他将指挥队伍的出发。)\n\n- Commandement (名词)：指挥，控制\n  - 例句：Le commandement de l\'avion est crucial pour assurer la sécurité des passagers. (飞机的控制对于确保乘客的安全至关重要。)\n\n- Commandable (形容词)：可指挥的\n  - 例句：Cette unité est commandable par un système informatique. (这个单元可以通过计算机系统进行指挥。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1541, 107, ' bon de réduction ', ' 优惠券', '1. 词性：名词\n2. 词义：折扣券，减价券\n3. 例句：\n   - J\'ai un bon de réduction pour cette robe, je vais l\'utiliser. (我有一张这件衣服的折扣券，我要用它。)\n   - Si tu as un bon de réduction, tu peux gagner beaucoup d\'argent en épargne. (如果你有一张折扣券，你可以节省很多钱。)\n\n变形及其词义：\n- bonne (f): 好的，形容词\n   - Cette robe est très bonne. (这件衣服很好。)\n- bonnes (fp): 好的，形容词复数\n   - Les bonnes choses arrivent à ceux qui les attendent. (好事会发生在等待它们的人身上。)\n- bonnet (m): 小帽子，名词\n   - Il porte un bonnet de voyage. (他戴着一顶旅行帽。)\n- bonneterie (f): 针织品，名词\n   - La bonneterie est une des techniques artisanales les plus anciennes. (针织是最早的手工艺技术之一。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1542, 105, ' Fête du Travail ', ' 劳动节', '1.词性：\nFête du Travail 是名词短语。\n\n2.词义：\nFête du Travail 意为“劳动节”，是一个特定的节日名称，用于庆祝劳动和劳动者的成就。\n\n3.例句：\n- La Fête du Travail est célébrée le premier mai. (劳动节在五月一日庆祝。)\n- Les syndicats organisent souvent des manifestations pour la Fête du Travail. (工会经常组织游行来庆祝劳动节。)\n\n4.变形及其词义：\n由于 \"Fête du Travail\" 是一个专有名词，它并没有变形。不过，我们可以谈论与这个节日相关的其他词汇或短语。例如：\n\n- Célébrer la Fête du Travail (庆祝劳动节)\n- Vacances de la Fête du Travail (劳动节假期)\n- Manifestation de la Fête du Travail (劳动节游行)\n\n请注意，\"Fête du Travail\" 本身作为一个固定短语，并不进行词形变化。上述相关表达是对这一节日活动的描述，而不是该短语的变形。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1543, 105, ' Pâques ', ' 复活节', '1. 词性：名词（nom）\n2. 词义：复活节\n3. 例句：Pendant Pâques, les familles se réunissent souvent pour célébrer ensemble.\n           - 在复活节期间，家人们常常聚在一起庆祝。\n\n4. 变形及其词义和例句：\n   - Pâque - 形容词（adjectif），与复活节相关的，用于形容与复活节有关的事物。\n     例句：C\'est une œuvre de Pâque, très symbolique.\n          - 这是一件复活节作品，非常具有象征意义。\n   - Pascale - 形容词（adjectif），与复活节有关的，通常用来形容复活节期间的宗教仪式或习俗。\n     例句：La Pascale évoque souvent la résurrection du Christ.\n          - 复活节常常让人联想到基督的复活。\n   - Pasquale - 形容词（adjectif），意大利语中复活节的意思，用于形容与复活节相关的事物。\n     例句：Les distraccions pasquales sont très populaires en Italie.\n          - 在意大利，复活节的娱乐活动非常受欢迎。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1544, 105, ' Fête de l\'Assomption ', ' 圣母升天节', '1. 词性：\nFête de l\'Assomption 是一个名词短语。\n\n2. 词义：\nFête de l\'Assomption 指的是天主教节日“圣母升天节”，庆祝圣母玛利亚被接升天堂的节日，通常在8月15日。\n\n3. 例句：\n- La Fête de l\'Assomption célèbre la montée au ciel de la Vierge Marie. (圣母升天节庆祝圣母玛利亚升天的节日。)\n- Le jour de la Fête de l\'Assomption, beaucoup de pelerins se rendent à la basilique de la Visitation à Ein Kerem. (圣母升天节那天，许多朝圣者前往艾因凯雷姆的访亲堂。)\n\n变形及其词义和例句：\n\na. Assomption (名词)\n词义：指“升天”的行为或事件，特指圣母玛利亚的升天。\n例句：L\'Assomption de la Vierge Marie est un événement religieux célèbre chez les catholiques. (圣母玛利亚的升天是天主教徒庆祝的一个宗教事件。)\n\nb. Assomptif (形容词)\n词义：与升天有关的。\n例句：Les cérémonies assomptifs sont solennelles. (升天仪式是庄严的。)\n\nc. Assomptive (形容词)\n词义：与升天有关的。\n例句：La journée de l\'Assomption est un moment assomptive important pour les fidèles. (圣母升天节对信徒来说是一个重要时刻。)\n\nd. Assompteur (名词)\n词义：指那些相信或支持圣母玛利亚升天教义的人。\n例句：Les assompteurs célèbrent la Fête de l\'Assomption avec grande dévotion. (那些相信圣母升天的人以极大的虔诚庆祝圣母升天节。)\n\n请注意，\"Assomptif\" 和 \"Assomptive\" 这两个形容词不常用，而且在现代法语中很少见，所以上述形容词的例子可能在实际语境中不常见。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1545, 105, ' Chandeleur ', ' 圣蜡节', '1. 词性：名词\n2. 词义：Chandeleur 指的是“圣蜡节”或“Candlemas”，这是天主教的一个节日，庆祝于2月2日。它标志着圣诞节季的结束，并且是耶稣诞生后40天举行的一个仪式，据信圣母玛利亚在这一天带婴儿耶稣去耶路撒冷的圣殿进行奉献。\n3. 例句：\n   - Nous célébrerons Chandeleur avec des crêpes traditionnelles.（我们将用传统煎饼来庆祝圣蜡节。）\n   - Le jour de Chandeleur, on pratique de retourner une crêpe au-dessus de l\'épaule pour être heureux toute l\'année.（在圣蜡节那天，我们习惯将煎饼抛过肩膀，以求全年好运。）\n\n变形及其词义：\n- Chandeleurs : 名词复数形式，指多个圣蜡节或与这个节日相关的物品或习俗。\n  - Exemple : Les Chandeleurs sont connus pour leurs traditions gastronomiques variées.（圣蜡节以其多样的饮食传统而闻名。）\n\n- Chandeleur : 形容词，与圣蜡节有关的或用于描述圣蜡节的。\n  - Exemple : Les crêpes sont un dessert typique de la fête des Chandeleur.（煎饼是圣蜡节典型的甜点。）\n\n请注意，\"Chandeleur\" 这个词在法语中没有动词变形，因为它是一个名词。以上提供的形容词形式是基于原名词创造的，用来描述与圣蜡节相关的事物。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1546, 105, ' All Saints\' Day ', ' 诸圣节', '1.词性： 名词\n2.词义： 万圣节，诸圣节\n3.例句： Le 1er novembre, c\'est la fête des morts, on honore les ancêtres. (11月1日是万圣节，我们纪念祖先。)\n4.变形及词义：\n   - La Toussaint (名词，专有名词，指代“万圣节”)\n     例句： Nous célèbrons La Toussaint à la maison de ma grand-mère. (我们在祖母家庆祝万圣节。)\n   - toussaint (形容词，意为“所有圣人的”)\n     例句： Le jour de toussaint est un moment de paix et de contemplation. (诸圣日是一个和平与沉思的时刻。)\n   - toussainte (名词，女性名字)\n     例句： Marie a pris pour nom de baptême \"Toussainte\", en mémoire de la fête des morts. (玛丽以“Toussainte”为洗礼名，以纪念亡灵节。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1547, 105, ' Fête nationale française ', ' 法国国庆日（巴士底日）', '1. 词性：名词短语\n2. 词义：法国国庆日，通常指的是每年的7月14日，庆祝1789年巴黎人民攻占巴士底狱的事件，这一事件标志着法国大革命的开始。\n3. 例句：\n   - La Fête nationale française est célébrée le 14 juillet avec des spectacles de feu d\'artifice.\n   - Les Français fièrent souvent un grand déjeuner sur la terrasse pour célébrer la Fête nationale française.\n\n变形及其词义：\n- Fêter (动词): 庆祝，纪念\n   - Exemple: Les habitants de la ville fêtent le bicentenaire de leur édifice historique.\n- National (形容词): 国家的，国民的\n   - Exemple: Cette année, le gouvernement a organisé des événements culturels pour célébrer le jour national.\n- Français (形容词): 法国的；(名词)法国人\n   - Exemple (形容词): Les droits nationaux sont protégés par la loi française.\n   - Exemple (名词): Les Français ont le droit de vote à l\'âge de 18 ans.\n\n请注意，\"Fête nationale française\" 本身作为一个固定搭配（专有名词短语），没有变形。上述提供的是组成该短语的部分单词的变形和词义。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1548, 105, ' Lundi de Pâques ', ' 复活节星期一', '1. 词性：\nLundi de Pâques 是一个名词短语。\n\n2. 词义：\nLundi de Pâques 指的是复活节星期一，即复活节后的第一天。\n\n3. 例句：\n- Nous avons décidé de partir en vacances le Lundi de Pâques. (我们决定在复活节星期一去度假。)\n- Le Lundi de Pâques, tout le monde est content car il y a souvent des jours fériés. (在复活节星期一，每个人都很高兴，因为通常有假期。)\n\n变形及其词义和例句：\n- Lundi : 名词，意为“星期一”。\n  - Je vais me faire couper les cheveux dimanche, donc je serai beau lundi. (我打算星期天去剪头发，所以星期一我会很漂亮。)\n- Pâques : 名词，意为“复活节”。\n  - Pâques est une période où beaucoup de gens cèlèbrent Jésus ressuscité. (复活节是许多人庆祝耶稣复活的时期。)\n- De : 介词，表示所属关系或来源。\n  - C\'est un cadeau de ma mère. (这是我妈妈的礼物。)\n- Le : 定冠词，用于阳性单数名词前。\n  - Le chien est sur le tapis. (狗在地毯上。)\n- Les : 定冠词，用于阴性复数名词前。\n  - Les filles sont parties en vacances. (女孩们去度假了。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1549, 105, ' Pentecôte ', ' 五旬节', '1. 词性：Pentecôte 是名词。\n2. 词义：Pentecôte 指的是耶稣升天的节日，通常在复活节后的第40天庆祝。\n3. 例句：\n   - Nous célébrerons Pentecôte cette année à la campagne. (我们今年将在乡下庆祝耶稣升天节。)\n   - Le dimanche de Pentecôte, les chrétiens célèbrent l\'ascension de Jésus. (耶稣升天周日，基督徒们庆祝耶稣的升天。)\n\n变形及其词义和例句：\n- Pentecot（非正式）：指代Pentecost，耶稣升天节。\n   - C\'est fini pour cette année, on se retrouve à la Pentecot ! (今年就这样了，耶稣升天节再见！)\n\n- Pentecotique（形容词）：与耶稣升天节有关的。\n   - Les cerémonies pentecotiques sont très importantes pour les chrétiens. (耶稣升天节的仪式对基督徒来说非常重要。)\n\n- Pentecotal（形容词）：与耶稣升天节有关的，是pentecotique的另一种形式。\n   - Il a participé à une récitation pentecotal hier soir. (他昨晚参加了一个关于耶稣升天节的朗诵会。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1550, 105, ' Ascension ', ' 耶稣升天节', '1. 词性：名词\n2. 词义：提升，升高；耶稣升天节\n3. 例句：L\'ascension de la lumière est un phénomène physique intéressant.\n          （光的上升是一个有趣的物理现象。）\n          Le jour de l\'Ascension, les chrétiens célèbrent la montée du Seigneur vers le ciel.\n          （在耶稣升天节那天，基督徒们庆祝主升天。）\n\n变形及其词义：\n- Ascensionnel, e（形容词）：与上升有关的\n  例：L\'effet Ascensionnel est souvent observé dans les phénomènes naturels.\n       （上升效应经常在自然现象中被观察到。）\n\n- Ascenseur（名词）：电梯\n  例：Prenez l\'ascenseur pour le sixième étage.\n       （请乘坐电梯到六楼。）\n\n目前给出的信息不足以提供所有可能的变形和词义，但以上是根据常见用法提供的相关变形。在法语中，“Ascension”主要用作名词，关于它的形容词形式“ascensionnel”较为少见，而“ascenseur”是日常用语中常用的名词，指代电梯。其他变形如动词等在现代法语中不常见或已不使用。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1551, 105, ' Toussaint ', ' 诸圣节', '1. 词性：\nToussaint 是名词。\n\n2. 词义：\n- Toussaint 是一个姓氏，用于指代特定的人或家族。\n- 在法语中，Toussaint 也可以指代“万圣节”（Toussaint的节日），即每年的11月1日，用来纪念已故的亲人。\n\n3. 例句：\n- Mon voisin s\'appelle Toussaint. (我的邻居叫图森。)\n- Le 1er novembre, c\'est la fête de la Toussaint. (11月1日是万圣节。)\n\n变形及其词义：\n- Toussainte: 名词，指万圣节的庆祝活动或万圣节期间。\n-例句： J\'ai préparé des gâteaux pour la Toussainte. (我为万圣节准备了蛋糕。)\n\n- Toussaints: 名词复数形式，可以指多个姓Toussaint的人，或者与万圣节相关的多个事物。\n- 例句： Les Toussaints vont à la fête de la Toussainte. (图森一家要去参加万圣节庆典。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1552, 105, ' Halloween ', ' 万圣节前夕', '1. 词性：名词（nom）\n2. 词义： Halloween 在法语中通常直接借用自英语，指的是万圣节前夜，即每年10月31日的节日。\n3. 例句：\n   - Pour Halloween, j\'ai préparé une grande fête avec des déguisement et des bonbons. (为了万圣节，我准备了一个盛大的派对，有化妆和糖果。)\n   - Les enfants portent des costumes pour aller faire \"trick or treat\" le Halloween. (孩子们穿着服装去“不给糖就捣蛋”。)\n\n变形及其词义：\n- Halloweenien(ne) 形容词，意为与Halloween相关的或具有其特征的。\n  - Cette ambiance Halloweenienne est très captivante. (这种万圣节氛围非常吸引人。)\n- Halloweeniste 名词，指庆祝或参与Halloween的人。\n  - Il est un vrai halloweeniste et celebrera la fête avec joie. (他是一个真正的万圣节爱好者，将会愉快地庆祝这个节日。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1553, 105, ' Noël ', ' 圣诞节', '1. 词性：Noël 是名词。\n2. 词义：圣诞节；圣诞季节。\n3. 例句：\n   - Noël est une période de fêtes et de réunions familiales.（圣诞节是一个庆祝和家庭团聚的时期。）\n   - Les cadeaux sont un rituel traditionnel du Noël.（礼物是圣诞节的传统仪式。）\n\n变形及其词义，以及例句：\n\n- Noël (基本形式): 如上所述，指圣诞节或圣诞季节。\n\n- Noëliste, Noëlistes (形容词或名词): 与圣诞节有关的，或者特指那些在圣诞节期间表演的人。\n   - Exemple: Les comédiens noëlistes ont organisé une soirée de variétés pour célébrer Noël.（圣诞演员们组织了一场综艺节目晚会来庆祝圣诞节。）\n\n- Noël (复数): Noëls, 表示多个圣诞节或多次圣诞季节。\n   - Exemple: Les Noëls passés ont toujours été très agréables chez eux.（他们过去的圣诞节总是非常愉快。）\n\n法语中“Noël”这个词没有其他复杂的变形，它主要用作名词，指代圣诞节这一节日或时期。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1554, 105, ' Jour de l\'An ', ' 新年', '1. 词性：Jour de l\'An 是名词短语。\n2. 词义：Jour de l\'An 的意思是“新年的第一天”，即“元旦”。\n3. 例句：\n   - Nous fêtons le Jour de l\'An avec des présentations et des festivités. (我们通过互赠礼物和庆祝活动来庆祝元旦。)\n   - Le Jour de l\'An est un jour férié dans la plupart des pays. (元旦在大多数国家是一个公众假期。)\n\n变形及其词义和例句：\n- Jour : 名词，意为“天”或“日子”。\n  - Chaque jour, il faut se reveiller tôt pour aller travailler. (每天，他都需要早起去上班。)\n- An : 名词，意为“年”。\n  - C\'est un an chargé de nouvelles découvertes. (这是充满新发现的一年。)\n- Jour de l\'an passé : 名词短语，意为“去年的元旦”。\n  - Jour de l\'an passé， j\'ai été en vacances à la montagne. (去年的元旦，我去山上度假了。)\n\n注意：Jour de l\'An 作为固定短语表示“元旦”，没有其他变形用于表示不同年份的元旦。每个年份的元旦都是 Jour de l\'An，只是上下文中可能会提到具体的年份。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1555, 105, ' Assomption ', ' 圣母升天节', '1. 词性：名词\n2. 词义：Assomption 是魁北克省的一个城市，也是天主教中的一个节日名称，即圣母升天节（l\'Assomption de la Vierge Marie）。\n3. 例句：\n   - J\'ai une amie qui vit à Assomption. (我有一个朋友住在阿松普雄。)\n   - La fête de l\'Assomption tombera cette année le 15 août. (今年的圣母升天节将在8月15日。)\n\n变形及词义：\n- Assomptionnaire (形容词)：与Assomption有关的，例如指该城市的居民或相关的事物。\n  - Exemple : Les Assomptionnaires sont fiers de leur ville. (阿松普雄的居民为他们的城市感到自豪。)\n\n请注意，\"Assomption\" 作为一个专有名词（地名、节日名）通常不会有太多变形，以上提供的是与其相关的形容词形式。其他如动词等变形在此上下文中不适用。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1556, 105, ' 14 juillet ', ' 国庆日（巴士底日）', '1. 词性：日期表达\n2. 词义：7月14日，法国国庆日\n3. 例句：\n   - Nous célébrons toujours notre anniversaire le 14 juillet. (我们总是在7月14日庆祝我们的周年纪念日。)\n   - Le 14 juillet, les rues de Paris sont animées par des parades et des feux d\'artifice. (7月14日，巴黎的街道上充满了游行和烟火。)\n\n变形及其词义：\n- 14ème juillet (十四日七月) - 表示7月的第14天，强调日期的顺序。\n   - Exemple: La fête nationale française a lieu le 14ème juillet. (法国国庆日在7月14日举行。)\n- Juillet 14 (七月十四) - 另一种表达相同日期的方式，顺序颠倒。\n   - Exemple: Les gens se réunissent souvent pour des activités pendant le juillet 14. (人们经常在7月14日聚会参加活动。)\n- 14e juillet (十四日七月) - 使用序数词“e”来表示“第14”，书面语中更常见。\n   - Exemple: Le 14e juillet, nous commémorons l\'émeute de 1789. (7月14日，我们纪念1789年的起义。)\n\n注意：法语中日期的表达方式灵活，可以根据语境和习惯选择不同的表达形式。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1557, 105, ' Fête des Mères ', ' 母亲节', '1. 词性：名词\n2. 词义：母亲节，这是一个庆祝母亲的节日。\n3. 例句：\n   - Pour la Fête des Mères, j\'ai offert un cadeau à ma mère. (为了母亲节，我给妈妈送了一件礼物。)\n   - La Fête des Mères est une occasion pour hommage les mères et leur dévouement. (母亲节是向母亲们及其奉献精神致敬的时刻。)\n\n变形及词义：\n- Fêter (动词) : 庆祝\n   - Exemple : Nous fêtons la Fête des Mères chaque année. (我们每年庆祝母亲节。)\n- Fêtard (名词) : 庆祝者\n   - Exemple : Les fêtards ont organisé une fête à l\'honneur des mères. (庆祝者们组织了一次以母亲为荣誉的庆祝活动。)\n- Fêté (形容词) : 被庆祝的\n   - Exemple : La journée de la Fête des Mères est fêtée dans tout le pays. (母亲节这天在全国都被庆祝。)\n\n请注意，\"Fête des Mères\" 作为一个专有名词，本身没有变形，但相关联的词汇可以有变形和不同的词义。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1558, 105, ' Fête des Pères ', ' 父亲节', '1. 词性：名词短语\n2. 词义：父亲节（专指法国的父亲节，每年6月的第三个星期日）\n3. 例句：\n   - Pour la Fête des Pères, j\'ai achepté un nouveau livre pour mon père.\n     （为了父亲节，我给爸爸买了一本新书。）\n   - Les enfants préparent souvent des cadeaux pour leurs pères pour célébrer la Fête des Pères.\n     （孩子们通常会准备礼物来庆祝他们的父亲节。）\n\n变形及词义：\n- Fêter (动词) : 庆祝\n   - Exemple : Nous fêtons la Fête des Pères chaque année.\n     （我们每年都会庆祝父亲节。）\n- Fêtard (名词) : 庆祝者，参加庆祝的人\n   - Exemple : Les fêtards ont organisé une soirée exceptionnelle pour leur père.\n     （庆祝者们为他们的父亲组织了一场特别的晚会。）\n- Fêté (形容词) : 被庆祝的\n   - Exemple : La journée de la Fête des Pères est un moment fêté chez moi.\n     （在我家，父亲节那天是一个被庆祝的时刻。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1559, 105, ' Fête de la Victoire ', ' 胜利日', '1. 词性：名词短语\n2. 词义：胜利日，特指第二次世界大战结束的纪念日。\n3. 例句：\n   - Le Fête de la Victoire est un jour public en France.\n   - C\'est au Fête de la Victoire que nous avons appris la fin de la guerre.\n4. 变形及其词义：\n   - Fêter (动词)：庆祝\n       - Nous fêtons la victoire avec un grand dîner.\n   - Victorieux (形容词)：胜利的\n       - L\'équipe a été considérée comme victorieuse.\n   - Victoire (名词)：胜利\n       - La victoire est finalement notre.', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1560, 105, ' Fête de la Marié ', ' 圣母领报节', '1. 词性：名词短语（phrase nominale）\n2. 词义：结婚纪念日，婚礼庆典\n3. 例句：\n   - Nous célébrons notre fête de la marié depuis dix ans.\n   - Il y a un grand party pour la fête de la marié.\n\n变形及其词义：\n- Fêter (动词)：庆祝\n   例句：Nous allons fêter notre anniversaire de marriage.\n- Fêtard (形容词)：节日的，喜庆的\n   例句：Il porte un costume fêtard pour la soirée.\n- Fêtif (形容词)：喜庆的，欢快的\n   例句：La musique fait l\'atmosphère fêtif à la cérémonie.', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1561, 105, ' Saint Nicolas ', ' 圣尼古拉节', '1.词性：\nSaint Nicolas 是一个法语专有名词，用于指代一个特定的人名或地名。在这个情况下，它通常指的是 Saint Nicholas，即圣尼古拉斯，一个基督教圣人和儿童的守护者，也是现代圣诞老人的原型之一。\n\n2.词义：\n- Saint Nicholas（圣尼古拉斯），一个基督教圣人，以慷慨和慈善而闻名。\n- 在某些情况下，Saint Nicolas 也可能是某些地方的名称。\n\n3.例句：\n- Nous célébrons tous les ans la fête de Saint Nicolas le 6 décembre. (我们每年都会庆祝12月6日的圣尼古拉斯节。)\n- Les enfants ont mis leurs souliers pour que Saint Nicolas y pose des cadeaux. (孩子们放好了他们的鞋子，以便圣尼古拉斯能在里面放些礼物。)\n\n变形及其词义：\n由于 \"Saint Nicolas\" 是专有名词，它没有像动词那样的变形。然而，如果要谈论与圣尼古拉斯相关的事物，可以使用形容词形式 \"saint-nicolas\"，例如在描述与节日相关的物品时。\n\n例句：\n- Le marché de Noël saint-nicolas est très populaire dans notre ville. (我们城市的圣尼古拉斯圣诞市场非常受欢迎。)\n\n请注意，由于 \"Saint Nicolas\" 是专有名词，其用法和变形不会像普通名词或动词那样广泛。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1562, 105, ' Épiphanie ', ' 主显节', '1. 词性：名词（nom féminin）\n2. 词义：\n   - 启示，顿悟，灵感突发的时刻\n   - 主显节（基督教节日，庆祝耶稣诞生后首次显现给三位博士）\n3. 例句：\n   - J\'ai eu une épiphanie pendant la nuit et j\'ai compris comment résoudre le problème.\n     （我在夜里有了一个顿悟，明白了如何解决这个问题。）\n   - La fête de l\'Épiphanie célèbre la première apparition du Christ aux mages.\n     （主显节庆祝基督首次显现给三博士。）\n\n变形及其词义：\n- Épiphanie（基本形式，如上所述）\n- Épiphanies（复数形式）\n   - Exemple : Les épiphanies ne sont pas rares quand on est en pleine créativité.\n     （当你处于创作高峰期时，顿悟并不罕见。）\n- Épiphanisante（形容词，形容某事物能激发顿悟的）\n   - Exemple : Cette exposition est vraiment épiphanisante pour les artistes.\n     （这次展览对艺术家来说确实具有启发性。）\n- Épiphaniser（动词，指引发顿悟或启示）\n   - Exemple : Cet article a épiphanisé beaucoup de gens sur l\'importance de la santé mentale.\n     （这篇文章让许多人顿悟到心理健康的重要性。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1563, 105, ' 1er mai ', ' 劳动节', '1. 词性：\n- \"1er mai\" 是一个名词短语，指的是日期“五月一日”。\n\n2. 词义：\n- 表示日历中的特定日子，即每年5月的第一天。\n\n3. 例句：\n- (a) Le 1er mai, c\'est la Fête du Travail en France. (五月一日是法国的劳动节。)\n- (b) J\'ai rendez-vous le 1er mai pour l\'entretien. (我五月一日有个面试约会。)\n\n变形及其词义和例句：\n- \"1er mai\" 这个表达本身没有变形，因为它是一个固定搭配，指的是特定的一天。不过，如果要表达其他月份的第一天，可以用类似的结构，例如 \"1er janvier\" (一月一日), \"1er février\" (二月一日) 等。\n\n例句（其他月份的第一天）：\n- (c) Le 1er janvier, c\'est la Saint Sylvestre. (一月一日是除夕夜。)\n- (d) Nous fêtons le 1er février comme le Jour de l\'Epoux Ideal. (我们把二月一日当作理想丈夫日来庆祝。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1564, 105, ' Armistice ', ' 停战纪念日', '1. 词性：\nArmistice 是名词。\n\n2. 词义：\n- 休战，暂时停止战斗\n- 停战协议\n\n3. 例句：\n- Les deux pays ont signé une armistice pour un temps limité. (两国签署了一份有限期停战协议。)\n- L\'armistice a été conclue après des négociations prolongées. (经过漫长的谈判后，双方达成了停战协议。)\n\n变形及其词义和例句：\n- Armistique (形容词): 与停战有关的\n  - Exemple: Le traité armistique a été signé hier. (昨天签署了停战条约。)\n- Armistement (名词): 停战状态\n  - Exemple: Le pays a entrer en armistement après six mois de guerre. (经过六个月的战争后，该国进入了停战状态。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1565, 105, ' 1er novembre ', ' 诸圣节', '1. 词性：\n- **1er novembre** 是一个名词短语，指的是日历上的一个特定日期。\n\n2. 词义：\n- **1er novembre** 直译为“11月1日”，通常用于指代该日期或与该日期相关的事件。\n\n3. 例句：\n- **Nous célébrerons notre anniversaire le 1er novembre.** (我们将在11月1日庆祝我们的生日。)\n- **Le 1er novembre, j\'ai commencé ma nouvelle vie.** (11月1日，我开始了我的新生活。)\n\n变形及其词义和例句：\n- **novembre**（名词）- 十一月\n    - **Il fait froid en novembre.** (十一月天气很冷。)\n- **premier**（形容词）- 第一的\n    - **C\'est la première fois que je l\'entends dire.** (这是我第一次听到他说这个。)\n- **premier novembre**（名词短语）- 十一月初\n    - **Le temps va se retourner au premier novembre.** (天气将在十一月初转好。)\n\n注意：虽然“1er”和“premier”在很多情况下可以互换使用，但在某些固定表达中，它们的使用是有区别的，如“le 1er novembre”特指11月1日这一日期，而“premier novembre”则更倾向于描述时间段而非具体日期。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1566, 105, ' 8 mai ', ' 欧洲胜利日', '1. 词性：\nmai 是名词。\n\n2. 词义：\n- mai 表示“五月”，是一年中的第五个月。\n\n3. 例句：\n- 1. Nous avons planifié une réunion le 8 mai. (我们计划在5月8日召开一次会议。)\n- 2. Les fleurs éclosent en mai. (花朵在五月绽放。)\n\n变形及其词义：\n- mai (基本形式): 如上所述，表示“五月”。\n- maial (形容词): 与“mai”相关的形容词，用于描述与五月相关的事物。\n  - Exemple: Le temps est souvent maial en mai. (五月的天气通常是美妙的。)\n- maieul (形容词): 罕见的形式，通常不单独使用，但在复合词中可能出现。\n  - Exemple: La beauté maieul de la nature. (大自然那如五月般美丽的景色。)\n\n请注意，\"maial\" 和 \"maieul\" 不是常见的变形，且在日常法语中使用较少。最常用的形式就是 \"mai\"。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1567, 108, ' Pomme ', ' 苹果', '1. 词性：名词\n2. 词义：苹果\n3. 例句：\n   - \"J\'ai une pomme pour le dessert.\"（我有一个苹果作为甜点。）\n   - \"La pomme est un fruit juteux et savoureux.\"（苹果是一种美味可口的水果。）\n\n变形及其词义：\n1. Pomme (名词) - 苹果\n   例句： \"Elle aime manger des pommes.\"（她喜欢吃苹果。）\n\n2. Pommes (复数名词) - 苹果们\n   例句： \"Nous avons une boîte de pommes.\"（我们有一盒苹果。）\n\n3. Pomper (动词) - 采摘苹果\n   例句： \"Il pompe les pommes du jardin.\"（他正在从花园里采摘苹果。）\n\n4. Pompée (形容词) - 被采摘过的苹果\n   例句： \"Cette pomme est trop pompée, elle n\'est pas mûre.\"（这个苹果被摘得太久了，它不熟了。）\n\n5. Pompé (过去分词) - 被采摘的苹果\n   例句： \"Les pommes ont été pompées hier soir.\"（这些苹果昨晚被采摘了。）\n\n6. Pompées (复数形容词) - 被采摘过的苹果们\n   例句： \"Les pommes sont toutes pompées, elles sont prêtes à être consommées.\"（所有的苹果都被采摘过了，它们准备好被食用了。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1568, 108, ' Pêche ', ' 桃子', '1. 词性：名词\n2. 词义：钓鱼；捕鱼；桃子\n3. 例句：\n   - Je vais à la pêche ce week-end.（我这周末要去钓鱼。）\n   - J\'ai mangé une belle pêche hier.（我昨天吃了一个美味的桃子。）\n\n变形及其词义：\n- Pêcher（动词）：去钓鱼；捕鱼\n   - Il pêche souvent le samedi.（他经常在周六去钓鱼。）\n- Pêcheur（名词）：渔夫；钓鱼者\n   - Le pêcheur est parti de bonne heure.（渔夫很早就出发了。）\n- Pêcheuse（名词）：女渔夫；女钓鱼者\n   - La pêcheuse a ramassé beaucoup de poissons.（女渔夫捕到了许多鱼。）\n- Pêchot（名词）：小渔船\n   - Il est parti en pêchot pour une journée de pêche.（他乘坐小渔船出发，进行一天的钓鱼活动。）\n\n请注意，以上信息是基于标准的法语用法，实际使用中可能会有所不同。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1569, 108, ' Melon ', ' 甜瓜', '1.词性：\nLe mot \"Melon\" en français est un nom masculin.\n\n2.词义：\n- Fruit comestible, grosse, à chair juteuse et jaune, qui a des graines, et dont la pulpe est souvent rosée. (可食用的水果，大且多汁，呈黄色，含有种子，果肉常带有玫瑰色。)\n- Par extension, le melon désigne une personne stupide, con. (扩展意义上，melon指一个愚蠢的人。)\n\n3.例句：\n- J\'aime beaucoup manger du melon au soleil. (我非常喜欢在阳光下吃西瓜。)\n- Tu es un vrais melon! (你真是个傻瓜！)\n\n变形及其词义和例句：\n- Melonnière : Une plantation de melons. (西瓜地。)\n  Exemple : Il travaille dans une melonnière. (他在一片西瓜地里工作。)\n\n- Mélon : Un synonyme de melon, plus rare. (与melon同义，较少见。)\n  Exemple : Je préfère le mélon au melon. (我更喜欢西瓜而不是甜瓜。)\n\n注意：法语中“melon”一词通常指的是我们所说的西瓜，而“cantaloupe”（在英语中有时简称为“melon”）在法语中称为“melon d\'eau”。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1570, 108, ' Cacahouète ', ' 花生', '1. 词性：名词\n2. 词义：cacahouète 是一个法语单词，意思是“花生”。\n3. 例句：\n   - Je préfère les cacahouètes au lieu des pommes de terre. (我更喜欢花生而不是土豆。)\n   - Les cacahouètes sont un excellente source de protéines. (花生是一种极好的蛋白质来源。)\n\n变形及其词义：\n- cacahouète (n.f.): 未变形的名词形式，表示“花生”。\n   - Les cacahouètes sont trop croustillantes pour moi. (对我来说，花生太硬了。)\n- cacahouètes (n.f.pl.): 复数形式的名词，表示多个“花生”。\n   - J\'ai acheté des cacahouètes pour le week-end. (我买了一些花生来过周末。)\n- cacahoueter (v.): 动词形式，表示“吃花生”或“用花生喂”。\n   - Il aime cacahoueter pendant les matchs de foot. (他喜欢在足球比赛期间吃花生。)\n- cacahuète (n.f.): 另一种拼写方式，也表示“花生”。\n   - Pourrait-tu m\'apporter une cacahuète ? (你能给我带一个花生吗？)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1571, 108, ' Papaye ', ' 木瓜', '1. 词性：名词\n2. 词义：木瓜，番木瓜\n3. 例句：J\'aime beaucoup manger des papayes, elles sont très savoureuses. (我非常喜欢吃木瓜，它们非常美味。)\n4. 变形及其词义：\n   - Papayer（动词）：种植木瓜\n   - Papayage（名词）：木瓜树，木瓜植物\n   - Papayéen（形容词）：与木瓜有关的\n5. 变形例句：\n   - Je vais papayer dans mon jardin. (我要在我的花园里种木瓜。)\n   - Le papayage est très abondant dans cette région. (这个地区的木瓜树非常丰富。)\n   - C\'est un fruit papayéen que j\'adore. (这是我喜欢的与木瓜有关的水果。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1572, 108, ' Abricotier ', ' 杏子', '1. 词性：\nAbricotier 是名词。\n\n2. 词义：\nAbricotier 主要指的是杏树或杏子。\n\n3. 例句：\n- Les abricots sont murs, on peut les cueillir.\n- J\'ai planté un abricotier dans le jardin.\n\n变形及其词义：\n- Abricot (名词)：指单个的杏子。\n  - Je préfère les abricots secs que les abricots frais.\n- Abricotier (名词)：如上，指杏树或杏子。\n  - L\'abricotier est un fruit très apprécié en été.\n- Abricotine (形容词)：与杏子相关的或像杏子的。\n  - La couleur de sa robe était abricotine, très vive.\n- Abricotier (动词)：这个词没有直接的动词形式，但可以通过其他方式表达，例如 \"cueillir des abrics\" 来表示采摘杏子的行为。\n\n注意：法语中通常使用 \"abricot\" 来指单个的杏子，而 \"abricottier\" 较少使用，更多使用 \"arbre à abricots\" 来指杏树。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1573, 108, ' Mangue ', ' 芒果', '1. 词性：\nMangue 是名词。\n\n2. 词义：\n- 芒果树，属于漆树科的一种热带果树。\n- 芒果，这种树上结的果实。\n\n3. 例句：\n- J\'adore les mangues, elles sont délicieuses. (我喜欢芒果，它们很美味。)\n- Le mangue est un fruit tropical très apprécié. (芒果是一种非常受欢迎的热带水果。)\n\n变形及其词义和例句：\n- Manguier（阳性名词）：芒果树\n  - Le manguier que nous avons planté dans le jardin commence à fleurir. (我们在花园里种的芒果树开始开花了。)\n\n- Manguer（动词）：采摘芒果\n  - Nous allons manguer ce week-end, le temps sera idéal. (我们这个周末要去摘芒果，天气会很好。)\n\n由于\"mangue\"是一个名词，在法语中它没有动词形态或形容词形态的直接变形。不过，可以通过与其他词汇组合来形成相关表达。例如：\n\n- Manguier（如上所述）指芒果树。\n- Mangue pimentée（辣椒味的芒果），通过与\"pimentée\"（辣的，加了辣椒的）结合来描述一种特定风味的芒果。\n  - J\'ai essayé la mangue pimentée, c\'était un peu capiais. (我尝试了辣椒味的芒果，有点奇怪。)\n\n请注意，\"manguer\"作为动词并不是一个标准或广泛接受的形式，而是一个假设性的构造，用于说明如何从名词衍生出相关的动词意义。实际上，人们更可能会用“cueillir des mangues”(采摘芒果)或简单地说“manger des mangues”(吃芒果)。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1574, 108, ' Raisin ', ' 葡萄', '1. 词性：\nRaisin 是名词。\n\n2. 词义：\n- 葡萄；\n- 葡萄酒酿造用的葡萄；\n- 葡萄干。\n\n3. 例句：\n- J\'aime beaucoup les raisins, ils sont sucrés et bons pour la santé. (我非常喜欢葡萄，它们甜而且对健康有益。)\n- Les raisins secs sont un excellent choix de snack sain. (葡萄干是一种极好的健康零食选择。)\n\n变形及其词义：\n- Raisiné(e)（形容词）：含有葡萄的；用葡萄制成的。\n  - Cette tarte est raisinée, elle contient beaucoup de raisins. (这个派含有葡萄，里面有很多葡萄。)\n\n- Raisinage（名词）：采摘葡萄；葡萄收获。\n  - Le raisinage est une période importante pour les vignerons. (对于葡萄种植者来说，采收葡萄是一个重要的时期。)\n\n- Desraisiné(e)（动词）：去除葡萄；使失去葡萄。\n  - Il a déraisiné la moisson avant la cuisson. (他在烹饪前去除了葡萄串中的葡萄。)\n\n请注意，这些变形和例句是基于单词“Raisin”的标准用法，实际使用中可能还有其他语境特定的变形或含义。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1575, 108, ' Noix ', ' 核桃', '1. 词性：\n- Nom féminin (名词，阴性)\n\n2. 词义：\n- noix（核桃）\n- la noix de coco（椰子）\n\n3. 例句：\n- J\'aime très bien les noix. (我非常喜欢核桃。)\n- La noix de coco est un aliment riche en gras. (椰子是一种富含脂肪的食物。)\n\n变形及其词义和例句：\n- noix -> noix（复数）\n    Exemple: Les noix sont un excellent ingrédient pour une salade. (核桃是沙拉的绝佳配料。)\n\n- noix -> noyaux（核，中心）\n    Exemple: Les noyaux des fruits contiennent souvent de la nourriture pour les insectes. (水果的核常常含有昆虫的食物。)\n\n- noix -> noix（过去分词形式）\n    Exemple: Les noix que j\'ai achetées sont très fraîches. (我买的核桃非常新鲜。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1576, 108, ' Cerise ', ' 樱桃', '1. 词性：\nCerise 是名词。\n\n2. 词义：\n- 樱桃（树或其果实）\n- 樱桃色，鲜红色\n\n3. 例句：\n- J\'ai mangé une poignée de cerises. (我吃了一把樱桃。)\n- La couleur de sa jupe était un joli cerise. (她的裙子颜色是一种漂亮的樱桃红。)\n\n变形及其词义和例句：\n- Cerises, pluriel : 樱桃的复数形式\n  - Les cerises sont mûres. (樱桃成熟了。)\n\n- Cérisse, adjectif féminin : 形容红色的女性形容词\n  - Elle porte un manteau cérisse. (她穿着一件樱桃红色的大衣。)\n\n- Cérise, adjectif masculin ou adverbe : 形容红色的男性形容词或副词\n  - Il a achete une voiture cérise. (他买了一辆樱桃红色的车。)\n  - Elle a peint les murs cérise. (她把墙涂成了樱桃红色。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1577, 108, ' Ananas ', ' 菠萝', '1. 词性：\nAnanas 是名词。\n\n2. 词义：\n- 菠萝，一种热带水果。\n- （非正式）一团糟，混乱的状态。\n\n3. 例句：\n- J\'aime beaucoup manger des morceaux d\'ananas. (我非常喜欢吃菠萝块。)\n- Le projet est un véritable ananas, on ne sait plus à qui on doit parler. (这个项目真是一团糟，我们都不知道该和谁说话了。)\n\n变形及其词义和例句：\n- Ananas (名词， 单数): 如上所述，指“菠萝”或“混乱的状态”。\n  - Example: Je vais acheter un ananas pour faire une salade. (我去买个菠萝来做沙拉。)\n\n- Ananas (名词， 复数): 指多个“菠萝”或多次“混乱的状态”。\n  - Example: Il y avait des ananas partout dans la maison après le bal. (舞会后，房子里到处都是乱糟糟的。)\n\n- Ananas (形容词): 形容与“菠萝”相关的事物。\n  - Example: Un cocktail ananas a une saveur incroyable. (菠萝鸡尾酒的味道令人难以置信。)\n\n请注意，\"ananas\" 在法语中主要用作名词，并不常用作形容词。上述形容词用法比较少见，更多用于具体指代“菠萝味”的事物。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1578, 108, ' Noz ', ' 榛子', '1. 词性：Noz 是名词。\n2. 词义：鼻子、嗅觉、突出部分、工具的尖端。\n3. 例句：\n   - J\'ai attrapé un froid, je sens mon nez qui commence à m\'en coller. (我感冒了，我感觉我的鼻子开始粘上了。)\n   - Il a la noz très fini, c\'est son plus grand défaut. (他的鼻子很细，这是他最大的缺点。)\n\n变形及其词义与例句：\n- Nom masculin (阳性名词): Noz - 鼻子、嗅觉、突出部分、工具的尖端。\n  - J\'ai attrapé un froid, je sens mon nez qui commence à m\'en coller. (我感冒了，我感觉我的鼻子开始粘上了。)\n- Adjectif masculin (阳性形容词): Mulley - 多鼻的。\n  - Cette fille est mulley, elle a des problèmes de respiration. (这个女孩鼻子很多，她有呼吸问题。)\n- Verbe (动词): Flairer - 闻、嗅。\n  - Le chien a flairé le gibier et a immédiatement commencé à le suivre. (狗闻到了猎物的气味，立即开始追踪。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1579, 108, ' Fraise ', ' 草莓', '1. 词性：\nFraise 是一个名词。\n\n2. 词义：\n- 草莓（植物及其果实）\n- 草莓色，一种鲜艳的红色带有微细的深色点状图案\n\n3. 例句：\n- J\'aime beaucoup manger des fraises en été. (夏天我非常喜欢吃草莓。)\n- Cette robe est à la mode cette saison, elle a l\'aspect de fraise. (这件连衣裙是这个季节的流行款式，它有草莓色的外观。)\n\n变形及词义：\n- Fraiser (动词): 指用草莓装饰或用草莓味的东西调味。\n  - Exemple: On pourrait fraiser le gâteau avec du sirop de fraise. (我们可以用草莓糖浆给蛋糕加味。)\n\n- Fraisier (名词): 一种以草莓为主要风味的甜点，通常是一种奶油蛋糕。\n  - Exemple: Le fraisier est un plat sucré très apprécié en France. (Fraisier是一种在法国非常受欢迎的甜点。)\n\n- Framboise (名词): 野生草莓，较小且味道更浓郁。\n  - Exemple: La framboise croît naturellement dans les bois et sur les bords de chemins. (野生草莓自然生长在树林和路边。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1580, 108, ' Myrtille ', ' 蓝莓', '1. 词性：名词\n2. 词义：蓝莓\n3. 例句：\n   - J\'aime beaucoup les myrtilles, elles sont douces et exquises. (我非常喜欢蓝莓，它们又甜又细腻。)\n   - Les myrtilles sont riches en antioxydants et ont des bienfaits pour la santé. (蓝莓富含抗氧化剂，对健康有益。)\n\n变形及其词义：\n- Myrtille (名词): 蓝莓\n  - Ce dessert est garni de myrtilles. (这道甜点配了蓝莓。)\n\n- Myrtillier (名词): 蓝莓树\n  - Le myrtillier produit des fruits colorés. (蓝莓树结出有色的果实。)\n\n- Myrtillique (形容词): 与蓝莓有关的\n  - Cette tarte a une saveur myrtillique délicieuse. (这个馅饼有美味的蓝莓味。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1581, 108, ' Banane ', ' 香蕉', '1. 词性：名词（nom féminin）\n2. 词义：香蕉，通常指水果。\n3. 例句：\n   - J\'aime beaucoup manger des bananes. (我非常喜欢吃香蕉。)\n   - Pouvez-vous m\'apporter une banane, s\'il vous plaît? (你能给我拿一根香蕉吗？)\n\n变形及其词义和例句：\n- Bananier, é， adjective (形容词): 与香蕉有关的，例如指种植或销售香蕉的人。\n   - Cette région est connue pour être bananière. (这个地区以种植香蕉而闻名。)\n- Bananifère, é， adjective (形容词): 产生香蕉的。\n   - Les plantations bananifères sont très abondantes ici. (这里的香蕉园非常丰富。)\n- Débananer, verbe (动词): 去除香蕉皮。\n   - Il a débanané rapidement pour préparer le dessert. (他迅速剥了香蕉准备甜点。)\n\n请注意，法语中没有直接从“Banane”派生出很多变形，以上列举的是与香蕉相关且常见的词汇和用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1582, 108, ' Orange ', ' 橙子', '1. 词性：\nOrange 是名词（nom），在法语中通常指水果橙子，也可指颜色橙色。\n\n2. 词义：\n- 橙子（la fruit orange）\n- 橙色，橘色（la couleur orange）\n\n3. 例句：\n- J\'aime beaucoup manger des oranges. (我非常喜欢吃橙子。)\n- Ma chambre est peinte en orange. (我的房间被漆成了橙色。)\n\n变形及其词义和例句：\n\n- Oranger（阳性名词）：橙树\n  - L\'oranger donne des fruits délicieux. (橙树结出美味的果实。)\n\n- Orangeraie（阴性名词）：橙园\n  - Il travaille dans une orangeraie. (他在一个橙园工作。)\n\n- Orangeate（形容词）：橙色的，橘色的\n  - Elle a acheté un châle orangeate. (她买了一条橙色的围巾。)\n\n请注意，\"oranger\" 和 \"orangeraie\" 是具体指向橙树和橙园的词汇，而 \"orangeate\" 是形容词形式，用来描述具有橙色特征的事物。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1583, 108, ' Châtaigne ', ' 栗子', '1. 词性：\nChâtaigne 是名词。\n\n2. 词义：\n- 栗子，板栗（植物的果实）。\n- 板栗树（植物本身）。\n\n3. 例句：\n- J\'ai acheté une poignée de châtaignes pour faire un dessert au automne. (我买了一把板栗来做一个秋天的甜点。)\n- Les châtaigniers sont en fleur, le paysage est magnifique. (板栗树开花了，风景非常美丽。)\n\n变形及其词义和例句：\n- Châtaignier, -ière (栗子树/板栗树)\n  - 词义：板栗树，栗子树。\n  - 例句：Le châtaignier est un arbre fruitier très apprécié. (栗子树是一种非常受欢迎的果树。)\n\n- Châtaigneraie (栗子林)\n  - 词义：栗子树林。\n  - 例句：Nous aimons faire des randonnées dans la châtaigneraie. (我们喜欢在栗子林里徒步旅行。)\n\n- Châtaignelier (栗子树丛)\n  - 词义：由多棵栗子树形成的小树丛。\n  - 例句：Il y avait un petit châtaignelier près de notre maison où nous prenons souvent l\'ombre. (我们家附近有一个小栗子树丛，我们经常在那里乘凉。)\n\n- Châtaigneul (栗子果)\n  - 词义：指单个的栗子果。\n  - 例句：La châtaigneul peut être cuisiné à la vapeur ou à la broche. (栗子可以用蒸的或烤的方式来烹饪。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1584, 108, ' Mirabelle ', ' 梨', '1. 词性：名词\n2. 词义：蜜桃；李子\n3. 例句：\n   - J\'aime beaucoup les mirabelles, elles sont douces et juteuses. (我非常喜欢蜜桃，它们又甜又多汁。)\n   - Les mirabelles sont en pleine saison, on peut les acheter partout. (蜜桃正是季节，到处都可以买到。)\n\n变形及词义：\n- Mirabelle (f): 蜜桃；李子\n- Mirabelles (fpl): 复数形式，表示多个蜜桃或李子\n- Miroiter (v): 用\"mireter\"的形式，表示采摘蜜桃或李子\n- Miroite (v): 用\"mirote\"的形式，表示采摘蜜桃或李子\n- Miroité (v): 用\"mirote\"的形式，表示采摘蜜桃或李子\n\n例句：\n- Je vais miroiter des mirabelles dans le jardin. (我要去花园里摘些蜜桃。)\n- On va faire une tarte aux mirabelles que nous avons miroitées hier. (我们要用昨天摘的蜜桃做一个馅饼。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1585, 108, ' Kiwi ', ' 猕猴桃', '1. 词性：名词\n2. 词义：猕猴桃，新西兰人\n3. 例句：\n   - J\'aime beaucoup manger des kiwis, ils sont très bons pour la santé.（我非常喜欢吃猕猴桃，它们对健康很有益。）\n   - Le Kiwi est un oiseau nocturne qui se reproduit facilement en captivité.（几维鸟是一种夜行性鸟类，在人工饲养下容易繁殖。）\n\n变形及词义：\n- Kiwi (单数)：猕猴桃，新西兰人\n  - Le kiwi est un fruit très riche en vitamines.（猕猴桃是一种富含维生素的水果。）\n- Kiwis (复数)：猕猴桃们，新西兰人们\n  - Il y a des kiwis sur le plateau de fruits.（水果盘里有猕猴桃。）\n- Kiwier/Kiwière (形容词)：与猕猴桃相关的，新西兰的\n  - Un coupe-kiwi est un cocktail au kiwi.（一杯猕猴桃鸡尾酒是含有猕猴桃的鸡尾酒。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1586, 108, ' Figue ', ' 无花果', '1. 词性：\nFigue 是名词。\n\n2. 词义：\nFigue 主要指“无花果”或“无花果树”。\n\n3. 例句：\n- J\'aime beaucoup les figues sèches. (我非常喜欢干无花果。)\n- Il y a des figuiers dans le jardin de mon grand-père. (我祖父的花园里有无花果树。)\n\n变形及其词义，每个变形一个例句：\n\n- Figuer (动词): 意味着“想象”，“考虑”，或“计算在内”。\n  - Je ne figuais pas qu\'il arriverait si tôt. (我没料到他会这么早到。)\n\n- Figurant (名词): 指在电影、戏剧等中的“临时演员”或“配角”。\n  - Mon cousin travaille souvent comme figurant dans des films. (我的表兄经常在电影中担任临时演员。)\n\n- Figuratif (形容词): 表示“形象化的”或“比喻的”。\n  - Cette expression a un sens figuratife. (这个表达有比喻的意义。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1587, 109, ' chirurgie ', ' 外科', '1. 词性：chirurgie 是名词。\n2. 词义：chirurgie 主要指的是外科医学或手术操作。\n3. 例句：\n   - Il a été admis à la faculté de médecine pour spécialiser dans la chirurgie. (他被医学院录取，专攻外科。)\n   - La chirurgie est un domaine avancé de la médecine qui nécessite des compétences très spécifiques. (外科是医学的一个先进领域，需要非常专业的技能。)\n\n变形及词义：\n- Chirurgical (形容词): 与外科医学或手术有关的。\n  - Exemple: Les instruments chirurgicaux doivent être stérilisés avant chaque intervention. (外科器械在每次手术前都必须进行消毒。)\n- Chirurge (名词): 指从事外科的医生，即外科医生。\n  - Exemple: Le chirurge a réussi l\'intervention avec grande précision. (外科医生非常精确地完成了手术。)\n- Chirurgien (名词): 也是外科医生的意思，与“chirurge”同义。\n  - Exemple: La consultation du chirurgien s\'est soldée par une décision d\'opération imminente. (外科医生的咨询以立即手术的决定告终。)\n\n注意：在实际使用中，“chirurgical”较少单独使用，而“chirurgien”和“chirurge”都常用来指代外科医生，但“chirurge”更偏向于文学或正式语境中使用。在日常交流中，“chirurgien”更为常见。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1588, 109, ' santé ', ' 健康', '1. 词性：名词\n2. 词义：健康，身体状况\n3. 例句：\n   - Je me sens en santé. (我感觉身体健康。)\n   - Il est essentiel de prendre soin de sa santé. (照顾好自己的健康是非常重要的。)\n\n变形及其词义：\n- santé (名词): 健康，身体状况\n   - Je me sens en santé. (我感觉身体健康。)\n- santé (形容词): 健康的\n   - Manger des fruits et des légumes est bon pour la santé. (吃水果和蔬菜对健康有益。)\n- santement (副词): 健康地\n   - Il va à la gymnase pour rester santement. (他去健身房是为了保持健康。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1589, 109, ' traitement ', ' 治疗', '1. 词性：名词（Nom）\n2. 词义：\n   - 处理，治疗，疗程\n   - 对待，待遇\n   - 管理，操作\n3. 例句：\n   - Le traitement de cette maladie peut être long. (这种病的治疗可能会很长。)\n   - Il a reçu un traitement injuste à l\'université. (他在大学受到了不公正的对待。)\n\n变形及词义：\n- Traiter (动词)：对待，治疗\n   - Exemple: Elle traite ses patients avec beaucoup de compassion. (她以极大的同情心对待她的患者。)\n\n- Traiteur (名词)：处理者，治疗师\n   - Exemple: Le traiteur spécialisé dans la physiothérapie a aidé le patient à récupérer la motilité. (专门从事物理治疗的治疗师帮助患者恢复了活动能力。)\n\n以上是关于 \"traitement\" 的一些基本信息和用法。希望这能帮到你！', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1590, 109, ' opération ', ' 手术', '1. 词性：名词（nom féminin）\n2. 词义：操作，运算；手术；行动，作战。\n3. 例句：\n   - Elle a subi une opération chirurgicale pour corriger sa vision. （她接受了一次外科手术来矫正视力。）\n   - L\'opération de réparation du réseau électrique a duré plusieurs heures. （修复电网的操作持续了几个小时。）\n\n变形及其词义和例句：\n1. Opérer - 动词（verbe），意为进行手术，操作，执行。\n   - Le docteur a opéré sur le patient en trois heures. （医生在三个小时内为病人进行了手术。）\n   \n2. Opératoire - 形容词（adjectif），意为手术的，操作的。\n   - La salle opératoire est équipée de la dernière génération de matériel médical. （手术室配备了最新一代的医疗设备。）\n\n3. Opératrice - 名词（nom féminin），意为女操作员，女手术师。\n   - La nouvelle opératrice a commencé ses stages en hôpital. （新来的女手术师开始在医院实习。）\n\n4. Opérationnel, le - 形容词（adjectif masculin），意为操作的，可操作的，有效的。\n   - Cette stratégie est operationnelle et devrait améliorer les résultats. （这个策略是有效的，应该会改善结果。）\n\n5. Opératif,ve - 形容词（adjectif masculin/féminin），意为有效的，起作用的。\n   - Les mesures prises ont été rapidement opératives. （采取的措施很快产生了效果。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1591, 109, ' cardiologie ', ' 心脏病学', '1. 词性：\nCardiologie 是名词。\n\n2. 词义：\n- 心脏病学，即关于心脏疾病的医学分支。\n\n3. 例句：\n- Mon père est allé chez le cardiologue pour une consultation en cardiologie. (我父亲去心脏病专家那里进行了一次心脏病咨询。)\n- La cardiologie diagnostique et thérapeutique est très avancée dans cet hôpital. (这家医院的诊断和治疗心脏病学非常先进。)\n\n变形及其词义：\n- Cardiologue (名词): 心脏病学家，专门从事心脏病治疗的医生。\n  - Example: Le cardiologue a recommandé des changements de régime pour ma mère. (心脏病学家建议我妈妈改变饮食习惯。)\n  \n- Cardiologique (形容词): 与心脏病学相关的。\n  - Example: Il a commencé un traitement cardiologique pour son arrhythmie. (他开始了针对心律不齐的心脏病治疗。)\n\n- Cardiologie (无复数形式变化): 如原词所示，通常不变为复数形式。\n  - Example: La clinique spécialisée dans la cardiologie a recevu des prix de qualité. (这个专门从事心脏病学的诊所获得了质量奖。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1592, 109, ' exercice ', ' 运动', '1. 词性：名词\n2. 词义：练习，训练；习题，作业\n3. 例句：\n   - J\'ai beaucoup d\'exercices à faire pour l\'examen demain. (我有很多练习要做，为明天的考试做准备。)\n   - Il est important de faire des exercices tous les jours pour rester en forme. (每天做练习以保持健康是很重要的。)\n\n变形及其词义和例句：\n- Exercer (动词): 练习，锻炼；行使（职权）\n  - Elle exerce le métier de cuisinier depuis dix ans. (她从事厨师职业已经十年了。)\n- Exercice (名词): 同上\n- Exercice (动词): 同上\n- Exercice (形容词): 用于形容经常进行体育锻炼的人或事物\n  - Il est très exercice, il court tous les jours. (他很注重锻炼，每天都跑步。)\n- Exercices (名词复数): 练习，训练；习题，作业\n  - Le professeur a donné des exercices aux élèves pour le week-end. (老师给学生们布置了周末的作业。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1593, 109, ' hospitalisation ', ' 住院', '1. 词性：名词\n2. 词义：住院治疗；入院\n3. 例句：\n   - Elle a subi une longue hospitalisation après son accident. (她出事故后经历了长时间的住院治疗。)\n   - La hospitalisation pour une chirurgie non urgente peut être différée. (非紧急手术的住院可以被推迟。)\n\n变形及其词义：\n- Hospitaliser (动词): 使住院\n  - Exemple: Le médecin a décidé de hospitaliser le patient pour une prise en charge plus appropriée. (医生决定让病人住院以获得更恰当的治疗。)\n\n- Hospitalisé (形容词): 住院的\n  - Exemple: Le patient hospitalisé dans la salle d\'urgence est en réanimation. (在急诊室住院的病人正在接受重症监护。)\n\n- Hospitalière (名词): 医院护士\n  - Exemple: La hospitalière a distribué des analgesiques aux patients en attente. (医院的护士给等候的病人分发了止痛药。)\n\n- Hospitalier (形容词): 与医院有关的\n  - Exemple: Les services hospitaliers ont été modernisés pour améliorer le confort des patients. (医院的服务设施已经现代化，以改善病人的舒适度。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1594, 109, ' réanimation ', ' 重症监护', '1. 词性：\nRéanimation 是名词。\n\n2. 词义：\nRéanimation 主要有两个常用词义：\n- 复苏，复活（医学上指使停止跳动的心脏重新跳动）\n- 振兴，复兴（指使某事物恢复活力或重新流行）\n\n3. 例句：\n- 医学上的复苏： \"Le médecin a ordonné une réanimation immédiate pour le patient.\"\n- 振兴或复兴： \"La ville a besoin d\'un programme de réanimation pour attirer plus de tourists.\"\n\n变形及其词义和例句：\n- Réanimer (动词): 使复苏，使振兴\n  - \"Les medecins ont essayé de réanimer le patient après la crise cardiaque.\"\n- Réanime (形容词): 被复苏的，有活力的\n  - \"Les efforts de réanimation ont rendu les quartiers animés et attractifs.\"\n- Réanimant (现在分词作形容词): 正在复苏的，使人复苏的\n  - \"Cette nouvelle politique est très réanimante pour l\'économie du pays.\"\n- Réanimée (过去分词作形容词): 已复苏的\n  - \"La ville, maintenant réanimée, attire de nombreux visiteurs.\"\n- Réanimation (名词): 复苏，振兴\n  - \"La réanimation de l\'entreprise a permis sa survie dans un marché compétitif.\"', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1595, 109, ' urgence ', ' 急诊', '1. 词性：名词 (nom féminin)\n2. 词义：紧急情况，急迫性\n3. 例句：\n   - L\'urgence de ce problème ne peut plus être ignorée. (这个问题的紧急性再也不能被忽视了。)\n   - Il y avait une urgence dans son appel, j\'ai immédiatement compris qu\'il y avait un problème. (他的电话里有一种紧迫性，我立刻意识到有问题。)\n\n变形及其词义和例句：\n- Urgent, e (形容词 adj.): 紧急的，迫切的\n   - C\'est une affaire urgente. (这是一件紧急的事情。)\n- Urgentement (副词 adv.): 紧急地，迫切地\n (他要求我紧急介入。   - Il m\'a demandé d\'intervenir urgentement.)\n- Urgence (名词 nom f.): 紧急情况，急迫性（同原形）\n   - La médecine d\'urgence est chargée de traiter les patients en cas d\'urgence. (急诊医学负责在紧急情况下治疗病人。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1596, 109, ' médecin ', ' 医生', '1. 词性：\nmédecin 是名词。\n\n2. 词义：\n- 医生，行医者；\n- （古）学者，有学问的人。\n\n3. 例句：\n- J\'ai un rendez-vous avec le médecin demain. 我明天和医生有个约会。\n- Elle a fait carriere de médecin. 她从事了医生职业。\n\n4. 变形及其词义：\n- médecine (f): 医学 - Elle étudie la médecine. 她学习医学。\n- médical (adj): 医学的 - Il travaille dans un environnement médical. 他在医疗环境中工作。\n- médeciner (v): 用医药治疗 - Le docteur a dû médeciner beaucoup de patients. 医生必须医治很多病人。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1597, 109, ' soigner ', ' 治疗', '1.词性：动词\n2.词义：照料，治疗，护理\n3.例句：\n- Elle s\'occupe de soigner ses blessures. (她忙着照料她的伤口。)\n- Il a été soigné avec des médicaments modernes. (他接受了现代药物治疗。)\n\n变形及其词义：\n- Soigneur/Soigneuse（名词）：护士，医生\n- Soin（名词）：照顾，护理；注意，关怀\n- Soigneux/Soigneuse（形容词）：细心的，仔细的\n- Soigneusement（副词）：细心地，仔细地', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1598, 109, ' anesthésie ', ' 麻醉', '1. 词性：名词\n2. 词义：麻醉，麻醉状态；麻醉剂\n3. 例句：\n   - L\'anesthésie a été administree avant la chirurgie pour soulager le patient de la douleur.\n   - Le médecin s\'est posé des questions sur l\'usage de l\'anesthésie pendant l\'opération.\n\n变形及其词义：\n- Anesthésique (形容词)：与麻醉有关的，用于麻醉的\n  - Exemple : Le médicament anesthésique a été injecté au patient pour réduire la douleur.\n- Anesthésiste (名词)：麻醉师\n  - Exemple : L\'anesthésiste s\'est occupé de monitorer la condition du patient pendant l\'intervention chirurgicale.\n- Anesthésie (不可数名词)：指麻醉的行为或状态\n  - Exemple : L\'anesthésie générale a été appliquée pour assurer la relaxation complète du patient pendant l\'opération.', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1599, 109, ' vaccination ', ' 疫苗接种', '1. 词性：\nVaccination 是名词。\n\n2. 词义：\n- 疫苗接种\n- 注射疫苗的行为或过程\n\n3. 例句：\n- Elle a eu sa vaccination contre la grippe l\'année dernière. (她去年接种了流感疫苗。)\n- Il est important de faire la vaccination pour prévenir les maladies infectieuses. (预防传染病，进行疫苗接种是很重要的。)\n\n变形及词义：\n- Vacciner (动词): 给...接种疫苗\n  - Exemple: Le médecin va vacciner le petit garçon contre la rougeole. (医生将给这个小男孩接种麻疹疫苗。)\n\n- Vaccin (名词): 疫苗\n  - Exemple: Le vaccin contre la polio a éliminé la maladie dans beaucoup de pays. (脊髓灰质炎疫苗在许多国家已经根除了该病。)\n\n- Vacciné (形容词): 已接种疫苗的\n  - Exemple: Le chat est maintenant vacciné contre la rage. (这只猫现在已接种了狂犬病疫苗。)\n\n请注意，法语单词的准确用法和变形可能根据上下文有所不同。上述信息提供了基本概念，但在具体使用时可能需要根据具体情况调整。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1600, 109, ' maladie ', ' 疾病', '1.词性： 名词\n2.词义： 疾病；病状\n3.例句：\n- Je suis malade, j\'ai une maladie.（我生病了，我有一种病。）\n- La maladie de Parkinson est difficile à guérir.（帕金森病很难治愈。）\n\n变形及其词义：\n- maladif (形容词)：有病的；多病的\n  - Cette région est maladive, beaucoup de personnes y sont malade.（这个地区多病，很多人生病。）\n- maladière (名词)：病弱的女性\n  - La maladière a besoin de soins constants.（这位病弱的女性需要持续的照顾。）\n- maladier (名词)：病弱者\n  - Le maladier est confiné à la maison parce qu\'il est trop faible pour sortir.（这位病弱者被限制在家中，因为他太虚弱无法外出。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1601, 109, ' diète ', ' 饮食', '1. 词性：\nDiète 是名词。\n\n2. 词义：\n- 饮食，食物；\n- （动物的）食物，饲料；\n- （病人的）饮食规定，食谱。\n\n3. 例句：\n- Pour maigrir, elle suit une diète très stricte. (为了减肥，她遵循一个非常严格的饮食计划。)\n- Le médecin lui a prescrit une diète équilibrée pour soigner son ulcère. (医生给她开了一个平衡的饮食处方来治疗她的溃疡。)\n\n变形及其词义和例句：\n- Diète (f): 如上所述，指饮食、食物或食谱。\n- Dièté (m): 指被喂食的动物或人。\n  - Il est un excellent chien de vénerie, mais il refuse toujours la diète qu\'on lui donne. (它是一只优秀的猎犬，但它总是拒绝人们给它的食物。)\n- Diètant, Diètante (m/f): 指正在节食的人。\n  - Elle est en train de suivre une diète, elle est donc diètante. (她正在遵循一种饮食，因此她是正在节食的人。)\n- Dièter (v): 指进行节食。\n  - Pour perdre du poids, elle se diète. (为了减肥，她在节食。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1602, 109, ' gynécologie ', ' 妇产科', '1. 词性：\nGynécologie 是名词。\n\n2. 词义：\n- 妇科医学，专门研究女性生殖系统疾病的医学分支。\n- 有时也指妇科医生的实践或工作领域。\n\n3. 例句：\n- Je me suis inscrit chez le gynécologue pour des conseils de planification familiale. (我去妇科医生那里登记，以获取家庭计划的建议。)\n- La gynécologie est une spécialité médicale qui se concentre sur la santé des femmes. (妇科是一个专注于女性健康的医学专业。)\n\n4. 变形及其词义和例句：\n- Gynécologue (名词): 妇科医生\n  - Mon gynécologue ma dit de prendre des vitesses de plusieurs jours. (我的妇科医生告诉我需要休息几天。)\n- Gynécologique (形容词): 与妇科有关的\n  - Les examens gynécologiques sont essentiels pour la détection précoce des problèmes. (妇科检查对于早期发现问题至关重要。)\n- Gynécologie (不变，作为名词使用，如上文所示)\n\n请注意，法语单词的变形通常涉及名词、动词、形容词等不同词性的转换，但“gynécologie”主要用作名词，相关的形容词和从名词派生的词汇（如“妇科医生”）会有不同的形式。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1603, 109, ' radiologie ', ' 放射科', '1. 词性：\nRadiologie 是名词。\n\n2. 词义：\n- 放射学（医学分支，使用射线如X射线进行诊断和治疗）\n\n3. 例句：\n- Je suis médecin en radiologie. (我是放射科医生。)\n- La radiologie permet de visualiser l\'intérieur du corps humain. (放射学可以让人体内视化。)\n\n4. 变形及其词义与例句：\n- Radiologue (名词) : 放射学家\n  - Exemple : Le radiologue a analysé les images scanographiques. (放射学家分析了扫描图像。)\n- Radiologique (形容词) : 关于放射学的\n  - Exemple : L\'équipement radiologique est très avancé. (放射学设备非常先进。)\n- Radiologiez (动词) : 进行放射学检查（非正式用法，通常用radiographier或scanner作为动词）\n  - Exemple : Le patient devra se faire radiologier pour exclure un fracture. (患者将接受放射学检查以排除骨折。)\n\n注意：在标准法语中，“radiologiez”不是一个常用词汇，而“radiographier”或“faire un scanner”更为常见。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1604, 109, ' dermatologie ', ' 皮肤病学', '1. 词性：名词\n2. 词义：皮肤学，皮肤病学\n3. 例句：\n   - Je suis allergique, j\'ai besoin de voir un dermatologue. (我对某些东西过敏，我需要看皮肤科医生。)\n   - La dermatologie est une spécialité médicale qui étudie la peau et les maladies cutanées. (皮肤病学是一个医学专业，研究皮肤和皮肤疾病。)\n\n变形及其词义：\n- Dermatologue (名词): 皮肤科医生\n  - J\'ai eu rendez-vous avec un dermatologue pour examiner cette eruption. (我预约了一位皮肤科医生来检查这个皮疹。)\n- Dermatologique (形容词): 与皮肤学相关的\n  - Il y avait une étude dermatologique intéressante sur le traitement des dérmatites. (有一项关于治疗皮炎的有趣的皮肤病学研究。)\n- Dermatologie (名词): 皮肤学，皮肤病学\n  - L\'hospitalisation dans un service de dermatologie a permis de diagnostiquer sa dermatite. (在皮肤科住院使他的皮炎得到了诊断。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1605, 109, ' pharmacie ', ' 药房', '1. 词性：名词\n2. 词义：药房，药店；药剂学\n3. 例句：\n   - J\'ai besoin d\'aller à la pharmacie pour acheter du médicament. (我需要去药房买药。)\n   - Elle travaille comme pharmacienne dans une grande pharmacie. (她在一家大药房当药剂师。)\n\n变形及其词义：\n- Pharmacien, pharmacienne（药剂师）：指在药房工作的人，负责配药和提供药物咨询。\n   例句：Le pharmacien nous a conseillé un bon produit pour le dédouleur. (药剂师给我们推荐了一个很好的止痛产品。)\n\n- Pharmaceutique（药剂学的，药品的）：形容词，与药剂学或药品有关的。\n   例句：La pharmaceutique est un domaine très important de la santé publique. (药剂学是公共卫生领域非常重要的一部分。)\n\n- Pharmacies（药房的复数形式）：指多个药房或药店。\n   例句：Il y a trois pharmacies dans le centre-ville. (市中心有三家药房。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1606, 109, ' douleur ', ' 疼痛', '1. 词性：名词\n2. 词义：痛苦，疼痛；悲伤，苦恼\n3. 例句：\n   - Je ressentais une douleur écrasante dans le ventre. (我感到胃里有一种难以忍受的疼痛。)\n   - La douleur de son décès me hante encore. (他去世的痛苦仍然困扰着我。)\n\n变形及词义：\n- douloureux, douloureuse (形容词): 痛苦的\n   - Cette blessure est très douloureuse. (这个伤口非常疼。)\n- douleur (名词复数): 痛苦，疼痛；悲伤，苦恼\n   - Elle a bucheré ses douleurs en se retirant un peu. (她通过稍微退一步来掩饰自己的痛苦。)\n- douloir (动词): 感到痛苦\n   - Le patient douloirait après l\'opération. (病人手术后会感到疼痛。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1607, 108, ' Starfruit ', ' 杨桃', '1. 词性：\nCarambole (n.m.) - 星果，又名杨桃。\n\n2. 词义：\n- Un fruit avec une forme en étoile, connu sous le nom de carambole en anglais.\n\n3. 例句：\n- J\'ai bu un jus de carambole au petit-déjeuner.\n- Le carambole est un fruit tropical riche en vitamines.\n\n4. 变形及其词义和例句：\n- Carambolerais (adj.): Se dit d\'un fruit qui a la forme d\'un carambole.\n  - Cette pomme était si ronde et aplatie que je l\'ai prise pour une tomate, mais c\'était juste un fruits carambolerais.\n\n- Caramboleux (adj.): Qui ressemble à un carambole.\n  - La forêt était peuplée de plantes exotiques, y compris des arbres caramboleux dont les feuilles formaient des étoiles verdoyantes.\n\n注意：由于“Starfruit”是英文单词，在法语中直接对应的名词是“carambole”，而形容词形式如“carambolerais”或“caramboleux”并不是常用词汇，但可以根据需要构造以适应特定语境。上述形容词用法为假设性构造，用以展示如何形成相关形容词。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1608, 108, ' Goji Berry ', ' 枸杞子', '1. 词性：\nGoji Berry 在法语中通常用作名词，表示一种特定的浆果。\n\n2. 词义：\nGoji Berry 在法语中指的就是枸杞浆果，它是一种常用于健康食品和传统中医的红色小浆果。\n\n3. 例句：\n- J\'aime mélanger des goji berry à mon yogourt pour ajouter de la nourriture. (我喜欢把枸杞浆果混入我的酸奶里以增加营养。)\n- Les goji berry sont connus pour leurs bienfaits sur la santé. (枸杞浆果以其对健康的益处而闻名。)\n\n变形及其词义：\n- Goji Berry 的复数形式是 goji berries，表示多个枸杞浆果。\n- 例句：Elle achète des goji berries fraîches à la marché. (她在市场买了新鲜的枸杞浆果。)\n\n由于 \"Goji Berry\" 是外来词，直接从英语引入到法语中，它在法语中并没有复杂的变形系统，一般保持原形使用。其他相关变形或衍生词可能会根据具体语境创造，但这不是标准变形，而是根据需要而定。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1609, 108, ' Tamarillo ', ' 塔马里洛', '1. 词性：\nTamarillo 是名词。\n\n2. 词义：\nTamarillo 指的是一种小型的番茄类水果，也被称作“树番茄”或“金桔”。\n\n3. 例句：\n- J\'ai acheté des tamarillos pour notre déjeuner de weekend. (我买了些金桔作为我们周末早餐的水果。)\n- Les tamarillos sont excellents dans les salades avec des arugula et du fromage de chèvre. (金桔在搭配芝麻菜和山羊奶酪的沙拉中非常美味。)\n\n变形及其词义：\n- Tamarillo（复数形式）：指多个tamarillos。\n- Des tamarillos sont parfois utilisés comme garniture en desserts. (金桔有时会用作甜点的装饰。)\n\n注意：由于\"tamarillo\"是一个专有名词，指特定的水果，它没有其他变形或衍生词义。上述提到的“tamarillos”仅是其复数形式。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1610, 108, ' Durian ', ' 榴莲', '1. 词性：名词\n2. 词义：榴莲（一种热带水果）\n3. 例句：\n   - Le durian a une odeur très puissante. (榴莲有一种非常强烈的气味。)\n   - J\'ai essayé le durian pour la première fois, et j\'ai trouvé qu\'il a une saveur unique. (我第一次尝试了榴莲，发现它有独特的味道。)\n\n变形及其词义和例句：\n- Durien (形容词): 与榴莲相关的或类似榴莲的\n  - Les fruits duriens ont souvent une odeur forte. (榴莲类水果通常有强烈的气味。)\n- Durienne (名词，阴性形式): 指榴莲或与榴莲相关的事物\n  - La durienne a étonné les participants de la conférence. (榴莲让会议的参与者感到惊讶。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1611, 108, ' Elderberry ', ' 接骨木果', '1. 词性：\nElderberry 在法语中对应的单词是 \"sureau\"，它是一个名词。\n\n2. 词义：\nSureau 主要指的是接骨木果，这是一种植物的果实，通常用于制作果酱或药用。\n\n3. 例句：\n- Je vais cueillir des sureaux pour faire de la confiture. (我去摘一些接骨木果来做果酱。)\n- Les sureaux sont très abondants cette année. (今年接骨木果特别多。)\n\n变形及其词义和例句：\n- Sureaulx (复数形式): 指多个接骨木果。\n  - J\'ai trouvé un tas de suréaulx sous l\'arbre. (我在树下发现了许多接骨木果。)\n- Sureaulerie (名词): 指种植接骨木果的地方或者与接骨木果相关的活动。\n  - La sureaulerie est un passe-temps agréable pendant l\'été. (夏天里，采集接骨木果是一种愉快的消遣。)\n\n注意：法语单词的拼写和变形可能会根据地区和语境有所不同，上述信息基于标准法语。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1612, 108, ' Guava ', ' 番石榴', '1. 词性：名词\n2. 词义：番石榴，番石榴树；番石榴果\n3. 例句： J\'aime beaucoup manger de la goyave. (我非常喜欢吃番石榴。)\n          La goyave est un fruit très santé. (番石榴是一种非常健康的食物。)\n\n变形及其词义：\n- Goyavier（形容词）：与番石榴有关的\n  例句： Ce sont des agrumes goyaviers. (这些是与番石榴有关的柑橘类水果。)\n- Goyavelier（名词）：种植番石榴的人\n  例句： Le goyavelier a planté beaucoup de goyaves. (种植番石榴的人种了很多番石榴。)\n- Goyavelisation（名词）：指将其他事物与番石榴相关联或赋予其番石榴特性的过程\n  例句： La goyavelisation de la cuisine locale a enrichi le menu. (将当地菜肴与番石榴相结合丰富了菜单。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1613, 108, ' Litchi ', ' 荔枝', '1. 词性：\nLitchi 是名词。\n\n2. 词义：\n- litchi（荔枝）是一种热带水果，属于无患子科，外皮红色且粗糙，内部是透明且多汁的白色果肉。\n- 在植物学中，litchi 也指这种植物或其果实。\n\n3. 例句：\n- J\'ai acheté des litchis pour le dessert. (我买了一些荔枝做甜点。)\n- Les litchis sont très sucrés et exotiques. (荔枝非常甜而且有异国风味。)\n\n变形及其词义和例句：\n- Litchier（荔枝树）：指的是生长荔枝的树。\n  - Cette aire est plantée avec des litchiers. (这片土地种着荔枝树。)\n\n- Litchiers（复数形式，多个荔枝树）：\n  - Les litchiers sont en fleurs, cela promet une bonne récolte. (荔枝树开花了，预示着一个好收成。)\n\n由于 \"litchi\" 是一个名词，它没有动词形态或其他形容词变形。通常，名词的变形只涉及单复数变化，而 \"litchi\" 的复数形式仍为 \"litchis\"。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1614, 108, ' Loquat ', ' 枇杷', '1. 词性：\nLoquat 在法语中通常作为名词使用。\n\n2. 词义：\nLoquat 主要指“枇杷”，一种亚热带的水果，属于蔷薇科。\n\n3. 例句：\n- J\'ai mangé un loquat hier, c\'était très bon. (我昨天吃了一个枇杷，非常好吃。)\n- Les loquats sont en pleine saison maintenant. (现在是枇杷的旺季。)\n\n变形及其词义：\n- Loquats (复数形式)：指多个枇杷。\n  - J\'ai acheté des loquats à la marché. (我在市场买了些枇杷。)\n- Loquant (形容词)：形容与枇杷相关的特性或来自枇杷的。\n  - La saveur loquant de ce yaourt est incroyable. (这款酸奶的枇杷味真是太棒了。)\n  \n由于“loquat”是借用词，直接从其他语言（如英语）引入法语，它在法语中并没有复杂的变形体系。主要的变形就是其复数形式“loquats”。而“loquant”作为形容词使用的情况非常少见，更多的是直接使用“loquat”作名词。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1615, 108, ' Ugli Fruit ', ' 尤力果', '1. 词性：名词\n2. 词义：柚子，一种大型柑橘类水果，皮厚且多汁。\n3. 例句：\n   - J\'aime beaucoup le ugli fruit, son jus est très frais.\n   - Les agrumes, comme l\'ugli fruit, sont riches en vitamines.\n4. 变形及其词义：\n   - Uglier（较少使用）：指与柚子相关的事物或人。\n     例句：Il avait une pomme d\'uglier dans sa poche.\n   - Uglifruitier（较少使用）：种植或销售柚子的人。\n     例句：Le uglifruitier vend des fruits très frais.\n   - Uglifié（形容词，极少使用）：与柚子有关的或像柚子的。\n     例句：La salle était ornée de fleurs d\'uglifié.\n\n请注意，除了基本形式 \"ugli fruit\" 外，其它变形在现代法语中使用非常有限，可能不常见或仅在特定地区使用。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1616, 108, '', ' Cédrat ', '以法语中非常常用的单词 \"être\" 为例，我们来分析它的词性、词义、例句以及变形。\n\n### 1. 词性：\n动词 (verbe)\n\n### 2. 词义：\nêtre 是法语中的一个不规则动词，意为“是”、“存在”。它用于表达状态、身份、地点等。\n\n### 3. 例句：\n- Je suis content(e). (我很高兴。)\n- Il est docteur. (他是医生。)\n\n### 变形及其词义和例句：\n#### a. 现在时变形：\n- je suis（我是）\n  - Je suis étudiant. (我是学生。)\n- tu es（你是）\n  - Tu es là. (你在那里。)\n- il/elle/on est（他/她/我们是）\n  - Il est tard. (天晚了。)\n- nous sommes（我们是）\n  - Nous sommes prêts. (我们准备好了。)\n- vous êtes（你们是/您是）\n  - Vous êtes trop tard. (您太晚了。)\n- ils/elles sont（他们/她们是）\n  - Elles sont parties. (她们已经离开了。)\n\n#### b. 过去时变形（部分）：\n- je fus（我曾经是）\n  - Je fus médecin. (我曾经是医生。)\n- tu fus（你曾经是）\n  - Tu fus juste. (你是对的。)\n- il/elle/on fut（他/她/我们曾经是）\n  - Il fut le premier à arriver. (他是第一个到达的。)\n- nous fûmes（我们曾经是）\n  - Nous fûmes très contents. (我们曾经非常满意。)\n- vous futes（你们曾经是/您曾经是）\n  - Vous futes raisonnable. (您曾经是合理的。)\n- ils/elles furent（他们/她们曾经是）\n  - Elles furent incroyables. (她们曾经不可思议。)\n\n### 注意：\nêtre 的变形非常复杂，因为它是一个不规则动词，这里只列举了一部分常用时态的变形。其他时态（如未来时、条件时、虚拟式等）也有各自的变形和用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1617, 110, ' Semences ', ' 种子', '1. 词性：名词\n2. 词义：种子，籽粒；起因，起源\n3. 例句：\n   - Les semences de céréales sont utilisées pour produire du pain.\n     （谷物的种子被用来制作面包。）\n   - Cette idée a donné naissance à une nouvelle série de produits.\n     （这个想法催生了一个新的产品系列。）\n\n变形及其词义：\n- Semencier (名词)：播种者，种植者\n  - Le semencier a commencé à semer les graines dans le champ.\n    （播种者开始在田里播种。）\n- Semenceuse (名词)：播种机\n  - La semenceuse automatique a facilité la tâche des cultivateurs.\n    （自动播种机简化了农民的工作。）\n- Séminal, e (形容词)：种子的，播种的\n  - Les études séminales ont ouvert la voie à de nouvelles découvertes.\n    （开创性的研究为新的发现铺平了道路。）', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1746609928755.mp3');
INSERT INTO `word_list` VALUES (1618, 110, ' Forêt ', ' 森林', '1. 词性：名词\n2. 词义：森林，树林\n3. 例句：\n   - Il a perdu la tête dans la forêt. (他在森林里迷路了。)\n   - La forêt était si dense qu\'on ne pouvait pas voir le jour. (森林如此茂密以至于无法看到阳光。)\n\n变形及词义：\n- Forêt (基本形式，名词) - 如上所述，意为“森林”。\n- Forêt (复数形式，名词) - 意为“森林们”，指多片森林。\n  - Exemple : Les forêts de la région sont riches en espèces. (这个地区的森林物种丰富。)\n- Forêt (不变形) - 在法语中，名词通常不通过变形来表达不同的格或数，而是通过冠词和上下文来确定。\n- Forêtier, Forêtrie (形容词) - 与森林有关的，森林的。\n  - Exemple : Le paysage forêtrier est très attirant. (森林景观非常吸引人。)\n\n请注意，\"Forêt\" 作为名词，在法语中没有动词形式或其他复杂的变形。其用法主要围绕其作为名词的基本意义展开。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1619, 110, ' Chêne ', ' 橡树', '1. 词性：\nChêne 是一个名词。\n\n2. 词义：\n- 橡树（一种树）\n- 比喻意义下，可以指代一个家族、团体或组织的根基、核心成员或创始人。\n\n3. 例句：\n- Le chêne est un arbre très connu pour son robustesse et sa longévité.\n- Il voulait remonter jusqu\'à la source, retrouver le chêne en personne.\n\n变形及其词义与例句：\n- Chênes (复数)：多棵橡树\n  - Le parc est peuplé de chênes magnifiques.\n- Chêné (形容词)：与橡树相关的或具有橡树特征的\n  - Cette région est connue pour ses chemins chênés.\n- Chênement (副词)：坚固地，坚定地\n  - Il a chênement soutenu sa cause.\n- Chêner (动词)：用橡木制成，或比喻支持、加强\n  - Le bois de chêne a été chêné pour la fabrication du meuble.\n- Chêneux (形容词)：似橡树的，或指与橡树有关的\n  - Les arbres chêneux forment un appareil foliage dense.', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1620, 110, ' Fouquet ', ' 灌木丛', '1. 词性：Fouquet 是法语中的一个名词。\n\n2. 词义：Fouquet 主要指一个在历史上著名的法国财政官，尼古拉·富凯（Nicolas Fouquet），他在17世纪为法国国王路易十四服务。除此之外，Fouquet 也可以指代与此人相关的家族、地产或其它由他创立的事物。\n\n3. 例句：\n   - Nicolas Fouquet a été un grand financier français sous le règne de Louis XIV.\n     (尼古拉·富凯是路易十四统治时期一位伟大的法国财政家。)\n   - Le château de Vaux-le-Vicomte fut construit par Nicolas Fouquet.\n     (沃克斯-勒-维孔特城堡是由尼古拉·富凯建造的。)\n\n变形及词义：\n\n- Fouquier (没有普遍认可的变形，此词通常保持原形使用，不进行变形)\n\n由于 Fouquet 是专有名词，它通常不会像普通名词那样有复数形式或其他形态的变化。因此，在实际应用中，我们几乎总是看到它以原始形态出现。如果需要表示相关的概念，通常会通过添加形容词或其它描述性的词汇来达成。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1621, 110, ' Liane ', ' 藤蔓', '1. 词性：名词\n2. 词义：藤蔓植物；攀缘植物\n3. 例句：Le liane s\'est rampante sur le mur. (藤蔓在墙上蔓延。)\n\n1. 词性：形容词\n2. 词义：柔软的，柔弱的\n3. 例句：Elle a des mains fines et lianes. (她有双细长柔软的手。)\n\n变形及词义：\n- Lianesses (名词复数) - 多个藤蔓植物\n例句：Les lianesses ont envahi la forêt. (藤蔓植物已经占据了整片森林。)\n\n- Lianeur (男性名词) - 攀爬者或指某种特定的攀缘植物\n例句：Le lianeur a atteint le sommet de l\'arbre. (攀爬者到达了树顶。)\n\n- Liaenneuse (女性名词) - 同上，用于女性\n例句：La liaenneuse a repéré sa proie. (女攀爬者发现了她的猎物。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1622, 110, ' Insectes ', ' 昆虫', '1. 词性：\nInsectes 是名词，复数形式。\n\n2. 词义：\n- Insectes 指“昆虫”，是动物界的一个大类，通常具有三对腿和一对触角。\n\n3. 例句：\n- Il y avait des insectes autour de la lampe.（灯周围有一些昆虫。）\n- Les enfants ont appris beaucoup sur les insectes lors de leur séjour à l\'entomologie.（孩子们在昆虫学之旅中了解了很多关于昆虫的知识。）\n\n变形及其词义：\n- Insecte（单数形式）：指单个的昆虫。\n  - L\'insecte volait vers la fenêtre.（昆虫飞向窗户。）\n\n- Insectologie（学科名）：研究昆虫的科学。\n  - Elle étudie la biologie et plus particulièrement l\'insectologie.（她学习生物学，更具体地说是昆虫学。）\n\n- Insecticide（形容词或名词）：指杀死昆虫的物质；作为名词时，指杀虫剂。\n  - L\'usage excessif d\'insecticides peut endommager les réseaux trophiques.（过度使用杀虫剂可能会损害食物链。）\n\n- Insectivore（形容词或名词）：指以昆虫为食的动物；作为名词时，指食虫动物。\n  - Les oiseaux insectivores ont un rôle important dans la gestion de la faune des insectes.（食虫鸟类在管理昆虫群落方面起着重要作用。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1623, 110, ' Sapin ', ' 松树', '1. 词性：名词\n2. 词义：圣诞树；冷杉\n3. 例句：\n   - Nous allons chercher un sapin de Noël. (我们去买一棵圣诞树。)\n   - Le sapin est un arbre très populaire en France pendant les fêtes de Noël. (冷杉是法国圣诞节期间非常受欢迎的一种树。)\n\n变形及其词义：\n- Sapinier（名词）：冷杉树苗\n  - Exemple : Il plante des sapiniers dans son jardin. (他在花园里种了一些冷杉树苗。)\n- Sapine（名词，较少使用）：指冷杉的针叶或树脂\n  - Exemple : La sapine du sapin a une odeur agréable. (冷杉的树脂有一种宜人的香味。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1624, 110, ' Plantes ', ' 植物', '1. 词性：名词（féminin）\n2. 词义：植物，花草，作物\n3. 例句：\n   - J\'aime planter des plantes dans mon jardin. (我喜欢在我的花园里种植物。)\n   - Les plantes fournissent l\'oxygène nécessaire pour la respiration. (植物提供呼吸所需的氧气。)\n\n变形及其词义：\n- Plante (单数形式，表示一个植物)\n  - Exemple : Voici une plante que j\'ai trouvée dans le parc. (这是我在公园里找到的一株植物。)\n- Plantée (过去分词，用作形容词，表示被种植的)\n  - Exemple : La vigne plantée dans le jardin donne beaucoup de raisins. (在花园里种植的葡萄树产了很多葡萄。)\n- Plantant (现在分词，用作形容词或名词，表示种植者)\n  - Exemple : Le plantant de cette vigne a beaucoup travaillé. (这位葡萄园的种植者工作很努力。)\n- Plantation (名词，表示种植行为或种植区域)\n  - Exemple : La plantation de cette année a été couronnée de succès. (今年的种植非常成功。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1625, 110, ' Herbes ', ' 草本植物', '1. 词性：名词（nom féminin）\n2. 词义：草本植物，草药\n3. 例句：\n   - Je vais faire une infusion avec des herbes aromatiques. (我要用香草泡茶。)\n   - Il plante des herbes médicinales dans son jardin. (他在花园里种植草药。)\n\n变形及词义：\n- Herbe (阴性名词，单数形式)：草，植物\n  - Cette herbe croît rapidement. (这种草长得很快。)\n- Herbes (阴性名词，复数形式)：草，植物（复数）\n  - Les herbes sauvages couvrent le terrain abandonné. (野草覆盖了废弃的土地。)\n- Herbacée (阴性名词，形容词形式)：草本的，草本植物的\n  - Ce tissu est fait d\'une herbacée très douce. (这种布料是由非常柔软的草本制成的。)\n- Herbivore (阳性/阴性名词，形容词形式)：食草的\n  - Les herbivores sont souvent moins agressifs que les carnivores. (食草动物通常比食肉动物不那么具有攻击性。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1626, 110, ' Hétre ', ' 榛树', '1. 词性：名词\n2. 词义：橡树\n3. 例句：L\'hétre est un arbre très courrant en France.（橡树在法国是一种很常见的树。）\n\n变形及其词义：\n- hétaire（形容词）：橡树的，与橡树有关的\n  例句：Les chênes hétaires sont très grands.（橡树非常巨大。）\n- hétanophylle（形容词）：具有橡树叶形状的\n  例句：Les feuilles de l\'hétanophylle sont très caractéristiques.（橡树叶形状的叶子非常有特点。）\n- hétanoïde（形容词）：含有橡树成分的\n  例句：Le produit contient des extraits hétanoïdes.（该产品含有橡树提取物。）\n\n请注意，以上提供的变形和例句可能不完全准确，因为法语中关于“Hétre”这个词的变形并不常见，且可能需要根据具体语境来创造。在实际使用中，请根据具体情况进行查询和核实。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1627, 110, ' Bois ', ' 木头', '1. 词性：名词\n2. 词义：木头、木材\n3. 例句：Le bois était très dur, il a fallu beaucoup d\'efforts pour le tailler. (这木头非常硬，需要很大的力气来切割。)\n\n变形及其词义：\n- Bois (复数): 木材们\n  - 例句：Les bois sont des matières premières importantes en construction. (木材是建筑中重要的原材料。)\n\n- Boiser (动词): 用木料做\n  - 例句：Il a boisé la porte pour qu\'elle soit plus solide. (他用木料加固了门，使其更坚固。)\n\n- Boise (形容词): 多树木的\n  - 例句：Cette région est très boise, tu y verras beaucoup d\'arbres. (这个地区树木很多，你会看到很多树。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1628, 110, ' Erable ', ' 枫树', '1. 词性：\nErable 是一个名词。\n\n2. 词义：\n- 枫树，特别是糖枫树（Acer saccharum），一种北美洲的树种，其树液可以制糖。\n- 枫木，指由枫树木材制成的产品或物品。\n\n3. 例句：\n- L\'erable est une des sources traditionnelles de sucre au Canada. (枫树是加拿大传统糖源之一。)\n- Les meubles en bois d\'erable ont une beauté incomparable. (枫木家具拥有无与伦比的美。)\n\n变形及词义：\n- Erabler (动词): 从枫树中提取糖浆或糖。\n  - Exemple: Les producteurs locals erablent pour produire du sirop d\'érable. (当地生产者提取枫树汁以生产枫糖浆。)\n\n- Erablerie (名词): 枫树种植园或枫糖浆生产的场所。\n  - Exemple: Pendant le printemps, la ferme est transformée en une erablerie où on extrait le jus d\'érable. (春天时，农场变成枫糖浆生产地，人们在这里提取枫树汁。)\n\n- Erabler (名词): 从事枫糖浆生产的人。\n  - Exemple: Les erablers commencent le travail de récolte bien avant le jour. (制糖工人在天亮之前就开始了采集工作。)\n\n请注意，法语单词的具体用法和意义可能会根据地区和上下文有所不同。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1629, 110, ' Conifère ', ' 针叶树', '1. 词性：\nConifère 是名词。\n\n2. 词义：\n- Conifère 指的是松柏类植物，即针叶树，如松树、冷杉等。\n- 在更广泛的意义上，它也可以指代任何具有锥形果实的树木或灌木。\n\n3. 例句：\n- Le pin est un conifère très commun dans les forêts de notre région.\n  (松树是我们地区森林中很常见的一种针叶树。)\n- Le sapin est un conifère qui donne de l\'ombre et de la protection contre le vent.\n  (冷杉是一种提供荫凉和防风的针叶树。)\n\n变形及其词义，每个变形一个例句：\n\n- Coniferes (复数形式):\n  - Exemple: Les conifères sont importants pour la production de bois de haute qualité.\n  (针叶树对于生产高质量的木材很重要。)\n\n- Conifere (形容词):\n  - Exemple: Les forêts conifériennes sont riches en espèces.\n  (针叶林物种丰富。)\n\n由于 \"Conifère\" 是一个名词，它没有动词变形或其他类型的变形。以上列出的是名词的复数形式和形容词形式。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1630, 110, ' Feuillage ', ' 树叶', '1. 词性：\nFeuillage 是名词。\n\n2. 词义：\n- 植物的叶子部分，尤指树的叶丛。\n- 泛指任何植物的叶片集合。\n\n3. 例句：\n- Le feuillage des arbres est très dense dans cette forêt. (这片森林里的树叶非常茂密。)\n- Il y avait un parfum de feuillage après la pluie. (雨后有一种树叶的香气。)\n\n4. 变形及词义：\n- Feuilla(g)euse (形容词): 多叶的，叶子茂密的。\n  - Cette plante est très feuillagèuse. (这株植物叶子非常多。)\n- Feuille (名词): 单片叶子。\n  - La feuille tombe lentement de la branche. (叶子从树枝上缓缓落下。)\n- Feuiller (动词): 长出叶子，用叶子覆盖。\n  - Les arbres commencent à feuiller. (树木开始长出叶子。)\n\n注：法语单词 \"Feuillage\" 没有其他直接变形，因为它是一个不可数名词，通常不涉及时态或人称的变化。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1631, 110, ' Mushrooms ', ' 蘑菇', '1. 词性：\nLes champignons (名词)\n\n2. 词义：\n- 食用菌，蘑菇（食物）\n- 真菌（生物分类）\n\n3. 例句：\n- Je mange souvent des champignons de Paris. (我常吃巴黎蘑菇。)\n- Les champignons sont une variété de fungus. (蘑菇是一种真菌种类。)\n\n变形及其词义：\n- Championnier (名词) - 采蘑菇者\n  - Il est un passionné championnier, toujours en quête de nouveauté. (他是一名狂热的采蘑菇者，总是在寻找新奇的东西。)\n\n- Champignonner (动词) - 采蘑菇\n  - Elle aime champignonner dans les bois quand le temps est frais. (她喜欢在天气凉爽时去森林里采蘑菇。)\n\n- Champignonniste (名词/形容词) - 研究蘑菇的学者或对蘑菇有特别兴趣的人\n  - Cette étude a été menée par un champignonniste renommé. (这项研究是由一位著名的蘑菇学者主导的。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1632, 110, ' Arbre ', ' 树', '1. 词性：名词\n2. 词义：树；木；乔木。\n3. 例句：\n   - Il y a beaucoup d\'arbres dans le parc. (公园里有很多树。)\n   - L\'arbre de Noël est très beau cette année. (今年的圣诞树很漂亮。)\n\n变形及其词义和例句：\n- arbre (名词): 树；木；乔木。\n  - Il y a beaucoup d\'arbres dans le parc. (公园里有很多树。)\n- arbres (复数名词): 树；木；乔木。\n  - Les arbres sont en fleurs en été. (夏天时树都开花了。)\n- arboreal (形容词): 树木的；与树木有关的。\n  - Les oiseaux ont un comportement arboreal. (鸟类有树木相关的行为。)\n- arborescent (形容词): 似树的；树状的。\n  - Les plantes arborescentes peuvent croître à une grande hauteur. (树状植物可以长到很高的高度。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1633, 110, ' Fruit ', ' 果实', '1. 词性：\nLe mot \"fruit\" en français est un nom commun.\n\n2. 词义：\n- Fruit (nom masculin) : Produit de la fleur fertilisée d\'un arbre, d\'une plante ou d\'un buisson, que l\'on mange souvent.\n\n3. 例句：\n- Ces fruits sont très frais et riches en vitamines.\n- Je préfère les fruits secs pour le petit déjeuner.\n\n4. 变形及其词义：\n- Fruitier, fruitière (adjectif) : se dit d\'une personne qui cultive des fruits. Exemple : Cette dame est une véritable fruitière, tout ce qu\'elle plante pousse.\n- Fruiterie (nom féminin) : Magasin où l\'on vend du fruit. Exemple : J\'achète toujours mes fruits à la fruiterie autour de la coin.\n- Fruitier (nom masculin) : Personne qui possède une fruiterie. Exemple : Le fruitier de la rue du Château vendrait des fruits biologiques.\n\nChaque forme porte sur le domaine du fruit, mais chacune avec un sens légèrement différent.', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1634, 110, ' Oiseaux ', ' 鸟类', '1. 词性：\nOiseaux 是名词，复数形式。\n\n2. 词义：\nOiseaux 主要指鸟类。\n\n3. 例句：\n- Il y a beaucoup d\'oiseaux dans le jardin. (花园里有很多鸟。)\n- Les oiseaux migrent vers le sud en hiver. (鸟类冬天会迁徙到南方。)\n\n变形及其词义：\n- Oiseau, élégant animal ailé， qui vole dans les airs et vit essentiellement de ses rations de grains, de fruits et d\'insectes. (鸟，优雅的有翼动物，在空中飞翔，主要以谷物、水果和昆虫为食。)\n  - Example: L\'oiseau a volé sur la branche. (鸟儿飞到了树枝上。)\n\n- Oiseler, celui qui étudie les oiseaux et qui observe leur comportement. (鸟类学者，研究鸟类并观察其行为的人。)\n  - Example: Mon oncle est un oiseler passionné. (我的叔叔是一个狂热的鸟类学者。)\n\n- Oiselerie, endroit où l\'on élève des oiseaux, souvent pour les former à des exercices divers. (鸟类饲养场，人们在此饲养鸟类，通常是为了训练它们进行各种活动。)\n  - Example: Nous allons visiter une oiselerie de week-end. (我们周末将去参观一个鸟类饲养场。)\n\n- Oiselet, jeune oiseau, généralement non aile. (小鸟，通常指没有长出羽毛的年轻鸟。)\n  - Example: Le petit oiselet n\'a pas encore ouvert les yeux. (这只小小鸟还没有睁开眼睛。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1635, 110, ' Mammifères ', ' 哺乳动物', '1. 词性：\nMammifères 是名词，复数形式。\n\n2. 词义：\n- Mammifères 指的是哺乳动物这一类群，包括所有拥有乳腺，能够分泌乳汁喂养幼崽的脊椎动物。\n\n3. 例句：\n- Les mammifères sont des vertébrés qui nourrissent leurs petits avec du lait. (哺乳动物是用奶喂养幼崽的脊椎动物。)\n- Il y a plusieurs espèces de mammifères dans cette région, dont des lions et des éléphants. (这个地区有几种哺乳动物，包括狮子和大象。)\n\n变形及其词义：\n- Mammifère (单数)：指单个哺乳动物。\n  - Le mammifère en question est un chimpanzé. (所说的哺乳动物是一只黑猩猩。)\n\n- Mammifères (复数)：指多个哺乳动物。\n  - Les mammifères varient grandement en taille et en poids. (哺乳动物在大小和重量上有很大差异。)\n\n请注意，\"Mammifères\" 作为专有名词，通常只有单数和复数形式，没有其他复杂的变形。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1636, 110, ' Chêne verte ', ' 绿橡树', '1. 词性：\nChêne verte 是一个名词短语，由两个名词组成：“chêne”（橡树）和“verte”（绿色的）。\n\n2. 词义：\nChêne verte 指的是一种名为“绿橡树”的植物，通常是指幼小或年轻的橡树，其叶子呈绿色。\n\n3. 例句：\n- Le chêne verte croît souvent en zone tempérée.\n  - 绿橡树通常生长在温带地区。\n\n- Il a planté un chêne verte dans le jardin.\n  - 他在花园里种了一棵绿橡树。\n\n变形及其词义：\n- Chêne (名词): 橡树，指成熟的橡树。\n  - Le chêne est un arbre très long à vivre.\n    - 橡树是一种寿命很长的树。\n\n- Verte (形容词): 绿色的，形容颜色为绿色的事物。\n  - Elle porte une robe verte.\n    - 她穿着一条绿色的裙子。\n\n- Vert (名词): 绿色，也可以作为名词使用，表示颜色。\n  - Le vert est un des couleurs de la nature.\n    - 绿色是大自然的颜色之一。\n\n注意：在法语中，“verte”作为名词时通常指的是“绿色植物”，而形容词“verte”用于形容事物是绿色的。在“chêne verte”这个短语中，“verte”作为形容词修饰“chêne”。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1637, 111, ' バイオリン ', ' 小提琴', '1. 词性：名詞\n2. 词义：\n   - バイオリン（Violin）：小提琴\n3. 例句：\n   - 彼女はバイオリンをひきます。(她拉小提琴。)\n   - バイオリンの音色がとても美しい。(小提琴的音色非常美妙。)\n\n变形及其词义和例句：\n- バイオリスタ (Violinist): 小提琴手\n  - 彼は有名なバイオリスタです。(他是一位著名的小提琴手。)\n- バイオリンプレー (Violin player): 小提琴演奏者\n  - そのバイオリンプレーは若いですね。(那位小提琴演奏者很年轻呢。)\n- バイオリンコンサート (Violin concert): 小提琴音乐会\n  - 来週、バイオリンコンサートがあります。(下周有一个小提琴音乐会。)\n- バイオリンクラブ (Violin club): 小提琴俱乐部\n  - 私はバイオリンクラブに参加しています。(我参加了小提琴俱乐部。)', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1724205815738.mp3');
INSERT INTO `word_list` VALUES (1638, 111, ' 音楽 ', ' 音乐', '1. 词性：音楽（おんがく）是名词。\n2. 词义：音乐。\n3. 例句：\n   - 私の趣味は音楽です。 (わたしのしゅみはおんがくです。) - 我的兴趣是音乐。\n   - この CD には いろいろな 音楽が 收録されています。 (この CD には いろいろな おんがくが しゅうろくされています。) - 这张CD收录了各种各样的音乐。\n\n变形及词义：\n- 音楽的（おんがくて）：形容词，意为“音乐的”。例句：音楽的才能 (おんがくてのさいのう) - 音乐才能。\n- 音楽に（おんがくに）：表示方向或目的，意为“为了音乐”或“在音乐方面”。例句：彼は音楽に貢献 (かこん) しました。(かれはおんがくにこんけんしました。) - 他为音乐做出了贡献。\n\n注意：日语中名词通常不会像动词那样有复杂的变形系统，所以“音楽”这个词没有像动词那样的多种变形。上述提供的是与“音楽”相关的一些用法和搭配。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1639, 111, ' ハーモニー ', ' 和声', '1. 词性：名词（名詞）\n2. 词义：\n   - 和声、和声学\n   - 调和、协调\n3. 例句：\n   - ハーモニーは音楽の中で非常に重要です。 (和声在音乐中非常重要。)\n   - この曲のハーモニーはとても美しい。 (这首曲子的和声非常美丽。)\n\n变形及其词义：\n   - ハーモニカル (形容词)：和声的、和声学的\n     - ハーモニカルな音楽 (和声的音乐)\n   - ハーモニズム (名词)：和谐主义、和声主义\n     - 彼の作品にはハーモニズムが溢れている。 (他的作品中充满了和谐主义。)\n   - ハーモニファイア (名词)：和声狂、和声迷\n     - 彼は本当のハーモニファイアだ。 (他是一个真正的和声迷。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1640, 111, ' エレクトロニカ ', ' 电子音乐', '1.词性：名词\n2.词义：电子学，电子技术\n3.例句：\n  - 私は大学でエレクトロニカを専門として勉強しています。\n     - (我在大学里专攻电子学。)\n  - 現代の科学技術では、エレクトロニカが欠かせない分野です。\n     - (在现代科技中，电子学是一个不可或缺的领域。)\n\n变形及其词义：\n- エレクトロニカス（Electronics）： 作为英文借词，通常不变形，保持原样使用。\n- 例句：最近、エレクトロニカス産業は急激に発展しています。\n     - (最近，电子产业正在迅速发展。)\n\n由于“エレクトロニカ”是直接借用自英语的词汇，在日语中它通常不会像传统日语词汇那样有复杂的变形。其使用和词义主要保持与原英语词汇“electronics”相同，指代电子学或电子技术相关的内容。在日本语中，外来语往往直接以原形使用，而不经过变形。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1641, 111, ' リズム ', ' 节奏', '1. 词性：名词（名詞）\n2. 词义：\n   - 音楽の中で、一定の長さと強さを持つ拍子。\n   - 物事の進むスピードや調子。\n3. 例句：\n   - この曲はリズムがいい。\n   - 彼女は人生のリズムを自分で制御している。\n\n变形及其词义：\n- リズムになる（动词）：具有节奏，变成有节奏的状态。\n  - 彼は歌ってリズムになった。\n- リズム付ける（动词）：给...加上节奏。\n  - 作曲家は新しい曲にリズムを付けた。\n- リズム感（名词）：对节奏的感觉或感知。\n  - 舞者は素晴らしいリズム感を持っている。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1642, 111, ' 歌手 ', ' 歌手', '1. 词性：名词\n2. 词义：歌手、歌唱家\n3. 例句：\n   - この歌手は私の大好きだ。 (这个歌手是我最喜欢的。)\n   - 彼女は若い時から歌手になる夢を見ていた。 (她从年轻时就梦想成为歌手。)\n\n变形及其词义：\n- 歌手さん (歌手桑/Mr./Ms. Singer)：表示对歌手的尊称。\n  - 例句：歌手さんのライブが大好きです。 (我非常喜欢歌手桑的现场表演。)\n\n- 歌手たち (歌手们)：表示多个歌手。\n  - 例句：歌手たちが集まって音楽祭りを開催した。 (歌手们聚集起来举办了音乐节。)\n\n- 歌手になる (成为歌手)：表示动作或变化的过程。\n  - 例句：彼は小さい頃から歌手になるのが夢でした。 (他从小就梦想成为歌手。)\n\n- 歌手である (是歌手)：表示状态或身份。\n  - 例句：彼女は天才的歌手であると評価されています。 (她被评价为一个天才的歌手。)\n\n- 歌手だ (是歌手)：非正式的说法，用于口语中。\n  - 例句：兄は歌手だってよ。 (哥哥是歌手哦。)\n\n请注意，日语中没有直接的“变形”概念，上述提到的是通过添加不同的词缀或助词来表达相关的概念。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1643, 111, ' ドラム ', ' 鼓', '1.词性：名詞（名词）\n2.词义：鼓、鼓状物、滚筒\n3.例句：音楽の中ではドラムが重要な役割を果たしています。(在音乐中，鼓扮演着重要的角色。) / 彼はドラムを叩くことが大好きです。(他非常喜欢打鼓。)\n\n变形及其词义：\n- ドラムカー (Drummer)：鼓手\n  例文：あのバンドのドラムカーはとても有名です。(那个乐队的鼓手非常有名。)\n- ドラムロール (Drum roll)：鼓点滚奏\n  例文：演奏の最中にドラムロールが入りました。(演奏进行到一半时加入了鼓点滚奏。)\n\n以上为日语单词“ドラム”的基本信息和相关变形。由于“ドラム”本身作为一个名词，其变形相对有限，主要围绕与鼓相关的角色或动作。请注意，虽然提供了基本的意义和用法，但语言是活的，具体使用可能根据语境有所变化。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1644, 111, ' ポップス ', ' 流行音乐', '1. 词性：名词\n2. 词义：\n   - ポップス（Pops）：通常指流行音乐中的男歌手，特别是那些在青少年中有很高人气的男歌手。也可以指代一般的流行文化偶像或公众人物。\n3. 例句：\n   - 最近、若者たちの間で人気があるポップスは誰ですか？\n     (最近在年轻人中很受欢迎的Pops是谁呢？)\n   - 彼女は今、このポップスのコンサートに行くことを夢見ています。\n     (她现在梦想着去这个Pops的演唱会。)\n\n变形及其词义：\n- ポップスだった（Pops datta）：过去时态，表示过去是Pops的状态。\n  - 例句：彼は十年前にはポップスだったようです。\n    (据说他在十年前是个Pops。)\n\n- ポップスになる（Pops ni naru）：成为Pops。\n  - 例句：彼女の息子は高校を卒業して、ポップスになりました。\n    (她的儿子高中毕业后成为了Pops。)\n\n- ポップスらしい（Pops rashii）：看起来像是Pops的。\n  - 例句：あの若者はポップスらしいようですね。\n    (那个年轻人看起来像是个Pops呢。)\n\n- ポップスがいる（Pops ga iru）：有Pops存在。\n  - 例句：今、多くのポップスがいます。\n    (现在有很多Pops存在。)\n\n- ポップスに関心を持つ（Pops ni kanjo o motte）：对Pops感兴趣。\n  - 例句：彼女は新しいポップスに関心を持っています。\n    (她对新的Pops感兴趣。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1645, 111, ' ピアノ ', ' 钢琴', '1.词性：名詞\n2.词义：钢琴。是一种键盘乐器，通过按键来操作小锤敲击琴弦发音。\n3.例句：\n   - 私は小さい頃からピアノを習いました。(我从小就开始学习弹钢琴。)\n   - 彼女はピアノで「ハンデルのワルツ」を演奏しました。(她用钢琴演奏了《汉德尔的华尔兹》。)\n\n变形及词义：\n- ピアニスト(pianist): 钢琴家，弹奏钢琴的人。\n  - 例文： 世界中の有名なピアニストが集まっています。(世界著名的钢琴家们聚集在这里。)\n\n- ピアノアコーディオン(piano accompaniment): 钢琴伴奏，用钢琴为其他乐器或歌声提供音乐支持。\n  - 例文： この歌にはピアノアコーディオンが必要です。(这首歌需要钢琴伴奏。)\n\n- ピアノカウンター(piano counter): 钢琴计数器，一种用于记录钢琴按键次数的设备。\n  - 例文： この研究ではピアノカウンターを使用して、演奏者の指技を測定しました。(在这项研究中，我们使用了钢琴计数器来测量演奏者的指法技巧。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1646, 111, ' オーケストラ ', ' 管弦乐队', '1. 词性：名词\n2. 词义：管弦楽団。交響楽団。\n3. 例句：オーケストラの指揮者は、それぞれの演奏を指し示す。\n     （交响乐团的指挥者指导每个演奏。）\n    オーケストラが奏でる音楽は、人々に夢と感動を与える。\n     （交响乐团演奏的音乐给人们带来梦想和感动。）\n\n变形及其词义：\n- オーケストラ化（名词）：交響化。管弦楽化。\n  例句：この小さな会堂は、オーケストラ化された演奏会在開催することができます。\n     （这个小礼堂可以进行交响乐化的音乐会。）\n- オーケストラ的（形容词）：交響的。管弦楽的。\n  例句：オーケストラ的な音楽を作り出すためには、多くの工夫が必要です。\n     （为了创作交响乐音乐，需要很多努力。）\n- オーケストラ型（名词）：交響型。管弦楽型。\n  例句：この作品は、オーケストラ型の音楽である。\n     （这部作品是交响乐型的音乐。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1647, 111, ' ジャズ ', ' 爵士', '1. 词性：名詞\n2. 词义：ジャズは、音楽の一種であり、アフロアメリカン人の間で生まれたものです。それは、主に薩克斯風、トランペット、ドブロフォン、バス、ピアノ、ギターなどの楽器を使用して演奏されます。\n3. 例句：私はジャズが大好きです。每週末、友達と一緒にジャズクラブへ行きます。\n\n变形：\n1. ジャズを演奏する（動詞）：ジャズを演奏することを楽しみます。\n2. ジャズの（連体詞）：彼はジャズの歌手であり、世界中を旅行しています。\n3. ジャズ的（形容詞）：彼女はジャズ的な服を着ています。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1648, 111, ' ギター ', ' 吉他', '1. 词性：名词\n2. 词义：吉他（一种弹拨乐器）\n3. 例句：\n   - ギTAー를 彈くのが大好きです。 (我喜欢弹吉他。)\n   - 彼はギTAーが上手いです。 (他吉他弹得很好。)\n\n变形及其词义：\n- ギ타리スト (guitarist): 吉他手\n  - 彼女は有名なギ타리ストです。 (她是著名的吉他手。)\n- ギタープレイ (guitar play): 吉他演奏\n  - 今日はギタープレイを練習しましょう。 (今天我们来练习吉他演奏吧。)\n- ギターリスト (guitar list): 吉他列表\n  - これは私のギターリストです。 (这是我的吉他列表。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1649, 111, ' ダイナミックス ', ' 动态', '1. 词性：名词\n2. 词义：动力学，动态学；动力论\n3. 例句：\n   - 物理学の中で、ダイナミックスは重要な分野だ。\n     (在物理学中，动力学是一个重要的领域。)\n   - 最近の研究では、ダイナミックスが進歩している。\n     (最近的研究表明，动力学正在进步。)\n\n变形及其词义：\n- 动词：ダイナミックスする（使...具有动力）\n  - 例句：新しい技術を導入して、会社をダイナミックスさせたい。\n    (我想通过引入新技术，使公司更具动力。)\n- 形容词：ダイナミックス的（与动力学相关的）\n  - 例句：この論文はダイナミックス的な観点から書かれている。\n    (这篇论文是从动力学的观点写的。)\n- 副词：ダイナミックスに(动态地，有动力地)\n  - 例句：この機械はダイナミックスに動く。\n    (这台机器动态地运行。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1650, 111, ' クラシック ', ' 古典', '1. 词性：形容詞\n2. 词义：古典的，经典的，传统的\n3. 例句：\n   - この音楽はクラシックです。(这首音乐是古典的。)\n   - 彼はクラシックの芸術を研究しています。(他在研究古典艺术。)\n4. 变形及其词义：\n   - クラシカル(形容词): 古典的，经典的，传统的\n       例句：それはクラシカルな作品です。(那是一篇古典作品。)\n   - クラシックにする(动词): 使成为古典，使成为经典\n       例句：この映画はクラシックにされました。(这部电影被奉为经典。)\n   - クラシックだ(连体形): 是古典的，是经典的\n       例句：あれはクラシックだ小说です。(那是一本古典小说。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1651, 111, ' メロディ ', ' 旋律', '1. 词性：名詞\n2. 词义：\n   - メロディ（旋律）： 音楽の中で、主旋律となる歌や曲。また、歌や曲が美しく流れるようす。\n   - メロディ（調子）： 話し方や文章の調子。\n3. 例句：\n   - この曲のメロディは非常に美しい。\n   - 彼の話し方のメロディが変わった。\n\n变形及其词义：\n- メロディアル（形容詞）： 美しい旋律を持つ。例：メロディアルな曲。\n- メロディフル（形容詞）： 豊富な旋律を備えている。例：メロディフルな演奏。\n- メロディック（形容詞）： 音楽的な旋律を特徴としている。例：メロディックな作品。\n- メロディズム（名詞）： 特定の旋律型。例：新しいメロディズムを作り出す。\n\n以上是根据日语单词「メロディ」的基本词性和常用词义，以及其衍生词和相关例句的解释。希望这些信息对您有所帮助！', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1652, 111, ' 歌 ', ' 歌曲', '1. 詞性：名詞\n2. 詞義：歌（うた）の意味は主に次のようになります。\n   - 音楽的な旋律と言葉で構成された芸術作品。歌。\n   - 鳥が鳴く声。鳥唄。\n3. 例句：\n   - 「私は音楽を聞きながら、新しい歌を作りました。」\n   - 「朝、庭の小鳥の歌がきこえました。」\n\n变形：\n- 歌う（うたう）：動詞。唱歌。例：「彼女は美しい歌声で歌いました。」\n- 歌って（うたって）：て形。唱歌。例：「友達と一緒に歌って、楽しく遊んだ。」\n- 歌わない（うたわない）：未然形。不唱歌。例：「疲れているので、今晩は歌わない。」\n- 歌います（うたいます）：丁寧形。唱歌。例：「先生、この歌を歌いますか。」\n- 歌った（うたった）：た形。唱歌。例：「昨日、彼女は生日パーティーで歌った。」\n- 歌ろう（うたろう）：意向形。想要唱歌。例：「一緒に歌ろう！」\n- 歌ねば（うたねば）：仮定形。如果不唱歌。例：「歌ねば、彼は喜べません。」\n- 歌っている（うたっている）：進行形。正在唱歌。例：「今、部屋で誰かが歌っています。」\n- 歌ってあげます（うたってあげます）：謙讓語。为您唱歌。例：「お客様、今度は私が歌ってあげましょうか。」\n- 歌ってもらえますか（うたってもらえますか）：尊敬語。能为您唱歌吗？例：「先生、私が歌ってもらえますか？」', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1653, 111, ' ロック ', ' 摇滚', '1.词性：名词（名詞）\n2.词义：ロックの意味は主に次の通りです。\n   - ロック音楽：ロック・アンド・ロールの略で、西洋音楽の一派。\n   - ロック：建物や扉などの錠や鍵。\n3.例句：\n   - 最近ロック音楽が好きになった。\n   - 部屋のドアロックを外してください。\n4.变形とそれぞれの意味、例句：\n   - ロッキー（ロック＋いer）：ロック音楽を演奏する人。例：彼は有名なロッキーだ。\n   - ロックフェスティバル（ロック＋フェスティバル）：ロック音楽の祭り。例：ロックフェスティバルに行きたい。\n   - ロックバンド（ロック＋バンド）：ロック音楽を演奏するグループ。例：私の大好きなロックバンドが今週のコンサートに出演する。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1654, 111, ' コンサート ', ' 音乐会', '1. 词性：名词\n2. 词义：音乐会、演奏会\n3. 例句：\n   - 明日、私はコンサートに行く予定です。\n   - 最近、有名な歌手のコンサートが多いですね。\n\n4. 变形及其词义：\n   - コンサーティー（Concertier）：在管弦乐团中担任独奏或领奏的演奏者，如独奏小提琴手。\n     例句：彼は有名な交響楽団のコンサーティーだ。\n   - コンサーティナー（Concertiner）：参与音乐会的人，包括观众、演奏者等。\n     例句：今度のコンサートは多くのコンサーティナーが参加しました。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1655, 111, ' テンポ ', ' 速度', '1. 词性：名詞\n2. 词义：手帳、メモ帳、日記、予定表\n3. 例句：\n   - 私はテンポに予定を書きます。\n   - 彼女はテンポを使ってノートを取ります。\n\n变形及其词义：\n- テンポの複数形：テンポズ（手帳の複数）\n  - 例句：学生たちは全員テンポズを出してください。\n\n- テンポの形容詞：テンポな（手帳的、メモ帳的）\n  - 例句：彼はテンポな文具が好きです。\n\n- テンポの動詞：TENPO（手帳に入れる、メモ帳に書く）\n  - 例句：明日の会議の内容をTENPOしておく。\n\n- テンポの副詞：テンポに（手帳的に、メモ帳的に）\n  - 例句：テンポに予定を入力してください。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1656, 111, ' 演奏 ', ' 演奏', '1. 词性：动词（動詞）\n2. 词义：演奏、表演（音楽を演奏すること）\n3. 例句：\n   - 彼はピアノを演奏しました。 (Kare wa piano o ensoushimashita.) - 他演奏了钢琴。\n   - 交響楽団が新作を演奏しています。 (Kousougakudan ga shinsaku o ensoushite imasu.) - 交响乐团正在演奏新作品。\n\n变形及词义：\n- 演奏する (ensou suru): 演奏，基本形。\n   - 例句： 私は小さい時から鋼琴を演奏しています。 (Watashi wa chiisai toki kara piano o ensoushite imasu.) - 我从小就开始演奏钢琴。\n\n- 演奏した (ensou shita): 演奏，过去时。\n   - 例句： 昨日のコンサートでは多くの名曲を演奏しました。 (Kinou no konsaato de wa oku no meikyoku o ensoushimashita.) - 在昨天的音乐会中演奏了许多名曲。\n\n- 演奏して (ensou shite): 演奏，持续体或请求形式。\n   - 例句： 今、何を演奏していますか？ (Ima, nani o ensoushite imasu ka?) - 现在，你正在演奏什么？\n\n- 演奏す (ensou su): 演奏，命令形。\n   - 例句： 今度のリサイタルで、自分の得意な曲を演奏せよ。 (Kondo no risaitaru de, jibun no tokui na kyoku o ensoushioze.) - 在下次的独奏会上，演奏你最擅长的曲子吧。\n\n- 演奏せん (ensou sen): 演奏，可能形，表示能力或许可。\n   - 例句： あなたはどんな楽器を演奏できますか？ (Anata wa donna ongakuki o ensousemasu ka?) - 你能演奏什么样的乐器？\n\n请注意，日语中的动词变形非常多样，根据不同的语境和礼貌程度，还可能有其他变形方式，但以上列举的是一些基本和常见的形式。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1657, 111, 'ドラム', '架子鼓', '1. 词性：名词\n2. 词义：架子鼓，由多个鼓和铜钹组成的打击乐器。\n3. 例句：\n   - 私はドラムを弾きます。(我打鼓。)\n   - 彼のドラムが好きです。(我喜欢他的架子鼓。)\n\n其他变形及词义：\n- ドラムス (drums): 架子鼓的复数形式，指多套架子鼓或多个架子鼓部分。\n  - このバンドには四つのドラムスがあります。(这个乐队有四套架子鼓。)\n\n- ドラムマスター (drum master): 精通架子鼓的人，通常指技艺高超的架子鼓手。\n  - 彼は有名なドラムマスターです。(他是一位著名的架子鼓手。)\n\n- ドラムロー (drum roll): 连续快速的击鼓声，常用于音乐中制造紧张或激动的气氛。\n  - 映画のクリミカルシーズではいくつかのドラムローが使われています。(在电影的高潮场景中用到了几次鼓点。)\n\n由于“ドラム”是日语词汇，所有例句均以日语展示。', NULL, 0, '进阶/高级', NULL);
INSERT INTO `word_list` VALUES (1658, 112, ' 가슴', '衬衫', '1. 词性：名词\n2. 词义：心脏，心\n3. 例句：\n   - 나의 가슴이 많이 웃았어요. (我的心情很高兴。)\n   - 그는 가슴이 좋은 사람입니다. (他是个心地善良的人。)\n\n变形及词义：\n- 가슴에 (副词): 衷心地，真心地\n  - 가슴에 감사합니다. (衷心感谢。)\n\n- 가슴이 (形容词): 心脏的，心的\n  - 가슴이 순환이 좋아요. (心脏循环很好。)\n\n- 가슴을 (动词): 使心跳，心动\n  - 그 소리로 나의 가슴을 떨어졌어요. (那个声音让我心动了。)\n\n- 가슴으로 (副词): 用心地，真心实意地\n  - 가슴으로 한 일이야. (是真心实意做的事情。)', NULL, 1, NULL, 'src\\main\\resources\\MP3\\1724210356795.mp3');
INSERT INTO `word_list` VALUES (1659, 112, ' 팔칭', '袖扣', '1. 词性：\n- 팔칭 (八景) 是名词。\n\n2. 词义：\n- 主要指的是朝鲜时代学者们认为的朝鲜八道（即八个行政区）各自独特的风景名胜。每个道都有自己的“景”，合称为“八景”。\n- 在现代，有时也泛指任何地区或国家非常著名的八个景点或自然美景。\n\n3. 例句：\n- a. 한국의 팔칭에 대한 정보를 얻고 싶어요. (我想获取关于韩国八景的信息。)\n- b. 이 여행지는 우리 지역의 팔칭 중 하나입니다. (这个旅游景点是我们地区的八景之一。)\n\n变形及词义：\n- “팔칭”作为专有名词，通常没有变形。但在不同的语境中，可以有如下用法：\n- a. 팔칭 추천 (推荐八景)：指推荐值得一看的八个景点。\n- b. 팔칭 탐방 (八景探访)：指探访这八个著名景点的行为。\n\n例句：\n- a. 우리는 베스트 로드 탐방을 위해 팔칭 추천를 받아 갑니다. (我们为了最佳路线探访而收到八景推荐。)\n- b. 이번 여름 vacaion에는 팔칭 탐방을 계획하고 있습니다. (这个夏天假期我们计划进行八景探访。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1660, 112, ' 裤', '裤子', '1. 词性： \n裤（trousers）- 名词\n\n2. 词义： \n裤 - 下装的一种，通常有两个腿筒和一个腰围，用于覆盖腰部以下至脚部的区域。\n\n3. 例句： \n- 이 옷에는 베이지를 입고， 裤（裤子）를 입어요. (这件衣服要配腰带和裤子穿。)\n- 裤（裤子）가 너무 납작해요. (裤子太紧了。)\n\n变形及其词义：\n\n裤袜（leggings/pantyhose）- 裤与袜结合的服饰，通常由丝或尼龙制成，用于覆盖腿部至脚部。\n例句： 裤袜（leggings/pantyhose）씨는 여름에도 가능합니다. (裤袜在夏天也可以穿。)\n\n长裤（long trousers）- 裤长至脚踝或更长的裤子。\n例句： 그는 긴 裤（long trousers）를 좋아하지 않습니다. (他不喜欢长裤。)\n\n短裤（shorts）- 裤长至大腿或膝盖以上的裤子。\n例句： 여름에는 짧 裤（shorts）를 더 Often wear. (夏天我更常穿短裤。)\n\n运动裤（sweatpants/jogging pants）- 宽松舒适的裤型，通常用于运动或休闲时穿着。\n例句： 육当场裤（sweatpants/jogging pants）씨는 훌륭한 액티비티에 적합합니다. (运动裤适合进行积极活动。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1661, 112, ' 신발', '鞋', '1. 词性：\n신발（新發）是一个名词。\n\n2. 词义：\n- 新发，新生的毛发。\n- 新长出的植物或草。\n\n3. 例句：\n- 새끼가 나온 신발이 풀어지는 것을 보여요. (看到新长出的头发渐渐变多。)\n- 새로운 씨앗에서 신발이 나왔어요. (新种的草里长出了新芽。)\n\n变形及其词义：\n- 신발이： 新发的复数形式，表示多个新发。\n  - 예쁜 신발이가 얼마나 있어요？ (有多少新发？)\n\n- 신발을： 新发的宾格形式，用于动词之后。\n  - 그는 신발을 잘 볼 수 있어요. (他能很好地看到新发。)\n\n- 신발에： 新发的处所格形式，表示位置或方向。\n  - 신발에 액티브를 씌어 주세요. (请在新生发上涂抹激活剂。)\n\n- 신발으로： 新发的副词形式，表示方式或手段。\n  - 신발으로 살아야 합니다. (必须以新发的方式生活。)\n\n- 신발이라는： 新发的定语形式，用于修饰名词。\n  - 신발이라는 효과를 ost다. (具有新发的效果。)\n\n以上是关于“신발”（新发）的基本词性、常用词义和变形及其词义的概述。请注意，韩语中的变形通常涉及语法结构和语境的不同，因此提供的例句仅供参考。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1662, 112, ' 수건', '手套', '1. 词性：\n수건（修件）是一个名词，在韩语中通常指代修理或修复某个物件时所需的部件或配件。\n\n2. 词义：\n- 修理或修复时所需的部件、配件。\n- 泛指任何形式的补充材料或组件。\n\n3. 例句：\n- 이 컴퓨터를 수리하려면 어떤 수건이 필요해요？ (要修理这台电脑需要什么配件？)\n- 차량의 수건을 교환하는 데 가격이 너무 高かった. (更换车辆的配件费用太高了。)\n\n变形及其词义：\n- 수건에： 表示“对于配件”，用于表明针对的对象是配件。\n  - 수건에 관한 문제는 모두 해결되었어요. (所有关于配件的问题都已经解决了。)\n- 수건으로： 表示使用配件作为手段或方式。\n  - 이 기기를 복원하려면 새로운 수건으로 교환해야 합니다. (要恢复这个设备的功能，需要用新的配件来替换。)\n- 수건이： 表示拥有或涉及配件的状态。\n  - 저는 이 기기에 필요한 수건이 있어요. (我有这个设备需要的配件。)\n- 수건은： 用于强调配件或讨论与配件相关的内容。\n  - 수건은 이 기기의 성능에  direct impact을 미칠 수 없습니다. (配件对这台设备的性能有直接影响。)\n\n以上展示了“수건”一词的基本用法和变形，以及它们在句子中的应用。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1663, 112, ' 안ツ', '内衣', '1. 词性：\n안ツ（安子）是韩语中的汉字词，通常用作名词。\n\n2. 词义：\n在现代韩语中，“안ツ”不是一个常见词汇，因此没有特定的常用词义。然而，它可能是一个专有名词或用于特定情境下的名称。\n\n3. 例句：\n由于“안ツ”不是一个常用的韩语单词，所以很难提供标准的例句。如果它是某个人名、地名或其他专有名词的一部分，那么它的使用将完全取决于具体的上下文。\n\n关于变形及其词义：\n由于“안ツ”不是一个标准的韩语词汇，它没有变形。在韩语中，词汇的变形通常与动词、形容词等词类相关，涉及时态、语气、尊敬程度等方面的变化。然而，对于名词而言，尤其是不常见的名词，讨论变形没有实际意义。\n\n总结：\n“안ツ”作为一个不常见的韩语词汇，没有明确的常用词义和变形。如果它是一个专有名词或特定情境下的名称，其使用和理解将依赖于具体的上下文信息。在日常韩语交流中，这个词汇可能很少出现，或者根本不被使用。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1664, 112, ' 맥', '雨衣', '1. 词性：\n- 맥(Mak)是韩语中的名词。\n\n2. 词义：\n- 맥主要指的是“麦”，在农业或植物学领域使用，指一种谷物作物。\n- 另外，它也可以指代音乐领域的“麦克风”（Microphone），但这种情况较少见，通常使用外来词“마이크로폰”(Microphone)。\n\n3. 例句：\n- 맥田에 가면 맥이 많이 쌓인 것을 볼 수 있어요. (去麦田可以看到很多麦子堆成山。)\n- 우리 학교에는 맥의 실험场도 있어요. (我们学校也有麦子的实验田。)\n\n变形及其词义和例句：\n- 맥꾩(Mak-gang)：麦港、麦区。指专门种植麦子的地区或港口用于出口麦子。\n  - 맥꾩에서 맥을 수集하고 出荷한다. (在麦港收集麦子并装船运出。)\n\n- 맥병(Mak-byeong)：麦病。指麦子生长过程中可能出现的疾病。\n  - 맥병으로 맥이 죽은 것이 있었습니다. (有些麦子因为麦病而死亡了。)\n\n- 맥병지(Mak-byeong-ji)：麦病剂。指用来预防或治疗麦病的化学药剂。\n  - 맥병지를 사용하면 맥병을 예방할 수 있어요. (使用麦病剂可以预防麦病。)\n\n以上是基于“맥”这个词的基本含义和常见用法提供的例句。在韩国，人们更常直接使用外来词“마이크로폰”来指代麦克风。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1665, 112, ' 군지', '军装', '1. 词性：名词\n2. 词义：军队，武装力量；军旗\n3. 例句：\n   - 군지를 뛰어나오는 사람들은 모두 이루어 있었습니다. (走出军营的人们都非常整齐。)\n   - 군지의 기침에 따라 훈장을 끓낼 수 없었습니다. (按照规定，不能随意离开军营。)\n\n变形及其词义：\n- 군지하다（动词）：从军，参军\n  - 그는 20세에 군지하게 되었습니다. (他在20岁时参军了。)\n- 군지병（名词）：军旗\n  - 군지병이 날아지면 전쟁이 끝납니다. (军旗倒下意味着战争结束。)\n- 군지원（名词）：军人，士兵\n  - 군지원들이 훈장을 떠나셨다. (士兵们已经离开了军营。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1666, 112, ' 가죽', '帽子', '1. 词性：名词\n2. 词义：骨架，框架，骨骼\n3. 例句：\n- 이 애완기는 가죽이 좋은 것을 보여주고 있습니다. (这个机器人展示了一个很好的骨架。)\n- 그 사람의 가죽이 희소한 것으로 모두를 놀라웠습니다. (那个人的骨架很细小，让大家都笑了起来。)\n\n变形及其词义和例句：\n- 가죽이(骨架的形容词): 这个形容词用于描述与骨架相关的特性或状态。\n  - 그 애완기의 가죽이가 큰 것을 볼 수 있어요. (你可以看到那个机器人有一个大骨架。)\n- 가죽에(在骨架上): 这个副词用于描述某物位于骨架上的情况。\n  - 그 사람의 가죽에 귀멸荜이 많이 붙어 있었다. (那个人的骨架上有很多肌肉附着。)\n- 가죽으로(用骨架): 这个副词用于描述使用骨架作为工具或方法的情况。\n  - 그 예술작품은 가죽으로 만들어졌다. (那个艺术品是用骨架制作的。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1667, 112, ' 염기', '袜子', '1. 词性：\n- 염기是一个名词。\n\n2. 词义：\n- 主要词义为“药水”或“药剂”，指用于医疗或化学实验等目的的液体混合物。\n- 另一个常用词义是“酒精”。\n\n3. 例句：\n- 이 약품은 염기를 사용하여 제조되었습니다. (这种药物是用药剂制造的。)\n- 염기가 너무 많으면 건강에 부적절합니다. (酒精摄入过多对健康不利。)\n\n4. 变形及词义：\n- 염： 通常作为其他词汇的组成部分，如“염色（颜色）”，但单独使用较少，无具体词义。\n  - 예시： 그 염은 아름다워요. (那颜色很漂亮。)\n- 기： 表示“基础”或“基”，常用于构成复合词。\n  - 예시： 학습의 기초는 실천입니다. (学习的基础是实践。)\n\n请注意，\"염기\"本身并没有变形，提供的“염”和“기”是作为单独汉字可能的意义，并非直接由\"염기\"变形而来。在韩语中，单词的结构与汉语不同，不能简单地将一个词拆分成单个汉字来理解其意义或变形。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1668, 112, ' 긴소', '裙子', '1. 词性：\n긴소（紧小）是一个形容词，用于描述某物或情况的紧迫、紧凑或者小巧。\n\n2. 词义：\n- 紧迫的、紧张的\n- 狭小的、狭窄的\n- 紧凑的、密集的\n\n3. 例句：\n- 이 옷은 긴소해요. (这件衣服很紧。)\n- 숙박에는 긴소한 룸만 있었어요. (旅馆里只有小房间。)\n\n变形及其词义和例句：\n- 긴소하다（形容词原型）：表示某事物是紧迫的、狭窄的或紧凑的。\n  - 예쁜 친구들과 함께 살기 때문에 집이 조금 긴소해요. (因为和朋友们一起住，所以房子有点小。)\n\n- 긴소한（形容词+한，表示过去或完成的状态）：表示某事物曾经是或已经变得紧迫、狭窄或紧凑。\n  - 그 책상이 긴소한 것 같아요. (那个书架看起来曾经很小。)\n\n- 긴소하게（形容词+하게，表示方式或状态）：表示以紧迫、狭窄或紧凑的方式。\n  - 약속을 긴소하게 맞추고 싶습니다. (我想紧凑地安排约会。)\n\n- 긴소하여（形容词+하여，表示原因或理由）：表示因为紧迫、狭窄或紧凑的原因。\n  - 긴소하여 친구들과 함께 살아야 할 수 있어요. (因为地方小，所以我得和朋友一起住。)\n\n- 긴소지（形容词+지，表示程度或范围）：表示达到紧迫、狭窄或紧凑的程度。\n  - 창고가 긴소지 않아요. (仓库并不那么小。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1669, 112, ' 맨토', '毛衣', '1. 词性：\n- 맨토(manto)：名词\n\n2. 词义：\n- 맨토(manto)主要指一种覆盖物，通常用于户外活动如野餐、露营时作为坐垫或睡垫。它是由防水材料制成，轻便易携带。\n\n3. 例句：\n- 나는 캠핑에 가면 맨토를 갔다 싸우요. (我每次去露营都会带上manto。)\n- 여름에 해야 잭엄에 맨토를 놓고 잭엄을 enjoy하세요. (夏天的时候，你可以在沙滩上铺开manto享受沙滩时光。)\n\n变形及词义：\n- 目前没有广为人知的变形形式。在韩语中，物品名称如“맨토”通常不具有变形，它们保持原形不变。\n\n每个变形一个例句（由于没有变形，此部分省略）。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1670, 112, ' 장바구니', '围巾', '1. 词性：\n- 장바구니（章鱼）是名词。\n\n2. 词义：\n- 장바구니（章鱼）主要指海洋中的一种头足类动物，具有八条腕，常用于食用。\n\n3. 例句：\n- 1) 나는 앞둔 주말에 해수원에서 장바구니를 먹었다. (我在上周末去海边吃了章鱼。)\n- 2) 장바구니 튀김은 한국의 전망 요리입니다. (章鱼汤是韩国的传统料理。)\n\n变形及其词义与例句：\n- 장바구니(章鱼)的变形不常见，因为它是一个名词，但可以通过与其他词汇结合形成复合词或短语来表达不同的概念。例如：\n    - 장바구니 튀김 (章鱼汤)：以章鱼为主要食材的汤类料理。\n      - 예쁜 장바구니 튀김을 만들기 위해서는 신선한 장바구니와 좋은 大酱가 필요합니다. (为了制作美味的章鱼汤，需要新鲜的章鱼和优质的大酱。)\n    - 장바구니 고기 (章鱼烤肉)：将章鱼切成小块并用调料腌制后烤制的美食。\n      - 여름날에는 친탈하게 살gui는 장바구니 고기를 맛보는 것이 좋습니다. (夏天吃辣味十足的章鱼烤肉是个不错的选择。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1671, 112, ' 멀티캐슬', '运动服', '1. 词性：\n- 멀티캐슬： 名词\n\n2. 词义：\n- 멀티캐슬： 多种才能的，多才多艺的；多功能的\n\n3. 例句：\n- 이 사람은 멀티캐슬한 인재입니다. (这个人是个多才多艺的人才。)\n- 그는 멀티캐슬한 능력을 갖추고 있습니다. (他拥有多功能的能力。)\n\n变形及其词义：\n- 멀티캐슬하다： 变得多才多艺或多功能\n  - 그는 멀티캐슬하게 되었습니다. (他变得更多才多艺了。)\n\n- 멀티캐슬한： 形容词，描述某人或某物具有多种才能或功能\n  - 그는 멀티캐슬한 사람입니다. (他是个多才多艺的人。)\n\n- 멀티캐슬으로： 副词，以多才多艺或多功能的方式\n  - 그는 멀티캐슬으로 일을 처리합니다. (他以多功能的方式处理事情。)\n\n请注意，韩语中的单词通常不会像英语那样有复杂的变形，而是通过添加不同的词尾来表达不同的语法关系。以上提供的变形和例句是基于常见的用法，实际上可能不会有直接的变形形式。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1672, 112, ' 베리', '背心', '1. 词性：\n- 베리（berry）是名词。\n\n2. 词义：\n- 主要指小的、浆果类的水果，如草莓、蓝莓等。\n- 在韩国，这个词也常用来指代一种类似果汁吧的地方，提供各种浆果类饮品和甜点。\n\n3. 例句：\n- 나는 베리를 좋아합니다. (我喜欢浆果。)\n- 저는 가장 좋은 베리에 가졌습니다. (我去了最好的浆果店。)\n\n变形及词义：\n- 베리가： 表示“如果是浆果的话”或“关于浆果”，用于假设语气。\n  - 예： 베리가 있으면 좋아요. (如果有浆果的话，我就喜欢。)\n\n- 베리꾼： 表示“浆果爱好者”或“常去浆果店的人”。\n  - 예： 그는 정말 베리꾼입니다. (他真是个浆果爱好者。)\n\n- 베리色： 表示“浆果色”，即浆果的颜色，通常指红色、紫色等。\n  - 예： 이 옷의 색상은 베리색입니다. (这件衣服的颜色是浆果色。)\n\n注意：韩语中单词的变形不像英语那样通过加前缀或后缀来改变词义，而是通过与其他词语结合或改变语境来表达不同的意思。上述变形并非严格意义上的语法变形，而是根据语境和搭配的不同展现的不同用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1673, 112, ' 옷', '衣服', '1. 词性：\n- **名詞** (Noun)\n\n2. 词义：\n- **의빈(의빈)**: 衣服，服装。\n\n3. 例句：\n- **이 옷이 나는 것이라요.** 这件衣服是我的。\n- **어느 옷을 입고 갈까요？** 你打算穿什么衣服去？\n\n4. 变形及其词义和例句：\n- **變形不存在于韩语中对于“옷”这一单词的直接变形，因为它是一个名词。**\n\n在韩语中，名词通常不通过变形来表达不同的语法功能或意义，而是通过助词、语序、上下文等手段来实现。因此，对于“옷”（衣服）这个词而言，它本身没有变形形式。不过，可以通过与其他词汇的组合来扩展其含义或使用范围。例如：\n\n- **옷 着替える** (着替える): 换衣服（动词短语，表示更换衣服的动作）\n  - **예쁘게 着替え서 가세요.** 请换上漂亮衣服再去。\n\n由于“옷”是一个名词，所以它没有变形。在韩语中，名词通常保持原样，并通过其他语法结构来表达不同的意思或关系。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1674, 112, ' 팬이스', '脸巾', '1. 词性：\n- 팬이스 (fanisu) 是名词（Noun）。\n\n2. 词义：\n- 在韩语中，\"팬이스\" 通常指“粉丝”，尤其是指明星或名人的追随者、支持者。\n\n3. 例句：\n- 나는 그 가수의 팬이스입니다. (我那个歌手的粉丝。)\n- 팬이스들은 공연에 많이 참여했어요. (粉丝们积极参与了演出。)\n\n变形及其词义：\n- 在韩语中，\"팬이스\" 本身作为一个外来词（从英文 \"fans\" 演变而来），并没有像动词那样的多种变形。它主要是以名词形式存在，可以有复数形式 \"팬이스들\" (fanisudeul) 表示多个粉丝。\n\n- 单数形式：팬이스 (fanisu)\n  - 나는 그 가수의 팬이스입니다. (我是那位歌手的粉丝。)\n\n- 复数形式：팬이스들 (fanisudeul)\n  - 그 가수에 대한 팬이스들은 많습니다. (那位歌手有很多粉丝。)\n\n请注意，由于 \"팬이스\" 是一个名词，所以它的“变形”主要涉及数量的变化而不是动词那样的时态或语气变化。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1675, 112, ' 가방', '包', '1. 사전：\n2. 의존： 가방은 상자나 묶음에서 물건을 담는 공간입니다.\n3. 예제： 저는 가방에 책을 넣었습니다.\n\n변형 그리고 의존：\n- 가밥 (가방이): 가방이라는 사람을 의존하는 것입니다.\n  - 예제： 가밥가 책을 가지고 있어요.\n- 가봉 (가방에): 가방에 물건을 넣는 것을 의존합니다.\n  - 예제： 가봉에 책이 두 권 있어요.\n- 가벼 (가방으로): 가방을 통한 행위를 의존합니다.\n  - 예제： 가벼로 책을 빼내요.\n- 가병 (가방에서): 가방에서 물건을 꺼내는 것을 의존합니다.\n  - 예제： 가병에서 책을 꺼내요.', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1676, 112, ' 모자', '帽子', '1. 词性：\n모자 - 名词 (Noun)\n\n2. 词义：\n모자 - 帽子 (Hat)\n\n3. 例句：\n- 나는 겨울에는 큰 모자를 착용합니다. (我冬天会戴一个大帽子。)\n- 그는 모자를 얼마나 착용하는지 이렇게 잘 보이지 않습니다. (他戴的帽子遮住了大半张脸，看不清楚。)\n\n变形及词义：\n- 모자로： 作为帽子 (As a hat)\n  - 이 옷은 모자로 사용할 수도 있습니다. (这件衣服也可以当作帽子来使用。)\n\n- 모자가： 有帽子 (Has a hat)\n  - 그는 앞으로 모자가 있었지만， 지금은 없어 보인다. (他之前有帽子，但现在好像没有了。)\n\n- 모자를： 戴帽子 (Wear a hat)\n  - 여름에서는 모자를 착용하지 않습니다. (夏天我不戴帽子。)\n\n- 모자한： 像帽子一样的 (Like a hat)\n  - 그 것은 모자한 모양을 낗어났다. (那个东西呈现出像帽子一样的形状。)\n\n请注意，韩语中的名词通常不会像动词那样有多种变形，所以“모자”这个名词的变形主要是通过添加不同的后缀来表达不同的语法功能，而不是改变词根本身。上述例子展示了如何通过添加不同的助词或结构来表达与“帽子”相关的不同含义。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1677, 112, ' 악세서리', '领带', '1. 词性：\n- 악세서리： 名词\n\n2. 词义：\n- 主要指“副作用”，在医学上用来描述药物或治疗方法可能引起的非预期的、通常是不利的反应。此外，它有时也可以用来泛指任何事物或情况的负面影响或后果。\n\n3. 例句：\n- 이 악세서리는 허리에도 영향을 미칠 수 있습니다. (这种药的副作用可能会影响腿部。)\n- 새로운 의료법에 따른 악세서리를 予防하기 위해 그들은 많은 努力을 보낼 것입니다. (为了预防新法律带来的副作用，他们将不得不付出很多努力。)\n\n变形及其词义和例句：\n- 악세： 名词，意为“效果”或“作用”，通常用于正面效果。\n  - 예악세： 积极的效果或影响。\n    - 예악세를 최대화하기 위해서 그들은 많은 시간을 ivested 했습니다. (为了最大化积极效果，他们投入了大量时间。)\n\n- 서리： 名词，通常指“序列”或“系列”。\n  - 책서리： 一系列的书。\n    - 이 책장에는 한 책서리가 정돈되어 있습니다. (这个书架上整齐地排列着一系列的书。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1678, 112, ' 긴급', '长靴', '1.词性：\n- 긴급（紧急）是名词。\n\n2.词义：\n- 主要词义为“紧急情况”或“急迫需要”。\n\n3.例句：\n- 이 사건은 긴급한 것으로 처리해야 합니다. (这个案件需要紧急处理。)\n- 긴급 택시에 따라 직원들은 모두 출勤하였습니다. (根据紧急通知，所有员工都已出勤。)\n\n变形及其词义和例句：\n- 没有直接的变形，但可以与其他词语结合形成复合词或短语，表示相关紧急的概念。例如：\n  - 긴급 지원 (紧急支援)：迅速提供帮助或资源以应对紧急情况。\n    - 긴급 지원을 받아 화재를 끄쳤습니다. (接受紧急支援后，火被扑灭了。)\n  \n以上信息提供了关于韩语单词“긴급”的基本词性、常用词义以及使用该词的例句。同时，也解释了与紧急相关的复合词的使用，进一步丰富了对“긴급”这一词汇的理解和应用。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1679, 112, ' 망토', '围巾', '1. 词性：名词\n2. 词义：墙壁，墙面\n3. 例句：\n   - 이 망토는 너무 빠르다. (这个墙壁太薄了。)\n   - 망토에 사진을 釘았어요. (在墙上钉了照片。)\n\n变形及其词义和例句：\n- 망토로 (作为后缀，表示方向或位置): 在墙上\n   - 책상을 망토로 挂了电话。)\n- 망토에 (表示在墙上的动作或状态): 在墙上\n   - 새롭게 뽑은 친판을 망토에 꾸릴 것이라고 생각합니다. (我想把新买的画挂在墙上。)\n- 망토에서 (表示从墙上开始的动作): 从墙上\n   - 망토에서 잔다리를 내놨습니다. (我从墙上拿下了架子。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1680, 112, ' 셔츠', '帽子', '无法从大模型获取数据，请联系管理员！', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1681, 112, ' 낮케', '凉鞋', '1.词性： \n- 낮케(名詞)\n\n2.词义： \n- 낮케의 주요 의미는 \"새벽\"이며， 일반적으로 특정 시간을 나타낼 때 사용됩니다. 또한， 어떤 행동이나 이벤트가 새벽에서 발생하는 것을 의미할 수도 있습니다.\n\n3.例句： \n- ① 새벽에 귀여워하면 낮케에 귀여워하세요. (如果你喜欢早起，那就早上来吧。)\n- ② 낮케부터 야간까지 일을 합니다. (我从早上工作到晚上。)\n\n變形及其词义：\n- 낮(名词): 일반적으로 \"새벽\"을 의미합니다.\n   - 예： 낮부터 밤까지 즐기세요. (从早上玩到晚上吧。)\n\n- 케(动词): 일반적으로 \"가리키다\" 또는 \"지楠하다\"를 의미합니다.\n   - 예： 그 쪽으로 가리세요. (请朝那走。)\n\n注意：以上内容仅为示例，实际使用中可能需要根据语境进行调整。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1682, 112, ' 롱캣', '连帽衫', '1. 词性：\n- 롱캣（Noun）\n\n2. 词义：\n- 롱캣主要指的是一种传统的韩式糖果，由麦芽糖制成，通常呈棒状或块状，颜色为白色或淡黄色。它是韩国传统市场中常见的小吃之一，具有粘稠和略带甜味的特点。\n\n3. 例句：\n- 어린 시대에는 롱캣을 많이 먹었다.（小时候我经常吃롱캣。）\n- 롱캣은 한국의 전통 가맹으로， 사람들에게 맛있고 즐길 수 있습니다.（롱캣是韩国的传统糖果，对人们来说既美味又有趣。）\n\n变形及其词义：\n- 롱캣하다（动词）：制作롱캣的动作。\n  - 예： 엄마는 새로운 방법으로 롱캣을 만들어 드리고 있어요.（妈妈正在尝试用新方法制作롱캣。）\n\n目前没有其他常见的变形形式。在现代韩语中，“롱캣”作为一个名词使用最为广泛，而关于它的制作过程或其他形态的词汇不是很常见。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1683, 112, ' 스weater', '毛衣', '1. 词性：\n- 스웨터(sweater) - 명사 (名词)\n\n2. 词义：\n- 스웨터(sweater) - 羊毛가락， 핸드질 등을 사용하여 짤리는 상의 종류. \n- 英： Sweater - A type of garment for the upper body, typically made of wool or a similar material.\n\n3. 例句：\n- 이 겨울에는 스웨터를 입고 나出해야 합니다. (这个冬天，我需要穿上毛衣才能出门。)\n- 그는 새로운 스웨터를 쇼핑에서 구매했습니다. (他刚在商场买了一件新毛衣。)\n\n变形及其词义和例句：\n- 스웨터를 착다 (穿着毛衣) - 英： To wear a sweater\n  - 예： 오늘은 커서요， 스웨터를 착아야 합니다. (今天很冷，我得穿上毛衣。)\n- 스웨터를 입다 (穿毛衣) - 英： To put on a sweater\n  - 예： 어느 시즌も 좋아요， 우리는 계절에 따라 스웨터를 입어야 합니다. (无论哪个季节，我们都需要根据季节穿上毛衣。)\n- 스웨터를 두다 (脱掉毛衣) - 英： To take off a sweater\n  - 예： 집에 들어가면 바로 스웨터를 떼어야 합니다. (一回到家，我就得立即脱掉毛衣。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1684, 112, ' 담백', '夹克', '1. 词性：动词\n2. 词义：捡起，拾起；恢复，复原\n3. 例句：\n   - 담백하다 - 他捡起了地上的钱包。\n   - 탈암을 담백하다 - 恢复自信。\n\n变形及其词义：\n- 담백하다（原型）： 捡起，拾起；恢复，复原\n  - 그는 지하에 놓쳤서 담백하고 나왔다 - 他因掉到地下室而恢复过来。\n- 담백한다（过去式）： 已经捡起，已经恢复\n  - 그는 귀여운 사람을 담백한다 - 他已经恢复了健康。\n- 담백해（命令形）： 请捡起，请恢复\n  - 지龔 놓친 것들을 담백해 - 请捡起地上的东西。\n- 담백할（将来式）： 将要捡起，将要恢复\n  - 나는 이제 담백할 - 我将要恢复。\n- 담백며（进行时）： 正在捡起，正在恢复\n  - 그는 지하로 떨어졌다 담백며 - 他正在从地下室恢复过来。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1685, 112, ' 헤드밴드', '头巾', '1. 词性：名詞\n2. 词义：\n   - （体育竞技）头部触地得分\n   - （音乐）敲打，敲击\n3. 例句：\n   - 축구 match에서 헤드밴드를 낸다. (在足球比赛中头球得分。)\n   - 그는 가수의 노래를 들어， 심장이 헤드밴드할 것 같다. (他听着那首歌，心脏仿佛在跳动。)\n\n變形及其词义和例句：\n- 헤드하다 (动词)：用头撞或碰\n  - 축구 ball을 헤드하다. (用头顶足球。)\n\n- 헤드밴드 shot (名词)：头球射门\n  - 축구 match에서 헤드밴드 shot을 시깨ダ다. (在足球比赛中尝试头球射门。)\n\n- 헤드밴드ing (动名词)：正在进行头球动作\n  - 선수가 헤드밴드ing 중이다. (球员正在进行头球动作。)\n\n韩语单词“헤드밴드”主要作为名词使用，指在体育尤其是足球中的头球得分，或在音乐中形容强烈的节奏感。其变形包括动词形式“헤드하다”，指进行头球动作；名词形式“헤드밴드 shot”特指足球中的头球射门；以及动名词形式“헤드밴드ing”，描述正在进行的头球动作。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1686, 112, ' 굽의', '领带', '1. 词性：\n굽의 是名词。\n\n2. 词义：\n- 表示“骨头”的复数形式，即“骨头们”。\n- 用于比喻时，可以表示某事物的核心或基本部分。\n\n3. 例句：\n- 이 앞에는 많은 굽들이 있었다.（那里以前有很多骨头。）\n- 그 사건의 굽의는 아직 알 수 없어.（那案件的核心还不清楚。）\n\n变形及其词义：\n- 굽： 单数形式的“骨头”，也可以指核心或基本部分。\n  - 예제： 한 굽을 꺼내세요.（请拿出一根骨头。）\n\n目前没有发现其他的变形形式。在韩语中，名词通常通过添加特定的后缀来形成复数，而“굽”这个词比较特殊，其复数形式是通过添加“의”（的复数标记）来实现的，形成了“굽의”。其他常见的变形可能涉及不同的意思或者不同的用法，但对于“굽”来说，最常见的还是其基本形式和复数形式“굽의”。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1687, 112, ' 가로수슬', '高帮鞋', '1. 词性：\n가로수슬(가로수슬)是一个名词。\n\n2. 词义：\n- 가로수슬： 指一种用于装饰、点缀或美化的小型物品，通常具有观赏价值。\n- 가로수슬： 也可以用来指代一些小巧精致的工艺品或艺术品。\n\n3. 例句：\n- 이 가로수슬은 어떻게 볼 수 있어요？ (这个工艺品看起来怎么样？)\n- 그 가로수슬이 너무 예쁘어， 구입을 고려해요. (那个工艺品太漂亮了，我考虑买下来。)\n\n4. 变形及其词义和例句：\n- 가로수슬들： 表示多个工艺品，复数形式。\n  - 가로수슬들을 모두 보여주세요. (请把所有的工艺品都展示给我看。)\n\n- 가로수슬에： 表示属于工艺品的一部分或与工艺品有关的事物。\n  - 가로수슬에 대한 정보를 알려주세요. (请告诉我关于工艺品的信息。)\n\n- 가로수슬이： 表示工艺品本身所具有的特点或属性。\n  - 가로수슬이 깔끔하다. (工艺品很精致。)\n\n- 가로수슬으로： 表示使用工艺品作为工具或手段。\n  - 가로수슬으로 装飾을 합니다. (用工艺品来装饰。)\n\n请注意，以上提供的例句仅为示例，实际使用时可能需要根据具体语境进行调整。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1688, 112, ' 맨T恤', 'T恤', '1. 词性：\n- 맨T恤（man tee-suh）是名词。\n\n2. 词义：\n- 맨T恤主要指的是男士的T恤衫，也可以泛指一般的T恤衫。\n\n3. 例句：\n- ① 나는 새로운 맨T恤를 사겼어요. (我买了一件新的男士T恤。)\n- ② 이 夏天에는 맨T恤와 슬랙을 입고 있어요. (这个夏天我有男士T恤和短裤。)\n\n4. 变形及词义：\n- ① 맨T셔츠（man tee-suh cheu-reu）：男士T恤衫，强调的是衣服的类型。\n   - 예쁜 맨T셔츠를 찾으려고 합니다. (我在找好看的男士T恤衫。)\n  \n- ② 맨T셔츠 쇼핑（man tee-suh cheu-reu shop-king）：男士T恤购物，指的是购买男士T恤的行为或场所。\n   - 맨T셔츠 쇼핑에 가서 좋은 곳을 추천해 주세요. (请推荐一个男士T恤购物的好地方。)\n\n请注意，韩语中“맨T恤”通常不会进行复杂的变形，上述提供的变形更多是在句子中的搭配使用，而不是词本身的变形。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1689, 112, ' 롱Gloves', '手套', '1. 사용한 言語： 한국어 (韩语)\n2. 품사： 명사 (名词)\n3. 의意：\n   - 손套 (手套)\n   - 지鳩이 (手笼)\n4. 예句：\n   - 손套을 입고 가芍妮达. (我戴上手套去。)\n   - 봄에는 지鳩이를 입어 行茜凈하게 보이다. (春天戴手笼，看起来很清爽。)\n\n변형 그리고 의意：\n- 롱스 ( gloves - 复数形式): 손套들 (多只手套)\n  - 롱스를 모두 찾았다. (我找到了所有的手套。)\n- 롱Sized (glove-sized - 形容词): 손套 크기즈\n  - 친구가 롱Sized 손套을 샀어요. (我朋友给我买了合适尺寸的手套。)\n- 롱less (mulley - 形容词): 손套 없이\n  - 롱less 손을 씌우면 춥다. (不戴手套摸会很冷。)\n- 롱like (glove-like - 形容词): 손套처럼\n  - 그 것은 롱like 외guan을 갖추고 있다. (它有着类似手套的外观。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1690, 112, ' 핸드캐시et', '手帕', '1. 词性：\n핸드캐시et 是一个名词。\n\n2. 词义：\n- 手机壳\n- 保护套\n- 保护壳\n\n3. 例句：\n- 저는 핸드캐시et를 구입하고 싶습니다. (我想购买一个手机壳。)\n- 이 핸드캐시et은 나의 폰에 맞아요. (这个手机壳适合我的手机。)\n\n变形及词义：\n- 핸드캐시et 꾼： 手机壳套装\n  - 저는 핸드캐시et 꾼을 구입하고 싶습니다. (我想购买一套手机壳。)\n\n- 핸드캐시et 컷： 手机壳贴纸\n  - 저는 핸드캐시et 컷을 붙여야 합니다. (我需要贴上手机壳贴纸。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1691, 112, ' 망토스', '连裤袜', '1. 词性：\n- 망토스 (Mantos) 是一个名词。\n\n2. 词义：\n- 通常指代地名，如厄瓜多尔的曼塔市（Manta），或用作人名、品牌名等。\n\n3. 例句：\n- 나는 망토스에 가졌다. (我去了曼塔市。)\n- 망토스가 제주시를 개최한 새로운 쇼핑몰이 열릴 예정입니다. (曼塔计划在济州岛开设一家新的购物中心。)\n\n变形及其词义和例句：\n- 由于\"망토스\"主要是一个专有名词，它没有常规的变形。不过，如果考虑其作为地名的使用，可能会有以下情况：\n  - 망토스에서 (在曼塔市): 나는 망토스에서 사랑하고 있었다. (我在曼塔市度假。)\n  - 망토스귀佳 (前往曼塔市): 우리는 망토스귀佳를 계속합니다. (我们正前往曼塔市。)\n\n请注意，\"망토스\"作为一个外来词，主要用于特定的名称，不常用于变形或派生新词。以上提供的用法主要围绕其作为地名的功能。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1692, 112, ' 골Cap', '帽子', '1. 词性：\n- 접미(名词)\n\n2. 词义：\n- 머리를 얼마나 짜는 것을 의미하며， 헤어 스타일에서 가장 기본적인 형태로써 주로 앞머리를 얼마나 짜고， 뒷머리를 얼마나 짜는지를 표현한다.\n- 따라서 \"골\"은 헤어 스타일에서 앞머리와 뒷머리의 길이 비율을 나타내는 言葉이다.\n- 예： 앞골， 뒷골， 골 Cap, 골 Cut, 골 Style 등과 같은 용어들을 생산할 수 있다.\n\n3. 例句：\n- 1) 이 헤어사廊에서 가장 흥椽한 골 Cut이 어떻게 되는지 알아보자.\n- 2) 그는 앞골이 5cm, 뒷골이 2cm의 골 Cap를 선택했다.\n\n变形及其词义：\n- 앞골 (Front Lift): 앞머리를 위로 릴리는 것을 의미하며， 헤어 스타일에서 많이 사용된다.\n- 뒷골 (Back Lift): 뒷머리를 위로 릴리는 것을 의미하며， 헤어 스타일에서 많이 사용된다.\n- 골 Cut (Haircut): 헤어를 절て 铰く 것을 의미하며， 헤어 스타일에서 많이 사용된다.\n- 골 Style (Hairstyle): 헤어를 鉸克斯하고， 스타일링하는 것을 의미하며， 헤어 스타일에서 많이 사용된다.', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1693, 112, ' 가로Socks', '袜子', '1. 词性：\n- 가로Socks: 名詞（Noun）\n\n2. 词义：\n- 가로Socks: 袜子，短袜\n\n3. 例句：\n- 이 옷은 가로Socks를 입는 것이 좋습니다. (这件衣服搭配袜子穿比较好。)\n- 가로Socks를 두 双脚씩 입으세요. (请穿上两双袜子。)\n\n变形及词义：\n- 가로Socksing: 动词，表示穿袜子的动作\n  - 그는 가로Socks를 가로Socksing합니다. (他正在穿袜子。)\n\n- 가로Socksless: 形容词，表示没有穿袜子的状态\n  - 그는 가로Socksless입니다. (他没有穿袜子。)\n\n- 가로Socksful: 形容词，表示充满袜子的状态\n  - 저의 창고는 가로Socksful입니다. (我的仓库里充满了袜子。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1694, 112, ' 밑Scarf', '头巾', '1. 사절：\n   - 词性：名词（Noun）\n   - 词义：围巾，头巾。\n   - 例句：\n     1) 봄이 되면 나는 큰 깃틸로 왕소매를 착하고 가요.\n        (春天到来时，我就会戴上大围巾去赏花。)\n     2) 그는 깊은 벚꽃 색의 사절를 입고 가요.\n        (他戴着深紫色的围巾出门了。)\n\n2. 사절의 변형 및 이들의 의미와 예문：\n   - 사절이라는 변형：\n     - 词性：形容词（Adjective）\n     - 词义：像围巾一样的，用于形容某物长而窄，可用于装饰或保暖。\n     - 例句：\n       - 그 친절한 여름， 사절이란 곡아리를 입고 ш辛하게 살았다.\n         (在那个寒冷的夏天，我戴着像围巾一样的长围巾，生活得很艰苦。)\n\n   - 사절으로는 변형：\n     - 词性：副词（Adverb）\n     - 词义：用围巾的方式，指以围巾覆盖或保护的方式。\n     - 例句：\n       - 봄이 되면 나는 사절으로 왕소매를 보며 가요.\n         (春天来临时，我会像戴围巾一样保护着花儿去赏花。)\n\n请注意，韩语中单词变形及其用法可能会根据具体语境有所变化，以上提供的信息是基于标准用法。此外，由于“사절”是一个名词，其形容词和副词形式是通过添加修饰词或其他方式表达的，而不是直接变形。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1695, 112, ' 굽Button', '纽扣', '1. 词性：\n- 굽Button: 可作为名词使用。\n\n2. 词义：\n- 通常指代“按钮”或“按键”，在计算机或电子设备的界面中，用于触发特定功能的图形或物理元件。\n\n3. 例句：\n- 이 컴퓨터의 굽Button을 눌러요. (请按一下这台电脑的按钮。)\n- 휴대폰에서 굽Button을 눌러면 앱이 실행되는데요. (在手机上按这个按钮可以运行应用程序。)\n\n变形及其词义：\n- 没有直接的变形，但可以用不同的词语来表达相似的概念，如 \"버튼(button)\"，直译为“按钮”。\n\n其他变形的例句（以“버튼”为例）：\n- 버튼을 클릭하세요. (Click the button.)\n- 이 버튼을 누르면 컴퓨터가 시작됩니다. (Pressing this button will start the computer.)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1696, 112, ' 팬츠', '围巾', '1. 词性：\n- 팬츠： 名词（Noun）\n\n2. 常用词义：\n- 粉丝，尤指名人或团体的粉丝（Fan of a celebrity or group）\n\n3. 例句：\n- 나는 그 밴드의 팬츠입니다. (我是那个乐队的粉丝。)\n- 팬츠들이 커서 농이를 기다리는 것을 봤요？ (你看过粉丝们等待签名的样子吗？)\n\n变形及其词义：\n- 没有直接的变形，但可以与其他词汇结合形成复合词或短语，如“迷妹”（狂熱的粉丝，尤其是女性粉丝），“明星粉丝”（明星的粉丝）。\n\n每个变形的例句：\n- 팬츠이라는 직접 사람의 이름은 있지만， 이 단어를 사용하는 경우가 별로 없습니다. (虽然没有直接以“粉丝”命名的人，但使用这个词的情况并不多。)\n- 친구가 아마 그 가수의 믿а일ie 粉絲です. (我朋友可能是那位歌手的狂热粉丝。)\n\n请注意，韩语中单词的变形和组合可能与上述解释略有不同，具体取决于语境和使用习惯。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1697, 112, ' 벨Tie', '领带', '1. 词性：\n벨Tie（Bel Tie）是一个名词。\n\n2. 词义：\n- 指一种用于固定或装饰的带子，通常用于领带、围巾等。\n- 在时尚领域中，也可以指一种流行元素或设计。\n\n3. 例句：\n- 이 옷에는 벨티를 꼭 붙여야 합니다. (这件衣服必须要系上领带。)\n- 그는 벨티를 찬아놔고 가요. (他戴着领带去上班。)\n\n变形及其词义：\n- 벨티式（Beltiseu）：形容词，表示与领带相关的样式或风格。\n  - 그는 옷은 벨티식이 좋습니다. (他的衣服领带样式很好。)\n\n- 벨티色（Beltiseok）：名词，表示领带的颜色。\n  - 그는 옷와 벨티색이 잘 맞아요. (他的衣服和领带颜色很搭配。)\n\n- 벨티긋（Beltijip）：动词，表示系领带的动作。\n  - 그는 옷을 着고 벨티를 긋고 가요. (他穿上衣服后系上领带就出门了。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1698, 113, '비', '雨', '1. 词性：名词\n2. 词义：雨\n3. 例句：\n   - 오늘 비가 많이 옵니다.（今天雨下得很大。）\n   - 봄이 되면 비가 자주 옵니다.（到了春天，经常下雨。）\n\n变形及词义、例句：\n\n**비의 변형은 없지만, 관련된 표현으로는 다음과 같은 것이 있습니다.**\n\n1. **비가 오다**（下雨）\n   - 例句：지금 비가 오는군요.（现在正在下雨呢。）\n\n2. **비가 멈추다**（雨停了）\n   - 例句：비가 멈추었으니 외출해도 될 거예요.（雨停了，可以外出了。）\n\n3. **빗방울**（雨点）\n   - 例句：빗방울이 창문을 때리는 소리가 들립니다.（听到雨点打在窗户上的声音。）\n\n4. **비소식**（雨的消息，预示下雨的迹象）\n   - 例句：날씨 예보에 따르면 내일 비소식이 있습니다.（据天气预报，明天有下雨的迹象。）\n\n5. **비바람**（风雨，风雨交加的天气）\n   - 例句：비바람 속에서도 외출해야 합니다.（即使风雨交加，也得外出。）\n\n6. **비를 맞다**（淋雨）\n   - 例句：우산을 잊고 비를 맞았어요.（忘记带伞，淋雨了。）\n\n7. **비가 그치다**（雨停了，与“비가 멈추다”类似，但更常用）\n   - 例句：비가 그쳤으니 운동장을 가봅시다.（雨停了，去操场吧。）\n\n8. **폭우**（暴雨）\n   - 例句：밤중에 폭우가 퍼붓었어요.（半夜下了暴雨。）\n\n9. **메음비**（梅雨，特指梅雨季节的雨）\n   - 例句：메음비 시즌에는 옷이 잘 마르지 않아요.（梅雨季节衣服不容易干。）\n\n10. **눈비**（雨雪，既像雨又像雪的降水）\n    - 例句：산에서 내려오는데 눈비가 내리기 시작했어요.（从山上下来的时候，开始下雨雪了。）\n\n这些变形和相关表达展示了“비”这个词在韩语中丰富的用法和含义，涵盖了与雨相关的各种情境和描述。', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1747886887474.mp3');
INSERT INTO `word_list` VALUES (1699, 113, '더위', '炎热', '1. 词性：名词\n2. 词义：热、暑热、炎热\n3. 例句：\n   - 요즘 더위가 정말 심해요.（最近天气真的很热。）\n   - 더위를避켜서 시원한 곳에 갔다.（为了避暑去了凉快的地方。）\n\n**变形及词义**：\n\n- **더운（形容词）**：热的、炎热的\n  - 例句：오늘은 아주 더운 날씨네요.（今天是很热的天气呢。）\n\n- **더워지다（动词）**：变热、热起来\n  - 例句：봄이 가고 여름이 되면서 점점 더워지네요.（春天过去，夏天到了，渐渐热起来了。）\n\n- **더웠다（形容词过去式）**：热的（过去时态，表示曾经热过）\n  - 例句：어젯밤은 너무 더웠다.（昨晚太热了。）\n\n- **더웁다（形容词定语形式）**：用于修饰名词，表示“热的”\n  - 例句：더웁다 공기를 느끼며 걷기 싫어진다.（感受到热的空气，都不想走路了。）\n\n注意：在韩语中，“더위”主要作为名词使用，表示“热”或“暑热”。其变形更多体现在与之相关的形容词、动词等形式上，且在实际使用中，并非所有变形都常用或具有明确的独立词义，上述变形仅为展示可能的语法变化。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1700, 113, '비옴', '阴天', '### 1.词性：\n名词（Noun）\n\n### 2.词义：\n- “비옴”是一个固有名词，通常指人名“裴翁”或“裵翁”，也可以作为姓氏使用。在韩国文化中，它可能是一个较为少见但存在的姓氏或名字。\n\n### 3.例句：\n- **例句1**: 비옴씨는 우리 학교의 새로운 역사 교사입니다.\n  - *解释*: 裴翁先生是我们学校新的历史老师。\n  \n- **例句2**: 저는 비옴이라는 특별한 친구가 있습니다.\n  - *解释*: 我有一个叫做裴翁的特别朋友。\n\n### 所有变形及其词义和例句：\n由于“비옴”是一个固有名词，它不像动词或形容词那样有词形变化。不过，根据其在句子中的语法角色，它可以与不同的助词或后缀结合使用，以表达不同的意思或关系。以下是一些常见的组合及其例句：\n\n#### 1. 비옴이 (Bi-omi)\n- **词义**: 表示主格，用于谓语的主语。\n- **例句**: 비옴이는 매일 아침 일찍 등교합니다.\n  - *解释*: 裴翁每天早晨很早去上学。\n\n#### 2. 비옴에게 (Bi-om-ge)\n- **词义**: 表示与格，用于动作的间接对象。\n- **例句**: 저는 비옴에게 수학 문제를 가르쳐 주었습니다.\n  - *解释*: 我对裴翁讲解了数学问题。\n\n#### 3. 비옴을 (Bi-om-eul)\n- **词义**: 表示宾格，用于动作的直接对象。\n- **例句**: 교사는 비옴을 반장으로 뽑았습니다.\n  - *解释*: 老师选裴翁为班长。\n\n#### 4. 비옴도 (Bi-om-do)\n- **词义**: 表示包含，相当于“也”。\n- **例句**: 비옴도 이번 시험에서 좋은 성적을 받았습니다.\n  - *解释*: 裴翁也在这次考试中取得了好成绩。\n\n这些变形展示了“비옴”在不同句子结构中的使用方法，但请注意，由于它是固有名词，其本身的形态并不发生变化。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1701, 113, '눈', '雪', '1. 词性：名词\n2. 词义：眼睛；视线；目光；见解；看法；雪花\n3. 例句：\n   - 눈이 매우 예쁘다.（眼睛非常漂亮。）\n   - 그의 눈빛은 날카웠다.（他的目光很锐利。）\n\n**变形及词义、例句：**\n\n**눈에（在……眼里，对……来说）**\n- 例：그녀는 내 눈에 가장 아름다운 사람이다.（在我眼里她是最漂亮的人。）\n\n**눈앞（眼前，跟前）**\n- 例：눈앞에 있는 기회를 놓치지 마세요.（不要错过眼前的机会。）\n\n**눈짓（使眼色，用眼神示意）**\n- 例：그는 눈짓으로 나를 불렀다.（他用眼神示意我过去。）\n\n**눈썰미（眼光，眼力）**\n- 例：그의 눈썰미는 정말 뛰어납니다.（他的眼光真的很卓越。）\n\n**눈물（眼泪）**\n- 例：그녀는 슬픔에 눈물을 흘렸다.（她因悲伤流下了眼泪。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1702, 113, '소나기', '阵雨', '1. 词性：名词\n2. 词义：\n    - 阵雨；骤雨\n    - （比喻）短暂的、一阵一阵的（类似阵雨般的情况，如一阵忙碌、一阵喧嚣等，不过这种用法相对较少，常见还是指自然现象中的阵雨）\n\n3. 例句：\n    - 소나기가 갑자기 쏟아졌다.（突然下起了阵雨。）\n    - 소나기처럼人来人往하다.（像阵雨一样人来人往，这里用“像阵雨”来比喻人来人往一阵一阵的情况。）\n\n4. 变形及词义、例句：\n    - 소나기가：是主格助词“가”与“소나기”的结合，在句子中作主语，词义仍为“阵雨”，例句：소나기사가 창문을 때린다.（阵雨打窗户。）\n    - 소나기도：是主格助词“도”与“소나기”的结合，用于表示“阵雨也……”，例句：바람이 불고 소나기라도 퍼붓는다.（刮着风，阵雨也倾盆而下。）\n    - 소나기에：是宾格助词“에”与“소나기”的结合，用于表示“在阵雨中”等意思，例句：소나기에 옷이 젖었다.（在阵雨中衣服湿了。）\n    - 소나기를：是宾格助词“를”与“소나기”的结合，用于表示“阵雨”作为宾语，例句：비닐 옷을 입어서 소나기를 막았다.（穿了塑料雨衣挡阵雨。）\n    - 소나기의：是属格助词“의”与“소나기”的结合，用于表示“阵雨的”，例句：소나기의 냄새가 좋다.（阵雨的气味很好闻。）\n    - 소나기로：是工具格助词“로”与“소나기”的结合，可表示“用阵雨（这种方式）”或者“因为阵雨”，例句：소나기로 더위를 식힐 수 있다.（可以用阵雨来消除暑热。） \n    - 소나기처럼：是“一样”格助词“처럼”与“소 나 기”的结合，用于表示“像阵雨一样”，例句：눈물이 소나기처럼 쏟아졌다.（眼泪像阵雨一样倾泻而下。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1703, 113, '눈비', '雨夹雪', '1. 词性：名词\n2. 词义：\n   - 雨夹雪；雨雪混杂的降水\n   - （在某些语境下可引申为）像雨夹雪一样混合或交织的状态\n3. 例句：\n   - 눈비가 내리기 시작했어요.（开始下雨夹雪了。）\n   - 하늘에 눈비가 흩뿌려지고 있다.（天空中飘着雨夹雪。）\n\n变形及词义、例句：\n- 눈비가：作为主格助词“가”的变形，用于句子的主语位置，表示“雨夹雪”这个主体。\n  - 눈비가 많이 옵니다.（雨夹雪下得很大。）\n- 눈비를：作为宾格助词“를”的变形，用于句子的宾语位置，表示动作涉及的对象是“雨夹雪”。\n  - 우리는 눈비를 보며 걸었습니다.（我们一边看着雨夹雪一边走。）\n- 눈비에：作为属格助词“에”的变形，用于表示地点、时间等，这里可理解为“在雨夹雪中”或“遇到雨夹雪的情况”。\n  - 눈비에 옷이 젖었어요.（在雨夹雪中衣服湿了。）\n- 눈비로：作为原因或目的助词“로”的变形，表示因为“雨夹雪”或者为了“雨夹雪”（这种情况较少，一般多表示原因）。\n  - 눈비로 길이 미끄러워졌어요.（因为雨夹雪路变得滑了。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1704, 113, '태풍', '台风', '1. 词性：名词\n2. 词义：台风\n3. 例句：\n   - 태풍이 다가오고 있습니다.（台风正在逼近。）\n   - 태풍으로 학교가 휴업되었습니다.（因为台风学校停课了。）\n\n**变形及词义与例句**：\n\n- **태풍의**：台风的（所有格形式，用于修饰名词，表示所属关系）\n  -例句：태풍의 영향으로 배가 출항을 연기했습니다.（受台风影响，船推迟了出航。）\n\n- **태풍을**：台风（宾格形式，在句子中作宾语）\n  - 例句：우리는 태풍을 기다렸습니다.（我们等了台风。此句在实际语境中可能不太自然，通常更自然的表达是等待台风过去或应对台风，这里仅为展示宾格形式）\n\n- **태풍에게**：对于台风（与格形式，表示动作的对象或针对的对象，但此形式在描述自然现象时较少直接使用，更多用于拟人化或比喻语境）\n  - 例句（较为生硬，实际使用中需根据语境调整）：인간은 태풍에게 무력합니다.（人类对于台风是无力的。）\n\n- **태풍으로서**：作为台风（此形式不常用，更多用于强调身份或角色，但在描述自然现象时较少见）\n  - 例句（构造）：태풍으로서, 그것은 강한 파괴력을 가지고 있습니다.（作为台风，它具有很强的破坏力。）\n\n注意：在实际应用中，“태풍”作为自然现象的名称，其变形并不像动词或形容词那样频繁或必要。上述变形更多是为了语法结构的完整性而列出，实际使用时需根据语境灵活选择。', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1746604276081.mp3');
INSERT INTO `word_list` VALUES (1705, 113, '맑음', '晴', '无法从大模型获取数据，请联系管理员！', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1706, 113, '구름', '云', '### 1. 구름 (구름)\n#### 1.1. 词性：名词（Noun）\n#### 1.2. 词义：\n- **云**：天空中由水蒸气凝结形成的可见物体。\n- **（比喻）虚无缥缈的事物**：常用于比喻难以捉摸或虚幻的东西。\n\n#### 1.3. 例句：\n- **例句1**: 하늘에 구름이 많다.  \n  （天上有很多云。）\n- **例句2**: 그의 꿈은 구름처럼 사라졌다.  \n  （他的梦想像云一样消失了。）\n\n---\n\n### 2. 变形及其词义与例句\n#### 2.1. 구름 -> 구름 (原形)\n- **词义**：云（基本词义）\n- **例句**: 날씨가 흐리면 구름이 많이 생겨요.  \n  （天气阴的时候会有很多云。）\n\n#### 2.2. 구름 -> 구름 같(다) [形容词短语]\n- **词义**：像云一样（比喻轻盈、虚无或飘渺）\n- **例句**: 그녀의 목소리는 구름 같다.  \n  （她的声音像云一样轻盈。）\n\n#### 2.3. 구름 -> 구름 밑 [名词短语]\n- **词义**：云下（指云的下方或被云覆盖的地方）\n- **例句**: 구름 밑에서 비가 쏟아졌다.  \n  （云下下起了倾盆大雨。）\n\n#### 2.4. 구름 -> 구름 위 [名词短语]\n- **词义**：云上（指云的上方或云层之上）\n- **例句**: 구름 위에 솟은 산은 신비롭게 보였다.  \n  （云上的山显得神秘莫测。）\n\n#### 2.5. 구름 -> 구름 사이 [名词短语]\n- **词义**：云间（指云与云之间的空隙）\n- **例句**: 구름 사이로 햇살이 비쳐났다.  \n  （阳光从云间透射出来。）\n\n---\n\n### 总结\n- **词性**：名词\n- **常用词义**：云、虚无缥缈的事物\n- **变形**：\n  - 구름 같(다)（像云一样）\n  - 구름 밑（云下）\n  - 구름 위（云上）\n  - 구름 사이（云间）', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1746604282068.mp3');
INSERT INTO `word_list` VALUES (1707, 113, '기온', '气温', '1. 词性：名词\n2. 词义：气温，温度\n3.例句：\n- 오늘의 기온은 어떻습니까?（今天的气温怎么样？）\n- 겨울이 되어서 기온이 많이 떨어졌어요.（到了冬天，气温下降了很多。）\n\n**变形及词义、例句：**\n\n**기온차（气温差）**\n- 뜻：두 곳 혹은 두 시간 사이의 기온의 차이（两地或者两个时间之间的气温差异）\n- 예문：서울과 부산의 기온차가 꽤 크다.（首尔和釜山的气温差相当大。）\n\n**기온계（温度计）**\n- 뜻：기온을 측정하는 도구（测量气温的工具）\n- 예문：기온계를 봐서는 지금 실내 기온이 22도입니다.（看温度计现在室内气温是22度。）\n\n**기온 상승（气温上升）**\n- 뜻：기온이 올라가는 것（气温升高）\n- 예문：햇볕이 강해지면서 기온 상승이 뚜렷해요.（阳光变强，气温上升很明显。）\n\n**기온 하락（气温下降）**\n- 뜻：기온이 내려가는 것（气温降低）\n- 예문：밤이 되자 기온 하락이 심해졌어요.（一到晚上，气温下降得厉害了。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1708, 113, '바람', '风', '1. **词性**: 名词(명사)\n\n2. **词义**:\n   - \"바람\" 可以指自然界的“风”或“气流”。\n   - 也可以用来比喻情绪、氛围的变化，类似于中文里的“风气”、“潮流”等含义。\n   - 在某些语境下，还特指某种倾向或者趋势。\n\n3. **例句**:\n   - 자연풍이 시원하게 불어요. (自然风吹来很凉爽。)\n   - 회사에 새로운 바람이吹いました. (公司里吹起了新风。) 这里指的是变化或改革的意思。\n\n**变形及其词义与例句**:\n\n- **바래다** (动词形式): 表示被风吹动的状态。\n  - 例：잎사가 바람에 바래요. (树叶随风摇曳。)\n\n- **바라지** (形容词比较级): 描述更加强烈的风的感觉。\n  - 例：오늘은 평소보다 바람이 더 바라지네요. (今天比平时风更大些。)\n\n- **바람직하다** (复合词): 意味着合理、恰当。\n  - 例：그 제안은 매우 바람직해 보입니다. (那个建议看起来非常合理。)\n\n- **바람막이** (名词): 防风设施。\n  - 例：여기는 겨울에 추우니까 바람막이를 설치했어야 해요. (这里冬天很冷，应该安装防风装置。)\n\n请注意，根据具体使用情况和上下文，\"바람\"可能还有其他特定领域的专业术语或者俗语中的特殊用法。上述解释基于日常语言中的常见理解和应用。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1709, 113, '날씨예보', '天气预报', '### 1. 날씨예보 词性：\n**名词 (명사)**\n\n---\n\n### 2. 词义：\n- **天气预报**（指对天气状况的预测和报告）\n\n---\n\n### 3. 例句：\n1. **날씨예보를 보면 오늘 비가 오지 않을 거예요.**  \n   （看天气预报的话，今天不会下雨。）  \n2. **매일 아침 뉴스에서 날씨예보를 전해요.**  \n   （每天早晨的新闻会播报天气预报。）\n\n---\n\n### 变形及词义（无严格变形，但可结合语法结构扩展）：\n虽然 **날씨예보** 本身是复合名词，没有典型的变形（如动词化、形容词化等），但可以通过添加助词或与其他词组合形成常用表达：\n\n#### 1. **날씨예보를 확인하다**  \n   - **词义**：确认/查看天气预报  \n   - **例句**：  \n     **출근 전에 날씨예보를 꼭 확인해요.**  \n     （上班前一定会查看天气预报。）\n\n#### 2. **날씨예보가 맞다**  \n   - **词义**：天气预报准确  \n   - **例句**：  \n     **오늘 날씨예보가 딱 맞았네!**  \n     （今天的天气预报完全准确啊！）\n\n#### 3. **날씨예보에 따르면**  \n   - **词义**：根据天气预报  \n   - **例句**：  \n     **날씨예보에 따르면, 이번 주 내내 맑겠습니다.**  \n     （根据天气预报，本周将持续晴朗。）\n\n---\n\n### 总结：\n- **날씨예보** 是固定名词，表示“天气预报”，无单独变形，但可通过语法结构与其他词搭配使用。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1710, 113, '흐림', '阴', '1. 词性：名词\n2. 词义：阴天、多云\n3. 例句：\n   - 오늘은 날씨가 흐림이다.（今天是阴天。）\n   - 흐림이 짙어지면서 비가 올 듯하다.（多云变得浓了，好像要下雨。）\n\n变形及词义、例句：\n\n**흐려짐（变阴、变多云）**\n- 词义：指天气从晴朗等状态逐渐变为阴天、多云的状态。\n- 例句：저녁이 되면서 하늘이 점점 흐려지고 있다.（到了晚上，天空渐渐变阴了。）\n\n**흐린 날（阴天）**\n- 词义：就是表示阴天的表达，“흐림”的另一种说法，强调具体的某一天是阴天的情况。\n- 例句：흐린 날에 외출을 하면 사진 찍기 좋아요.（阴天外出拍照挺好的。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1711, 113, '습도', '湿度', '1. **词性**：名词（명사）\n2. **词义**：湿度，指空气中所含水汽的量或比例。\n3. **例句**：\n   - 오늘은 습도가 높아 옷이 잘 마르지 않는다.（今天湿度高，衣服不容易干。）\n   - 이 방은 습도 조절기가 필요할 정도로 습기가 많다.（这个房间湿气很重，需要湿度调节器。）\n\n**变形及其词义与例句**：\n\n1. **습하다**（形容词，形容物体或环境潮湿、湿润）\n   - **例句**：비가 온 뒤에 공기가 습하다.（下雨后空气很潮湿。）\n\n2. **습기를**（在复合词或短语中作为“湿气”的名词形式，常与其他词汇结合使用）\n   - **例句**：이 빵은 습기를 많이 머금고 있어 부드러워졌다.（这个面包吸了很多湿气，变得柔软了。）\n\n注意：虽然“습기를”可以视为“습도”在特定语境下的变形应用，但它本身并不是一个独立的单词，而是作为名词短语的一部分。在韩语中，“습도”主要通过添加后缀或与其他词汇结合来形成新的表达，而不是像英语那样有严格的词形变化规则。因此，这里的变形更多是指其在复合词或短语中的应用形式。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1712, 113, '폭우', '暴雨', '1. 词性：名词\n2. 词义：暴雨、倾盆大雨\n3. 例句：\n   - 폭우가 쏟아지니 길에 사람들도 급히 대피하네.（下起暴雨，路上的人们也急忙避难。）\n   - 밤중에 폭우가 와서 논이 물에 잠겼다.（半夜下暴雨，田被水淹了。）\n\n变形及词义、例句：\n\n**폭우로**（作为“由于暴雨”的格词尾变形，表示原因等，这里可看作一种语法功能上的变形）\n- 词义：由于暴雨\n- 例句：폭우로 교통이 마비되었어요.（由于暴雨交通陷入了瘫痪。）\n\n**폭우를**（是“暴（爆）雨”的宾格变形，用于表示动作涉及的对象等情况）\n- 词义：暴雨（宾格，指暴雨这个对象）\n- 例句：우리는 폭우를 걱정하며 집 안에 대기했다.（我们一边担心着暴雨，一边在屋里待命。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1713, 113, '황사', '沙尘暴', '1. 词性：名词\n2. 词义：\n   - 黄沙（指从沙漠等地区吹起的沙尘，常造成沙尘暴天气）\n   - 沙尘天气（特指出现大量沙尘弥漫的天气状况）\n3. 例句：\n   - 황사가 심각해 외출을 삼가야 한다.（黄沙很严重，要尽量避免外出。）\n   - 오늘은 황사로 인해 공기가 탁하다.（今天是黄沙导致空气浑浊。）\n\n**变形及词义与例句**：\n\n**황사에**\n- 词义：在黄沙（天气状况下），表示与黄沙相关的环境或情境中\n- 例句：황사에 마스크를 착용해야 한다.（在黄沙天气里要佩戴口罩。）\n\n**황사를**\n- 词义：黄沙（作为宾语前置时的形式），比如“阻挡黄沙”等情况使用\n- 例句：나무를 심어 황사를 막는다.（种树来阻挡黄沙。）\n\n**황사로**\n- 词义：因为黄沙，由于黄沙（表示原因）\n- 例句：황사로 비행기가 연착됐다.（因为黄沙飞机延误了。）\n\n**황사처럼**\n- 词义：像黄沙一样（用于比喻，形容某种类似黄沙的状态或情形）\n- 例句：공기 중에 먼지가 황사처럼 가득 찼다.（空气中灰尘像黄沙一样充满了。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1714, 113, '미세먼지', '细颗粒物', '1. **词性**：  \n   名词（명사）\n\n2. **词义**：  \n   - 雾霾（空气中的细颗粒物污染）  \n   - 细颗粒物（特指空气污染中的PM2.5等微粒）\n\n3. **例句**：  \n   - 미세먼지 수치가 높아 외출을 삼가는 것이 좋습니다.  \n     （细颗粒物数值高，建议减少外出。）  \n   - 오늘 미세먼지 경보가 발령됐어요.  \n     （今天发布了雾霾警报。）\n\n---\n\n### **变形及词义**  \n1. **미세먼지로**（以“-로”结尾的名词形式，表示手段或原因）  \n   - **词义**：因雾霾、作为雾霾  \n   - **例句**：미세먼지로 호흡기 질환이 심해졌어요.  \n     （因雾霾导致呼吸道疾病加重。）\n\n2. **미세먼지의**（属格“-의”，表示所属或关联）  \n   - **词义**：雾霾的、细颗粒物的  \n   - **例句**：미세먼지의 영향으로 하늘이 뿌옇다.  \n     （受雾霾影响，天空灰蒙蒙的。）\n\n3. **미세먼지를**（宾格“-를”，作宾语）  \n   - **词义**：雾霾（作动作对象）  \n   - **例句**：공기 청정기가 미세먼지를 제거하는 데 효과적입니다.  \n     （空气净化器对去除雾霾很有效。）\n\n4. **미세먼지가**（主格“-가”，作主语）  \n   - **词义**：雾霾（作句子主语）  \n   - **例句**：미세먼지가 심해지면 운동장을 닫습니다.  \n     （雾霾严重时会关闭运动场。）\n\n---\n\n### **总结**  \n- **词性**：名词（명사），无动词或形容词变形。  \n- **核心变形**：通过附加格助词（-로, -의, -를, -가）改变语法功能，词义随语境调整。  \n- **特点**：原词为具体事物名词，变形后仅用于语法衔接，不改变核心含义。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1715, 113, '차가움', '寒冷', '1. 词性：名词\n2. 词义：寒冷、冷淡、冰冷的感觉或状态。\n3.例句：\n- 겨울이 되어서 강에 차가움이 가득하다.（因为到了冬天，江面上充满了寒冷。）\n- 그의 말투에는 일종의 차가움이 있었다.（他的语气里有一种冷淡。）\n\n变形及词义、例句：\n1. **차갑다**（形容词）：冷的、冷淡的\n- 오늘은 기온이 많이 차갑다.（今天气温很冷。）\n2. **차게**（副词）：冷冷地、冷淡地\n- 그는 나를 차게 바라봤다.（他冷冷地看着我。）\n3. **차갑게**（副词）：同“차게”，更强调状态\n- 바람이 차갑게 불었다.（风冷冷地吹着。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1716, 113, '우박', '冰雹', '### 우박  \n1. **词性**：名词  \n2. **词义**：  \n   - 冰雹（自然现象）  \n   - 比喻密集的打击或攻击（转义用法，较少见）  \n\n3. **例句**：  \n   - 오늘은 우박이 많이 내렸다.（今天下了很大冰雹。）  \n   - 농사를 망치는 우박 때문에 농민들이 고통받았다.（因毁坏庄稼的冰雹，农民们受苦了。）  \n\n---\n\n### 变形及词义  \n#### 1. **우박이**（助词“이”附加，表示主语）  \n   - **词义**：冰雹（作为句子的主语）  \n   - **例句**：우박이 창문을 때렸다.（冰雹敲打窗户。）  \n\n#### 2. **우박을**（助词“을”附加，表示宾语）  \n   - **词义**：冰雹（作为句子的宾语）  \n   - **例句**：아이들이 우박을 맞으며 뛰어놀았다.（孩子们顶着冰雹玩耍。）  \n\n#### 3. **우박에**（助词“에”附加，表示地点/时间）  \n   - **词义**：在冰雹中/时  \n   - **例句**：우박에 밭을 나가서는 안 된다.（冰雹时不能去田里。）  \n\n#### 4. **우박으로**（助词“로”附加，表示手段或原因）  \n   - **词义**：因冰雹/用冰雹  \n   - **例句**：우박으로 농작물이 파괴되었다.（庄稼因冰雹被毁。）  \n\n#### 5. **우박의**（助词“의”附加，表示所属）  \n   - **词义**：冰雹的  \n   - **例句**：우박의 크기는 돌멩이 같았다.（冰雹的大小像石头一样。）  \n\n---\n\n### 总结  \n- **核心词义**：自然现象“冰雹”，变形后通过助词扩展语法功能。  \n- **转义用法**：偶用于比喻密集打击（如：우박 같은 질타，“如冰雹般的斥责”），但日常以本义为主。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1717, 113, '날씨', '天气', '### 1. 날씨\n- **词性**：名词（명사）\n\n### 2. 词义：\n- **天气、气候**：指特定的天气状况或整体的气候情况。\n\n### 3. 例句：\n1. 오늘은 날씨가 참 좋습니다.（今天天气很好。）\n2. 여기 날씨는 매년 변함이 없어요.（这里的气候每年不变。）\n\n### 变形及其词义和例句：\n\n#### (1) 날씨가\n- **词义**：天气（主格助词“가”连接，用于句子主语）\n- **例句**：날씨가 추워서 밖에 나갈 수 없어요.（天气冷，所以不能外出。）\n\n#### (2) 날씨를\n- **词义**：天气（宾格助词“를”连接，用于句子宾语）\n- **例句**：날씨를 예측하는 것이 어렵습니다.（预测天气很难。）\n\n#### (3) 날씨에\n- **词义**：天气（属格助词“에”连接，表示与天气相关的状态或条件）\n- **例句**：날씨에 따라 옷을 입어야 합니다.（要根据天气穿衣服。）\n\n#### (4) 날씨로\n- **词义**：天气（工具格助词“로”连接，表示通过某种天气条件）\n- **例句**：비가 날씨로 인해 외출을 취소했습니다.（因下雨的天气取消了外出。）\n\n#### (5) 날씨로서\n- **词义**：作为天气（用于比较或评价）\n- **例句**：이곳 날씨로서는 여름에도 춥습니다.（作为这里的天气，夏天也很冷。）\n\n#### (6) 날씨와 함께\n- **词义**：与天气一起（共同关系）\n- **例句**：좋은 날씨와 함께 산에 오릅니다.（与好天气一起去爬山。）\n\n#### (7) 날씨에 따라\n- **词义**：根据天气（依存关系）\n- **例句**：날씨에 따라 여행 계획을 변경해야 합니다.（需要根据天气改变旅行计划。）\n\n#### (8) 날씨로 말미암아\n- **词义**：由于天气（原因）\n- **例句**：날씨로 말미암아 비행기가 결항되었습니다.（由于天气，航班被取消。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1718, 72, '복숭아 ', ' 桃子', '### 1.词性：\n名词（명사）\n\n### 2.词义：\n- 桃子（一种水果）\n- 桃树（结桃子的树木）\n\n### 3.例句：\n- **복숭아가 아주 맛있어요.**（桃子非常美味。）\n- **복숭아나무에 열린 복숭아들이 빨갛게 물들어요.**（桃树上结的桃子红通通的。）\n\n### 所有变形及其词义、例句：\n\n#### 复数形式：복숭아들\n- **词义**：多个桃子（复数形式，指多个桃子）\n- **例句**：**복숭아들이 모두 다 익었어요.**（桃子们都全部熟了。）\n\n#### 所有格形式：복숭아의\n- **词义**：桃子的（表示所属关系，用于描述与桃子相关的事物）\n- **例句**：**복숭아의 씨는 딱딱해요.**（桃子的核很硬。）\n\n#### 动词化形式（通过添加后缀构成）：복숭아를 먹다/주다 등\n- **词义**：吃桃子/给桃子等（根据添加的动词后缀不同，意义各异）\n- **例句**：**나는 복숭아를 좋아해서 자주 먹어요.**（我喜欢桃子所以经常吃。）\n\n#### 形容词化形式（通过添加后缀构成，但韩语中此词较少直接变形为形容词，通常通过短语表达）：\n- **说明**：韩语中“복숭아”本身不直接变形为形容词，但可以通过短语如“복숭아 같은”（像桃子一样的）来表达类似形容词的含义。\n- **例句**：**그녀의 얼굴은 복숭아 같은 붉은색이에요.**（她的脸像桃子一样红。）\n\n### 注意：\n- 韩语中的单词变形并不像英语或一些其他语言那样有固定的规则和形式，很多情况下是通过添加不同的后缀或与其他词汇组合来表达不同的意义。\n- 上述变形和例句仅供参考，实际使用中可能会根据语境和表达需要有所变化。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1719, 72, '블루베리 ', ' 蓝莓', '### 1.词性：\n**명사 (名词)**\n\n---\n\n### 2.词义：\n- **蓝莓**（一种蓝色浆果，用于水果、甜点或加工食品）  \n- **蓝莓味**（形容与蓝莓相关的味道或气味）  \n- **蓝莓植物**（指蓝莓的植株或种植）  \n\n---\n\n### 3.例句：\n1. **蓝莓**  \n   **例句**：블루베리가 제철이면 시장에 신선한 것이 많이 나옵니다.  \n   *(蓝莓当季时，市场上会有很多新鲜的。)*  \n\n2. **蓝莓味**  \n   **例句**：이 과자는 블루베리 맛이 浓郁해서孩子们很喜欢。  \n   *(这种零食有浓郁的蓝莓味，孩子们很喜欢。)*  \n\n---\n\n### 4.变形及词义（派生词）：\n\n#### 1. **블루베리쨈 (蓝莓酱)**  \n   - **词义**：用蓝莓制成的果酱。  \n   - **例句**：토스트에 블루베리쨈을 발라 먹으면 맛있어요.  \n     *(在吐司上涂蓝莓酱吃很美味。)*  \n\n#### 2. **블루베리농장 (蓝莓农场)**  \n   - **词义**：种植蓝莓的农场。  \n   - **例句**：주말에 가족과 블루베리농장에 체험학습을 가려고 합니다.  \n     *(周末打算和家人去蓝莓农场体验学习。)*  \n\n#### 3. **블루베리파이 (蓝莓派)**  \n   - **词义**：以蓝莓为馅料的甜点派。  \n   - **例句**：카페에서 판매하는 블루베리파이가 인기 상품이에요.  \n     *(咖啡厅卖的蓝莓派是人气商品。)*  \n\n#### 4. **블루베리즙 (蓝莓汁)**  \n   - **词义**：蓝莓榨成的果汁。  \n   - **例句**：아침에 건강을 위해 블루베리즙을 마십니다.  \n     *(早上为了健康喝蓝莓汁。)*  \n\n#### 5. **블루베리요거트 (蓝莓酸奶)**  \n   - **词义**：添加蓝莓或蓝莓味的酸奶。  \n   - **例句**：식단 관리 중이라 블루베리요거트를 자주 먹어요.  \n     *(因为饮食管理，所以经常吃蓝莓酸奶。)*  \n\n---\n\n### 总结：\n- **블루베리** 是名词，核心词义为“蓝莓”，也可引申为“蓝莓味”或“蓝莓植物”。  \n- 变形词多为复合名词，表示与蓝莓相关的加工食品或场所。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1720, 72, '오렌지 ', ' 橙子', '### 1.词性：\n- 名词\n\n### 2.词义：\n- 橙子（作为水果名称）\n- 橙色（颜色名称）\n- 橘色（颜色名称，与“橙色”意思相近，在韩语中通常用“오렌지”表示）\n\n### 3.例句：\n- 저는 오렌지를 좋아해요.（我喜欢橙子。）\n- 이 옷은 오렌지색이에요.（这件衣服是橙色的。）\n\n### 变形及其词义、例句：\n\n#### 复数形式：오렌지들\n- **词义**：橙子们（多个橙子）\n- **例句**：상에 오렌지들이 많이 있네요.（桌子上有很多橙子。）\n\n#### 形容词形式：오렌지색（的）\n- **词义**：橙色的\n- **例句**：그 그림은 오렌지색 배경이예요.（那幅画是橙色的背景。）\n\n#### 动词化（通过添加后缀构成，如“-화”表示“化为……”，但此处更常见的是用“오렌지로 변하다”等表达，不过直接变形为动词的情况较少，以下为一种可能的表达方式）：\n- **变形**：오렌지화（化为橙色，但此用法不常见，更自然的表达是“오렌지색으로 변하다”）\n- **词义**：变为橙色\n- **例句**：（此例句较为生硬，实际使用中会避免）잎사귀가 오렌지화 되어 가고 있습니다.（叶子正在变成橙色。）更自然的表达：잎사귀가 오렌지색으로 변하고 있습니다.（叶子正在变成橙色。）\n\n注意：韩语中单词的变形并不像英语那样有严格的规则，且很多变形在实际使用中并不常见或自然。上述变形仅为示例，实际使用时应根据语境选择合适的表达方式。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1721, 72, '배 ', ' 梨', '1.词性：名词\n2.词义：\n   - 船（泛指船只）\n   - 梨（水果）\n3.例句：\n   - 배가 항해를 시작했습니다.（船开始了航行。）\n   - 나는 배를 무척 좋아합니다.（我非常喜欢梨。）\n\n**变形及其词义和例句**：\n\n1. **배**（原形）：船、梨\n   - 例：우리는 배를 타고 섬에 갔다.（我们乘船去了岛上。）\n\n2. **배** + 수식어（修饰语，如“큰 배”大船）\n   - 例：큰 배는 바다에서 안정적으로 항해할 수 있다.（大船能在海上稳定航行。）\n\n3. **배** + 격조사（助词，如“배를”把船）\n   - 例：그는 배를 열심히 닦았다.（他努力地擦船。）\n\n4. **배**의 복수형（复数形式，虽然韩语中不常显式标记复数，但可通过上下文理解）\n   - 例：바다에는 많은 배들이 있습니다.（海上有很多船。）（注：这里“많은 배들이”中的“들”是复数后缀，但通常口语中可能省略，直接说“많은 배”）\n\n5. **배**의 다른 용법（其他用法，如作为量词前缀，表示“船次”，但此用法较少见且更偏向于特定语境）\n   - 例：이 배는 일주일에 두 번 운항합니다.（这艘船每周航行两次。）（注：这里的“배”更多是作为“船次”的隐含概念，并非直接变形）\n\n在韩语中，单词的变形并不像英语那样有明显的词尾变化，而是更多地通过助词、上下文以及动词或形容词的搭配来表达不同的含义和语法功能。因此，对于名词“배”来说，其变形主要体现在与不同助词或修饰语的结合上，而不是单词本身的形式变化。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1722, 72, '감귤 ', ' 柑橘', '1. 词性：名词\n2. 词义：柑橘类水果，通常指橘子或类似的柑橘属水果。\n3. 例句：\n   - 감귤을 많이 먹으면 피부에 좋아요. (多吃柑橘对皮肤好。)\n   - 시장에 가서 감귤을 좀 사 왔습니다. (我去市场买了些柑橘。)\n\n**变形及其词义与例句：**\n\n1. **감귤나무**（柑橘树）\n   - 例句：우리 집 앞에는 감귤나무가 있습니다. (我家门前有棵柑橘树。)\n\n2. **감귤농장**（柑橘农场）\n   - 例句：이번 주말에 감귤농장에 놀러 가자. (这个周末我们去柑橘农场玩吧。)\n\n3. **감귤즙**（柑橘汁）\n   - 例句：아침에 감귤즙을 마시면 건강에 좋습니다. (早上喝柑橘汁对健康有益。)\n\n4. **감귤류**（柑橘类）\n   - 例句：감귤류는 비타민 C가 풍부해요. (柑橘类富含维生素C。)\n\n5. **감귤향**（柑橘香）\n   - 例句：이 샴푸는 감귤향이 나요. (这款洗发水有柑橘香味。)\n\n6. **감귤밭**（柑橘园）\n   - 例句：봄이 되면 감귤밭에 꽃이 만발합니다. (春天来临时，柑橘园里开满了花。)\n\n7. **감귤껍질**（柑橘皮）\n   - 例句：감귤껍질로 장식을 만들 수 있습니다. (可以用柑橘皮做装饰品。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1723, 72, '키위 ', ' 猕猴桃', '### 1.词性：\n- **명사 (名词)**\n\n### 2.词义：\n- **키위**：\n  1. **猕猴桃**（一种水果）\n  2. **新西兰人**（常用于口语中，指新西兰国民或居民）\n  3. **“kiwi”**（其他含义，如品牌名、特定事物等，根据具体语境而定）\n\n### 3.例句：\n1. **作为“猕猴桃”**：\n   - 저는 키위를 아주 좋아해요.（我很喜欢吃猕猴桃。）\n   - 이 과일은 키위인데 맛이 아주 달답니다.（这种水果是猕猴桃，味道很甜。）\n2. **作为“新西兰人”**：\n   - 저 기사는 키위 기자입니다.（那位记者是新西兰人。）\n   - 이번 올림픽에서 키위 선수들이 좋은 성적을 거뒀어요.（在这次奥运会上，新西兰选手们取得了好成绩。）\n\n### 变形及词义、例句：\n- **复数形式**：키위들\n  - **词义**：多个猕猴桃 / 多个新西兰人\n  - **例句**：\n    - 상자에 많은 키위들이 들어 있습니다.（箱子里有很多猕猴桃。）\n    - 이곳에는 여러 명의 키위들이 여행을 왔어요.（这里来了好几名新西兰人旅游。）\n\n- **所有格形式**：키위의\n  - **词义**：猕猴桃的 / 新西兰人的\n  - **例句**：\n    - 키위의 씨는 조금 불편해요.（猕猴桃的籽有点麻烦。）\n    - 키위의 문화는 매우 독특해요.（新西兰的文化很独特。）\n\n- **动词化（较少直接使用，但可通过添加后缀构成相关动词，如“키위를 먹다”（吃猕猴桃）、“키위를 수확하다”（收获猕猴桃）等）**\n  - **词义**：吃猕猴桃 / 收获猕猴桃等与猕猴桃相关的动作行为\n  - **例句**：\n    - 저는 매일 아침 키위를 먹곤 합니다.（我每天早上都吃猕猴桃。）\n    - 농부들은 가을에 키위를 수확합니다.（农民们在秋天收获猕猴桃。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1724, 72, '파인애플 ', ' 菠萝', '### 1.词性：\n名词 (명사)\n\n### 2.词义：\n- 菠萝（一种热带水果）\n- （口语中有时也指）菠萝图案或菠萝形状的东西\n\n### 3.例句：\n- **파인애플을 좋아하세요?** （您喜欢菠萝吗？）\n- **나는 파인애플 주스를 마시고 싶다.** （我想喝菠萝汁。）\n\n### 变形及其词义与例句：\n\n1. **변형: 파인애플나무**\n   - **词义**：菠萝树（指菠萝植物本身）\n   - **例句**：**우리 집 앞엔 파인애플나무가 있어요.** （我家门前有棵菠萝树。）\n\n2. **변형: 파인애플맛**\n   - **词义**：菠萝味（指菠萝的味道或风味）\n   - **例句**：**이 캔디는 파인애플맛이에요.** （这个糖果是菠萝味的。）\n\n注意：在韩语中，“파인애플”作为一个外来词（来自英语“pineapple”），其变形并不像纯韩语词汇那样丰富和规则。上述变形更多是基于语境和表达需要而自然形成的，并非严格意义上的语法变形。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1725, 72, '체리 ', ' 樱桃', '### 체리\n\n#### 1. 词性：  \n**명사 (名词)**  \n\n#### 2. 词义：  \n- **자연어**：체리는 \"체리나무의 열매\"（樱桃的果实） 또는 \"체리나무\"（樱桃树）를 의미합니다.  \n- **인공어**：인터넷 용어에서 \"체리\"는 \"귀엽거나 사랑스러운 대상\"（可爱的事物或人）을 비유적으로 표현하는 단어로 쓰입니다.  \n\n#### 3. 例句：  \n1. **자연어**：  \n   저는 체리가 아주 좋아요.（我很喜欢樱桃。）  \n2. **인공어**：  \n   그녀는 진짜 체리 같다.（她真的很可爱。）  \n\n---\n\n#### 변형 및 어법：  \n1. **복수형**：체리들  \n   - **뜻**：많은 체리 또는 체리들을 일컬 때 사용됩니다.  \n   - **예문**：  \n     체리들이 나무에 주렁주렁 달려 있다.（樱桃们挂满了树。）  \n\n2. **속성사합성어**：체리맛（樱桃味）  \n   - **뜻**：체리의 맛을 나타내는 형용사적 표현입니다.  \n   - **예문**：  \n     이 과자는 체리맛이 난다.（这个零食有樱桃味。）  \n\n3. **목적어합성어**：체리주스（樱桃汁）  \n   - **뜻**：체리를 재료로 만든 음료수를 의미합니다.  \n   - **예문**：  \n     여름에 체리주스를 마시면 시원해요.（夏天喝樱桃汁很清爽。）  \n\n4. **활용된 표현**：체리피킹（ cherry picking，선별하는 행위）  \n   - **뜻**：좋은 것만 골라내는 행동을 비유적으로 표현합니다.  \n   - **예문**：  \n     시험 문제 중에 체리피킹 하는 것 같다.（考试题目中好像在挑简单的。）  \n\n---\n\n### 정리  \n- **체리**는 자연어에서 \"복숭아\"를, 인공어에서 \"사랑스러운 대상\"을 의미합니다.  \n- 변형으로는 복수형, 속성사합성어, 목적어합성어 등이 있으며, 비유적인 표현으로도 활용됩니다.', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1726, 72, '라즈베리 ', ' 覆盆子', '### 라즈베리\n\n#### 1. 词性：\n- 명사 (名词)\n\n#### 2. 词义：\n- 라즈베리（覆盆子，一种水果）\n- 라즈베리 맛（覆盆子味道，常用于描述食品或饮料的风味）\n- 라즈베리 색（覆盆子的红色，常用于描述颜色）\n\n#### 3. 例句：\n1. 저는 라즈베리가 들어간 잼을 좋아해요.  \n   （我喜欢含有覆盆子的果酱。）\n2. 이 케이트는 라즈베리 향이 나서 정말 맛있어요.  \n   （这个蛋糕有覆盆子的香味，非常好吃。）\n\n#### 4. 变形及其词义和例句：\n\n##### 라즈베리 (名词)\n- **라즈베리**：覆盆子  \n  - 例：라즈베리는 건강에 좋은 과일이에요.  \n    （覆盆子是对健康有益的水果。）\n\n##### 라즈베리맛 (复合名词)\n- **라즈베리맛**：覆盆子味道  \n  - 例：이 음료는 라즈베리맛이 강해요.  \n    （这种饮料覆盆子的味道很浓。）\n\n##### 라즈베리색 (复合名词)\n- **라즈베리색**：覆盆子的红色  \n  - 例：그녀의 입술은 라즈베리색으로 빛났어요.  \n    （她的嘴唇呈现出覆盆子的红色。）\n\n##### 라즈베리파이 (复合名词)\n- **라즈베리파이**：覆盆子派  \n  - 例：오늘은 라즈베리파이를 만들었어요.  \n    （今天做了覆盆子派。）\n\n##### 라즈베리농장 (复合名词)\n- **라즈베리농장**：覆盆子农场  \n  - 例：우리는 라즈베리농장에 가서 직접 따봤어요.  \n    （我们去了覆盆子农场并亲自采摘了覆盆子。）\n\n##### 라즈베리쨈 (复合名词)\n- **라즈베리쨈**：覆盆子果酱  \n  - 例：빵에 라즈베리쨈을 발라 먹으면 맛있어요.  \n    （在面包上涂覆盆子果酱吃很好吃。）\n\n##### 라즈베리주스 (复合名词)\n- **라즈베리주스**：覆盆子汁  \n  - 例：라즈베리주스를 넣으니 음료가 더 새로워졌어요.  \n    （加入覆盆子汁后，饮料变得更加清爽了。）\n\n##### 라즈베리셰イ크 (复合名词)\n- **라즈베리셰이크**：覆盆子奶昔  \n  - 例：여름에 라즈베리셰이크를 마시면 시원해요.  \n    （夏天喝覆盆子奶昔很凉爽。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1727, 72, '흑미과일 ', ' 黑莓', '### 1.词性：\n**名词（Noun）**\n\n### 2.词义：\n- **基本含义**：黑米与水果的组合，通常指以黑米和水果为原料制成的食物、饮品，或两者混合的食材。  \n- **引申含义**：可泛指含有黑米和水果成分的食品，如黑米水果饭、黑米水果粥、黑米水果茶等。\n\n### 3.例句：\n1. **흑미과일로 만든 주스는 건강에 아주 좋다.**  \n   （用黑米和水果制成的果汁对健康非常有益。）  \n2. ** 이번에 출시한 흑미과일 요거트가 인기가 많아요.**  \n   （这次推出的黑米水果酸奶很受欢迎。）\n\n---\n\n### 变形及词义（派生词）：\n\n#### 1. **흑미과일즙（名词）**  \n   - **词义**：黑米与水果的混合果汁。  \n   - **例句**：  \n     **흑미과일즙을 매일 한잔씩 마시면 피부에 좋아요.**  \n     （每天喝一杯黑米水果果汁对皮肤好。）\n\n#### 2. **흑미과일요거트（名词）**  \n   - **词义**：添加黑米和水果的酸奶。  \n   - **例句**：  \n     **식탁에 흑미과일요거트를 놓았더니孩子们들이 좋아하네요.**  \n     （把黑米水果酸奶放在桌上后，孩子们很喜欢。）\n\n#### 3. **흑미과일떡（名词）**  \n   - **词义**：用黑米和水果制作的年糕或糕点。  \n   - **例句**：  \n     **흑미과일떡은 달고 향이 풍부해서 선물로 제격이에요.**  \n     （黑米水果年糕又甜又香，适合作为礼物。）\n\n#### 4. **흑미과일샐러드（名词）**  \n   - **词义**：混合黑米和水果的沙拉。  \n   - **例句**：  \n     **점심으로 흑미과일샐러드를 먹으니 상쾌해요.**  \n     （午餐吃黑米水果沙拉，感觉神清气爽。）\n\n---\n\n### 说明：\n- **흑미과일** 是复合名词，由 **흑미（黑米）** 和 **과일（水果）** 组合而成，通常用于描述两者结合的食品或食材。  \n- 变形词多为具体产品名称（如果汁、酸奶、年糕等），需根据实际语境使用。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1728, 72, ' 감 ', ' 柿子', '1. 词性：名词\n2. 词义：\n   - 感（觉）\n   - 感触\n   - 感想\n   - 感情\n   - 感受\n   - （物体的）感觉，触感\n3. 例句：\n   - 감이 좋다.（感觉很好。）\n   - 그녀는 음악에 대한 감이 뛰어났다.（她对音乐的感觉非常敏锐。）\n\n所有变形及其词义，每个变形一个例句：\n\n1. 감기 (感冒)\n   - 병원에 가서 감기를 고쳐야겠다.（得去医院治感冒了。）\n\n2. 감동 (感动)\n   - 그의 말은 나를 deeply 감동시켰다.（他的话深深感动了我。）\n\n3. 감정 (感情)\n   - 그는 화를 내면서도 감정을 잘 조절했다.（他虽然生气，但很好地控制了感情。）\n\n4. 감각 (感觉)\n   - 시력은 회복되었지만, 감각은 아직 없어요.（视力恢复了，但感觉还没有。）\n\n5. 감사 (感激)\n   - 당신의 도움에 대해 진심으로 감사드립니다.（真心感谢您的帮助。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1729, 72, ' 감귤 ', ' 柑橘', '### 감귤 (Gamgyul)\n\n#### 1. 词性：  \n**名词**（명사, 명사）\n\n#### 2. 词义：  \n- **柑橘类水果**，特指韩国常见的柑橘品种（如橘子、橙子等）。  \n- **柑橘属植物**（如柑橘树或其果实）。\n\n#### 3. 例句：  \n1. 겨울에 제주도에서 감귤을 먹으니 참 맛있네요.  \n   （冬天在济州岛吃柑橘，真好吃。）  \n2. 후배가 감귤을 선물로 보내 주었어요.  \n   （后辈送了柑橘作为礼物。）\n\n---\n\n### 变形及词义（派生词）：\n\n#### 1. **감귤나무** (Gamgyulnamu)  \n   - **词义**：柑橘树。  \n   - **例句**：우리 집 앞엔 감귤나무가 있어요.  \n     （我家门前有棵柑橘树。）\n\n#### 2. **감귤농장** (Gamgyulnongjang)  \n   - **词义**：柑橘农场。  \n   - **例句**：제주는 감귤농장이 많은데요.  \n     （济州岛有很多柑橘农场。）\n\n#### 3. **감귤즙** (Gamgyuljup)  \n   - **词义**：柑橘汁。  \n   - **例句**：새벽에 현탁한 감귤즙이 최고예요.  \n     （现榨的柑橘汁最好喝。）\n\n---\n\n### 总结：\n- **감귤** 是名词，指柑橘类水果或植物。  \n- 变形词通过复合名词（**감귤 + 다른 단어**）构成，表示与柑橘相关的事物（树、农场、汁等）。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1730, 72, ' 키위 ', ' 猕猴桃', '1. 词性：名词\n2. 词义：\n   - 猕猴桃（一种水果）\n   - （口语中有时可引申指代新西兰，因新西兰是猕猴桃的原产地之一且其国鸟是几维鸟，“키위”在韩语里也有新西兰的意思）\n3. 例句：\n   - 저는 키위를 아주 좋아합니다.（我很喜欢猕猴桃。）\n   - 그는 키위에 다녀왔다면서 재미있다고 했다.（他说去了新西兰，很有意思。）\n\n变形及词义、例句：\n- 키위로（以“猕猴桃”或“新西兰”相关，如表示方向、方式等，这里较难有典型常用变形，硬要举例类似“向猕猴桃方向”等抽象用法，但实际很少这样用，只是为了展示变形形式）\n  - 예: 나는 키위로 걸어갔다.（我朝着猕猴桃那边走去。——这种句子在实际使用中很奇怪，只是为了满足变形示例需求，正常很少这么说）\n\n韩语中“키위”主要就是名词用法，常见的就是上述“猕猴桃”“新西兰”相关含义，其变形在实际语言运用中并不常见且很多变形后的用法比较生硬、不自然，所以能列举的典型有用变形较少。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1731, 72, ' 파파야 ', ' 木瓜', '### 파파야 (papaya)\n\n#### 1. 词性：  \n**명사 (名词)**\n\n#### 2. 词义：  \n- **파파야**：木瓜（一种热带水果，也指植物本身）。  \n- **변형**：无其他常用变形，但可与其他词组合使用（如 **파파야 주스** = 木瓜汁）。\n\n#### 3. 例句：  \n1. **과일에 파파야가 있네요**.  \n   （水果中有木瓜呢。）  \n2. **파파야는 위장 건강에 좋대요**.  \n   （木瓜对肠胃健康有好处。）\n\n---\n\n### 변형 및 용례 (变形及例句)：  \n1. **파파야나무**（木瓜树）  \n   - **용례**：우리 집 앞에 파파야나무가 자라고 있어요.  \n     （我家门前种着木瓜树。）  \n\n2. **파파야꽃**（木瓜花）  \n   - **용례**：파파야꽃은 흰색이고 향기가 좋아요.  \n     （木瓜花是白色的，而且很香。）  \n\n3. **파파야즙**（木瓜汁）  \n   - **용례**：파파야즙을 매일 마시면 피부에 좋다고요.  \n     （每天喝木瓜汁对皮肤好。）  \n\n4. **파파야씨**（木瓜籽）  \n   - **용례**：파파야씨는 약으로도 쓰인대요.  \n     （木瓜籽也可以入药。）  \n\n5. **파파야샐러드**（木瓜沙拉）  \n   - **용례**：태국 요리에서 파파야샐러드를 많이 먹어요.  \n     （泰国菜中常吃木瓜沙拉。）  \n\n---\n\n### 설명  \n- **파파야** 是外来语（出自西班牙语 *papayo*），在韩语中固定为名词，没有动词或形容词的变形。  \n- 其变形多为复合名词（如 **파파야나무**、**파파야즙**），表示与木瓜相关的事物或加工品。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1732, 72, ' 배 ', ' 梨', '1. 词性：名词\n2. 词义：\n   - 船\n   - 梨（特指韩国梨，与苹果等其他水果区分）\n3. 例句：\n   - 배가 항해를 시작했습니다. （船开始了航行。）\n   - 저는 배를 무척 좋아합니다. （我非常喜欢梨。）\n\n**变形及其词义与例句**：\n\n1. **배** 的变形较少，但可以通过与其他词汇结合形成新的词汇或短语。例如：\n\n   - **배 타기**（乘船）\n     - 例：우리는 배 타기를 즐겼습니다. （我们享受了乘船的乐趣。）\n\n   - **배나무**（梨树）\n     - 例：배나무 아래서 휴식을 취했습니다. （我们在梨树下休息了。）\n\n   - **배즙**（梨汁）\n     - 例：배즙이 아주 상큼해요. （梨汁非常清爽。）\n\n   注意，这些变形并不是“배”本身的变形，而是“배”作为词根与其他词汇结合形成的新词。在韩语中，“배”本身作为一个独立的单词，其变形并不如英语或其他语言那样丰富，它主要通过与其他词汇的组合来扩展其含义和用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1733, 72, ' 오렌지 ', ' 橙子', '### 1.词性：\n- 명사（名词）\n\n### 2.词义：\n- 橙子（作为一种水果）\n- 橘黄色（颜色）\n\n### 3.例句：\n- 저는 오렌지를 무척 좋아합니다.（我非常喜欢橙子。）\n- 이 옷은 오렌지색이네요.（这件衣服是橘黄色的。）\n\n### 变形及词义、例句：\n\n#### 오렌지주스（橙汁）\n- **词义**：用橙子榨出的汁液\n- **例句**：오렌지주스를 한 잔 줄까요?（要来一杯橙汁吗？）\n\n#### 오렌지색（橘黄色）\n- **词义**：类似橙子表皮的颜色，即橘黄色\n- **例句**：그 그림의 주된 색상은 오렌지색이에요.（那幅画的主要颜色是橘黄色。）\n\n#### 복수형：오렌지들\n- **词义**：表示多个橙子\n- **例句**：바구니에 오렌지들이 가득해요.（篮子里装满了橙子。）\n\n#### 형용사형：오렌지 같은\n- **词义**：像橙子一样的（可形容形状、颜色等类似橙子的特征）\n- **例句**：그녀는 오렌지 같은 밝은 머리칼을 가지고 있어요.（她有着像橙子一样明亮的头发颜色。）', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1746609293826.mp3');
INSERT INTO `word_list` VALUES (1734, 72, ' 피망 ', ' 辣椒（注：虽然辣椒不是水果，但在韩语中“피망”通常指甜椒，这里为了多样性而列出，实际使用时可根据需要替换为其他确切的水果单词）', '1.词性：名词\n2.词义：\n- 青椒（常见的蔬菜，通常为绿色，也有红色等品种）\n3.例句：\n- 저는 피망을 많이 먹어요.（我吃很多青椒。）\n- 시장에 가서 피망을 사 왔습니다.（去市场买了青椒回来。）\n\n变形及词义、例句：\n- 피망이（青椒的宾格形式，用于句子中作宾语时使用）\n    - 저는 피망이를 좋아합니다.（我喜欢青椒。）\n- 피망의（青椒的属格形式，表示所属关系等）\n    - 피망의 씨앗은 작은 편입니다.（青椒的种子比较小。）\n- 피망을（青椒的宾格形式，用于一些动词前的连接等情况）\n    - 저는 피망을 잘라서 넣었습니다.（我把青椒切了放进去。）', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1746609300921.mp3');
INSERT INTO `word_list` VALUES (1735, 72, ' 복숭아 ', ' 桃子', '1. 词性：名词（명사）\n2. 词义：桃子；桃树\n3. 例句：\n   - 저는 복숭아를 아주 좋아합니다. 我非常喜欢桃子。\n   - 우리 집 앞에 복숭아나무가 있습니다. 我家门前有棵桃树。\n\n**变形及其词义与例句：**\n\n1. **복숭앗**（假设形式，用于间接引语或条件句中，表示“如果/要是桃子……”，但此变形在实际使用中较为罕见且不自然，更多是理论上的变形，实际交流中通常不会这样使用）\n   - *불 자연스러운 표현이지만, 이론상 가능하다.* 这是一个不自然的表达，但理论上是可能的。\n   - 예: 그분이 복숭앗다면, 많이 드실 텐데. （如果那是桃子的话，他应该会吃很多。）*注意：此句仅为展示变形而造，实际交流中几乎不用。*\n\n2. **복숭이**（错误变形，韩语中并无此变形，正确的复数形式应为“복숭아들”，但“복숭아”作为水果名称，通常不强调复数形式，直接使用原形即可表示多个桃子）\n   - *사실한 표현은 아닙니다.* 这不是一个实际存在的表达。\n   - 정확한 표현: 여기 복숭아들이 참 많아요. 这里的桃子真多。\n\n3. **복숭아꽃**（复合名词，词义：桃花，由“복숭아”+“꽃”组成）\n   - 예: 복숭아꽃이 만발했습니다. 桃花盛开了。\n\n4. **복숭아씨**（复合名词，词义：桃核/桃籽，由“복숭아”+“씨”组成）\n   - 예: 복숭아씨를 뱉어 주세요. 请吐出桃核。\n\n5. **복숭아맛**（复合名词，词义：桃子的味道，由“복숭아”+“맛”组成）\n   - 예: 이 잼에는 복숭아맛이 난다. 这个果酱有桃子的味道。\n\n6. **복숭아색**（复合名词，词义：桃色/桃子的颜色，由“복숭아”+“색”组成，但更常用的表达是“분홍색”或“복숭화색”来指代桃红色）\n   - 예: 그녀는 복숭아색 스카프를 했다. 她戴了一条桃色的围巾。（尽管这种表达不是最典型的，但在某些语境下可以理解）\n\n7. **복숭아농장**（复合名词，词义：桃园，由“복숭아”+“농장”组成）\n   - 예: 우리는 복숭아농장을 견학갔다. 我们参观了桃园。\n\n8. **복숭아쨈**（复合名词，词义：桃子果酱，由“복숭아”+“쨈”组成）\n   - 예: 아침에 토스트에 복숭아쨈을 발라 먹어요. 早上我在吐司上涂桃子果酱吃。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1736, 72, ' 체리 ', ' 樱桃', '1.词性：名词\n2.词义：樱桃；樱桃色\n3.例句：\n- 체리가 제철입니다.（樱桃正当季。）\n- 그녀의 입술은 체리색이에요.（她的嘴唇是樱桃色的。）\n\n变形及词义、例句：\n- 체리색（名词）：樱桃色\n    -例句：그 화장품은 체리색을 내는데요.（那个化妆品能打造出樱桃色哦。）\n- 체리맛（名词）：樱桃的味道\n    -例句：이 잼에는 체리맛이 진해요.（这个果酱樱桃味很浓。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1737, 72, ' 살구 ', ' 杏', '### 1. 词性：\n**名词 (명사)**\n\n---\n\n### 2. 词义：\n- **杏子、杏树**（指植物或其果实）\n- **杏色**（一种淡红色或浅粉色，如“살구색”）\n\n---\n\n### 3. 例句：\n1. **과수원에 살구나무가 많이 있습니다.**  \n   （果园里有很多杏树。）  \n2. **그녀는 살구색 스카프를 메고 있습니다.**  \n   （她戴着一条杏色的围巾。）\n\n---\n\n### 变形及词义：\n\n#### 1. **살구색**  \n   - **词义**：杏色（浅红或淡粉色）  \n   - **例句**：**벽지 색깔이 살구색으로 되어 있어 따뜻한 분위기입니다.**  \n     （壁纸是杏色的，氛围很温暖。）\n\n#### 2. **살구나무**  \n   - **词义**：杏树（名词，复合词）  \n   - **例句**：**뒷뜰에 살구나무를 심었습니다.**  \n     （在后院种了一棵杏树。）\n\n#### 3. **살구꽃**  \n   - **词义**：杏花（名词，复合词）  \n   - **例句**：**살구꽃이 피기 시작했습니다.**  \n     （杏花开始开了。）\n\n#### 4. **살구잼**  \n   - **词义**：杏酱（名词，复合词）  \n   - **例句**：**빵에 살구잼을 발라 먹습니다.**  \n     （在面包上涂杏酱吃。）\n\n---\n\n### 总结：\n- **살구** 是名词，核心词义为“杏子/杏树”，也可衍生出颜色（살구색）或复合词（如살구나무, 살구꽃等）。  \n- 变形后多为复合名词，表示与“杏”相关的具体事物。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1738, 114, ' 지진 ', ' 地震', '### 1. 지진 的词性\n**名词（명사）**\n\n---\n\n### 2. 词义\n- **自然现象**：地震（地球内部能量释放导致的地面震动）。\n- **比喻义**：剧烈动摇或动荡（如社会、组织等发生重大变化时的隐喻）。\n\n---\n\n### 3. 例句\n1. **自然现象**  \n   **예문**：지진이 나서 집이 흔들렸어요.  \n   （地震导致房子摇晃。）  \n\n2. **比喻义**  \n   **예문**：그 사건으로 회사에 지진이 일어났다.  \n   （那件事引发公司剧烈动荡。）\n\n---\n\n### 4. 变形及词义\n#### (1) **지진 → 지진이**  \n- **变形类型**：主格助词 \"이\" 添加，作主语。  \n- **词义**：地震（作为句子的主语）。  \n- **例句**：지진이 날 때 동물들이 이상 행동을 보인다.  \n  （地震发生时，动物会异常行动。）\n\n#### (2) **지진 → 지진을**  \n- **变形类型**：宾格助词 \"을\" 添加，作宾语。  \n- **词义**：地震（作为句子的宾语）。  \n- **例句**：科學家들은 지진을 연구한다.  \n  （科学家们研究地震。）\n\n#### (3) **지진 → 지진도**  \n- **变形类型**：添加副词性助词 \"도\"，表示“即使地震”。  \n- **词义**：用于假设或让步语境（即使发生地震）。  \n- **例句**：지진이라도 안전한 곳으로 대피하세요.  \n  （即使地震，也要逃到安全的地方。）\n\n#### (4) **지진 → 지진이 나다**  \n- **变形类型**：动词短语搭配（发生地震）。  \n- **词义**：地震发生。  \n- **例句**：여기는 지진이 자주 나요.  \n  （这里经常发生地震。）\n\n---\n\n### 总结\n- **词性**：名词  \n- **核心词义**：地震（自然现象）或动荡（比喻）。  \n- **变形**：通过助词或搭配动词扩展语法功能，但词根意义不变。', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1746613263676.mp3');
INSERT INTO `word_list` VALUES (1739, 114, ' 변성암 ', ' 变质岩', '### 1.词性：\n名词（명사）\n\n### 2.词义：\n**변성암** 是由两个韩语单词组成的复合名词，**변성**（变性）和 **암**（岩/岩石）。在地质学中，它指经过变质作用形成的岩石，即“变质岩”。具体词义如下：\n- **변성암**：经过高温、高压或化学作用，原有岩石（如沉积岩、火成岩）发生物理或化学变化而形成的新岩石。\n\n### 3.例句：\n1. **변성암은 높은 온도와 압력 아래 원래의 암석이 변질되어 생성된 것이다.**  \n   （变质岩是在高温和高压下，原有岩石变质而形成的。）\n\n2. **그 지역의 지층에는 다양한 변성암들이 관찰된다.**  \n   （该地区的地层中可以观察到各种变质岩。）\n\n---\n\n### 变形及其词义与例句：\n#### 1. **변성**（名词 → 动词）\n- **词义**：变性，指物质或性质发生变化的过程。\n- **例句**：**물질의 변성을 연구하는 데 여러 가지 방법이 사용된다.**  \n  （研究物质的变性过程中使用了多种方法。）\n\n#### 2. **암**（单独使用）\n- **词义**：岩石，泛指未经特定说明的岩石。\n- **例句**：**이 산맥은 주로 화산암으로 구성되어 있다.**  \n  （这个山脉主要由火山岩构成。）\n\n#### 3. **변성암류**（변성암 +류，类别名词）\n- **词义**：变质岩类，指变质岩的类别或类型。\n- **例句**：**변성암류는 지각 운동의 역사를 기록하는 중요한 증거이다.**  \n  （变质岩类是记录地壳运动历史的重要证据。）\n\n#### 4. **변성작용**（변성 +작용，名词）\n- **词义**：变质作用，指岩石在高温、高压等条件下发生变质的过程。\n- **例句**：**변성작용은 새로운 암석을 생성시키는 과정이다.**  \n  （变质作用是生成新岩石的过程。）\n\n---\n\n### 总结：\n- **변성암** 是地质学术语，特指变质岩。\n- 其变形包括动词 **변성**、名词 **암**、类别名词 **변성암류** 和过程名词 **변성작용**，均与地质学或物质变化相关。', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1746609399475.mp3');
INSERT INTO `word_list` VALUES (1740, 114, ' 빙성설 ', ' 冰成说', '### 1. 词性：\n**빙성설** 是一个 **名词**，通常用于表示某种特定的理论或学说。\n\n### 2. 词义：\n- **冰成说**（빙성설）：一种地质学理论，认为某些地貌特征是由冰川作用形成的。\n- **冰川说**（빙성설）：与冰成说类似，强调冰川在地貌形成中的作用。\n\n### 3. 例句：\n1. **빙성설에 따르면, 이 산맥은 수백만 년 전에 형성된 빙하의 영향으로 만들어졌다.**  \n   （根据冰成说，这座山脉是数百万年前冰川的影响下形成的。）\n2. **학자들은 이 지역의 지형이 빙성설을 통해 설명될 수 있다고 주장한다.**  \n   （学者们主张，这个地区的地形可以通过冰成说来解释。）\n\n---\n\n### 变形及其词义：\n1. **빙성설적**（氷成説的）  \n   - 词义：与冰成说相关的，具有冰成说特征的。  \n   - 例句：**빙성설적인 해석은 이 현상을 더 잘 이해하게 한다.**  \n     （冰成说的解释能更好地理解这一现象。）\n\n2. **빙성설로**（以冰成说）  \n   - 词义：以冰成说的方式或角度。  \n   - 例句：**빙성설로 보면, 이 땅의 모양은 오래된 빙상의 결과이다.**  \n     （以冰成看来，这片土地的形状是古老冰山的结果。）\n\n3. **빙성설을**（冰成说）  \n   - 词义：作为宾语使用，表示冰成说这一理论。  \n   - 例句：**연구자들은 빙성설을 통해 새로운 지질학 이론을 발전시켰다.**  \n     （研究者通过冰成发展了新的地质学理论。）\n\n4. **빙성설의**（冰成说的）  \n   - 词义：表示所属关系，即冰成说的。  \n   - 例句：**빙성설의 견해는 현대 지질학에서広く 받아들여진다.**  \n     （冰成说的观点在现代地质学中被广泛接受。）\n\n---\n\n### 总结：\n- **词性**：名词  \n- **常用词义**：冰成说、冰川说  \n- **变形**：빙성설적、빙성설로、빙성설을、빙성설의  \n- **例句**：均用韩语书写，展示不同变形的用法。', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1746609404486.mp3');
INSERT INTO `word_list` VALUES (1741, 114, ' 판구조론 ', ' 板块构造论', '无法从大模型获取数据，请联系管理员！', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1742, 114, ' 퇴적암 ', ' 沉积岩', '1. 词性：名词\n2. 词义：沉积岩\n3. 例句：\n   - 이 지역은 다양한 종류의 퇴적암으로 유명하다.（这个地区以各种各样的沉积岩而闻名。）\n   - 지질학자들은 그곳의 퇴적암을 연구하고 있다.（地质学家们在研究那里的沉积岩。）\n\n变形及词义、例句：\n- 复数形式：퇴적암들\n  - 词义：沉积岩们（表示多个沉积岩）\n  - 例句：해변에는 많은 퇴적암들이 쌓여 있었다.（海边堆积了很多沉积岩。）\n- 所有格形式：퇴적암의\n  - 词义：沉积岩的\n  - 例句：퇴적암의 특성은 매우 독특하다.（沉积岩的特性非常独特。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1743, 114, ' 지질 ', ' 地质', '1.词性：\n名词\n\n2.词义：\n- 地质，地质情况（指地球的物质组成、结构、性质等相关内容）\n\n3.例句：\n- 지질학자는 지질을 연구하여 땅속의 비밀을 밝힙니다.（地质学家研究地质来揭示地下的秘密。）\n- 이 지역의 지질은 매우 복잡하여 채굴이 어렵습니다.（这个地区的地质非常复杂，开采很困难。）\n\n变形及词义、例句：\n- 지질학（名词）：地质学\n例句：그는 지질학 분야에서 뛰어난 업적을 이루었습니다.（他在地质学领域取得了出色的业绩。）\n- 지질연구소（名词）：地质研究所\n例句：지질연구소에서는 새로운 지질탐사 기술을 개발하고 있습니다.（地质研究所正在研发新的地质勘探技术。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1744, 114, ' 풍화작용 ', ' 风化作用', '1. 词性：名词\n2. 词义：风化作用（指岩石等在自然因素作用下发生的物理、化学变化过程）\n3. 例句：\n- 풍화작용은 지질학에서 매우 중요한 과정이다.（风化作用在地质学中是非常重要的过程。）\n- 이 지역의 돌들은 오랜 풍화작용을 거쳤습니다.（这个地区的石头经历了长期的风化作用。）\n\n**变形及词义、例句**：\n- **변형**：풍화적（形容词形式，用于描述与风化作用相关的性质或特征）\n  - **词义**：风化的，与风化作用有关的\n  - **例句**：이곳의 토양은 풍화적인 특성이 강합니다.（这里的土壤风化特性很强。）\n- **변형**：풍화되다（动词形式，表示被风化）\n  - **词义**：被风化，发生风化作用\n  - **例句**：바위가 오랜 시간 동안 풍화되었습니다.（岩石经过长时间被风化了。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1745, 114, ' 지각 ', ' 地壳', '1.词性：名词\n2.词义：迟到、睡过头、误时\n3.例句：\n- 지각을 하지 않도록 아침에 일찍 기상해야 합니다.（为了不迟到，早上要早点起床。）\n- 그는 자주 지각을 해서 회사에서 주의를 받았습니다.（他经常迟到，所以在公司受到了警告。）\n\n变形及词义、例句：\n- 지각생（迟到的学生）：지각생은 교실에 늦게 들어왔습니다.（迟到的学生晚进了教室。）\n- 지각대（迟到的队伍）：지각대가 길을 막고 있습니다.（迟到的队伍把路堵住了。）\n- 지각하기（迟到）：그는 항상 지각하기 때문에 다른 사람들을 불편하게 합니다.（他总是迟到，所以给别人带来了不便。）\n- 지각한（迟到的，形容词形式）：지각한 사람은 벌을 받아야 합니다.（迟到的人应该受到惩罚。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1746, 114, ' 지망경 ', ' 罗盘', '### 1.词性：\n- **名词**\n\n### 2.词义：\n- “志向、志愿；抱负”\n\n### 3.例句：\n- 그는 웅대한 지망경을 가지고 사업에 뛰어들었다.（他怀揣着宏伟的志向投身到了事业当中。）\n- 젊은 시절부터 높은 지망경을 품고 노력해왔다.（从年轻的时候起就怀揣着高远的志向一直努力着。）\n\n### 变形及词义、例句：\n- **지망**（名词，“志愿、志向”的略称）：그는 군인이 되는 것이 그의 지망이다.（他当军人是他的志愿。）\n- **지망하다**（动词，“有志向、立志”）：그는 젊어서부터 과학자를 지망헀다.（他从小就立志要成为科学家。）\n- **지망스러운**（形容词，“有志向的、志向远大的”）：그는 지망스러운 청년이다.（他是个有志向的青年。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1747, 114, ' 침식작용 ', ' 侵蚀作用', '1. 词性：名词\n2. 词义：侵蚀作用、腐蚀作用（指自然力量如风、水等对物体表面的磨损、破坏过程）\n3. 例句：\n   - 바닷물의 침식작용으로 해안 석회암이 특이한 모양을 지녔다. （海水的侵蚀作用使海岸石灰岩呈现出奇特的形状。）\n   - 강풍은 모래 바람을 일으켜 사막화 지역의 침식작용을 가속화시켰다. （狂风掀起沙尘，加速了沙漠化地区的侵蚀作用。）\n\n所有变形及其词义和例句：\n\n* 注意：韩语中“침식작용”作为一个复合名词，其变形不像简单动词或形容词那样直接。不过，我们可以探讨其可能的派生词或相关表达方式，但这些并不严格意义上属于“变形”。以下是一些与“침식작용”相关的表达：\n\n1. **침식** (名词)\n   - 词义：侵蚀、腐蚀\n   - 例句：바위의 침식은 수천 년 동안에 걸쳐 일어난 자연 현상이다. （岩石的侵蚀是经过数千年发生的自然现象。）\n\n2. **침식되다** (被动词)\n   - 词义：被侵蚀、被腐蚀\n   - 例句：이 지역의 토양은 강수로 인해 심하게 침식되었다. （这个地区的土壤因降雨而受到严重侵蚀。）\n\n3. **침식제** (名词)\n   - 词义：侵蚀剂（通常指化学上用于腐蚀的物质，但在此上下文中可能不常用）\n   - 例句：화학 실험에서 이 물질은 강한 침식제로 사용된다. （在化学实验中，这种物质被用作强侵蚀剂。）（注：此例句更偏向化学领域，与自然侵蚀作用不完全相关）\n\n4. **침식작용을 당하다** (短语)\n   - 词义：遭受侵蚀作用\n   - 例句：옛 석조 건축물은 오랜 시간 동안风雨의 침식작용을 당해 훼손되었다. （古老的石造建筑长时间遭受风雨的侵蚀作用而损坏。）\n\n请注意，上述“变形”并非严格意义上的词形变化，而是与“침식작용”相关的不同表达方式。在韩语中，复合名词的“变形”通常涉及添加前缀、后缀或改变词序来形成新的词汇或短语，而不是像英语那样的词尾变化。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1748, 114, ' 화산 ', ' 火山', '1. 词性：名词（noun）\n2. 词义：\n   - 火山\n   - （因爆发而形成的）山\n3. 例句：\n   - 화산이 폭발했습니다.（火山爆发了。）\n   - 그곳은 유명한 화산지역이다.（那里是著名的火山地区。）\n\n所有变形及其词义和例句：\n\n**화산**（基本形态）\n- 词义：火山\n- 例句：화산은 지구의 자연현상 중 하나이다.（火山是地球的自然现象之一。）\n\n**화산폭발**（复合名词，由“화산”+“폭발”组成）\n- 词义：火山爆发\n- 例句：화산폭발로 많은 사람이 피해를 입었다.（由于火山爆发，很多人受到了伤害。）\n\n**화산灰**（复合名词，由“화산”+“灰”组成，虽然“灰”在韩语中通常写作“회”，但此处为说明变形，采用直译）\n- 词义：火山灰\n- 例句：화산灰가 공기를 오염시켰다.（火山灰污染了空气。）\n\n**화산섬**（复合名词，由“화산”+“섬”组成，意为“火山岛”）\n- 词义：火山岛\n- 例句：제주도는 화산섬이다.（济州岛是一座火山岛。）\n\n**화산활동**（复合名词，由“화산”+“활동”组成，意为“火山活动”）\n- 词义：火山活动\n- 例句：이 지역의 화산활동이 잦아졌다.（这个地区的火山活动频繁了。）\n\n**화산학자**（复合名词，由“화산”+“학자”组成，意为“火山学家”）\n- 词义：研究火山的科学家\n- 例句：그는 유명한 화산학자이다.（他是一位著名的火山学家。）\n\n注意：在韩语中，单词的变形更多是通过组合和添加后缀来实现的，而不是像英语那样有严格的词形变化规则。上述变形主要是通过与其他词汇组合来形成新的词汇，以表达与“화산”相关的概念。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1749, 114, ' 유카리트 ', ' 火成岩', '1.词性：名词\n2.词义：\n- 尤加利（桉树）\n- 尤加利相关产品，如尤加利精油等\n3.例句：\n- 유카리트 숲에 가서 맑은 공기를 맡고 왔어요.（去了尤加利树林呼吸清新空气。）\n- 이 유카리트 오일은 향기가 참 좋네요.（这款尤加利精油香味真不错。）\n\n变形及词义、例句：\n- 유카리트나무（尤加利树）\n    -例句：유카리트나무로 만든 가구가 인기가 많습니다.（用尤加利树做的家具很受欢迎。）\n- 유카리트향（尤加利香味）\n    -例句：방에 유카리트향이 가득해요.（房间里充满了尤加利香味。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1750, 114, ' 지하수 ', ' 地下水', '1. 词性：名词\n2. 词义：地下水\n3. 例句：\n   - 지하수를 이용한 수돗물이 깨끗합니다.（利用地下水的自来水很干净。）\n   - 이 지역은 지하수가 풍부해요.（这个地区地下水很丰富。）\n\n变形及词义、例句：\n- 지하수방울（地下水位）：지하수방울이 높아졌어요.（地下水位升高了。）\n- 지하수오염（地下水污染）：지하수오염을 막기 위해 노력해야 합니다.（为了防止地下水污染需要努力。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1751, 114, ' 퇴적작용 ', ' 沉积作用', '1. **퇴적작용** (토적작용)\n   - **词性**：名词（명사）\n\n2. **词义**：\n   - 地质学中的“沉积作用”，指物质（如泥沙、矿物质等）在水、风、冰川等自然力的作用下逐渐堆积形成沉积层的过程。\n   - 广义上也可指其他领域中类似“积累、沉淀”的现象，但此义较少用。\n\n3. **例句**：\n   - 1. 강물에 의한 모래와 흙의 **퇴적작용**으로 평야가 형성되었다.  \n     （河水带来的泥沙通过沉积作用形成了平原。）\n   - 2. 호수 저층에서 발생한 **퇴적작용**이 화석을 잘 보존했다.  \n     （湖泊底层的沉积作用使化石得以完好保存。）\n\n---\n\n### **变形及词义**（无严格变形，但相关词汇扩展）：\n1. **퇴적**（动词/名词）  \n   - **词义**：沉积、堆积（动词）；沉积物（名词）。  \n   - **例句**：바닷물이 물러나면서 갯벌에 **퇴적**물이 쌓였다.  \n     （海水退去后，泥滩上堆积了沉积物。）\n\n2. **퇴적되다**（被动形动词）  \n   - **词义**：被沉积、被堆积。  \n   - **例句**：풍화된 암석은 바람에 의해 **퇴적되다**.  \n     （风化的岩石被风搬运并沉积。）\n\n3. **퇴적률**（名词）  \n   - **词义**：沉积速率。  \n   - **例句**：이 지역의 **퇴적률**은 매년 1밀리미터 정도이다.  \n     （该地区的沉积速率约为每年1毫米。）\n\n4. **퇴적층**（名词）  \n   - **词义**：沉积层。  \n   - **例句**：지층 속에 여러 **퇴적층**이 교대로 존재한다.  \n     （地层中存在多层交替的沉积层。）\n\n---\n\n### 总结：\n- **퇴적작용** 是地质学术语，核心词义为“沉积作用”，变形词汇多与“沉积”相关的动词、名词或复合词，常用于描述自然地质过程。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1752, 114, ' 단층 ', ' 断层', '1. **词性**：  \n   **명사 (名词)**\n\n2. **词义**：  \n   - **층수 없는 하나의 평면（单层；无楼层的平面）**  \n     例：건물의 단층 구조（建筑物的单层结构）  \n   - **지질학적 용법, 암석층이 한 층으로 된 상태（地质学中，岩层仅一层的状态）**  \n     例：이 지역은 단층으로 이루어져 있다（该地区由单层岩层构成）  \n   - **기타 확장 의미（其他扩展含义）**  \n     例：사회적인 단층（社会阶层的单一化）\n\n3. **例句**：  \n   - 이 집은 단층으로 지어졌어요.  \n     （这房子是单层建造的。）  \n   - 지각판의 단층 운동을 연구했습니다.  \n     （研究了地壳板块的单层运动。）\n\n---\n\n### **变形及词义**：  \n1. **단층식**  \n   - **뜻**：단층으로 이루어진 형태 또는 방식（单层的形式或方式）  \n   - **례구**：단층식 주택 설계가 인기입니다.  \n     （单层式住宅设计很受欢迎。）\n\n2. **단층 구조**  \n   - **뜻**：건물이 단하나의 층으로 이루어진 구조（建筑物仅一层的结构）  \n   - **례구**：이 오피스텔은 단층 구조로 되어 있습니다.  \n     （这个公寓是单层结构。）\n\n3. **단층화**  \n   - **뜻**：단층으로 변화되거나 단순화되는 과정（变为单层或简化的过程）  \n   - **례구**：사회적 단층화를 막기 위해 노력해야 합니다.  \n     （为防止社会阶层单一化，必须努力。）\n\n4. **단층론**  \n   - **뜻**：지질학에서 단층에 관한 이론（地质学中关于单层的理论）  \n   - **례구**：교수는 단층론에 대한 새로운 연구 결과를 발표했다.  \n     （教授发表了关于单层理论的新研究成果。）\n\n---\n\n### **总结**：  \n- **단층** 是名词，核心词义为“单层”或“单一岩层”，变形后可扩展为描述结构、过程或理论的词汇，常用于建筑、地质或社会现象中。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1753, 114, ' 지시대 ', ' 地质时代', '1. **词性**：名词\n\n2. **词义**：  \n   - 指示、指引、引导  \n   - （对某人或某事的）指导、指示  \n   - （交通、方向等的）标志、指示牌  \n\n3. **例句**：  \n   - 경찰의 지시대에 따라 차량이 정렬되었다.  \n     （按照警察的指示，车辆排列整齐。）  \n   - 교사는 학생들에게 시험지를 작성하는 지시대를 했다.  \n     （老师给了学生们写试卷的指导。）  \n\n---\n\n### **变形及词义**：  \n1. **지시대**（原形）  \n   - **词义**：指示、指导、标志  \n   - **例句**：길거리에 새로운 교통 지시대가 설치되었다.  \n     （街上安装了新的交通标志。）  \n\n2. **지시대하다**（动词形式）  \n   - **词义**：指示、引导  \n   - **例句**：선생님은 학생들을 지시대하여 실험을 시작하게 했다.  \n     （老师引导学生开始实验。）  \n\n3. **지시대받다**（被动词形）  \n   - **词义**：被指示、被引导  \n   - **例句**：우리는 교장님의 지시대받아 행사 준비를 했다.  \n     （我们按照校长的指示准备了活动。）  \n\n4. **지시대에**（格助词附加）  \n   - **词义**：在指示下、按照指示  \n   - **例句**：지시대에 따라 행동해야 한다.  \n     （必须按照指示行动。）  \n\n5. **지시대로**（工具状语）  \n   - **词义**：通过指示、以指示的方式  \n   - **例句**：그는 친절한 지시대로 우리에게 방향을 알려주었다.  \n     （他通过友好的指示为我们指了方向。）  \n\n---\n\n### **总结**：  \n- **核心词义**：围绕“指示、引导、标志”展开，既可指具体的动作（如指示行为），也可指抽象的概念（如指导原则）。  \n- **变形特点**：名词形式最常用，动词形式需搭配“하다”，被动形式强调“被指示”，格助词附加则用于语法结构中。', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1746609423698.mp3');
INSERT INTO `word_list` VALUES (1754, 114, ' 지층 ', ' 地层', '1. **词性**：  \n   名词（명사）\n\n2. **词义**：  \n   - 地层（地质学中岩层或土层的分层）  \n   - 层次结构（泛指分层的系统或结构）  \n   - （比喻）基础或底层部分  \n\n3. **例句**：  \n   - 지층을 분석함으로써 지질학자들은 역사를 추측할 수 있었다.  \n     （通过分析地层，地质学家们可以推测历史。）  \n   - 이 책의 내용은 지층처럼 체계적으로整理되었다.  \n     （这本书的内容像地层一样有体系地整理着。）\n\n---\n\n### **变形及词义**：\n\n1. **지층적**（지층 + 적，形容词后缀）  \n   - **词义**：与地层相关的，具有地层特征的  \n   - **例句**：지층적 구조를 연구하는 것은 환경을 이해하는 데 중요하다.  \n     （研究地层结构对理解环境很重要。）\n\n2. **지층학**（지층 + 학，学科后缀）  \n   - **词义**：地层学（研究地层结构的学科）  \n   - **例句**：그는 지층학을 전공하며 암석의 순서를 분석했다.  \n     （他主修地层学，分析岩石的层序。）\n\n3. **재지층**（재 + 지층，“再地层”）  \n   - **词义**：重新形成的地层（非标准词汇，但可用于特定语境）  \n   - **例句**：화산 폭발 후 새로운 재지층이 생겨났다.  \n     （火山爆发后形成了新的再地层。）\n\n4. **지층화**（지층 + 화，动词化后缀）  \n   - **词义**：形成地层的过程  \n   - **例句**：시간의 흐름에 따라 퇴적물은 지층화를 거쳤다.  \n     （随着时间的流逝，沉积物经历了地层化。）\n\n5. **지층 간**（지층 + 간，“地层之间”）  \n   - **词义**：地层之间的（关系或空间）  \n   - **例句**：지층 간의 불연속성은 지진의 원인이 될 수 있다.  \n     （地层之间的不连续性可能是地震的原因。）\n\n---\n\n### **总结**：\n- **核心词义**：以“地层”为核心，延伸出科学术语、比喻用法及变形词。  \n- **变形特点**：通过添加后缀（적, 학, 화, 간）扩展为形容词、学科、过程或关系描述。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1755, 114, ' 지열 ', ' 地热', '1.词性：名词\n2.词义：\n  - 地热\n  - 地下的热量\n3.例句：\n  - 지열을 이용한 난방 시스템은 환경에 친숙합니다.（利用地热的供暖系统对环境友好。）\n  - 이 지역은 지열 에너지가 풍부하여 발전소를 건설하기에 적합합니다.（这个地区地热能源丰富，适合建设发电厂。）\n\n**变形及词义、例句：**\n\n- **지열발전（地热发电）**\n  - 词义：利用地热进行发电\n  - 例句：우리나라에서는 지열발전에 대한 연구가 활발히 진행되고 있습니다.（我国正在积极开展对地热发电的研究。）\n\n- **지열난방（地热供暖）**\n  - 词义：利用地热进行供暖\n  - 例句：이 아파트는 지열난방 시스템을 도입하여 겨울철 난방비를 절약할 수 있습니다.（这个公寓引入了地热供暖系统，可以在冬季节省供暖费用。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1756, 114, ' 광물 ', ' 矿物', '### 광물（矿物）\n\n#### 1. 词性：\n**명사（名词）**\n\n#### 2. 词义：\n- **矿物**：指自然形成的无机固体物质，如金属、矿石、宝石等。\n- **矿产**：泛指地球中可开采的自然资源。\n\n#### 3. 例句：\n1. **광물은 땅속에서 자연적으로 형성된 것이다.**  \n   （矿物是地下自然形成的。）  \n2. **이 지역은 다양한 광물이 풍부하다.**  \n   （这个地区富含多种矿物。）\n\n---\n\n### 변형（变形）및 예문（例句）\n\n#### 1. **광물질（矿物质）**  \n   - **词义**：矿物成分，泛指矿物中的营养物质或化学元素。  \n   - **例句**：  \n     **바닷물에는 많은 양의 광물질이 함유되어 있다.**  \n     （海水中含有大量的矿物质。）\n\n#### 2. **광물화학（矿物化学）**  \n   - **词义**：研究矿物化学成分和结构的学科。  \n   - **例句**：  \n     **그는 광물화학 분야에서 권위있는 전문가이다.**  \n     （他是矿物化学领域的权威专家。）\n\n#### 3. **광물탐사（矿物勘探）**  \n   - **词义**：寻找和评估矿产资源的过程。  \n   - **例句**：  \n     **새로운 광물탐사를 통해 희토류가 발견되었다.**  \n     （通过新的矿物勘探，发现了稀土资源。）\n\n#### 4. **광물연료（矿物燃料）**  \n   - **词义**：化石燃料，如煤、石油等。  \n   - **例句**：  \n     **광물연료의 사용은 환경에 큰 영향을 미친다.**  \n     （矿物燃料的使用对环境有重大影响。）\n\n---\n\n### 정리（总结）\n- **광물** 是名词，核心词义为“矿物”或“矿产”，变形后可派生科学术语（如 광물화학）、复合词（如 광물탐사）等，均与“矿物”相关。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1757, 114, ' 암석 ', ' 岩石', '1. **词性**：名词\n\n2. **词义**：\n- 岩石\n- （地质学中的）岩体、岩层\n\n3. **例句**：\n- 산에 있는 암석은 다양한 종류가 있습니다. (山上的岩石有各种各样的种类。)\n- 이 암석은 화산활동으로 형성된 것입니다. (这块岩石是由火山活动形成的。)\n\n**变形及其词义与例句**：\n\n*암석本身为名词，其变形主要通过与其他词汇组合形成复合词或短语，而非直接的词形变化。以下是一些常见的组合及其含义和例句*：\n\n1. **변성암석 (变质岩)**\n   - **词义**：经过变质作用形成的岩石。\n   - **例句**：이 지역의 변성암석은 매우 오래되었습니다. (这个地区的变质岩非常古老了。)\n\n2. **침전암석 (沉积岩)**\n   - **词义**：由沉积物固结形成的岩石。\n   - **例句**：해안에는 많은 침전암석이 있습니다. (海岸边有很多沉积岩。)\n\n3. **화성암석 (火成岩)**\n   - **词义**：由岩浆冷却凝固形成的岩石。\n   - **例句**：이 산은 화성암석으로 가득 차 있습니다. (这座山充满了火成岩。)\n\n4. **암석층 (岩层)**\n   - **词义**：由岩石构成的层次。\n   - **例句**：지하수은 암석층을 통해서 이동합니다. (地下水通过岩层移动。)\n\n5. **암석학 (岩石学)**\n   - **词义**：研究岩石的科学。\n   - **例句**：그는 암석학을 전문으로 연구합니다. (他专门研究岩石学。)\n\n这些变形都是通过将“암석”与其他词汇结合来形成新的词汇，以表达更具体或相关的地质学术语。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1758, 115, 'ゴーヤ', '苦瓜', '1. 词性：名词（植物名）\n2. 词义：苦瓜、凉瓜。一种葫芦科植物，果实表面有瘤状突起，味苦，可食用，常见于亚洲料理中。\n3. 例句：\n   - ゴーヤチャンプルは沖縄の郷土料理です。\n   - 夏にはゴーヤを食べて暑さをしのぐのが良い。\n\n**变形及其词义与例句：**\n\n* ゴーヤ本身为名词，表示特定植物，在日语中通常不进行词形变化以表达不同词义。但可以通过添加不同的后缀或构成复合词来扩展其含义或用法。以下是一些常见的变形或相关表达方式：\n\n1. **ゴーヤの実**（ゴーヤのしつ） - 词义：苦瓜的果实。例句：ゴーヤの実は料理によく使われる。\n2. **ゴーヤ栽培**（ゴーヤさいばい） - 词义：苦瓜的栽培。例句：彼は家庭でゴーヤ栽培をしている。\n3. **ゴーヤ漬け**（ゴーヤづけ） - 词义：腌制的苦瓜。例句：このゴーヤ漬けはとても美味しい。\n4. **ゴーヤ入り**（ゴーヤいり） - 词义：含有苦瓜的（料理等）。例句：このサラダはゴーヤ入りでヘルシーだ。\n\n需要注意的是，这些变形并不是ゴーヤ本身的词形变化，而是通过添加其他词汇或后缀来构成的新词汇或短语，用以表达与苦瓜相关的更具体或更广泛的概念。', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1746679680568.mp3');
INSERT INTO `word_list` VALUES (1759, 115, 'ダイコン', '萝卜', '1. 词性：名词\n2. 词义：萝卜\n3. 例句：\n    - 私はダイコンを植えています。（我在种萝卜。）\n    - このスープはダイコンで作りました。（这个汤是用萝卜做的。）\n\n变形及其词义和例句：\n\n1. **ダイコンの**（所有格助词「の」附着，表示所属等关系，可理解为“萝卜的”）\n    - 例句：ダイコンの葉も食べられます。（萝卜的叶子也可以吃。）\n\n2. **ダイコンを**（宾格助词「を」附着，表示宾语，可理解为“把萝卜”“萝卜（宾）”）\n    - 例句：ダイコンを刻みます。（把萝卜切碎。）\n\n3. **ダイコンに**（格助词「に」附着，可表示对象、着落点等，这里可大致理解为“在萝卜上”“对于萝卜”等意思）\n    - 例句：塩をダイコンに振ります。（往萝卜上撒盐。）\n\n4. **ダイコンで**（格助词「で」附着，可表示手段、材料等，这里可理解为“用萝卜”“通过萝卜”等意思）\n    - 例句：ダイコンで料理を作ることができます。（可以用萝卜做菜。）\n\n5. **ダイコンが**（主格助词「が」附着，表示主语，可理解为“萝卜（主）”）\n    - 例句：ダイコンが大きくなりました。（萝卜长大了。）\n\n6. **ダイコンと**（并列助词「と」附着，表示并列，可理解为“和萝卜”）\n    - 例句：ニンジンとダイコンを買いました。（买了胡萝卜和萝卜。）\n\n7. **ダイコンも**（副助词「も」附着，表示也，可理解为“萝卜也”）\n    - 例句：キャベツもダイコンも新鮮です。（卷心菜和萝卜都很新鲜。）\n\n8. **ダイコンや**（并列助词「や」附着，表示并列，可理解为“萝卜之类的”“萝卜、还有……”，常用于列举）\n    - 例句：ダイコンやタマネギなどの野菜を買いました。（买了萝卜、洋葱之类的蔬菜。）\n\n9. **ダイコンのを**（所有格助词「の」与宾格助词「を」组合，表示所属事物的宾语形式，可理解为“萝卜的（东西）宾”）\n    - 例句：ダイコンの漬物を食べます。（吃萝卜的腌菜。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1760, 115, 'キュウリ', '黄瓜', '1. 词性：名词\n2. 词义：黄瓜\n3. 例句：\n    - キュウリはサラダに入れることができます。\n    - 私は冷やっこの上に刻んだキュウリを乗せて食べました。\n\n变形及词义和例句：\n\n**复数形式：キュウリたち**（词义：黄瓜们，用于表示多个黄瓜）\n例句：畑にはたくさんのキュウリたちが実っています。\n\n**连用形：キュウリを**（用于连接后续的动词等，表示对黄瓜进行某种动作）\n例句：キュウリを切ってサラダに入れましょう。', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1746679703721.mp3');
INSERT INTO `word_list` VALUES (1761, 115, 'エリンギ', '杏鲍菇', '1. 词性：名词\n2. 词义：杏鲍菇（一种食用菌）\n3. 例句：\n    - 今日の料理はエリンギを使った美味しい炒め物です。\n    - エリンギは肉厚で歯ごたえがあり、人気の食材です。\n\n变形及词义、例句：\n    - エリンギの（エリンギの）：表示所属，“杏鲍菇的”\n      例句：エリンギの軸は太くてしっかりしている。\n    - エリンギを（エリンギを）：表示把杏鲍菇作为宾语，用于动作的对象\n      例句：エリンギを切って鍋に入れます。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1762, 115, 'アスパラガス', '芦笋', '1. 词性：名词\n2. 词义：芦笋\n3. 例句：\n    - アスパラガスの炒め物はとても美味しいです。(Asparagus stir-fry is very delicious.)\n    - スーパーで新鮮なアスパラガスを買いました。(I bought fresh asparagus at the supermarket.)\n\n变形及词义、例句：\n\n**复数形式（基本无特定复数变形，可通过量词等表示复数概念）**：一般说“アスパラガスたち”可表示多个芦笋，但较少这样使用，更常见的是用“たくさんのアスパラガス”（很多芦笋）等表达。\n例句：テーブルの上にはたくさんのアスパラガスが置いてあります。(There are many asparaguses on the table.)\n\n**作为定语修饰其他名词时（通过“の”连接）**：例如“アスパラガスの料理”（芦笋的料理），此时词义仍为芦笋，用于限定其他事物与芦笋相关。\n例句：これはアスパラガスの料理の本です。(This is a book about asparagus dishes.)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1763, 115, 'ナス', '茄子', '1. 词性：名词\n2. 词义：茄子、eggplant\n3. 例句：\n    - ナスはおいしい野菜です。（茄子是美味的蔬菜。）\n    - ナスの炒め物を作りました。（做了茄子炒的菜。）\n\n**变形及其词义和例句**：\n\n**ない形（未然形）**：一般不常用“ナス”的未然形，若要表达“不做茄子相关的……”等意思，可理解为“ナスをしない”，但单独“ナス”本身没有典型的未然形用法及明确词义。\n\n**连用形**：\n    - 词义：连接后续动词等，表示与茄子相关的动作状态等，如“ナスを買う（买茄子）”“ナスを料理する（烹饪茄子）”。\n    - 例句：スーパーでナスを買いました。（在超市买了茄子。）\n\n**终止形**：\n    - 词义：用于结句，陈述关于茄子的事实等，就是其本身的“茄子”含义。\n    - 例句：これはナスです。（这是茄子。）\n\n**连体形**：\n    - 词义：修饰体言，说明是茄子相关的，比如“ナスの料理（茄子做的料理）”“ナスの旬（茄子的当季时期）”。\n    - 例句：ナスの料理はいろいろあります。（茄子做的料理有很多种。）\n\n**假定形**：一般不常用“ナス”的假定形来单独表达假设情况，若在句子中要表达“如果是茄子……”之类的假设，通常会用“もしナスなら……”这样的形式，但单独“ナス”本身没有典型的假定形用法及明确词义。\n\n**推量形**：一般也不常用“ナス”的推量形，要表达推测等意思时多是通过其他语法结构搭配，比如“おそらくナスだろう（恐怕是茄子吧）”，单独“ナス”没有典型的推量形用法及明确词义。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1764, 115, 'もやし', '豆芽', '1. 词性：名词\n2. 词义：豆芽（通常指黄豆芽）\n3. 例句：\n   - もやしを買ってきます。(我去买豆芽。)\n   - もやし炒めが好きです。(我喜欢炒豆芽。)\n\n变形及其词义和例句：\n\n1. もやしの（もやしの）：的（属格助词），表示所属或关联。\n   - 例句：もやしの炒め物を作ります。(我做豆芽炒菜。)\n\n2. もやしで（もやしで）：で（格助词），表示手段、方法或材料。\n   - 例句：もやしでサラダを作ります。(我用豆芽做沙拉。)\n\n3. もやしたち（もやしたち）：たち（复数助词），表示复数。\n   - 例句：もやしたちは栄養があります。(豆芽们有营养。)\n\n4. もやしが（もやしが）：が（主格助词），用于主语。\n   - 例句：もやしが大好きです。(我非常喜欢豆芽。)\n\n5. もやしを（もやしを）：を（宾格助词），用于宾语。\n   - 例句：もやしを食べます。(我吃豆芽。)\n\n6. もやしに（もやしに）：に（格助词），表示目标、方向或状态变化。\n   - 例句：もやしに醤油をかけます。(我给豆芽上撒酱油。)\n\n7. もやしから（もやしから）：から（格助词），表示起点、来源或原因。\n   - 例句：もやしから料理を始めます。(我从豆芽开始做菜。)\n\n8. もやしまで（もやしまで）：まで（格助词），表示到达点或极限。\n   - 例句：もやしまで全部使います。(我用到豆芽为止，全部用完。)\n\n9. もやしと（もやしと）：と（格助词），表示并列或共同行动。\n   - 例句：もやしとニンジンを炒めます。(我炒豆芽和胡萝卜。)\n\n10. もやしへ（もやしへ）：へ（格助词），表示方向或目标，但在此上下文中不常用，因为“へ”通常用于移动或方向性的动作，而“もやし”作为物体，一般不与“へ”结合使用来表达向豆芽移动的意思。不过，为了完整性，可以构造一个假设性的句子：\n    - 例句（假设性）：もしもやしへ飛べたら、どうする？(如果能飞向豆芽，你会怎么做？)（注意：这个句子在实际语境中可能不太自然，因为“へ”在这里的使用是假设性的，且“飛べたら”表示“如果能飞”，与“もやし”结合并不常见。）\n\n在实际使用中，“もやし”主要作为名词使用，并与其他词汇结合形成不同的句子结构，而不是通过变形来改变其词义。上述变形主要是基于日语语法中的格助词和助词的使用，而非“もやし”本身的变形。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1765, 115, 'パプリカ', '彩椒', '1. 词性：名词\n2. 词义：红辣椒、灯笼椒（一种蔬菜）\n3. 例句：\n    - パプリカはビタミンCが豊富です。\n    - サラダにパプリカを入れると彩りが良くなります。\n\n变形及词义、例句：\n- パプリカの（所有格）：表示属于帕普里卡的，比如“パプリカの種”（帕普里卡的种子），例句：パプリカの種を蒔きます。（播种帕普里卡的种子。）\n- パプリカたち（复数形式，较不常用，一般用「パプリカたち」来表示多个帕普里卡）：例句：畑にはたくさんのパプリカたちが育っています。（田里有很多正在生长的帕普里卡。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1766, 115, 'しいたけ', '香菇', '1. 词性：名词\n\n2. 词义：香菇（一种食用蘑菇）\n\n3. 例句：\n- 母が作ったしいたけの炊き込みご飯は絶品です。\n- スーパーで新鮮なしいたけを買ってきました。\n\n变形及其词义与例句：\n\n* 注意：在日语中，“しいたけ”作为一个具体名词，其变形并不像动词或形容词那样有固定的规律性变形来表达不同的意义。不过，我们可以根据语境构造一些短语或表达方式来展示其在不同情境下的使用。以下是一些基于“しいたけ”的常见表达方式和例句，虽然不算是严格的“变形”，但展示了其不同的使用场景：\n\n1. **しいたけ狩り**（香菇采摘）\n   - 例句：山でしいたけ狩りに行きました。\n   - 解释：表示去山上采摘香菇的活动。\n\n2. **しいたけ料理**（香菇料理）\n   - 例句：しいたけ料理が得意です。\n   - 解释：表示擅长制作香菇相关的菜肴。\n\n3. **しいたけの栽培**（香菇的栽培）\n   - 例句：しいたけの栽培方法を学びました。\n   - 解释：表示学习了香菇的栽培方法。\n\n4. **しいたけ味**（香菇味）\n   - 例句：このスープはしいたけ味がします。\n   - 解释：表示这汤有香菇的味道。\n\n5. **干しいたけ**（干香菇）\n   - 例句：干しいたけを使って料理をします。\n   - 解释：表示使用干香菇来烹饪。\n\n这些表达方式虽然不是“しいたけ”本身的变形，但展示了该词在不同语境下的灵活应用。在日语中，很多名词都是通过与其他词汇组合来形成新的表达意义的，而不是像动词或形容词那样有明显的词形变化。', NULL, 0, NULL, 'src\\main\\resources\\MP3\\1746679711233.mp3');
INSERT INTO `word_list` VALUES (1767, 115, 'ピーマン', '青椒', '1. 词性：名词\n2. 词义：青椒、甜椒\n3. 例句：\n    - 私はピーマンが苦手です。（我不太爱吃青椒。）\n    - ピーマンを炒めて料理の具にします。（把青椒炒一下当做菜肴的配料。）\n\n变形及词义、例句：\n    - ピーマンの：（表示所属，可理解为“青椒的”）\n        - 例句：ピーマンの炒め物は美味しいです。（青椒炒的菜很好吃。）\n    - ピーマンを：（表示动作的对象，可理解为“把青椒……”）\n        - 例句：ピーマンを細かく刻みます。（把青椒细细地切碎。）\n    - ピーマンで：（表示使用的工具、材料等，可理解为“用青椒……”）\n        - 例句：ピーマンで簡単な料理を作ってみましょう。（用青椒做个简单的菜吧。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1768, 115, 'カボチャ', '南瓜', '1. 词性：名词\n2. 词义：南瓜\n3. 例句：\n    - カボチャを丸ごと一つ買ってきました。（买了一整个南瓜。）\n    - カボチャの煮物はとてもおいしいです。（南瓜炖品非常好吃。）\n\n变形及词义、例句：\n\n**て形（カボチャって）**\n - 词义：表示并列、列举等，在这里可简单理解为“和南瓜相关的（动作、状态等）”，不过这种变形在实际应用中相对较少单独使用，更多是在一些固定表达或特定语境中出现。\n - 例句：カボチャって野菜は栄養が豊富だよ。（南瓜这种蔬菜营养丰富哦。）\n\n**た形（カボチャだった）**\n - 词义：表示过去的状态或用于描述某种既定事实、推测等，在这里意为“是南瓜”的过去式或推测等情况下的表达。\n - 例句：この料理の主な材料はカボチャだったんです。（这道菜的主要材料本来是南瓜。）\n\n**ない形（カボチャじゃない）**\n - 词义：表示否定，意思是“不是南瓜”。\n - 例句：これはカボチャじゃない、冬瓜だよ。（这不是南瓜，是冬瓜。）\n\n**可能形（カボチャができる）**\n - 词义：表示有可能做某事，这里指“能够收获南瓜”“有南瓜”等意思。\n - 例句：この畑では毎年たくさんのカボチャができる。（这块地里每年能收获很多南瓜。）\n\n**使役形（カボチャを食べさせる）**\n - 词义：表示使某人做某事，这里指“让（某人）吃南瓜”。\n - 例句：子供にカボチャを食べさせようとしたら、嫌がられました。（想让孩子吃南瓜，结果被嫌弃了。）\n\n**被动形（カボチャが食べられる）**\n - 词义：表示被动态，这里指“南瓜被吃”。\n - 例句：カボチャが食べられる前に、飾りとして置いていました。（在南瓜被吃之前，先放着当装饰。）\n\n**命令形（カボチャを食べろ）**\n - 词义：表示命令，这里指“吃南瓜”。\n - 例句：（ちょっと厳しい感じで）カボチャを食べろ！体にいいんだから。（有点严厉地说）吃南瓜！对身体好。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1769, 115, 'トマト', '番茄', '1. 词性：名词\n2. 词义：番茄、西红柿\n3. 例句：\n    - トマトはビタミンを豊富に含んでいる。(番茄富含维生素。)\n    - 私はトマトが好で、サラダに入れるのが好きだ。(我喜欢番茄，喜欢把它放在沙拉里。)\n\n变形及词义、例句：\n- トマトの（表示所属，可译为“番茄的”等）：トマトの畑は広大だ。(番茄田很广阔。)\n- トマトを（将其作为宾语成分时使用，可译为“番茄”等）：私はトマトを食べたい。(我想吃番茄。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1770, 115, 'タケノコ', '竹笋', '1. 词性：名词（名）\n2. 词义：①竹笋；②泛指嫩芽、新芽\n3. 例句：\n    ・山にタケノコを採りに行きます。/ 去山上采竹笋。\n    ・春になると、木々のタケノコが芽を出します。/ 一到春天，树木的嫩芽就发芽了。\n\n**变形及词义、例句：**\n\n**たけのこ（タケノコ的平假名写法，词义与タケノコ相同）**\n例句：たけのこは美味しいです。/ 竹笋很好吃。\n\n**たけのこの（タケノコ的连用形，表示所属等，词义为“竹笋的”）**\n例句：たけのこの煮物は人気があります。/ 竹笋煮的东西很受欢迎。\n\n**たけのこゆえ（因为竹笋，文语用法，现代日语较少使用，词义为“因为竹笋”）**\n例句：たけのこゆえ、料理が変わります。/ 因为竹笋，料理会发生变化。（此例句较为书面和古老风格的表达）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1771, 115, 'しめじ', '口蘑', '1. 词性：名詞\n\n2. 词义：しめじ是一种食用蘑菇，通常被称为“姬松茸”或“真姬菇”。\n\n3. 例句：\n   - 山の中でしめじを見つけました。\n   - しめじはお味噌汁に入れると美味しいです。\n\n4. 变形及其词义和例句：\n   - しめじの（しめじの）：表示属于しめじ的，用于连接名词，如“しめじの煮物”（煮的姬松茸）。\n     例句：しめじの煮物はとても美味しいです。\n   - しめじを（しめじを）：表示动作的对象，用于在句子中作为宾语，如“しめじを食べる”（吃姬松茸）。\n     例句：私はしめじをたくさん食べました。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1772, 115, 'オクラ', '秋葵', '1. 名词\n2.词性： 词义：秋葵、黄秋葵（一种蔬菜）\n3. 例句：\n    - オクラのネバネバが美味しいです。\n    - オクラを収穫する時期になりました。\n\n变形及其词义和例句：\n- オクラの（所有格）：表示秋葵的\n    - 例句：オクラの料理はいろいろあります。\n- オクラを（宾格）：表示秋葵这个对象，用于动作所涉及的对象\n    - 例句：オクラを刻みます。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1773, 115, 'チンゲンサイ', '小白菜', '1. 词性：名词\n2. 词义：青菜、小白菜\n3. 例句：\n    - チンゲンサイは栄養が豊富で、体に良いです。\n    - 私はチンゲンサイ入りの味噌汁が好きです。\n\n变形及词义和例句：\n- チンゲンサイの種（小白菜的种子）\n    - 例：このチンゲンサイの種を蒔けば、たくさん収穫できるでしょう。\n- チンゲンサイ畑（小白菜田）\n    - 例：彼は広大なチンゲンサイ畑を管理しています。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1774, 115, 'にんじん', '胡萝卜', '1. 词性：名词\n2. 词义：胡萝卜\n3. 例句：\n   - にんじんを刻んでください。(请把胡萝卜切碎。)\n   - にんじんは体にいいです。(胡萝卜对身体好。)\n\n变形及其词义和例句：\n\n**にんじん（基本形）**\n- 词义：胡萝卜\n- 例句：にんじんジュースが好きです。(我喜欢胡萝卜汁。)\n\n**にんじんたち（复数形，非正式，用于指多个胡萝卜或一群胡萝卜）**\n- 词义：胡萝卜们（复数，非正式用法）\n- 例句：畑のにんじんたちが大きくなりました。(田里的胡萝卜们都长大了。)\n\n**にんじんの（所有格，表示“胡萝卜的”）**\n- 词义：胡萝卜的\n- 例句：にんじんの千切りを作りましょう。(我们来做胡萝卜丝吧。)\n\n**にんじんを（宾格，表示动作的对象是胡萝卜）**\n- 词义：胡萝卜（宾格）\n- 例句：にんじんを食べた後で歯を磨きます。(吃了胡萝卜之后刷牙。)\n\n**にんじんで（工具格，表示使用胡萝卜做某事）**\n- 词义：用胡萝卜\n- 例句：にんじんで料理を作ることができます。(可以用胡萝卜做菜。)\n\n**にんじんと（并列格，表示与胡萝卜一起或对比）**\n- 词义：和胡萝卜\n- 例句：にんじんとジャガイモを一緒に炒めます。(把胡萝卜和土豆一起炒。)\n\n**にんじんも（也，表示胡萝卜也是其中之一）**\n- 词义：胡萝卜也\n- 例句：りんごもいいけど、にんじんも体にいいです。(苹果好，胡萝卜对身体也好。)\n\n**にんじんが（主格，表示胡萝卜是主语或主题）**\n- 词义：胡萝卜（主格）\n- 例句：にんじんが一番好きな野菜です。(胡萝卜是我最喜欢的蔬菜。)\n\n**にんじんで（地点格，虽然不常用，但理论上可以表示在胡萝卜上或通过胡萝卜的方式）**\n- 词义：在胡萝卜上/通过胡萝卜（较少见用法）\n- 例句：※この用法は日常会話ではほとんど使いませんが、仮に使うなら「にんじんで彫刻をする」のように、特定の芸術や技術を表現する際に限られます。（此用法在日常对话中几乎不用，但如果要用，比如“用胡萝卜进行雕刻”，来表达某种特定的艺术或技术时可能会用到。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1775, 115, 'キャベツ', '卷心菜', '1. 词性：名词（名）\n2. 词义：卷心菜、甘蓝\n3. 例句：\n    - キャベツの千切りをサラダに入れました。\n    - キャベツはビタミンUを豊富に含んでいます。\n\n**变形及其词义和例句**\n\n**ない形（未然形）**：キャベツを食べない（不吃卷心菜），这里“食べない”是动词“食べる”的未然形否定形式，“キャベツ”本身无变形，整体表示否定吃卷心菜这个动作。\n例句：私はキャベツを食べません。（我不吃卷心菜。）\n\n**た形（过去形）**：キャベツを食べた（吃了卷心菜），同样“キャベツ”无变形，“食べた”是动词“食べる”的过去式，表示过去进行了吃卷心菜的动作。\n例句：昨日はキャベツをたくさん食べました。（昨天吃了很多的卷心菜。）\n\n**ます形**：キャベツを食べます（吃卷心菜），“キャベツ”不变，“食べます”是动词“食べる”的礼貌体现在时肯定形式，用于表达一般现在时的礼貌说法。\n例句：私は毎日キャベツを食べます。（我每天吃卷心菜。）\n\n**て形**：キャベツを食べて（正在吃卷心菜或者吃过卷心菜之后做某事），“キャベツ”无变化，“食べて”是动词“食べる”的て形，可表示动作的进行或先后顺序等。\n例句：キャベツを食べてから、お肉を焼きます。（吃了卷心菜之后，再烤肉。）\n\n**ないで形（未然形否定）**：キャベツを食べずに（不吃卷心菜就……），“キャベツ”不变，“食べずに”是动词“食べる”的未然形否定的て形，常后续其他动作表示在没做前一个动作的情况下做后一个动作。\n例句：キャベツを食べずに、他の野菜だけ食べています。（不吃卷心菜，只吃其他的蔬菜。）\n\n**ば形（假定形）**：キャベツを食べれば（如果吃卷心菜的话），“キャベツ”无变形，“食べれば”是动词“食べる”的假定形，用于假设某种情况。\n例句：キャベツを食べれば、栄養バランスが良くなります。（如果吃卷心菜的话，营养均衡会变好。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1776, 115, 'ブロッコリー', '西兰花', '1. 词性：名词\n2. 词义：西兰花、绿花椰菜\n3. 例句：\n    - ブロッコリーは栄養価が高い野菜です。（西兰花是营养价值很高的蔬菜。）\n    - 私はブロッコリーが大好きです。（我非常喜欢西兰花。）\n\n变形及其词义和例句：\n\n**复数形式（通常不常用，日语中一般通过量词等表示数量概念，这里仅为示例一种可能的表达形式）：ブロッコリーたち**\n    - 词义：西兰花们（表示多个西兰花，但实际使用中较少这样直接说复数形式）\n    - 例句：ブロッコリーたちが畑で育っています。（西兰花们在地里生长着。）\n\n**作为料理名称等组合形式时的变形（比如在菜名等特定语境下可能会有不同的搭配表述，但本身词干基本不变）：例如“ブロッコリーのサラダ”（西兰花沙拉）等，这里的“の”表示所属、关联等意思，不是严格意义上的变形，只是常见搭配用法。\n    - 词义：西兰花相关的菜品等（根据具体搭配而定）\n    - 例句：これはブロッコリーのサラダです。（这是西兰花沙拉。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1777, 81, ' 竜巻', '龙卷风', '1. 词性：名词\n2. 词义：龙卷风\n3. 例句：\n    - 竜巻が近づいてきたので、人々は大急ぎで安全な場所に避難した。（因为龙卷风靠近了，人们急忙往安全的地方避难。）\n    - この地域では、春になると竜巻が発生することがある。（在这个地区，一到春天有时就会发生龙卷风。）\n\n变形及词义、例句：\n“竜巻”是名词，其变形主要在修饰其他名词作定语时，变为“竜巻の”，词义为“龙卷风的”。\n例句：竜巻の被害は甚大で、多くの家屋が破壊された。（龙卷风的灾害很严重，很多房屋被破坏了。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1778, 81, ' 干ばつ', '干旱', '1. 词性：名词\n2. 词义：干旱\n3. 例句：\n    - 今年は干ばつがひどく、農作物の収穫に影響が出ている。（今年干旱严重，对农作物的收成有影响。）\n    - その地域は長雨の後、急に干ばつに見舞われた。（那个地区在长时间的降雨之后，突然遭遇了干旱。）\n\n变形及词义、例句：\n- 干ばつする（动词）：干旱，发生干旱\n    - 例：この辺りは夏になるとよく干ばつする。（这附近一到夏天就经常干旱。）\n- 干ばつ状態（名词短语）：干旱状态\n    - 例：ダムの水が減少し、周辺は干ばつ状態になっている。（水库的水减少了，周边处于干旱状态。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1779, 81, ' 雷雨', '雷雨', '### 1. 词性：\n名词（名詞）\n\n### 2. 词义：\n- 雷雨、雷电交加的暴雨。\n- 比喻激烈的冲突或动荡。\n\n### 3. 例句：\n- 今日にわかに雷雨が襲ってきた。/ 今天突然下起了雷雨。\n- 彼の演説は雷雨のように聴衆の心を揺さぶった。/ 他的演讲如雷雨般震撼了听众的心。\n\n### 所有变形及其词义与例句：\n\n**雷雨**本身是一个复合名词，由“雷”（らい）和“雨”（う）组合而成，在日语中通常作为一个固定的词汇使用，不进行常规的变形（如动词变形、形容词变形等）。但为了满足要求，我们可以考虑其在不同语境下的“变体”或相关表达，尽管这些并不属于严格的语法变形：\n\n1. **雷鳴り**（らいめい） - 词义：雷鸣。例句：遠くで雷鳴りが聞こえる。/ 远处传来雷鸣声。\n   - 这里将“雷雨”中的“雨”替换为“鳴り”（鸣），形成了描述雷声的新词。\n\n2. **雷光**（らいこう） - 词义：闪电、雷光。例句：雷光が夜空を照らし出す。/ 闪电照亮了夜空。\n   - 这里将“雷雨”中的“雨”替换为“光”，形成了描述雷电光芒的新词。\n\n3. **雷雨風**（らいうふう） - 词义：伴有雷电的风雨。例句：台風接近中、雷雨風が強まる一方だ。/ 台风逼近，伴有雷电的风雨越来越强。\n   - 在“雷雨”后添加“風”，形成了描述更复杂天气现象的词汇。\n\n4. **激しい雷雨**（はげしいらいう） - 词义：激烈的雷雨。例句：外は激しい雷雨で、外出できない。/ 外面是激烈的雷雨，无法外出。\n   - 在“雷雨”前添加形容词“激しい”，形成了描述雷雨强度的短语。\n\n需要注意的是，这些“变形”并不是“雷雨”这个词本身的变形，而是通过添加其他词汇或改变词汇组合来形成的新词汇或短语，以表达更具体或更丰富的意义。在实际使用中，应根据语境选择合适的词汇或短语。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1780, 81, ' 空模様', '天空状况', '### 1. 词性：\n名词（noun）\n\n### 2. 词义：\n- 天空的样子、状态，指天气状况或天空的外观。\n- 比喻事物整体的状态或趋势。\n\n### 3. 例句：\n1. 今日の空模様は曇りで、雨が降りそうな気がします。（今天的天空状态是阴天，感觉好像要下雨。）\n2. 社会の空模様を読むことは、政治家の重要な能力の一つだ。（读懂社会的“天空状态”即社会的整体形势，是政治家的重要能力之一。）\n\n### 变形及词义、例句：\n- **「空模様」**：原形，表示天空的样子、状态或事物整体的状态等。\n    - 例句：明日は良い空模様のようで、お出かけ日和だろう。（明天好像是很好的天空状态，会是出门的好天气吧。）\n- **「空模様の」**：作为定语，修饰其他名词，表示“……的天空状态”或“……的整体状态”。\n    - 例句：この地域の空模様の変化は、気候の変動を示しているかもしれない。（这个地区天空状态的变化，可能显示出气候的变动。）\n- **「空模様を」**：作为宾语，表示“天空的样子”或“事物的状态”，常与动词搭配使用。\n    - 例句：窓辺から外を見て、空模様を観察していた。（在窗边看着外面，观察着天空的样子。）\n- **「空模様に」**：表示对象，可理解为“对于天空的状态”或“对于事物的整体状态”。\n    - 例句：空模様によれば、今日の夜は星がきれいに見えるだろう。（根据天空的状态来看，今晚的星星会很漂亮吧。）\n- **「空模様が」**：作为主语，表示“天空的状态”或“事物的整体状态”。\n    - 例句：空模様が悪いので、外出を控えることにした。（因为天空状态不好，所以决定控制外出。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1781, 81, ' 突風', '阵风', '### 突風（つぷう）\n\n1. **词性**：名词（ん）  \n2. **词义**：  \n   - 突然刮起的强风，阵风。  \n   - 比喻突然发生的、难以预测的变化或事件。  \n\n3. **例句**：  \n   - 自転車がゆれて危なかった。  \n     （突然刮起一阵风，自行车摇晃得很危险。）  \n   - 政界に突風が吹き荒れた。  \n     （政界突然掀起了一场风暴。）\n\n---\n\n### **变形及词义与例句**：\n\n#### 1. **突風的な**（つぷうてきな）  \n   - **词义**：像阵风一样突然的、突发的。  \n   - **例句**：  \n     彼の発言は突風的なものだ。  \n     （他的发言像阵风一样突然。）\n\n#### 2. **突風を巻き起こす**（つぷうをまきおこす）  \n   - **词义**：引发突如其来的风波或动荡。  \n   - **例句**：  \n     スキャンダルが突風を巻き起こした。  \n     （丑闻引发了突如其来的风波。）\n\n#### 3. **突風にさらされる**（つぷうにさらされる）  \n   - **词义**：暴露在突如其来的强风中，或陷入意外的困境。  \n   - **例句**：  \n     プロジェクトは突風にさらされ、停滞した。  \n     （项目突遭意外阻碍，陷入了停滞。）\n\n---\n\n### 说明：\n- **突風**本身是名词，变形后多为复合词或动词短语，需搭配助词或动词使用。  \n- 比喻义常用于抽象情境（如社会、政治领域的突发事件）。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1782, 81, ' 雹', '冰雹', '1. 词性：名词（自然现象相关）\n2. 词义：冰雹，指从云层中降下的冰块或冰粒。\n3. 例句：\n   - 今度の嵐は、雷に加えて激しい雹まで降った。/这次的暴风雨，除了雷还有激烈的冰雹。\n   - 作物が雹の被害に遭い、収穫量が大幅に減少した。/作物遭受了冰雹的灾害，收成量大幅减少。\n\n**变形及其词义与例句**（注：日语中“雹”作为独立单词时变形较少，但可构成复合词或通过助词连接表达不同状态）：\n\n1. **雹が降る（はうがふる）**：下冰雹\n   - 例句：突然空が暗くなって、外は雹が降り始めた。/突然天空变暗，外面开始下起了冰雹。\n\n2. **雹による（はうによる）**：由于冰雹（引起的）\n   - 例句：雹による農作物の損害は甚大だった。/由于冰雹，农作物的损失非常严重。\n\n3. **雹を伴う（はうをともなう）**：伴有冰雹\n   - 例句：この地域では、春先に雹を伴う強い嵐が時々ある。/在这个地区，初春时分有时会出现伴有冰雹的强烈暴风雨。\n\n4. **雹傷（はうきず）**：冰雹造成的伤痕\n   - 例句：車の屋根には、昨夜の雹でできた雹傷がいっぱいだった。/车的屋顶上满是昨晚冰雹造成的伤痕。\n\n在日语中，“雹”本身作为一个基础词汇，其变形更多体现在与其他词汇的组合或通过助词、动词等构成的短语中，以表达更具体的含义或状态。上述例句和变形展示了“雹”在不同语境下的使用方法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1783, 81, ' 寒波', '寒潮', '1. 词性：名词（通常作为「寒波」这一复合名词使用，但也可视为由形容词「寒い」+名词「波」构成的复合词）\n2. 词义：①寒冷的波浪；②气象学中的「寒潮」，即冷空气大规模南下的现象；③比喻突然袭来的冷意或困境\n3. 例句：\n   ・寒波が日本列島に襲来した。（寒潮袭击了日本列岛）\n   ・彼女の冷たい視線は寒波のように私を凍らせた。（她冰冷的视线如寒潮般让我僵住）\n\n---\n\n**变形与词义说明**：\n「寒波」为复合名词，无传统日语语法中的变形（如ます形、て形等）。但可通过添加助词或与其他词汇组合产生不同用法：\n\n1. **寒波が来る**（寒潮来临）  \n   例：この時期はいつも寒波が来る。（这个时期总是有寒潮来临）\n\n2. **寒波の影響で**（受寒潮影响）  \n   例：寒波の影響で野菜の値段が上がった。（受寒潮影响，蔬菜价格上涨）\n\n3. **寒波に見舞われる**（遭遇寒潮）  \n   例：北海道は今週寒波に見舞われている。（北海道本周遭遇了寒潮）\n\n4. **寒波のように**（如寒潮般，比喻冰冷猛烈）  \n   例：批判が寒波のように彼を襲った。（批评如寒潮般向他袭来）\n\n---\n\n**补充说明**：  \n「寒波」在日语中特指气象现象时，属于专业术语，日常对话中也可用于比喻情感或氛围的骤变。由于是复合名词，其变形主要依赖于助词或前后接词的变化，而非自身词尾变化。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1784, 81, ' 気圧', '气压', '1. 词性：名詞\n\n2. 词义：\n   - 大気の圧力（气压）\n   - 雰囲気や勢い（氛围、气势）\n\n3. 例句：\n   - 今日の気圧は低く、天気が崩れそうです。（今天的气压低，天气好像要变坏。）\n   - 会議室の中の気圧はとても重く、誰もが緊張していた。（会议室里的气氛非常沉重，大家都很紧张。）\n\n变形及其词义和例句：\n\n**～的（てき）**\n- 词义：～的な、～に関する（～的、与～相关的）\n- 例句：このデザインは非常に気圧的で、人目を引きます。（这个设计非常有气势，吸引眼球。）\n\n**～的に**\n- 词义：～の方法で、～のように（以～的方式、像～一样）\n- 例句：彼はいつも気圧的に物事を進めるので、周りも引き込まれる。（他总是以气势如虹的方式推进事情，周围的人也被带动起来。）\n\n**～気圧**\n- 词义：特定の気圧を指す場合の表現（表示特定气压时使用）\n- 注意：这种变形不是简单的词尾变化，而是根据语境可能需要添加数字或其他修饰词来具体化气压值，因此没有直接的固定例句。但可以理解为“XX気圧”（如“1000hPa気圧”）来表示具体的气压值。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1785, 81, ' 強風', '强风', '1. 词性：名詞\n2. 词义：①「強い風（つよいかぜ）」的简略说法，表示强风。②形容事物或情况具有强烈、强硬的性质，类似“强硬的态度、强烈的风格”等含义，但在使用中多侧重于表示自然现象中的强风。\n3. 例句：\n    - 強風で船が揺れている。（因为强风，船在摇晃。）\n    - あの人は強風な性格だ。（那个人是强硬的性格。）\n\n**变形及词义、例句：**\n\n**「強風」没有典型的变形形式，因为它是一个独立的名词。** 但可以通过添加助词等方式与其他词语组合，例如：\n\n- **「強風の日」**：意思是“有强风的日子”。例句：強風の日は外出を控えるべきだ。（有强风的日子应该控制外出。）\n- **「強風の中」**：表示“在强风中”。例句：強風の中を歩いてきた。（在强风中走了过来。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1786, 81, ' 梅雨', '梅雨', '1. 词性：名词\n2. 词义：梅雨（中国长江流域及韩国、日本等地初夏至盛夏间常阴雨的一种天气现象）\n3. 例句：梅雨入り（进入梅雨季节）、梅雨明け（梅雨结束）\n\n变形及其词义和例句：\n- 梅雨入り（名詞）：进入梅雨季节。例句：今年は梅雨入りが早いようだ。（今年好像进入梅雨季节比较早。）\n- 梅雨明け（名詞）：梅雨结束。例句：梅雨明けたら、暑い夏が待っている。（梅雨结束后，等待我们的是炎热的夏天。）\n\n需要注意的是，“梅雨”本身作为名词没有其他常规变形形式，上述“梅雨入り”“梅雨明け”是在其基础上构成的与梅雨相关现象相关的特定表达，可看作是一种复合名词性质的表述。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1787, 81, ' 台風接近', '台风接近', '1. 词性：名詞\n2. 词义：台風が近くに来る状態のこと。具体的には、台風が一定範囲内に入り、その影響が感じられるようになる状況を指す。\n3. 例句：\n    - 台風接近に伴い、船は避難港に向かった。\n    - ニュースによると、大型の台風接近が予想されている。\n\n**变形及其词义、例句**：\n\n* 台風接近中（名詞）：台風がまさに接近しつつある最中の状態。\n    - 例句：台風接近中、外出は控えるようにとのアナウンスがあった。\n\n* 台風接近する（動詞）：台風が近づく動作や状態変化を表す。\n    - 例句：台風が接近するにつれて、風が強くなってきた。\n\n* 台風接近した（動詞の過去形）：台風がすでに近づいたことを示す。\n    - 例句：台風が接近したため、飛行機の便が軒並みキャンセルになった。\n\n* 台風接近予定（名詞）：今後台風が接近することが予測されている状態。\n    - 例句：この地域は台風接近予定なので、早めの対策が必要だ。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1788, 81, ' 積雪', '积雪', '1. 词性：名词\n2. 词义：积雪、积雪量\n3. 例句：山の頂上には厚い積雪がある。(山的顶上有厚厚的积雪。) 冬になると、この地域は大量の積雪に見舞われる。(到了冬天，这个地区会遭遇大量的积雪。)\n\n变形及其词义和例句：\n- 積雪する (动词)：下雪、积雪\n  - 例句：山は毎年冬になると積雪する。(山每年冬天都会积雪。)\n- 積雪量 (名词)：积雪量\n  - 例句：この山の積雪量はすごいです。(这座山的积雪量很大。)\n- 積雪期 (名词)：积雪期\n  - 例句：この地域の積雪期は長い。(这个地区的积雪期很长。)', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1789, 81, ' 大気安定', '大气稳定', '1. 词性：名詞\n2. 词义：大气稳定的状态，通常用于描述气象、气候等与大气相关的稳定状况。\n3. 例句：\n   - 今日の大気は大変安定しているから、洗濯物を外に干しても大丈夫だ。\n   - この地域は大気安定の日が多く、天気が良い。\n\n**变形及其词义和例句**：\n\n* 注意：日语中“大気安定”作为一个复合名词，其变形并不像动词或形容词那样有固定的规律变化。但我们可以构造一些包含该词的短语或句子来展示其在不同语境中的使用。\n\n1. **大気安定度**（たいきあんていど）\n   - 词义：大气的稳定程度。\n   - 例句：この地域の大気安定度は高く、年間を通じて天気が変わらない。\n\n2. **大気安定層**（たいきあんていそう）\n   - 词义：大气中稳定的层次，通常指温度、湿度等气象要素变化较小的气层。\n   - 例句：高層では大気安定層が形成され、雲が発生しにくい状態になっている。\n\n3. **大気不安定**（たいきふあんてい）\n   - 词义：大气不稳定的状态，与“大気安定”相对。\n   - 例句：梅雨の時期は大気不安定で、突然の雨や雷雨が多くなる。\n\n4. **大気安定化**（たいきあんていか）\n   - 词义：使大气变得稳定的过程或状态。\n   - 例句：新しい技術を導入することで、工場周辺の大気安定化が図られた。\n\n这些变形和例句展示了“大気安定”一词在不同语境中的灵活应用。在实际使用中，可以根据具体语境选择合适的表达方式。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1790, 81, ' 強風注意報', '强风警报', '1. 词性：名词\n2. 词义：指针对强风发布的注意警报，是一种气象预警信息，提醒人们注意防范强风可能带来的危害。\n3. 例句：\n    - 今、強風注意報が発令されています。/现在，强风注意报已经发布。\n    - 強風注意報が出ているので、外出は控えた方がいいです。/因为强风注意报发布了，所以最好控制外出。\n\n**变形及词义和例句**：\n\n**強風警報**（词义：比“強風注意報”程度更严重，是针对强风发布的警报，意味着强风的影响可能更大、更具危险性）\n例句：この地域には強風警報が発表されました。/这个地区发布了强风警报。\n\n**強風**（词义：指强劲的风，强调风的强度大）\n例句：今日は一日中強風が吹いています。/今天一整天都刮着强风。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1791, 81, ' 熱波', '热浪', '1. 词性：名詞（名詞）\n\n2. 词义：\n- 熱い空気の流れ。暑さが厳しい状態。\n- 比喩的に、勢いのある運動や活動、またはその盛り上がり。\n\n3. 例句：\n- この夏は熱波が続き、外に出るのも大変だ。\n- 彼のプレゼンは会場に熱波を巻き起こした。\n\n**變形及其詞義與例句：**\n\n*注意：由於「熱波」本身為名詞，其變形主要依據日語名詞的一般變化規則，但通常不進行動詞或形容詞形式的變形。不過，為了符合題目要求，這裡將展示如何通過添加不同後綴或構詞成分來創造新的詞彙，並解釋這些新詞的可能詞義及例句。*\n\n1. **熱波的（ねつばの）** - 形容動詞な形容词形式，用來描述與「熱波」相關的狀態或特徵。\n   - 例句：この地域は熱波の時期になると、夜も寝苦しいほど暑くなる。\n\n2. **熱波化（ねつばか）** - 动词化，表示變得像熱波一樣熾熱或激烈的過程。\n   - 例句：議論は次第に熱波化し、誰も引き下がれなくなった。\n\n3. **熱波的な（ねつばてきな）** - 形容動詞な形容词形式，用來描述具有「熱波」特性的事物或狀態。\n   - 例句：彼の講演は熱波的で、聴衆の心を熱くさせた。\n\n4. **熱波を放つ（ねつばをはずつ）** - 動詞短语，表示散發出強烈的熱量或激情。\n   - 例句：彼女の笑顔はまるで太陽のように、周りに熱波を放っていた。\n\n5. **熱波の中（ねつばのなか）** - 名詞短语，表示在熱浪或激烈活動的中心位置。\n   - 例句：彼はいつも論争の熱波の中で、冷静に意見を述べることができる。\n\n6. **熱波を避ける（ねつばをよける）** - 動詞短语，表示避免或逃離熱浪或激烈的爭論等。\n   - 例句：暑すぎるので、私は熱波を避けて涼しい場所を求めた。\n\n7. **熱波のように（ねつばのように）** - 副詞短语，用來比喻某事物像熱浪一樣迅速蔓延或充滿激情。\n   - 例句：彼の言葉は熱波のように聴衆の心に広まった。\n\n8. **熱波の影響（ねつばのえいきょう）** - 名詞短语，表示受到熱浪或激烈活動的影響。\n   - 例句：熱波の影響で、作物の生育に悪影響が出ている。\n\n這些變形和詞彙展示了「熱波」這個詞在日語中的靈活運用和豐富含義。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1792, 110, 'Mare', '池塘', '1. 词性：阴性名词\n2. 词义：\n   - 水塘；水池；水坑\n   - （液体的）大量；许多\n   - （在某种情况下的）困境，窘境\n3. 例句：\n   - Il y a une mare dans le jardin.（花园里有一个水塘。）\n   - Une mare de sang sur le sol.（地上有一大滩血。）\n   - Se retrouver dans une mauvaise mare.（陷入困境。）\n\n**变形及词义和例句**：\n\n**复数形式**：mares\n - 词义：水塘；水池；水坑；大量；许多；困境，窘境（复数形式表示多个水塘、多摊液体或多种困境等）\n - 例句：Les mares du parc sont remplies d\'eau.（公园里的那些水塘装满了水。）\n\n**阴性形式（本身已是阴性，此处强调其作为阴性名词的特性）**：la mare\n - 词义：水塘；水池；水坑；大量；许多；困境，窘境（单数阴性形式，指代单个的水塘、一摊液体或一种困境等）\n - 例句：La mare est profonde.（这个水塘很深。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1793, 110, 'Ruisseau', '溪流', '1词性：. 名词\n2. 词义：小溪；细流\n3. 例句：\n- Le ruisseau coule tranquillement à côté de la forêt.（小溪静静地在森林旁边流淌。）\n- Les enfants ont joué près du ruisseau.（孩子们在小溪边玩耍。）\n\n**变形及词义和例句：**\n\n**复数形式：ruisseaux**\n词义：小溪们；多条细流\n例句：Les ruisseaux sont nombreux dans cette région.（这个地区有很多小溪。）\n\n**阴性单数形式（较少单独使用，常在一些特定语境或搭配中）：ruisselle**\n词义：小溪（阴性形式，使用频率较低）\n例句：La ruisselle qui traverse le jardin est très claire.（穿过花园的那条小溪非常清澈。）\n\n**动词变位（当“ruisseau”作为动词时，意为“使成细流”“流出细流”，不过这种用法相对较少见）**\n\n**第三人称单数现在时：ruisselle**\n词义：（某物）流出细流\n例句：La source ruisselle doucement.（源头轻轻地流出细流。）\n\n**第三人称复数现在时：ruissellent**\n词义：（多个事物）流出细流\n例句：Les rochers ruissellent d\'eau après la pluie.（下雨后，岩石渗出细流。）\n\n**第一人称单数复合过去时：j\'ai roussé**\n词义：我使（某物）成细流（这种时态和人称的用法在实际中极少用到，更多是理论上的变形）\n例句：J\'ai roussé l\'eau en dirigeant le tuyau.（我通过引导水管使水成细流。）\n\n**第三人称单数复合过去时：il a roussé**\n词义：他/它使（某物）成细流\n例句：Il a roussé le vin en versant lentement.（他慢慢地倒酒使其成细流。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1794, 110, 'Champignon', '蘑菇（与Mushrooms不同，更常用复数形式）', '1. 词性：名词（阳性，单数形式）\n2. 词义：\n    - 蘑菇（泛指蘑菇这一类菌类植物，是比较宽泛的指代）\n    - 伞菌（特指一种具体的蘑菇品种，如常见的平菇等属于伞菌类）\n3. 例句：\n    - J\'aime manger des champignons.（我喜欢吃蘑菇。这里泛指各种蘑菇）\n    - Les champignons poussent après la plue.（雨后蘑菇生长。这里也是泛指蘑菇）\n\n**变形及其词义和例句**：\n\n**复数形式：champignons**\n    - 词义：蘑菇（复数形式，指多个蘑菇或者多种蘑菇）\n    - 例句：Les champignons sont délicieux dans la salade.（蘑菇在沙拉里很美味。这里表示多种蘑菇混合在沙拉中）\n\n**阴性形式（在阴性名词搭配等语境下使用）：champignon（虽然拼写一样，但在语法上作为阴性单数形式时，意义依然是蘑菇相关概念）**\n    - 词义：蘑菇（当与之搭配的名词等为阴性时，它作为阳性名词在性数配合上的一种体现，比如在“une assiette de champignons”（一盘蘑菇），这里“assiette”是阴性单数，“champignons”虽然是阳性复数，但如果强调单个蘑菇放在阴性语境下，依然可以用“champignon”这种形式来体现性数配合）\n    - 例句：Une petite fille a trouvé un petit champignon près du bois.（一个小女孩在树林边发现了一个小蘑菇。这里“petite”是阴性形容词修饰“fille”，“petit”修饰“champignon”，整体体现出在阴性语境下的使用）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1795, 110, 'Cerisier', '樱花树', '1. 词性：名词\n2. 词义：\n   - 樱花树；樱桃树\n   - 樱桃（在某些地区或语境下，也可指代樱桃这种水果，但更常见的是用“cerise”表示樱桃）\n3. 例句：\n   - Le Japon est connu pour ses magnifiques cerisiers en fleurs. （日本以美丽的樱花树而闻名。）\n   - Nous avons un cerisier dans notre jardin qui donne des cerises délicieuses. （我们的花园里有一棵樱桃树，结出很好吃的樱桃。）\n\n**变形及其词义与例句**：\n\n*注意：由于“Cerisier”是一个名词，其变形并不像动词那样有规律的变位形式，但可以根据性别和数量的变化进行适当调整。以下是一些可能的变体和解释，尽管在实际应用中，这些变体并不总是都会出现或常用。*\n\n1. **复数形式**：Cerisaiers\n   - 词义：多棵樱花树/樱桃树\n   - 例句：Les cerisiers du parc sont en pleine floraison. （公园里的樱花树正在盛开。）\n\n2. **阴性形式**（虽然不常用，因为“Cerisier”通常指雄性树木，但为了完整性提供）：Cerisière\n   - 词义：雌性的樱桃树（在实际使用中非常罕见，因为通常不会特别强调樱桃树的性别）\n   - 例句：（这个例句比较牵强，因为法语中很少会用到“Cerisière”这个词）On trouve rarement des cerisières dans les vergers. （在果园里很少见到雌性的樱桃树。）\n\n*另外，值得注意的是，“Cerisier”作为名词，并没有像形容词或动词那样的直接“变形”。它主要根据句子的需要以单数或复数形式出现。在特定语境下，如果需要表达所有格或其他语法关系，会通过添加介词、连词或使用其他句法结构来实现，而不是通过单词本身的变形。*', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1796, 110, 'Loutre', '水獭', '1. 词性：\n名词（Masculin）\n\n2. 词义：\n- 獭，水獭（一种生活在水边的动物）\n\n3. 例句：\n- La loutre est un mammifère semi-aquatique. （水獭是一种半水生哺乳动物。）\n- On a observé une loutre dans la rivière. （我们在河里观察到了一只水獭。）\n\n**变形及其词义与例句**：\n\n*注意：由于“Loutre”是阳性名词，且为具体事物名称，其变形主要限于复数形式及在不同语境中的使用，不涉及性别或时态变化。以下是其基本变形和例句：**\n\n1. **复数形式**：\n   - 词形：Loutres\n   - 词义：多只獭，水獭们\n   - 例句：Les loutres sont très agiles dans l\'eau. （水獭们在水中非常敏捷。）\n\n2. **作为复合词或短语的一部分**（非严格意义上的变形，但展示其在不同语境中的应用）：\n   - 词组：Pêcheur de loutre （捕獭者）\n     - 词义：以捕捉水獭为职业的人\n     - 例句：Le pêcheur de loutre connaît tous les secrets de leur habitat. （捕獭者了解水獭栖息地的所有秘密。）\n\n   - 词组：Fourrière à loutre （水獭的巢穴）\n     - 词义：水獭居住的巢穴\n     - 例句：Nous avons découvert une fourrière à loutre près de la rivière. （我们在河边发现了一个水獭的巢穴。）\n\n*注：法语中名词的“变形”通常指的是根据语法规则进行的词形变化，如复数、所有格等。对于像“Loutre”这样的具体事物名称，其变形相对有限，主要集中在复数形式上。其他形式的“变形”更多是作为复合词或短语的一部分出现，而非单独存在的单词变形。*', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1797, 110, 'Vautour', '秃鹫', '1. 词性：名词\n2. 词义：秃鹫；贪婪的人，贪得无厌的人\n3. 例句：\n   - Le vautour plane haut dans le ciel en quête de proies.（秃鹫在高空中盘旋寻找猎物。）\n   - Il est considéré comme un vautour parmi les négociateurs, toujours prêt à profiter de la faiblesse des autres.（他在谈判者中被视为贪婪之人，总是准备利用他人的弱点。）\n\n变形及词义、例句：\n\n复数形式：Vautours\n词义：秃鹫们；一群贪婪的人\n例句：Les vautours ont commencé à se disputer la chair fraîche.（秃鹫们开始争抢新鲜肉块。）\n\n没有其他常见的变形形式，“vautour”作为阴性名词，其性、数变化主要通过添加复数后缀等常规方式体现，如上述复数形式“vautours”。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1798, 110, 'Bruyère', '欧石楠', '### 1. 词性：\n**名词**（阴性）\n\n### 2. 词义：\n- **主要词义**：石楠属植物（一种常用于花艺的灌木或草本植物，尤其指其花枝）。\n- **其他词义**：石楠丛生的地方；石楠花。\n\n### 3. 例句：\n1. *Je vais acheter une bruyère pour décorer la maison.*  \n   （我要买些石楠花来装饰房子。）  \n2. *La bruyère pousse surtout dans les landes bretonnes.*  \n   （石楠主要生长在布列塔尼的荒原上。）\n\n---\n\n### 变形及词义（所有变形均基于阴性名词形式）：\n\n#### 1. **复数形式**：**bruyères**  \n   - **词义**：多株石楠植物；多枝石楠花。  \n   - **例句**：*Les bruyères embellissent le jardin en hiver.*  \n     （石楠花让花园在冬天也变得美丽。）\n\n#### 2. **动词化使用**（罕见，需上下文补充）：  \n   - **bruyérer**（动词不定式，旧式用法）  \n     - **词义**：种植或采集石楠。  \n     - **例句**：*Les Bretons bruyèrent autrefois pour récolter les fleurs.*  \n       （布列塔尼人过去常采集石楠花。）  \n   - **备注**：现代法语中更常用名词形式，动词化用法已过时。\n\n---\n\n### 总结：\n- **核心词义**：石楠植物或其花枝，复数形式为**bruyères**。  \n- **例句特点**：多与自然、装饰或地域文化（如布列塔尼）相关。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1799, 110, 'Soleil', '太阳', '1. 词性：名词\n2. 词义：太阳；阳光\n3. 例句：\n- Le soleil brille aujourd\'hui.（今天阳光明媚。）\n- Tourner le dos au soleil.（背对着太阳。）\n\n**变形及其词义与例句：**\n\n- **Soleils**（复数形式，词义：太阳们；多个太阳，在特定语境下如天文学等可能会用到，不过日常较少用复数形式）\n例句：Dans certaines croyances, il existe plusieurs soleils dans l\'univers.（在某些信仰中，宇宙中存在多个太阳。）\n\n- **Au soleil**（介词短语，词义：在太阳下；在阳光下）\n例句：Nous avons pris l\'apéritif au soleil.（我们在太阳下喝了开胃酒。）\n\n- **Devant la soleil**（介词短语，词义：在太阳面前，不过这种表达在日常中不常用，相对生硬，更常见的是“devant le soleil”，这里按照要求给出变形及示例，实际使用中多用“devant le soleil”）\n例句：Il se tenait droit devant la soleil, les yeux fermés.（他笔直地站在太阳面前，闭着眼睛。此句仅为展示变形，实际表达不太自然。正常应是“Il se tenait droit devant le soleil, les yeux fermés.” ）\n\n- **Sous le soleil**（介词短语，词义：在太阳下；在阳光下，和“au soleil”类似，但“sous le soleil”更强调在太阳的笼罩、照射之下的感觉）\n例句：Les fleurs s\'ouvrent sous le soleil.（花朵在阳光下绽放。）\n\n- **Sans soleil**（介词短语，词义：没有太阳；无阳光）\n例句：La pièce est sombre sans soleil.（没有阳光，这个房间很昏暗。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1800, 110, 'Mousse', '苔藓', '1. 词性：名词\n2. 词义：\n   - 泡沫；慕斯（一种甜点）\n   - （头发的）摩丝\n3. 例句：\n   - La mousse sur la bière est très fine.（啤酒上的泡沫非常细腻。）\n   - J\'aime manger la mousse au chocolat.（我喜欢吃巧克力慕斯。）\n\n**变形及其词义与例句：**\n\n1. **复数形式：mosaïques**\n   - 词义：通常不用于表示“泡沫”或“慕斯”的复数，但在某些特定语境下，如描述多种颜色或类型的泡沫混合时，可能使用。不过，更常见的是保持“mousse”不变来表示复数概念。\n   - 例句：Les mosaïques de couleurs sur l\'eau sont magnifiques.（水面上的色彩泡沫很美。）*（注意：此句更多是为了展示复数形式而造，实际使用中“mousse”作为不可数名词，通常不直接加“s”表示复数。）*\n\n2. **阴性形式（当需要配合阴性名词或形容词时）：无直接阴性形式**\n   - 词义：由于“mousse”本身是不变的名词，它没有直接的阴性形式。在需要配合阴性上下文时，通常通过添加描述性词汇或改变句子结构来实现。\n   - 例句：La mousse à raser pour les femmes est très douce.（适合女性的剃须摩丝非常柔和。）*（这里通过“à raser pour les femmes”来指定是女性使用的，而非直接改变“mousse”的形式。）*\n\n**说明**：\n- “Mousse”在法语中主要用作名词，其词义相对稳定，不像动词或形容词那样有丰富的变形。\n- 在提供例句时，我尽量保持了句子的简洁性和实用性，同时确保能够准确反映“mousse”的词义和用法。\n- 对于“阴性形式”，由于“mousse”是名词且没有直接的阴性对应形式，因此我通过添加描述性词汇来模拟其在阴性上下文中的使用。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1801, 110, 'Érable rouge', '红枫树', '### 法语单词：Érable rouge\n\n#### 1. 词性：\n- **名词**（Masculin）\n\n#### 2. 词义：\n- **糖枫树**（Acer saccharum，一种北美洲特有的枫树，其树液可用于制作枫糖浆）\n- **糖枫叶**（通常指糖枫树的红色叶子，尤其在秋季）\n\n#### 3. 例句：\n- Le **érable rouge** est un arbre emblématique du Canada.  \n  （糖枫树是加拿大的象征性树木。）\n- Les **érables rouges** sont particulièrement magnifiques en automne.  \n  （糖枫树在秋天特别美丽。）\n\n---\n\n### 变形及其词义与例句：\n\n#### 1. **Érable rouge**（阳性单数形式）\n- **词义**：糖枫树（单数）\n- **例句**：L\'**érable rouge** produit une sève sucrée utilisée pour faire le sirop d\'érable.  \n  （糖枫树产出一种甜汁液，用于制作枫糖浆。）\n\n#### 2. **Érables rouges**（阳性复数形式）\n- **词义**：糖枫树（复数）\n- **例句**：Les **érables rouges** du Québec sont les plus réputés au monde.  \n  （魁北克的糖枫树是世界上最著名的。）\n\n#### 3. **Érable rouge**（作为不可数名词，指“糖枫叶”或“糖枫木”）\n- **词义**：糖枫叶、糖枫木（抽象或泛指）\n- **例句**：La couleur de l\'**érable rouge** est associée à l\'automne.  \n  （糖枫叶的颜色与秋天相关。）\n\n---\n\n### 总结：\n- **Érable rouge** 是一个阳性名词，主要指糖枫树或其红色叶子。\n- 变形包括单数形式（**érable rouge**）和复数形式（**érables rouges**），以及作为不可数名词的用法。\n- 例句展示了其在具体语境中的使用。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1802, 110, ' Roche', '岩石', '1. 词性：名词\n2. 词义：\n    - 岩石；石头\n    - （山脉、悬崖等的）岩体，岩层\n    - （某些地名中的）岩石地区，石山\n    - （宝石、矿物等的）原石，未加工的矿石\n3. 例句：\n    - La roche est dure et solide.（岩石又硬又结实。）\n    - Il a trouvé une roche précieuse dans la montagne.（他在山里发现了一块珍贵的宝石原石。）\n\n**变形及词义和例句**：\n\n“roche” 是阴性单数形式，其变形主要在作为名词的性数配合上，以下是一些常见变形：\n\n1. 复数形式：roches\n    - 词义：岩石；石头（复数概念）\n    - 例句：Les roches de cette rivière sont très belles.（这条河里的石头非常漂亮。）\n\n2. 阴性单数所有格：de la roche\n    - 词义：……的岩石（表示所属关系，这里“de la”是不定冠词与介词的组合，用于阴性单数名词前）\n    - 例句：C\'est de la roche volcanique.（这是火山岩。）\n\n3. 阴性单数宾格：la roche\n    - 词义：岩石；石头（宾格形式在句子中作直接宾语）\n    - 例句：Ils ont déplacé la roche hier.（他们昨天移开了那块石头。）\n\n4. 阴性单数主格（尊称或诗歌等特殊用法）：La Roche（首字母大写用于特定名称或尊称，一般较少单独这样使用，更多是作为复合词或特定名称的一部分）\n    - 词义：岩石（尊称或特定名称时的含义，如用于地名等）\n    - 例句：La Roche est un nom de lieu connu.（“拉罗什”是一个知名的地名。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1803, 110, ' Crépuscule', '黄昏', '1. 词性：名词\n2. 词义：\n    - 黄昏，傍晚时分（太阳落山后到天完全黑之前这段时间）\n    - 暮色，昏暗的光线（形容类似黄昏那种光线较暗的状态）\n3. 例句：\n    - Le crépuscule est un moment magique pour se promener.（黄昏是散步的魔幻时刻。）\n    - La salle était dans le crépuscule, il faisait presque nuit.（大厅里暮色沉沉，几乎就像夜晚一样。）\n\n**变形及词义、例句：**\n\n**复数形式：crépuscules**\n    - 词义：多个黄昏时刻；多种暮色状态\n    - 例句：Les crépuscules d\'été sont souvent très beaux.（夏天的黄昏常常很美。）\n\n**动词变位（假设以“crépusculaire”为动词，虽然实际法语中一般不用此动词形式，仅为按要求示例变形）：**\n    - 第一人称单数（je crépuscule）：无实际意义，假设为“我呈现黄昏状态”（不符合法语实际用法，仅为变形示例）\n    - 例句：Je crépuscule devant la fenêtre.（我在窗前呈现出一种黄昏般的状态。）（这种句子在实际法语中不成立，只是按照变形规则编造）\n    - 第三人称单数（il/elle crépuscule）：无实际意义，假设为“他/她呈现黄昏状态”（不符合实际用法）\n    - 例句：Il crépuscule dans la pièce sombre.（他在黑暗的房间里呈现出黄昏状态。）（同样不符合实际法语表达习惯，仅为变形示例）\n\n需要注意的是，在标准法语中，“crépuscule”主要是名词，没有常规的动词变位形式，上述动词变位只是为了完成变形任务而做的假设性示例。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1804, 110, ' Cerfs', '鹿', '### 1. 词性：\n**名词**（Masculin, Pluriel）\n\n### 2. 词义：\n- **“鹿”的复数形式**，指多只雄性或雌雄混合的鹿。\n\n---\n\n### 3. 例句：\n1. **Les cerfs traversaient la forêt en courant.**  \n   （鹿群在森林中奔跑穿行。）  \n2. **Les chasseurs ont vu des cerfs près du lac.**  \n   （猎人在湖边看到了鹿。）\n\n---\n\n### 变形及词义（所有格、单数形式等）：\n#### 1. **Cerf**（单数，阳性）  \n- **词义**：单数形式的“鹿”（雄性或泛指）。  \n- **例句**：*Un cerf boit à la rivière.*  \n  （一只鹿在河边喝水。）\n\n#### 2. **Cerfs**（复数，阳性）  \n- **词义**：复数形式的“鹿”。  \n- **例句**：*Les cerfs sont nombreux dans cette région.*  \n  （这个地区有很多鹿。）\n\n#### 3. **Cerf** 的所有格变形：  \n- **au cerf**（单数，阳性所有格）  \n  - **词义**：属于鹿的（如鹿的角、鹿的习性等）。  \n  - **例句**：*Les cornes du cerf sont impressionnantes.*  \n    （鹿的角非常壮观。）  \n\n- **aux cerfs**（复数，阳性所有格）  \n  - **词义**：属于鹿的（复数）。  \n  - **例句**：*Les traces aux cerfs indiquent qu\'ils sont passés par ici.*  \n    （鹿的足迹表明它们曾路过这里。）\n\n---\n\n### 总结：\n- **Cerfs** 是复数名词，指“鹿”的群体。  \n- 单数形式为 **Cerf**，所有格为 **du cerf**（单数）和 **des cerfs**（复数）。  \n- 例句均体现其自然或语境中的复数用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1805, 110, ' Sable', '沙子', '1. 词性：名词\n\n2. 词义：沙，沙子\n\n3. 例句：\n- Les enfants jouent dans le sable.（孩子们在沙滩上玩耍。）\n- Le vent a soulevé des nuages de sable.（风卷起了阵阵沙尘。）\n\n**变形及其词义与例句：**\n\n*注意：法语中“sable”作为名词，其变形主要体现在单复数形式上，以及在某些短语或表达中的使用，但基本的词义保持不变，即“沙，沙子”。以下是一些常见的变形和用法示例：**\n\n1. **复数形式**：\n   - 词形：sables\n   - 词义：沙子（复数）\n   - 例句：Les sables du désert sont infinis.（沙漠中的沙子是无穷无尽的。）\n\n2. **在短语中的使用**（非严格意义上的变形，但展示不同语境下的用法）：\n   - 短语：plage de sable（沙滩）\n     - 例句：Nous allons à la plage de sable en été.（我们夏天去沙滩。）\n   - 短语：sable fin（细沙）\n     - 例句：Ce sable fin est doux au toucher.（这细沙摸起来很柔软。）\n\n虽然“sable”本身没有像动词那样的时态、人称等变形，但在不同的语境和短语中，它以不同的形式出现，丰富了法语的表达。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1806, 110, ' Vents', '风', '### 1. 词性：\n**名词（masculin）**\n\n---\n\n### 2. 词义：\n- **风；气流**（自然现象或科学概念）  \n- **（乐器的）吹奏声；管风琴声**（音乐相关）  \n- **（复数）观点；意见；思潮**（抽象意义，常与定语搭配）  \n- **（诗歌/文学中）爱情的推动力**（比喻用法）\n\n---\n\n### 3. 例句：\n1. **自然现象**：  \n   *Les vents soufflent fort aujourd’hui.*  \n   （今天风很大。）  \n2. **抽象意义（观点）**：  \n   *Les vents de l’opinion ont changé.*  \n   （舆论的风向变了。）\n\n---\n\n### 4. 变形及词义（所有格、单复数形式）：\n#### **单数形式**：\n- **Vent**（不变）：  \n  - **自然现象**：*Le vent est froid.*（风很冷。）  \n  - **抽象意义**：*Suivre son vent*（追随自己的倾向/直觉）。\n\n#### **复数形式**：\n- **Vents**：  \n  - **多股风**：*Les vents d’ouest apportent de la pluie.*（西风带来雨水。）  \n  - **多种观点**：*Les vents de changement soufflent dans le pays.*（变革的思潮在这个国家蔓延。）  \n\n#### **所有格形式**：\n- **Vent(s)**（所有格与主格相同）：  \n  - **自然的风**：*Le vent du matin est frais.*（早晨的风很清新。）  \n  - **抽象所有**：*Les vents de colère ont passé.*（愤怒的风暴过去了。）\n\n---\n\n### 总结：\n- **Vent** 既可指具体的“风”，也可引申为抽象的“动向”或“思潮”。  \n- **Vents** 复数形式强调多股风或多种观点，需根据语境区分。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1807, 110, ' Aurore', '极光', '1. 词性：名词（阴性）\n2. 词义：\n    - 奥罗拉（Aurores），罗马神话中的曙光女神，对应的希腊神话中叫厄俄斯（Éos）。\n    - 朝霞，晨曦。\n3. 例句：\n    - Aurore est une déesse de la lumière du matin dans la mythologie romaine.（奥罗拉是罗马神话中清晨之光的女神。）\n    - Le ciel est teinté de belles couleurs à l\'aurore.（朝霞把天空染成了美丽的颜色。）\n\n**变形及其词义和例句**：\n\n**复数形式：Aurores**\n - 词义：奥罗拉（多个，一般用于神话语境指多位类似角色或概念的集合，较少这样用）；朝霞（多场朝霞或者不同状态下的朝霞统称）\n - 例句：Les aurores sont un spectacle magique que l\'on peut admirer parfois.（朝霞是人们有时可以欣赏到的神奇景象。）\n\n在法语中，“Aurore”作为专有名词（指曙光女神）时变形相对较少且不常用复数来表示多个女神（因为通常就特指那一位女神），而作为“朝霞”这个普通名词词义时，复数形式使用相对较多一些来表示不同时间或者不同状态下的朝霞情况。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1808, 110, ' Ruisseau', '小溪', '1. 词性：名词\n2. 词义：小河；溪流\n3. 例句：\n   - Le ruisseau coule tranquillement à travers la forêt.（这条小溪静静地流过森林。）\n   - Les enfants ont joué près du ruisseau toute l\'après-midi.（孩子们整个下午都在小溪边玩耍。）\n\n**变形及其词义和例句**：\n\n- Ruisseau (阳性单数)：小河；溪流\n  - 例句：Le ruisseau est clair et frais.（这条小溪清澈又凉爽。）\n\n- Ruisseaux (阳性复数)：小河们；溪流们\n  - 例句：Les ruisseaux de montagne sont souvent ressourçants.（山间的溪流常常很提神。）\n\n- Ruisseau (阴性单数，不常用，通常用阳性形式表示小河或溪流，但在特定文学或诗意语境中可能使用)：[此形式在标准法语中不常见，但若使用，意义同阳性单数]\n  - 例句：（较为罕见，但可构造）Ce ruisseau, si doux et si paisible, m\'inspire.（这条如此温柔、如此宁静的小溪给了我灵感。）【注：此句为假设性例句，实际使用中需根据语境判断】\n\n- Ruisseaux (阴性复数，同样不常用，通常避免使用，因为“ruisseau”作为阴性名词表示小河或溪流非常罕见）：[意义同阴性单数，但在实际使用中几乎不存在]\n  - 例句：（几乎不可能构造，因为不符合常规用法）\n\n**注意**：在标准法语中，“ruisseau”几乎总是用作阳性名词来指代小河或溪流。阴性形式在常规语境中极为罕见，且通常不建议使用，除非在特定的文学或诗意表达中，为了某种特殊的修辞效果而刻意采用。因此，上述关于阴性形式的例句仅为了说明其理论上的变形，而非实际推荐用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1809, 110, ' Brume', '薄雾', '### 1. 词性：\n名词 (masculin)\n\n### 2. 词义：\n- **雾；霭**\n- **模糊；朦胧**\n- **（玻璃等表面的）雾气，水汽**\n- **轻微的混乱；困惑**\n\n### 3. 例句：\n- La brume rend la route dangereuse. （雾使道路变得危险。）\n- Le matin, il y a toujours une légère brume sur la rivière. （早上，河面上总是有一层薄雾。）\n\n---\n\n### 变形及词义：\n\n#### 1. **Brûme** (阴性形式，较少用，但存在)\n- **词义**：同“Brume”，指雾、霭等。\n- **例句**：La brûme du matin est très belle. （早晨的雾非常美。）\n\n#### 2. **Brumeux** (形容词，阳性)\n- **词义**：有雾的；多雾的；模糊的。\n- **例句**：Le temps est brumeux aujourd\'hui. （今天天气多雾。）\n\n#### 3. **Brumeuse** (形容词，阴性)\n- **词义**：有雾的；多雾的；模糊的。\n- **例句**：La journée est brumeuse, difficile de voir loin. （今天天气多雾，难以看清远处。）\n\n#### 4. **Brumer** (动词，不及物)\n- **词义**：起雾；变得模糊。\n- **例句**：Le verre brumait à cause de la condensation. （玻璃因冷凝而起雾。）\n\n#### 5. **Brumiser** (动词，及物或不及物)\n- **词义**：使模糊；使朦胧；起雾。\n- **例句**：La lune brumisait à travers les nuages. （月亮透过云雾显得朦胧。）\n\n---\n\n### 总结：\n- **Brume** 是一个阳性名词，主要表示“雾、霭”等自然现象，也可以引申为“模糊、朦胧”等抽象概念。\n- 其变形包括阴性形式 **Brûme**、形容词 **Brumeux/Brumeuse**、动词 **Brumer** 和 **Brumiser**，分别用于描述与“雾”相关的状态或动作。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1810, 110, ' Sous', 'bois', '1. 词性：介词、副词\n2. 词义：\n   - 介词时表示“在……下面；在……之下；低于；少于”等意思，用于描述位置、数量、程度等方面的相对关系。\n   - 副词时表示“在下面；往下；低声地”等意思，常用于描述动作的方向或声音的状态。\n3. 例句：\n   - Il est sous la table.（他在桌子下面。）\n   - Le chien est sous le lit.（狗在床底下。）\n   - J\'ai moins de 20 ans, je suis encore sous les 20 ans.（我不到20岁，我还在20岁以下。）\n   - Il a parlé sous voix.（他低声说话。）\n\n**变形及其词义和例句**：\n\n* 作为介词，sous没有变形，它始终表示“在……下面；在……之下；低于；少于”等意思。\n* 作为副词，sous的常见变形是“dessous”，但“dessous”更多用作名词，表示“下面；底部”。当需要强调动作的方向或状态时，通常还是直接使用“sous”。不过，为了展示一个与“sous”相关的变形用法，我们可以考虑“sous-entendu”（暗示，间接提到），但这里更多是作为一个复合词出现，而不是“sous”本身的变形。如果我们要构造一个类似变形的语境，可以这样写：\n\n  * “Sous-entendu” (作为复合词的一部分，表示“暗示”)：Il y a eu un sous-entendu dans ses paroles.（他的话中有暗示。）\n\n  但请注意，这并不完全是“sous”作为独立单词的变形，而是它在复合词中的用法。对于“sous”本身作为副词的变形，实际上并不常见，因为它的基本形式已经足够表达所需的意思。如果要展示一个更接近“变形”的例子，我们可以考虑使用“sous”的不同语境来构造句子，但这并不改变“sous”本身的形式：\n\n  * “Il marche sous la pluie.”（他在雨中行走。）——这里的“sous”仍然是副词，表示“在……下”的意思，只是语境从“桌子下面”变成了“雨中”。\n\n综上所述，“sous”作为介词和副词，其基本形式已经非常灵活且常用，变形并不多见。在大多数情况下，我们通过改变“sous”后面的名词或动词来表达不同的意思，而不是改变“sous”本身。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1811, 110, ' Chênaie', '橡树林', '1. 词性：名词\n2. 词义：橡树林；橡树丛\n3. 例句：\n   - La chênaie est un endroit magnifique pour une promenade en forêt.（橡树林是进行森林漫步的美妙之地。）\n   - Les animaux habitent souvent dans la chênaie.（动物们经常栖息在橡树林里。）\n\n变形及词义、例句：\n\n|变形|词义|例句|\n|----|----|----|\n|chênais|复数形式，表示多片橡树林或橡树丛|Les chênais de cette région sont très anciens.（这个地区的这些橡树林非常古老。）|\n|chênaies|复数形式，同chênais|Les chênaies abritent de nombreuses espèces d\'oiseaux.（这些橡树林庇护着许多种鸟类。）| \n\n需要注意的是，“Chênaie”这个词在日常使用中可能相对较不常见，其变形在实际文本中出现的频率也较低，但按照法语语法规则，以上给出了常见的复数变形及相关示例。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1812, 110, ' Faune', '动物群', '1. 词性：名词\n2. 词义：动物群；动物区系；动物志（某一地区或时期的动物总体）\n3. 例句：\n   - La faune de l\'Afrique est très diversifiée.（非洲的动物群非常多样化。）\n   - L\'étude de la faune aide à comprendre l\'environnement.（对动物群的研究有助于理解环境。）\n\n**变形及其词义和例句：**\n\n- **复数形式：faunes**\n  - 词义：不同地区或不同类别的动物群；多种动物区系\n  - 例句：Les différentes faunes du monde offrent une grande richesse biologique.（世界上不同的动物群提供了丰富的生物多样性。）\n\n- **阴性单数形式：faune（不变）**\n  - 词义：同上，用于阴性语境中，但实际使用中“faune”不分阴阳性，此变形仅为语法结构上的说明。\n  - 例句：La faune locale est adaptée à son environnement.（当地的动物群适应了其环境。）\n\n- **阴性复数形式：faunes（不变）**\n  - 词义：同上，用于指代多个不同的动物群或动物区系，阴性形式在法语中不常用，但为保持语法完整性列出。\n  - 例句：（此形式在实际使用中较少见，因“faune”本身不分阴阳性，故例句略。）\n\n- **所有格形式：de la faune / de la faune（不变）**\n  - 词义：表示“……的动物群的”，用于构成短语或从句，指出所属关系。\n  - 例句：L\'équilibre de la faune est précieux pour l\'environnement.（动物群的平衡对环境至关重要。）\n\n注意：由于“faune”是一个不可数名词，且通常不分阴阳性，因此其变形相对有限。上述变形主要是基于法语名词的基本语法规则进行说明，实际使用中可能并不常见所有形式的独立使用。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1813, 110, ' Végétation', '植被', '1. 词性：名词\n2. 词义：植物群落；植被；植物生长（总体）\n3. 例句：\n   - La forêt est une région avec une riche végétation.（森林是一个有着丰富植被的地区。）\n   - L\'étude de la végétation dans cette zone est très importante pour la recherche écologique.（研究这个地区的植物群落对于生态研究非常重要。）\n\n**变形及词义和例句：**\n\n**复数形式：végétations**\n词义：不同种类的植物群落；多种植物生长情况（强调多个不同的植物群体概念）\n例句：Ces régions ont des végétations très différentes en fonction des climats.（这些地区由于气候不同有着非常不一样的植物群落。）\n\n**动词变位相关（由动词végéter派生，不过végétation是名词，这里只是补充说明关联动词的情况帮助理解名词用法）：**\n\n**végéter**\n- 第三人称单数现在时：végète\n词义：（植物）生长；（某地）有植被生长\n例句：La montagne végète abondamment tout l\'été.（这座山整个夏天植被茂盛地生长着。）\n- 第一人称现在时：végète\n词义：我（这里一般不用，因为主语通常是植物或某个地方等，强调整片区域有植物生长的状态，很少用于人称主语说自己像植物一样生长，除非在拟人化等特殊语境中）\n例句：Je me sens comme si je végétais dans cette petite ville tranquille.（我感觉好像在这个宁静的小城里像植物一样自在生长。不过这种用法比较文学化和特殊。）\n- 直陈式现在时阴性单数（用于描述女性或阴性事物像植物生长的状态，也很少见）：végète\n例句：La terre végète sous la pluie fine.（土地在细雨下仿佛在生长。这里把土地拟人化用végète来描述一种有生机的状态，但实际更多还是用于植物本身或某个区域整体的植被生长情况的描述，名词végétation更常用来表示植被这个概念。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1814, 110, ' Frêne', '椴树', '### 1. 词性：\n**名词**（Masculin）\n\n---\n\n### 2. 词义：\n- **欧洲花楸树**（一种落叶乔木，常见于法国，果实红色，可用于制作果酱或酒精饮料）\n- **（口语中）花楸果酒**（由花楸果实酿制的饮料）\n\n---\n\n### 3. 例句：\n1. **Le frêne est un arbre méditerranéen dont les fruits sont utilisés pour faire des sirops.**  \n   （花楸是地中海地区的一种树，其果实可用来制作糖浆。）  \n2. **Buvons du frêne pendant les fêtes de fin d\'année !**  \n   （年终节日时，我们喝花楸果酒庆祝吧！）\n\n---\n\n### 4. 变形及词义（所有格、指代等）：\n#### **Le Frêne**（主有形容词形式，用于专有名词）  \n- **词义**：花楸的（如地名、品牌名）  \n- **例句**：**La maison du Frêne** est un vieux corps de ferme.  \n  （“花楸之家”是一座古老的农舍。）\n\n#### **Au Frêne**（介词+名词，表示位置）  \n- **词义**：在花楸树旁  \n- **例句**：**Nous avons planté des fleurs au frêne.**  \n  （我们在花楸树旁种了花。）\n\n#### **Frêne**（不变，口语中作动词）  \n- **词义**：酿造花楸果酒（罕见用法，多为俚语）  \n- **例句**：**Il a appris à frêne avec son grand-père.**  \n  （他跟着祖父学会了酿花楸果酒。）\n\n---\n\n### 总结：\n- **核心词义**围绕“花楸树”或“花楸果酒”，变形较少（名词无性数变化），但需注意主有形容词和介词搭配的特殊用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1815, 110, ' Saule', '柳树', '1. 词性：名词\n2. 词义：柳树；柳属植物\n3. 例句：\n   - Le saule est un arbre qui pousse près des cours d\'eau.（柳树是一种生长在水边附近的树。）\n   - Les branches du saule sont souples et ondulées.（柳树的树枝很柔软且呈波浪状。）\n\n变形及其词义和例句：\n\n**复数形式：saules**\n词义：柳树（复数形式，指多棵柳树）\n例句：Les saules de la rivière sont en pleine floraison.（河边的柳树正处于盛花期。）\n\n**阴性单数形式：saule**（较少使用，在某些特定语境或文学表达中可能出现，通常表示“柳树”这一概念的女性化或诗意化的表达）\n词义：柳树（阴性单数，较为诗意或文学性的用法）\n例句：La saule, avec ses longs cheveux verts, dansait au vent.（那棵柳树，带着它长长的绿发，在风中翩翩起舞。）\n\n**阴性复数形式：saules**（与阳性复数形式相同，但用于指代阴性单数形式的复数情况，不过在实际使用中，由于“saule”作为阴性单数形式并不常见，所以其阴性复数形式也很少使用）\n词义：柳树（阴性复数，理论上的概念，实际使用极少）\n例句：（此例句较为生硬，仅为展示变形而造）Les saules, ces arbres aux airs féminins, bordent le chemin.（那些柳树，这些有着女性气质的树，排列在道路两旁。）\n\n注意：在法语中，“saule”作为阴性单数形式并不如阳性单数形式“saule”（即“柳树”的标准拼写）常用，且其阴性复数形式“saules”在实际使用中几乎不会出现。上述关于阴性形式的例句和解释更多是为了展示单词的变形规则，而非实际语言中的常见用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1816, 110, ' Aulne', '桤木', '### 1. 词性：\n**名词**（masculin）\n\n### 2. 词义：\n- **“桤木”**：一种落叶乔木，属于桦木科，常见于湿润地区。\n- **“阿尔涅河”**：法国中西部的一条河流，流经多个地区，最终注入卢瓦尔河。\n\n### 3. 例句：\n1. *Le bois d\'aulne est léger et résistant.*  \n   （桤木轻便且坚固。）  \n2. *La ville de Châteauroux est située sur les bords de l\'Aulne.*  \n   （沙托鲁城位于阿尔涅河畔。）\n\n---\n\n### 变形及词义（所有格、与介词搭配）：\n#### 1. **Aulnois, e**  \n- **词义**：桤木的（形容词形式，用于描述与桤木相关的事物）。  \n- **例句**：*L\'écorce d\'aulnois est utilisée en médecine traditionnelle.*  \n  （桤木的树皮被用于传统医学。）\n\n#### 2. **à l\'Aulne**  \n- **词义**：在阿尔涅河畔（介词短语，表示地点）。  \n- **例句**：*Ils ont construit leur maison à l\'Aulne, près de Châteauroux.*  \n  （他们在阿尔涅河畔、沙托鲁附近建了房子。）\n\n#### 3. **Aulnais**  \n- **词义**：桤木林（集合名词，指桤木生长的树林）。  \n- **例句**：*Les oiseaux nichent dans les aulnais au bord de la rivière.*  \n  （鸟儿在河岸的桤木林中筑巢。）\n\n---\n\n### 总结：\n- **词性**：名词（masculin）。  \n- **常用词义**：桤木（植物）或阿尔涅河（地理名称）。  \n- **变形**：根据语境可衍生出形容词（aulnois）、地点短语（à l\'Aulne）或集合名词（aulnais）。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1817, 110, ' Bambou', '竹子', '1. 词性：名词\n2. 词义：竹子；竹竿\n3. 例句：\n   - Le panda mange du bambou. 熊猫吃竹子。\n   - Il a fabriqué un panier avec des tiges de bambou. 他用竹竿做了一个篮子。\n\n**变形及其词义与例句**：\n\n*注意：法语中“bambou”作为名词，其变形并不像动词那样有明显的时态或人称变化，但可以根据性别和数量有所变化（尽管“bambou”通常被视为不变尖词，即不分阴阳性，但在某些语境下，为了语法一致，可能会采用“bambous”作为复数形式，尽管这种用法不如英语中常见）。以下是一些可能的“变形”（更多是基于语法结构而非实际词汇变化）及其解释和例句：\n\n1. **Bambou (singulier, invariable)**\n   - 词义：竹子；竹竿（单数形式，不变）\n   - 例句：Le bambou est une plante rapide à croître. 竹子是一种生长迅速的植物。\n\n2. **Bambous (pluriel, rarement utilisé)**\n   - 词义：竹子；竹竿（复数形式，较少使用，通常保持单数形式不变）\n   - 例句：Les pandas mangent principalement du bambou. 熊猫主要以竹子为食。\n   - *注：在实际使用中，即使表示复数，也更常保持“bambou”不变，因为法语中许多外来词作为不变尖词处理。*\n\n3. **En bambou**\n   - 词义：用竹子制成（作为介词短语或形容词短语）\n   - 例句：Cette maison est entièrement construite en bambou. 这座房子完全用竹子建造。\n\n4. **Bâti en bambou**\n   - 词义：用竹子建造（过去分词短语，用于描述某物由竹子构成）\n   - 例句：Le pont était bâti en bambou et paraissait fragile. 桥是用竹子建造的，看起来挺脆弱的。\n\n*注意：上述“变形”更多是为了展示法语中如何通过不同方式表达与“bambou”相关的概念，而非严格意义上的词汇变形。在实际应用中，“bambou”通常作为不变尖词使用，不随性别、数量或时态变化。*', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1818, 110, ' Forêt primaire', '原始森林', '1. 词性：名词（阴性，单数）\n2. 词义：原始森林\n3. 例句：\n   - La forêt primaire est un endroit où la nature a gardé son aspect originel.（原始森林是一个自然保持其原始面貌的地方。）\n   - La protection de la forêt primaire est cruciale pour la biodiversité.（保护原始森林对生物多样性至关重要。）\n\n**变形及其词义与例句**：\n\n* 由于“Forêt primaire”是一个复合名词，且“primaire”作为形容词修饰“forêt”，在法语中，名词的变形通常涉及数（单数/复数）和性（阴性/阳性）的变化，以及可能的前置词或后缀添加。但在这个特定短语中，“Forêt primaire”作为一个整体，其变形主要限于数的变化，因为“primaire”是形容词，不随名词变性，而“forêt”本身已经是阴性单数形式。\n\n1. **复数形式**：Forêts primaires\n   - 词义：多片原始森林\n   - 例句：Les forêts primaires du monde sont en train de disparaître à cause de la déforestation.（世界上的原始森林正因砍伐而消失。）\n\n* 注意：在法语中，当名词前有形容词时，通常是形容词根据名词的性数变化，而名词本身保持不变（除了数的变化）。在这个例子中，“primaire”不需要根据“forêt”的性数变化，因为它已经是正确的形式来修饰阴性单数名词“forêt”。如果要表达多片原始森林，我们只需将“forêt”变为复数形式“forêts”，而“primaire”保持不变。\n\n因此，除了上述的复数形式外，“Forêt primaire”没有其他常见的变形。如果需要表达不同的性数组合（如阳性单数、阳性复数等），通常会改变名词部分（如果存在对应的阳性形式），但在这个例子中，“forêt”本身就是阴性形式，且没有直接的阳性对应词来表示“原始森林”。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1819, 110, ' Peuplier', '杨树', '1. 词性：名词\n2. 词义：杨树；柳树（在某些地区也指）\n3. 例句：\n   - Le Peuplier est un arbre qui pousse rapidement.（杨树是一种生长迅速的树。）\n   - Les feuilles du peuplier tremblent avec le vent.（杨树的叶子随风摇曳。）\n\n**变形及其词义与例句**：\n\n由于“Peuplier”是一个名词，并且不是法语中的不规则名词，其变形主要遵循法语名词的一般复数形式规则，即在词尾加上“-s”。此外，作为名词，它没有像动词那样的时态或人称变化。以下是其主要变形及例句：\n\n1. **单数形式**：\n   - 词形：Peuplier\n   - 词义：杨树；柳树（在某些地区也指）\n   - 例句：Le long de la rivière, on voit de nombreux peupliers.（沿着河边，可以看到许多杨树。）\n\n2. **复数形式**：\n   - 词形：Peupliers\n   - 词义：（多棵）杨树；柳树（复数）\n   - 例句：Les peupliers de la forêt sont en pleine croissance.（森林里的杨树正处于茂盛的生长期。）\n\n需要注意的是，“Peuplier”作为名词，其变形相对简单，主要就是单复数的变化。在句子中，它通常作为主语、宾语或定语使用，具体取决于句子的结构和语境。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1820, 116, '床单', 'le drap', '### 法语单词：**drap**\n\n---\n\n#### 1. 词性：  \n**名词（Masculin）**\n\n---\n\n#### 2. 词义：  \n- **床单**（铺在床垫上的织物，通常与“housse”搭配使用）；  \n- **布料**（广义指用于裁剪或覆盖的织物，如窗帘、桌布等）；  \n- **（戏剧、绘画中的）背景布**（舞台或画面的背景）。\n\n---\n\n#### 3. 例句：  \n1. **Je change la couette et les draps toutes les semaines.**  \n   （我每周更换被子和床单。）  \n2. **Le drap est sale, il faut le laver.**  \n   （床单脏了，该洗了。）\n\n---\n\n#### 4. 变形及词义（所有变形均基于“drap”的直接形式）：  \n法语中“drap”没有常见的屈折变形（如性、数、格变化），但存在以下衍生形式或复合词：  \n\n| 变形/复合词 | 词义 | 例句 |  \n|---------|------|-------|  \n| **draps** | 复数形式，指多条床单或多种布料 | **Les draps sont en lin.**（这些床单是亚麻的。） |  \n| **drapeau** | 旗帜（词源相同，引申为“布制标志”） | **Le drapeau français est tricolore.**（法国国旗是三色的。） |  \n| **housse de couette** | 被套（与“drap”搭配使用） | **J’ai changé la housse de couette et les draps.**（我换了被套和床单。） |  \n\n---\n\n### 总结：  \n- **drap** 的核心词义是“床单”或“布料”，复数形式为 **draps**。  \n- 其他变形（如 **drapeau**）需通过复合词或派生词实现，词义与“布”的物理属性或象征意义相关。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1821, 116, '厕所', 'les toilettes', '### 法语单词：Toilette\n\n#### 1. 词性：\n- 名词（Masculine - 阳性）\n\n#### 2. 词义：\n- 厕所，洗手间\n- 化妆间，梳妆台\n- （特定语境下）洗漱、梳妆的动作或过程\n\n#### 3. 例句：\n- Où est la toilette, s\'il vous plaît?\n  （请问，厕所在哪里？）\n- Elle se maquille dans la toilette avant de sortir.\n  （她在出门前在梳妆台前化妆。）\n\n#### 变形及其词义与例句：\n\n**注意**：法语中“toilette”作为名词，其变形主要体现在单复数形式上，以及由于性别和数的变化而引起的冠词和形容词变化，但单词本身形式不变。以下是其基本变形（主要考虑单复数）：\n\n1. **Singulier (单数)**\n   - **词形**：toilette\n   - **词义**：厕所，洗手间；化妆间，梳妆台\n   - **例句**：La toilette est juste à gauche.\n     （厕所就在左边。）\n\n2. **Pluriel (复数)**\n   - **词形**：toilettes\n   - **词义**：多间厕所，多个洗手间；多个化妆间或梳妆台（较少用，通常指场所内的多个设施）\n   - **例句**：Les toilettes sont propres et bien entretenues.\n     （这些厕所干净且维护得很好。）\n\n**其他说明**：\n- “Toilette”作为名词，在句子中通常作为主语、宾语或表语出现。\n- 在表示“厕所”时，常用定冠词“la”或“les”（根据单复数）来限定，如“aller aux toilettes”（去上厕所）。\n- 在表示“化妆间”或“梳妆台”时，同样使用定冠词，并且可能伴有形容词来进一步描述，如“une jolie toilette”（一个漂亮的梳妆台）。\n- “Toilette”在特定语境下，也可以指“洗漱、梳妆的动作或过程”，但这种用法相对较少见，且通常不通过变形来表达，而是通过句子结构来体现。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1822, 116, '宿舍', 'la résidence', '### 1. 词性：\n- **名词**（masculin）\n\n### 2. 词义：\n- **宿舍**：学生或员工居住的集体住所，通常指学校、公司等提供的住宿。\n- **寝室**：特指睡觉的房间。\n\n### 3. 例句：\n- **La résidence universitaire accueille des étudiants de toute la France.**  \n  （大学宿舍欢迎来自法国各地的学生。）\n- **Les chambres du dortoir sont petites mais fonctionnelles.**  \n  （宿舍的房间虽小但功能齐全。）\n\n---\n\n### 变形及词义：\n1. **复数形式**：**dortoirs**  \n   - **词义**：多个宿舍。  \n   - **例句**：Ces dortoirs ont été rénovés l\'année dernière.  \n     （这些宿舍去年进行了翻新。）\n\n2. **动词变位**：**dortoir** 本身是名词，无动词变形。但可组成短语 **être au dortoir**（在宿舍）。  \n   - **例句**：Les élèves doivent être au dortoir à 21h.  \n     （学生必须在晚上9点前回到宿舍。）\n\n---\n\n### 总结：\n- **词性**：名词（m）  \n- **常用词义**：集体宿舍、寝室  \n- **变形**：复数 **dortoirs**，无其他变形。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1823, 116, '椅子', 'la chaise', '1. 词性：名词（masculin）\n\n2. 词义：\n- 椅子，坐具\n- （某些机构、职位的）席位，职位\n- （学术、艺术等领域的）教授职位，大师职位\n\n3. 例句：\n- J\'ai acheté une nouvelle chaise pour la salle à manger.（我给餐厅买了一把新椅子。）\n- Il a obtenu la chaise de professeur à l\'université.（他在大学获得了教授职位。）\n\n变形及其词义与例句：\n\n1. 复数形式：chaises\n   - 词义：多把椅子，多个席位，多个职位\n   - 例句：Les chaises sont toutes occupées.（所有的椅子都有人坐了。）\n\n2. 并无其他常用变形，但“chaise”在不同语境下可指代不同含义的“席位”或“职位”，如：\n   - 在政治语境中，“la chaise du président”指的是总统的职位。\n     例句：Il aspire à la chaise du président depuis longtemps.（他长期以来一直渴望总统的职位。）\n   - 在学术语境中，“une chaise d\'élite”可能指的是一个精英教授的职位。\n     例句：Elle a été nommée à une chaise d\'élite dans le département de mathématiques.（她被任命为数学系的一个精英教授职位。）\n\n注意：法语中“chaise”作为名词，其变形主要是复数形式“chaises”，而其他形式的“变形”更多是依赖于语境和搭配来体现不同的含义，并非严格的词形变化。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1824, 116, '钥匙', 'la clé', '1. 词性：名词（masculin）\n2. 词义：\n    - 钥匙，开锁的工具。\n    - 关键；要害；关键因素。\n3. 例句：\n    - J\'ai trouvé les clés de la maison.（我找到了房子的钥匙。）\n    - La clé de la réussite, c\'est de travailler dur.（成功的关键就是努力工作。）\n\n**变形及其词义和例句：**\n\n**复数形式：clés**\n词义：钥匙（复数形式）\n例句：Les clés sont sur la table.（钥匙在桌子上。）\n\n**阴性形式（当表示某个抽象概念的关键等时，可用阴性形式）：clé**\n词义：关键；要害（阴性形式）\n例句：La clé de la solution est de bien analyser le problème.（解决问题的关键在于好好分析问题。）', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1825, 116, '桌子', 'la table', '1. 词性：名词（阳性，单数）\n2. 词义：桌子\n3. 例句：\n   - La table est dans la salle à manger. （桌子在餐厅里。）\n   - Ils sont autour de la table. （他们围坐在桌子旁。）\n\n**变形及其词义和例句：**\n\n1. **阴性形式：la table**\n   - 词义：桌子（阴性形式，通常用于特定语境或作为复合词的一部分）\n   - 例句：La table de chevet est près du lit. （床头柜在床边。）\n\n2. **复数形式：les tables**\n   - 词义：桌子（复数）\n   - 例句：Les tables sont bien arrangées dans la salle de réunion. （会议室里的桌子摆放得很整齐。）\n\n3. **所有格形式：la table de...**\n   - 词义：……的桌子\n   - 例句：C\'est la table de mon bureau. （这是我办公桌的桌子。）\n\n4. **动词形式（作为名词时不适用，但相关动词为“tabler”）：**\n   - 词义：讨论，商议（注意：这是动词“tabler”的词义，与名词“table”不同）\n   - 例句：Nous avons tablé longtemps avant de prendre une décision. （我们讨论了很久才做出决定。）\n\n注意：在法语中，“table”作为名词时，其变形主要体现在性别、数量和所有格上，而不像英语那样有复杂的时态和语态变化。上述变形涵盖了“table”作为名词时的常见用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1826, 116, '门', 'la porte', '### 1. 词性：\n**名词**（masculin）\n\n---\n\n### 2. 词义：\n- **物体**：指实物“门”（如房屋、家具的门）。\n- **抽象概念**：象征“入口”“通道”或“机会”。\n- **引申义**（口语/俗语）：表示“关键”或“解决方法”。\n\n---\n\n### 3. 例句：\n1. *Ouvrez la porte, il fait froid dehors.*  \n   （打开门，外面很冷。）  \n2. *La porte du succès est toujours entreouverte.*  \n   （成功之门永远半开着。）\n\n---\n\n### 4. 变形及词义：\n#### **直接宾格**：la porte  \n- **词义**：作为动作的承受者（如“开门”中的“门”）。  \n- **例句**：*J\'ouvre la porte.*  \n  （我开门。）\n\n#### **主有形容词**：porte（阳性），porte（阴性）*  \n- **词义**：表示“属于……的门”。  \n- **例句**：*La porte arrière de la voiture.*  \n  （车的后门。）  \n  *注：阳性（porte）用于阳性名词前，阴性（porte）极少用，通常用“de”替代。*\n\n#### **复数形式**：les portes  \n- **词义**：多扇门或象征多个“入口”。  \n- **例句**：*Les portes du métro sont automatiques.*  \n  （地铁的门是自动的。）\n\n---\n\n### 附：特殊用法\n- **俗语**：*Chercher la porte*（找门）→ 意为“找借口离开”。  \n  *例句*：*Il a cherché la porte pour éviter la dispute.*  \n  （他找借口离开了以避免争吵。）', NULL, 0, NULL, NULL);
