INSERT INTO `word_list` VALUES (1829, 116, '肥皂', 'le savon', '1. 词性：名词 (masculin)\n2. 词义：\n   - 肥皂，用于清洁的块状或液态物质。\n   - （引申义）任何具有清洁作用的物质或产品。\n\n3. 例句：\n   - J\'ai oublié d\'emmener mon savon à l\'entraînement de gym. (我忘记带肥皂去健身房了。)\n   - Elle acheta un savon pour les mains à la pharmacie. (她在药店买了一块洗手皂。)\n\n**变形及其词义与例句：**\n\n虽然“savon”作为名词没有像动词那样的时态变化，但它在不同的语境和用法中会有不同的形式或搭配，以下是一些常见的表达方式及其例句：\n\n1. **du savon** (不定冠词+名词)：表示一些肥皂\n   - J\'ai besoin d\'acheter du savon pour la maison. (我需要买些家用肥皂。)\n\n2. **le savon** (定冠词+名词)：特指某块肥皂或肥皂这一物品\n   - Le savon est tombé dans l\'eau. (肥皂掉进水里了。)\n\n3. **un savon** (不定冠词+名词)：表示一块肥皂\n   - Il a pris un savon pour se laver les mains. (他拿了块肥皂来洗手。)\n\n4. **des savons** (复数形式)：表示多块肥皂或多种肥皂\n   - Les savons ménagers sont souvent parfumés. (家用肥皂通常带有香味。)\n\n5. **savons** (我们/你们/他们用的形式，如在祈使句中或作为动词的直接宾语等)：虽然这种形式不是“savon”本身的变形，但在实际使用中，根据主语的不同，动词和代词会有所变化，而“savon”作为名词保持不变。例如：\n   - Nous utilisons des savons naturels. (我们使用天然肥皂。)\n   - Vous devez acheter des savons pour le camping. (你们得为露营买些肥皂。)\n\n注意：法语中名词的“变形”主要指的是复数形式、与不同冠词和代词的搭配以及在某些特定语境中的使用方式，而不是像动词那样有时态的变化。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1830, 116, '毛巾', 'la serviette', '### 1. 词性：\n**名词（masculin）**\n\n### 2. 词义：\n- 毛巾（用来擦干身体或物品的织物）\n- （引申）类似毛巾功能的物品\n\n### 3. 例句：\n1. **Je me séche avec une serviette.**  \n   （我用毛巾擦干身体。）  \n2. **La serviette de bain est en tissu épais.**  \n   （浴巾是用厚实的布料做的。）\n\n---\n\n### 变形及词义（所有变形均指“毛巾”，词性为名词，阴性以“-e”结尾）：\n\n#### 1. **Serviette**  \n   - **词义**：小毛巾（如餐巾、手帕）  \n   - **例句**：**Mettez votre serviette sur vos genoux.**  \n     （把餐巾放在膝盖上。）\n\n#### 2. **Serviettes** (复数)  \n   - **词义**：多条毛巾（如家庭或餐厅用的毛巾）  \n   - **例句**：**Les serviettes de table sont en papier.**  \n     （餐巾是纸做的。）\n\n#### 3. **Serviettes-éponge** (复合词)  \n   - **词义**：海绵毛巾（吸水性强的毛巾）  \n   - **例句**：**Utilisez des serviettes-éponge pour essuyer les verres.**  \n     （用海绵毛巾擦杯子。）\n\n---\n\n### 总结：\n- **基础词**：**serviette**（毛巾），阴性名词，复数加“-s”。  \n- **变形**：根据语境可组合成复合词（如“serviettes-éponge”），但核心词义不变。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1831, 116, '灯', 'la lampe', '1. 词性：名词（femme）\n2. 词义：灯；照明设备；发光体；灯塔；启示之物\n3. 例句：\n   - La lampe est allumée. （灯亮着。）\n   - Il y a une lumière dans la pièce. （房间里有一盏灯。）\n\n**变形及其词义与例句：**\n\n1. **lumières (复数形式)**\n   - 词义：灯的复数形式，表示多盏灯或泛指照明。\n   - 例句：Les lumières de la ville sont magnifiques la nuit. （夜晚城市的灯光很美。）\n\n2. **lampe (同义词，更常用于指具体的灯具)**\n   - 词义：特指一种灯具，如油灯、电灯等。\n   - 例句：Je suis allé acheter une nouvelle lampe pour mon bureau. （我去给我的办公室买了一盏新灯。）\n\n3. **phare (特指灯塔或车灯等大型或特定用途的照明设备)**\n   - 词义：灯塔；车灯；指引之光。\n   - 例句：Le phare du bateau était éclairé pour guider les navires. （船上的灯塔亮着以引导船只。）\n\n4. **béton (虽非直接相关，但作为“混凝土”的法语词，可引申为“基础、基石”，在此作为对比或隐喻使用，非直接变形)**\n   - 词义：混凝土；基础；基石。（注：此词与“灯”无直接变形关系，仅为展示不同词性的示例）\n   - 例句：La fondation en béton est solide comme le béton. （混凝土基础坚如磐石。）（此句中“béton”与“灯”无关，仅为语法结构示例）\n\n注意：在法语中，“灯”的主要变形是其复数形式“lumières”，而其他如“lampe”、“phare”等则更多是同义词或特定语境下的用词，并非严格意义上的变形。因此，在列举变形时，我们主要关注了复数形式的变化，并补充了几个相关的同义词作为参考。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1832, 116, '窗户', 'la fenêtre', '### 法语单词：**fenêtre**\n\n---\n\n#### 1. **词性**  \n名词（*féminin*，阴性）\n\n---\n\n#### 2. **常用词义**  \n- 窗户（建筑中的开口结构）  \n- （引申）窗口、橱窗、显示框（如软件窗口、相机取景框等）  \n- （转义）心灵或思想的窗口（比喻）  \n\n---\n\n#### 3. **例句**  \n1. *Ouvrez la fenêtre, il fait du vent.*  \n   （打开窗户，外面有风。）  \n2. *La fenêtre de l\'ordinateur est en bois.*  \n   （电脑的窗口边框是木制的。）  \n\n---\n\n### **变形及词义与例句**  \n（注：*fenêtre* 为阴性名词，复数形式需变化，无其他变位，但需注意搭配动词的性数配合。）\n\n---\n\n#### **复数形式**  \n- **词形**：**fenêtres**  \n- **词义**：窗户（复数）  \n- **例句**：  \n  *Les fenêtres sont sales, elles ont besoin d\'être lavées.*  \n  （窗户脏了，需要清洗。）\n\n---\n\n#### **搭配介词的常见表达**  \n1. **par la fenêtre**（通过窗户）  \n   - **例句**：  \n     *Il est entré par la fenêtre.*  \n     （他从窗户进来。）  \n\n2. **devant la fenêtre**（在窗户前）  \n   - **例句**：  \n     *Il y a un fauteuil devant la fenêtre.*  \n     （窗户前有一把扶手椅。）  \n\n3. **ouvrir/fermer la fenêtre**（开/关窗户）  \n   - **例句**：  \n     *Elle a fermé la fenêtre pour ne pas faire rentrer le froid.*  \n     （她关上窗户以免冷风进入。）\n\n---\n\n### **总结**  \n- *Fenêtre* 的核心词义围绕“窗户”展开，复数形式为 *fenêtres*，搭配介词可扩展比喻或具体场景的用法。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1833, 116, '枕头', 'l\'oreiller', '1. 词性：名词 (masculin)\n2. 词义：用来支撑头部的卧具，通常放在床上或沙发上。\n3. 例句：\n   - J\'ai changé la taie de mon oreiller. (我换了我的枕头套。)\n   - Il dort toujours sans oreiller. (他总是不用枕头睡觉。)\n\n**变形及其词义和例句：**\n\n1. **oreillers** (复数形式)\n   - 词义：多个枕头\n   - 例句：Les enfants ont des oreillers en forme de coussins. (孩子们有形状像垫子的枕头。)\n\n2. **oreiller** (单数形式，不变)\n   - 词义：一个枕头\n   - 例句：Il a posé sa tête sur l\'oreiller. (他把头放在枕头上。)\n\n注意：在法语中，“oreiller”作为名词，其复数形式是直接在词尾加“s”，即“oreillers”。该词没有其他常见的变形形式，因为它是一个不可数名词（在这里指的是物品，不是物质），且在句子中通常作为主语、宾语或介词的宾语出现。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1834, 116, '被子', 'la couette', '### 1. 词性：\n名词（masculin）\n\n### 2. 词义：\n- **覆盖物**：用于保暖或保护的覆盖物，如床上的被子。\n- **遮盖物**：泛指任何用于遮盖的物体，如植物上的霜、雪等自然覆盖物。\n\n### 3. 例句：\n1. J\'ai mis un *dessus-de-lit* sur le lit pour me réchauffer.  \n   （我在床上放了一床被子来保暖。）  \n2. La montagne était recouverte d\'un épais *dessus-de-lit* de neige.  \n   （山峰被厚厚的一层雪覆盖。）\n\n---\n\n### 变形及词义与例句：\n法语中 **\"dessus-de-lit\"** 是完整形式，但口语中常用 **\"couette\"**（阴性名词）代替。以下是相关变形和用法：\n\n#### 1. **Desseins**（复数形式）\n- **词义**：多指床单、床罩等床上用品（集合意义）。  \n- **例句**：Les *dessins* du lit sont en coton bio.  \n  （床上的床单是有机棉的。）\n\n#### 2. **Couette**（口语常用词，阴性名词）\n- **词义**：特指现代意义上的羽绒被或厚被。  \n- **例句**：Jette un œil sur la nouvelle *couette* que j\'ai achetée.  \n  （看看我新买的羽绒被。）\n\n#### 3. **Couverture**（广义覆盖物，阴性名词）\n- **词义**：泛指覆盖物，如毯子、桌布等。  \n- **例句**：Une *couverture* de ventre est indispensable l\'hiver.  \n  （冬天一条腹毯是必不可少的。）\n\n---\n\n### 总结：\n- **\"Dessous-de-lit\"** 是正式用语，强调功能（覆盖/保暖）。  \n- **\"Couette\"** 更口语化，特指现代厚被。  \n- **\"Couverture\"** 范围更广，可指任何覆盖物。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1835, 116, '房间', 'la chambre', '### 法语单词：Chambre\n\n1. **词性**：  \n   名词（Féminin）\n\n2. **词义**：  \n   - 房间（如卧室、客厅等）  \n   - （法律或政治语境中的）议会、议院  \n   - （复数）私生活、隐私  \n\n3. **例句**：  \n   - La chambre est spacieuse et lumineuse. （房间宽敞明亮。）  \n   - La Chambre des députés a voté la loi. （众议院通过了这项法律。）  \n\n---\n\n### 变形及词义与例句：\n\n#### 1. **Chambre**（原形）  \n   - **词义**：房间；议院  \n   - **例句**：La chambre à coucher est en haut. （卧室在楼上。）  \n\n#### 2. **Chambres**（复数）  \n   - **词义**：多个房间；私生活  \n   - **例句**：Les chambres de l\'hôtel sont modernes. （酒店的房间很现代。）  \n   - **例句**：Respecter les chambres des autres. （尊重他人的隐私。）  \n\n#### 3. **Au sujet de la chambre**（关于房间的表达）  \n   - **词义**：用于描述房间的特征或状态  \n   - **例句**：La température de la chambre est agréable. （房间的温度很舒适。）  \n\n#### 4. **La Chambre**（首字母大写，特指议会）  \n   - **词义**：法国议会（国民议会）  \n   - **例句**：La Chambre a adopté le budget. （议会通过了预算案。）  \n\n---\n\n### 总结：\n- **Chambre** 的核心词义是“房间”和“议院”，复数形式可表示“多个房间”或“隐私”。  \n- 在法律或政治语境中，首字母大写的 **La Chambre** 特指法国议会。', NULL, 0, NULL, NULL);
INSERT INTO `word_list` VALUES (1836, 116, '书架', 'l\'étagère', '1. 词性：阳性名词\n2. 词义：放置书籍的架子、书柜\n3. 例句：\n    - J\'ai acheté un étagère à livres pour ranger mes bouquins.（我买了一个书架来放我的书。）\n    - Il a posé le livre sur l\'étagère.（他把书放在了书架上。）\n\n变形及词义、例句：\n- 复数形式：étagères à livres，词义：书架（复数），例句：Les étagères à livres sont remplies de livres.（这些书架摆满了书。）\n\n注意：“étagère à livres”是一个复合名词，表示“书架”，其变形主要遵循法语名词复数的一般规则，即在阳性单数名词后加“s”构成复数形式。在这个复合名词中，“à livres”作为定语修饰“étagère”，整体表达“用于放书的架子”的意思。', NULL, 0, NULL, NULL);
